INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "捕捉鱼类。", "primary_collocate": null, "pronunciation": "bǔ yú", "ipa": "pu˨˩˦ y˧˥", "syllable_count": 2, "sentences": [{"text": "这个地方不让人随便捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天河水很冷，很少有人捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人靠捕鱼过日子。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里的鱼越来越少，捕鱼变得很难。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是禁止捕鱼的时间。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李想去海边学捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护鱼类，这里三个月不能捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在船上捕鱼十年了。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们可以在湖边钓鱼，但是不能捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捕鱼是这个小岛上最重要的工作。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕了鱼", "label": "体标"}, {"form": "捕过鱼", "label": "体标"}, {"form": "捕鱼业", "label": "复合"}], "register": "中性", "sense_fingerprint": "捕捉鱼类，泛指抓鱼这件事或这种工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确答案。捕鱼（bǔ yú）指捕捉鱼类，泛指抓鱼这件事或这种工作。"}, {"text": "哺育", "is_correct": false, "explanation": "哺育（bǔ yù）与捕鱼（bǔ yú）第二个音节声调不同（第四声），意思是喂养幼小的动物或婴儿。"}, {"text": "补语", "is_correct": false, "explanation": "补语（bǔ yǔ）与捕鱼（bǔ yú）第二个音节声调不同（第三声），是语法术语，指动词后补充说明的成分。"}, {"text": "不予", "is_correct": false, "explanation": "不予（bù yǔ）与捕鱼两个音节的声调都不同，意思是不给予、不加以。"}], "explanations": {"捕鱼": "正确答案。捕鱼（bǔ yú）指捕捉鱼类，泛指抓鱼这件事或这种工作。", "哺育": "哺育（bǔ yù）与捕鱼（bǔ yú）第二个音节声调不同（第四声），意思是喂养幼小的动物或婴儿。", "补语": "补语（bǔ yǔ）与捕鱼（bǔ yú）第二个音节声调不同（第三声），是语法术语，指动词后补充说明的成分。", "不予": "不予（bù yǔ）与捕鱼两个音节的声调都不同，意思是不给予、不加以。"}, "sentence_index": null, "correct_answer": "捕鱼"}, "level_3": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确。“不让人随便捕鱼”说的是对捕鱼这件事的限制。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”指人或动物降生，不能作“不让人随便”的动作，句意说不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是自然现象，人不能决定，“不让人随便下雨”说不通。"}, {"text": "长大", "is_correct": false, "explanation": "语义：长大是自然过程，不能被“不让人随便”限制，句意说不通。"}], "explanations": {"捕鱼": "正确。“不让人随便捕鱼”说的是对捕鱼这件事的限制。", "出生": "搭配：“出生”指人或动物降生，不能作“不让人随便”的动作，句意说不通。", "下雨": "语义：下雨是自然现象，人不能决定，“不让人随便下雨”说不通。", "长大": "语义：长大是自然过程，不能被“不让人随便”限制，句意说不通。"}, "sentence_index": 0, "correct_answer": "捕鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿着网在树上捕鱼，抓到了三只小鸟。", "explanation": "这里应该用〈捕鸟〉。捕鱼只指抓鱼，在树上抓小鸟要说捕鸟。"}, {"text": "猎人在森林里捕鱼，打到了一只野鹿。", "explanation": "这里应该用〈捕猎〉。捕鱼只指抓鱼，在森林里抓野生动物要说捕猎。"}, {"text": "小猫在厨房里捕鱼，抓住了一只老鼠。", "explanation": "这里应该用〈抓老鼠〉。捕鱼只指抓鱼，猫抓老鼠不能说捕鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确。“这里三个月不能捕鱼”是为了保护鱼类而禁止的活动。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：阅读是看书，与“为了保护鱼类”的禁令无关，句意说不通。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”后面要接水平、数量等，不能说“三个月不能提高”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理环境，与保护鱼类的禁令不合，句意说不通。"}], "explanations": {"捕鱼": "正确。“这里三个月不能捕鱼”是为了保护鱼类而禁止的活动。", "阅读": "语义：阅读是看书，与“为了保护鱼类”的禁令无关，句意说不通。", "提高": "搭配：“提高”后面要接水平、数量等，不能说“三个月不能提高”。", "打扫": "语义：打扫是清理环境，与保护鱼类的禁令不合，句意说不通。"}, "sentence_index": 6, "correct_answer": "捕鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里捕鱼，准备晚饭。", "explanation": "这里应该用〈烧鱼〉。捕鱼是捕捉鱼类，在厨房里做鱼要说烧鱼。"}, {"text": "我每天去市场捕鱼，再买回家吃。", "explanation": "这里应该用〈购买〉。捕鱼是捕捉鱼类，去市场拿钱买鱼要说购买。"}, {"text": "夏天我们去游泳池捕鱼。", "explanation": "这里应该用〈游泳〉。捕鱼是捕捉鱼类，在泳池里玩水要说游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时在船上捕鱼过。", "corrected_sentence": "他年轻时在船上捕过鱼。", "error_description": "错误：“捕鱼过”；正确：“捕过鱼”。表示经历的“过”要紧跟动词“捕”，不能放在宾语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民们每天早上都去海边捕鱼着。", "corrected_sentence": "渔民们每天早上都去海边捕鱼。", "error_description": "错误：“捕鱼着”；正确：“捕鱼”。表示习惯性动作不用“着”，而且“着”也不能放在宾语“鱼”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
