INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人家；家庭。", "primary_collocate": null, "pronunciation": "hù", "ipa": "xu˥˩", "syllable_count": 1, "sentences": [{"text": "我们村有三十多户人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家是村里最穷的一户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼住着四十户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每户都有一台电视。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一户人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有五户人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全村一共两百户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是新搬来的一户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一户的孩子都在外地工作。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一户的灯还亮着？", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戶", "label": "繁体"}, {"form": "农户", "label": "复合"}, {"form": "住户", "label": "复合"}], "register": "中性", "sense_fingerprint": "人家，家庭（按家计数）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。户 hù 指人家、家庭，按家计数。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。"}, {"text": "湖", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是湖泊。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}, {"text": "壶", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。"}], "explanations": {"户": "正确答案。户 hù 指人家、家庭，按家计数。", "虎": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。", "湖": "hú（第二声）与 hù（第四声）声调不同，意思是湖泊。", "呼": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。", "壶": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。"}, "sentence_index": null, "correct_answer": "户"}, "level_3": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。“三十多___人家”需要按家计数的量词，“户”符合。"}, {"text": "口", "is_correct": false, "explanation": "搭配：“口”用于计算人口，不用于按家计数人家。"}, {"text": "位", "is_correct": false, "explanation": "语域：“位”是敬称，用来数有身份的人，不能用来数人家。"}, {"text": "间", "is_correct": false, "explanation": "语义：“间”用于计量房屋，不能用来计数村里的人家。"}], "explanations": {"户": "正确答案。“三十多___人家”需要按家计数的量词，“户”符合。", "口": "搭配：“口”用于计算人口，不用于按家计数人家。", "位": "语域：“位”是敬称，用来数有身份的人，不能用来数人家。", "间": "语义：“间”用于计量房屋，不能用来计数村里的人家。"}, "sentence_index": 0, "correct_answer": "户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有五户学生。", "explanation": "这里应该用〈名〉。户只用来计算家庭，计算学生要用〈名〉或〈个〉。"}, {"text": "这一户书很多。", "explanation": "这里应该用〈本〉。户是计算家庭的量词，计算书要用〈本〉。"}, {"text": "每户小猫都很可爱。", "explanation": "这里应该用〈只〉。户只用于家庭，计算小猫要用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88766, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。户 hù 指人家、家庭，按家计数。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是胡须或胡同。"}, {"text": "乎", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，用于语气，与“户”不同。"}, {"text": "忽", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是忽然。"}], "explanations": {"户": "正确答案。户 hù 指人家、家庭，按家计数。", "胡": "hú（第二声）与 hù（第四声）声调不同，意思是胡须或胡同。", "乎": "hū（第一声）与 hù（第四声）声调不同，用于语气，与“户”不同。", "忽": "hū（第一声）与 hù（第四声）声调不同，意思是忽然。"}, "sentence_index": null, "correct_answer": "户"}, "level_3": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。“全村一共两百___”需要按家计数的量词，“户”符合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”用于计量小动物或成对的物品，不能用于计数村里的人家。"}, {"text": "间", "is_correct": false, "explanation": "语义：“间”用于计量房屋，不能用来计数全村的人家。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于计量平面的物品，与“全村一共两百”的人家搭配不当。"}], "explanations": {"户": "正确答案。“全村一共两百___”需要按家计数的量词，“户”符合。", "只": "语义：“只”用于计量小动物或成对的物品，不能用于计数村里的人家。", "间": "语义：“间”用于计量房屋，不能用来计数全村的人家。", "张": "搭配：“张”用于计量平面的物品，与“全村一共两百”的人家搭配不当。"}, "sentence_index": 6, "correct_answer": "户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的户很幸福。", "explanation": "这里应该用〈家〉。〈户〉指人家、家庭这一单位，不能用“他的户”来说家庭的生活状态；表示家庭的幸福要用〈家〉。"}, {"text": "他推开了那扇户。", "explanation": "这里应该用〈门〉。现代汉语中“户”不指门，门才指门扇。"}, {"text": "这一户窗很亮。", "explanation": "这里应该用〈扇〉，不能用〈户〉。窗要用〈扇〉计算，〈户〉只用于家庭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, valid