INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88767, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "本身是说这个东西自己,不是别的。", "primary_collocate": null, "pronunciation": "běn shēn", "ipa": "pən˨˩˧ ʂən˥˥", "syllable_count": 2, "sentences": [{"text": "手机本身不贵，贵的是话费。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书本身不错，就是封面不好看。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题本身不大，大的是他的态度。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服本身很好，只是颜色我不喜欢。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事本身没有错，错在说话的方式。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子本身不旧，旧的是里面的家具。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作本身不累，累的是路上花的时间。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药本身没有毒，吃多了才有问题。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词本身很简单，意思却不好懂。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛本身不重要，重要的是大家玩得开心。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本身：指前面提到的事物自己，与相关的其他事物相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本身", "is_correct": true, "explanation": "本身：指手机自己，与“话费”相对，说明手机本身的价格不贵。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”只指人，不能指手机。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指其他人，不指前面提到的手机自己。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能与“手机”组合作主语。"}], "explanations": {"本身": "本身：指手机自己，与“话费”相对，说明手机本身的价格不贵。", "本人": "语义：“本人”只指人，不能指手机。", "别人": "语义：“别人”指其他人，不指前面提到的手机自己。", "大家": "搭配：“大家”指人群，不能与“手机”组合作主语。"}, "sentence_index": 0, "correct_answer": "本身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子很本身，就是价格有点高。", "explanation": "这里“本身”不能受“很”修饰。“本身”是代词，应写作“房子本身”，不能说“很本身”。"}, {"text": "这把伞本身了很好，但是太小。", "explanation": "这里“本身”后面不能直接加“了”。“本身”是代词，不与“了”连用，应去掉“了”。"}, {"text": "这个方案本身过很好，只是太贵。", "explanation": "这里“本身”后面不能加“过”。“本身”不与“过”连用，应去掉“过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本身", "is_correct": true, "explanation": "本身：指工作自己，与“路上花的时间”相对，说明工作本身不累。"}, {"text": "各自", "is_correct": false, "explanation": "配价：“各自”要求复数主体，而“工作”是单一对象，不能这样用。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指人，不指工作本身。"}, {"text": "彼此", "is_correct": false, "explanation": "配价：“彼此”需要双方互指，不能单独指一项工作。"}], "explanations": {"本身": "本身：指工作自己，与“路上花的时间”相对，说明工作本身不累。", "各自": "配价：“各自”要求复数主体，而“工作”是单一对象，不能这样用。", "某人": "语义：“某人”指人，不指工作本身。", "彼此": "配价：“彼此”需要双方互指，不能单独指一项工作。"}, "sentence_index": 6, "correct_answer": "本身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛很本身，大家都玩得很开心。", "explanation": "这里“本身”不能受“很”修饰。“本身”是代词，应写作“比赛本身”，不能说“很本身”。"}, {"text": "比赛本身过不重要，重要的是大家玩得开心。", "explanation": "这里“本身”后面不能加“过”。“本身”不与“过”连用，应去掉“过”。"}, {"text": "比赛本身了很重要，但是大家都没来。", "explanation": "这里“本身”后面不能加“了”。“本身”不与“了”连用，应去掉“了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车本身了很好，只是油耗高。", "corrected_sentence": "这辆车本身很好，只是油耗高。", "error_description": "错误：“本身”后面多加了“了”。“本身”是代词，不与“了”连用，应去掉“了”，写作“这辆车本身很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作本身的不难，难的是时间安排。", "corrected_sentence": "这份工作本身不难，难的是时间安排。", "error_description": "错误：“本身”后面多加了“的”，“本身”是代词，不能直接加“的”后接否定短语“不难”。正确：应写作“这份工作本身不难”，“不”紧接“本身”之后作修饰成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
