INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88768, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指事物自己,不指其他。", "primary_collocate": null, "pronunciation": "běn shēn", "ipa": "pən˨˩˧ ʂən˥˥", "syllable_count": 2, "sentences": [{"text": "游戏本身没有错，错的是玩太久。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "礼物本身不重要，重要的是心意。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱本身不是坏东西，要看怎么用。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法本身很好，只是现在用不上。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影本身很好看，只是太长了。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水本身没有味道，加了糖才变甜。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司本身很小，但是客户很多。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "词典本身很重，我不想每天带着。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校本身不大，但是图书馆很漂亮。", "target_word": "本身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山本身不高，爬起来却很累。", "target_word": "本身", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本身：指事物自己，不包括与它有关的其他方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 4 words above tier T1 (max 2): 那座 (Zipf 3.06), 不高 (Zipf 3.8), 爬起来 (Zipf 3.0), 很累 (Zipf 3.45)']::text[], '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本身", "is_correct": true, "explanation": "本身：指游戏自己，不包括玩的时间等其他方面，说明游戏本身没有错。"}, {"text": "其余", "is_correct": false, "explanation": "语义：“其余”指剩下的部分，不指游戏自己。"}, {"text": "彼此", "is_correct": false, "explanation": "配价：“彼此”需要双方互指，不能单独指代一个游戏。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能与“游戏”组合作主语。"}], "explanations": {"本身": "本身：指游戏自己，不包括玩的时间等其他方面，说明游戏本身没有错。", "其余": "语义：“其余”指剩下的部分，不指游戏自己。", "彼此": "配价：“彼此”需要双方互指，不能单独指代一个游戏。", "大家": "搭配：“大家”指人群，不能与“游戏”组合作主语。"}, "sentence_index": 0, "correct_answer": "本身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法很本身，只是现在用不上。", "explanation": "这里“本身”不能受“很”修饰。“本身”是代词，应写作“办法本身”，不能说“很本身”。"}, {"text": "这门课本身过很难，但是很有用。", "explanation": "这里“本身”后面不能加“过”。“本身”不与“过”连用，应去掉“过”。"}, {"text": "这所学校很本身，但是图书馆很漂亮。", "explanation": "这里“本身”不能受“很”修饰。“本身”是代词，应写作“学校本身”，不能说“很本身”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
