INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "二老是爸爸和妈妈，或是两位老人。", "primary_collocate": null, "pronunciation": "èr lǎo", "ipa": "aɻ˥˩ lɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我下个月接二老来北京住。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老身体都好，请别担心。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年我要回家看二老。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月给二老寄钱。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老最盼着接到孩子的电话。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们二老喝茶还是喝水？", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老在家吃饭，我们就不回去了。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是给二老买的新衣服。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老一直住在老家的小院里。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我陪二老去公园走走。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "称自己或别人的爸爸和妈妈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不能被接来北京住。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是物，不会来北京住。"}, {"text": "令尊", "is_correct": false, "explanation": "语域：“令尊”是敬称别人父亲的用法，不能用于说话人自己的父母。"}, {"text": "二老", "is_correct": true, "explanation": "指说话人的父母，与“接……来北京住”相符。"}], "explanations": {"行李": "语义：行李是物品，不能被接来北京住。", "房子": "语义：房子是物，不会来北京住。", "令尊": "语域：“令尊”是敬称别人父亲的用法，不能用于说话人自己的父母。", "二老": "指说话人的父母，与“接……来北京住”相符。"}, "sentence_index": 0, "correct_answer": "二老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园里来了很多二老在散步。", "explanation": "这里应该用〈老人〉。二老指两位老人或父母双亲，泛指多位老人时不用“二老”。"}, {"text": "我家的二老在小学读三年级。", "explanation": "这里应该用〈弟弟〉。二老指父母或两位老人，不指上小学的孩子。"}, {"text": "我爸爸去世了，现在只有二老一个人住。", "explanation": "这里应该用〈妈妈〉。二老指两位，只指一个人时不能用“二老”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "语义：地铁不能在家吃饭。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆不能在家吃饭。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“在家吃饭”的主语应是人，“饭店”不搭配这个动作。"}, {"text": "二老", "is_correct": true, "explanation": "指两位老人，与“在家吃饭”相符。"}], "explanations": {"地铁": "语义：地铁不能在家吃饭。", "花盆": "语义：花盆不能在家吃饭。", "饭店": "搭配：“在家吃饭”的主语应是人，“饭店”不搭配这个动作。", "二老": "指两位老人，与“在家吃饭”相符。"}, "sentence_index": 6, "correct_answer": "二老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对刚结婚的二老感情很好。", "explanation": "这里应该用〈夫妻〉。二老指父母或年长的老人，不用于刚结婚的年轻夫妻。"}, {"text": "我们公司新来的两位二老很努力。", "explanation": "这里应该用〈同事〉。二老指父母或老人，不指新来的同事。"}, {"text": "他家有三位二老。", "explanation": "这里应该用〈长辈〉。二老专指两位，不能说三位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常给二老们打电话。", "corrected_sentence": "我常给二老打电话。", "error_description": "错误在“二老”后加了“们”。“二老”本身已表示复数，不能再加“们”，应说“我常给二老打电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请一个二老来家里吃饭。", "corrected_sentence": "我们请二老来家里吃饭。", "error_description": "量词错误：“二老”本身已指两位老人，前面不用“一个”，应直接说“请二老来家里吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
