INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指父母双亲；两位老人。", "primary_collocate": null, "pronunciation": "èr lǎo", "ipa": "aɻ˥˩ lɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他陪二老出国旅行，玩了十天。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的二老每天早上一起打太极。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您二老慢走，路上请小心。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老都已经七十多岁了。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请二老到家里吃饭。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老都喜欢听京剧。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们给二老做了一桌好菜。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二老的身体，是儿女最关心的事。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的二老都住在乡下。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的二老常带孙子玩。", "target_word": "二老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指父母双亲，也指一起出现的两位老人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "语义：地铁不会出国旅行，不能被陪着去旅行。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆不会出国旅行。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“陪”的对象应是人，“陪行李出国旅行”搭配不当。"}, {"text": "二老", "is_correct": true, "explanation": "指父母双亲，与“陪……出国旅行”相符。"}], "explanations": {"地铁": "语义：地铁不会出国旅行，不能被陪着去旅行。", "花盆": "语义：花盆不会出国旅行。", "行李": "搭配：“陪”的对象应是人，“陪行李出国旅行”搭配不当。", "二老": "指父母双亲，与“陪……出国旅行”相符。"}, "sentence_index": 0, "correct_answer": "二老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家的二老都在上学。", "explanation": "这里应该用〈孩子〉。二老指父母或两位老人，不指上学的孩子。"}, {"text": "我家门口有一只二老。", "explanation": "这里应该用〈小狗〉。二老指父母或两位老人，不能指动物。"}, {"text": "我们家的二老两岁了。", "explanation": "这里应该用〈宝宝〉。二老指父母或年长的老人，不指两岁的幼儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑不吃饭，不能享用一桌好菜。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会吃饭。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“给……做一桌好菜”的对象应是人，“冰箱”不搭配。"}, {"text": "二老", "is_correct": true, "explanation": "指父母或老人，可以享用孩子们做的一桌好菜，与句意相符。"}], "explanations": {"电脑": "语义：电脑不吃饭，不能享用一桌好菜。", "汽车": "语义：汽车不会吃饭。", "冰箱": "搭配：“给……做一桌好菜”的对象应是人，“冰箱”不搭配。", "二老": "指父母或老人，可以享用孩子们做的一桌好菜，与句意相符。"}, "sentence_index": 6, "correct_answer": "二老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对刚出生的二老很可爱。", "explanation": "这里应该用〈婴儿〉。二老指父母或年长的老人，不指刚出生的婴儿。"}, {"text": "这对新婚的二老很恩爱。", "explanation": "这里应该用〈夫妻〉。二老指父母或年长的老人，不用于新婚的年轻夫妻。"}, {"text": "邻居家的二老在幼儿园上课。", "explanation": "这里应该用〈小朋友〉。二老指父母或老人，不指在幼儿园上课的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想送二老们一件礼物。", "corrected_sentence": "我想送二老一件礼物。", "error_description": "错误在“二老”后加了“们”。“二老”本身已表示复数，不能再加“们”，应说“我想送二老一件礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想请一个二老来家里做客。", "corrected_sentence": "我想请二老来家里做客。", "error_description": "量词错误：“二老”本身已指两位老人，前面不用“一个”，应直接说“请二老来家里做客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
