INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担是用肩膀扛着东西走。", "primary_collocate": null, "pronunciation": "dān", "ipa": "tan˥˥", "syllable_count": 1, "sentences": [{"text": "他肩上担着两桶水。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农每天早上去河边担水。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时担过很多年柴。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两筐菜担到集市上去卖。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很长，他担着米走了一个小时。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这桶水太重，我一个人担不动。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前村里没有水管，大家都要去井边担水。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民担着稻草走回家。", "target_word": "担", "complexity_tier": "T3", "furigana": "nóngmín dānzhe dàocǎo zǒu huí jiā.", "sentence_source": "generated"}, {"text": "车进不去，工人们只好一趟趟地担货。", "target_word": "担", "complexity_tier": "T3", "furigana": "chē jìn bù qù, gōngrénmen zhǐ hǎo yí tàng tàng de dān huò.", "sentence_source": "generated"}, {"text": "孩子们跟着爸爸担着空桶去河边。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担着", "label": "体标（着）"}, {"form": "担了", "label": "体标（了）"}, {"form": "担过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "用肩膀挑扛东西行走（担水、担柴）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88771, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "担", "is_correct": true, "explanation": "正确答案：担（dān），指用肩膀挑扛东西。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dān（第一声）声调不同，意思是胆子。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋。"}, {"text": "摊", "is_correct": false, "explanation": "tān 与 dān 声母不同（t／d），意思是摊开、摊位。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dān 韵母不同（-ang／-an），意思是担任、正在。"}], "explanations": {"担": "正确答案：担（dān），指用肩膀挑扛东西。", "胆": "dǎn（第三声）与 dān（第一声）声调不同，意思是胆子。", "蛋": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋。", "摊": "tān 与 dān 声母不同（t／d），意思是摊开、摊位。", "当": "dāng 与 dān 韵母不同（-ang／-an），意思是担任、正在。"}, "sentence_index": null, "correct_answer": "担"}, "level_3": {"options": [{"text": "担", "is_correct": true, "explanation": "正确。“担着”指用肩膀挑着两桶水，符合句意。"}, {"text": "拎", "is_correct": false, "explanation": "搭配：“拎”是用手提，不说“肩上拎着”。"}, {"text": "抬", "is_correct": false, "explanation": "配价：“抬”通常需要两人或借助工具，单人“肩上抬着两桶水”不通。"}, {"text": "摇", "is_correct": false, "explanation": "语义：“摇”不是搬运动作，句子意思不通。"}], "explanations": {"担": "正确。“担着”指用肩膀挑着两桶水，符合句意。", "拎": "搭配：“拎”是用手提，不说“肩上拎着”。", "抬": "配价：“抬”通常需要两人或借助工具，单人“肩上抬着两桶水”不通。", "摇": "语义：“摇”不是搬运动作，句子意思不通。"}, "sentence_index": 0, "correct_answer": "担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手担着两筐菜去集市卖。", "explanation": "这里应该用〈拎〉。担需要用肩膀或扁担挑扛，用手提的东西要说〈拎〉。"}, {"text": "他用小推车担着两筐菜去集市卖。", "explanation": "这里应该用〈推〉。担是用肩膀挑扛，用车运的东西要说〈推〉。"}, {"text": "他把这个消息担给了所有的村民。", "explanation": "这里应该用〈告诉〉。担只用于用肩挑东西或承担责任、后果，传递消息要说〈告诉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88771, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "担", "is_correct": true, "explanation": "正确答案：担（dān），指用肩膀挑扛东西。"}, {"text": "淡", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是味道淡、颜色浅。"}, {"text": "班", "is_correct": false, "explanation": "bān 与 dān 声母不同（b／d），意思是班级。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dān 只差韵尾鼻音（-ang／-an），意思是担任、正在。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 dān 声母不同（g／d），意思是干燥。"}], "explanations": {"担": "正确答案：担（dān），指用肩膀挑扛东西。", "淡": "dàn（第四声）与 dān（第一声）声调不同，意思是味道淡、颜色浅。", "班": "bān 与 dān 声母不同（b／d），意思是班级。", "当": "dāng 与 dān 只差韵尾鼻音（-ang／-an），意思是担任、正在。", "干": "gān 与 dān 声母不同（g／d），意思是干燥。"}, "sentence_index": null, "correct_answer": "担"}, "level_3": {"options": [{"text": "担", "is_correct": true, "explanation": "正确。“担水”指用扁担挑水，与“去井边”的语境相合。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍水”是拍打水面，与去井边取水的语境不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗水”不是常用搭配，句子说的是取水。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱水”不说，抱的对象一般是人或成件的东西。"}], "explanations": {"担": "正确。“担水”指用扁担挑水，与“去井边”的语境相合。", "拍": "语义：“拍水”是拍打水面，与去井边取水的语境不符。", "洗": "搭配：“洗水”不是常用搭配，句子说的是取水。", "抱": "搭配：“抱水”不说，抱的对象一般是人或成件的东西。"}, "sentence_index": 6, "correct_answer": "担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈担着一束鲜花走进了家门。", "explanation": "这里应该用〈捧〉。担用于肩挑重物，双手拿着的花要说〈捧〉。"}, {"text": "她担着孩子走了很远的路。", "explanation": "这里应该用〈抱〉。担是用肩膀挑扛东西，抱孩子要说〈抱〉。"}, {"text": "奶奶担着一碗热汤慢慢走过来。", "explanation": "这里应该用〈端〉。担用于肩挑，碗在手中要说〈端〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把两根水担回了家。", "corrected_sentence": "他把两桶水担回了家。", "error_description": "错误：量词用“根”，正确应为“桶”。“根”用于细长的东西，水要用“桶”计量，应说“两桶水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没把水担回了家。", "corrected_sentence": "他没把水担回家。", "error_description": "错误：“没”与“了”不能同用。“没”表示未发生，句末不能再加“了”，应说“他没把水担回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
