INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "承担（责任、风险、后果等）。", "primary_collocate": null, "pronunciation": "dān", "ipa": "tan˥˥", "syllable_count": 1, "sentences": [{"text": "这件事出了问题，我来担责任。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕担风险，决定自己开公司。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错是我犯的，后果我一个人担。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作出了错，经理担了全部责任。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的责任，我可担不起。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的学费，爸爸一个人担着。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心去做，出了事我替你担。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要担一定的风险。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有的责任都担了下来。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕，有问题大家一起担。", "target_word": "担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担着", "label": "体标（着）"}, {"form": "担了", "label": "体标（了）"}, {"form": "担起", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "承担责任、风险、后果等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "担", "is_correct": true, "explanation": "正确答案：担（dān），指承担责任。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dān（第一声）声调不同，意思是胆子。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋。"}, {"text": "摊", "is_correct": false, "explanation": "tān 与 dān 声母不同（t／d），意思是摊开、摊位。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dān 韵母不同（-ang／-an），意思是担任、正在。"}], "explanations": {"担": "正确答案：担（dān），指承担责任。", "胆": "dǎn（第三声）与 dān（第一声）声调不同，意思是胆子。", "蛋": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋。", "摊": "tān 与 dān 声母不同（t／d），意思是摊开、摊位。", "当": "dāng 与 dān 韵母不同（-ang／-an），意思是担任、正在。"}, "sentence_index": null, "correct_answer": "担"}, "level_3": {"options": [{"text": "担", "is_correct": true, "explanation": "正确。“担”表示承担，与“我来”相合，符合句意。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是推卸，与前句“我来”的承担意思相反。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是逃避，与“我来”承担的意思相反。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能搭配“责任”，句子语义不通。"}], "explanations": {"担": "正确。“担”表示承担，与“我来”相合，符合句意。", "推": "语义：“推”是推卸，与前句“我来”的承担意思相反。", "躲": "语义：“躲”是逃避，与“我来”承担的意思相反。", "洗": "搭配：“洗”不能搭配“责任”，句子语义不通。"}, "sentence_index": 0, "correct_answer": "担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他担了这次比赛的冠军。", "explanation": "这里应该用〈获得〉。担用于责任、风险、后果，奖项和荣誉要说〈获得〉。"}, {"text": "她担了一双明亮的眼睛。", "explanation": "这里应该用〈拥有〉。担用于承担责任、后果，人的身体特征要说〈拥有〉。"}, {"text": "大家都担这份快乐。", "explanation": "这里应该用〈享受〉。担用于责任、风险、后果，快乐要说〈享受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88772, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "担", "is_correct": true, "explanation": "正确答案：担（dān），指承担责任。"}, {"text": "淡", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是味道淡、颜色浅。"}, {"text": "班", "is_correct": false, "explanation": "bān 与 dān 声母不同（b／d），意思是班级。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dān 只差韵尾鼻音（-ang／-an），意思是担任、正在。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 dān 声母不同（g／d），意思是干燥。"}], "explanations": {"担": "正确答案：担（dān），指承担责任。", "淡": "dàn（第四声）与 dān（第一声）声调不同，意思是味道淡、颜色浅。", "班": "bān 与 dān 声母不同（b／d），意思是班级。", "当": "dāng 与 dān 只差韵尾鼻音（-ang／-an），意思是担任、正在。", "干": "gān 与 dān 声母不同（g／d），意思是干燥。"}, "sentence_index": null, "correct_answer": "担"}, "level_3": {"options": [{"text": "担", "is_correct": true, "explanation": "正确。“我替你担”表示替对方承担后果，符合句意。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是逃避，与“替你”承担的意思相反。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”不能搭配“出了事”，句子说的是承担后果。"}, {"text": "捡", "is_correct": false, "explanation": "搭配：“捡”指拾取，不能用于承担后果。"}], "explanations": {"担": "正确。“我替你担”表示替对方承担后果，符合句意。", "躲": "语义：“躲”是逃避，与“替你”承担的意思相反。", "搬": "搭配：“搬”不能搭配“出了事”，句子说的是承担后果。", "捡": "搭配：“捡”指拾取，不能用于承担后果。"}, "sentence_index": 6, "correct_answer": "担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师正在担他的进步。", "explanation": "这里应该用〈表扬〉。担用于责任、风险、后果，称赞别人的进步要说〈表扬〉。"}, {"text": "他很努力，终于担上了大学。", "explanation": "这里应该用〈考上〉。担用于责任、风险、后果，考取学校要说〈考上〉。"}, {"text": "妈妈一直担我的学习。", "explanation": "这里应该用〈支持〉。担用于责任或后果，不用于支持他人的学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔损失，最后把他一个人担了。", "corrected_sentence": "这笔损失，最后由他一个人担了。", "error_description": "错误：不能用“把”引出承担者，应用“由”。正确说法是“最后由他一个人担了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个后果，我们大家都要担起下来。", "corrected_sentence": "这个后果，我们大家都要担下来。", "error_description": "错误：趋向补语重复。“起”与“下来”都是补语，二者不能同时出现在动词后面。正确说法是“担下来”，去掉“起”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
