INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亦作是也可以这样写。", "primary_collocate": null, "pronunciation": "yì zuò", "ipa": "i˥˩ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "“叮咛”亦作“丁宁”，两种写法都可以。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“吩咐”亦作“分付”，多见于旧书。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“号啕”亦作“嚎啕”，这样写也对。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“凑合”亦作“凑和”，意思没有变化。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“嘟囔”亦作“嘟哝”，两种写法都常见。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“蹒跚”亦作“盘跚”，指走路慢而不稳。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“暗淡”亦作“黯淡”，老师说都可以用。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“糟蹋”亦作“糟踏”，都是浪费的意思。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“按语”亦作“案语”，书里两种写法都有。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“推诿”亦作“推委”，意思是不愿负责。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "说明某个词也可以这样写，列出可用的异体写法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 咛 (Zipf 1.8)','sentence 5 above tier T3: contains vocabulary far above tier T3: 跚 (Zipf 1.18)']::text[], 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88773, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦作", "is_correct": true, "explanation": "亦作：也写作，是正确答案。"}, {"text": "移作", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是移作他用。"}, {"text": "一座", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一座，如“一座山”。"}, {"text": "以作", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用作、当作。"}], "explanations": {"亦作": "亦作：也写作，是正确答案。", "移作": "yí（第二声）与 yì（第四声）声调不同，意思是移作他用。", "一座": "yī（第一声）与 yì（第四声）声调不同，意思是一座，如“一座山”。", "以作": "yǐ（第三声）与 yì（第四声）声调不同，意思是用作、当作。"}, "sentence_index": null, "correct_answer": "亦作"}, "level_3": {"options": [{"text": "亦作", "is_correct": true, "explanation": "正确：“亦作”表示也写作，“叮咛”亦作“丁宁”。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：“拆分”是把整体分开，不能用来连接两个词形。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示对立，与“两种写法都可以”相冲突。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”需要对比的对象，不能直接连接两个词形。"}], "explanations": {"亦作": "正确：“亦作”表示也写作，“叮咛”亦作“丁宁”。", "拆分": "语义：“拆分”是把整体分开，不能用来连接两个词形。", "反对": "语义：“反对”表示对立，与“两种写法都可以”相冲突。", "比较": "搭配：“比较”需要对比的对象，不能直接连接两个词形。"}, "sentence_index": 0, "correct_answer": "亦作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他亦作老师，常给学生讲课。", "explanation": "这里的“亦作”表示“也当作”，指当成某种身份，不是“也写作”。这个意思不能用来说明词的写法。"}, {"text": "这只鸟亦作“喜鹊”，很常见。", "explanation": "这里应该用〈又称〉。“亦作”只用于说明词的另一种写法，不能用来说动物的另一个名字。"}, {"text": "这次比赛，他亦作裁判，维持秩序。", "explanation": "这里应该用〈也担任〉。“亦作”只用于说明词的另一种写法，不能用来说担任裁判这类职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亦作", "is_correct": true, "explanation": "正确：“亦作”表示也写作，“暗淡”亦作“黯淡”。"}, {"text": "超过", "is_correct": false, "explanation": "语义：“超过”表示程度更高，与“老师说都可以用”不合。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”用于具体物件，不能用来拆分两个词形。"}, {"text": "分离", "is_correct": false, "explanation": "语义：“分离”表示分开，与“都可以用”不符。"}], "explanations": {"亦作": "正确：“亦作”表示也写作，“暗淡”亦作“黯淡”。", "超过": "语义：“超过”表示程度更高，与“老师说都可以用”不合。", "拆开": "搭配：“拆开”用于具体物件，不能用来拆分两个词形。", "分离": "语义：“分离”表示分开，与“都可以用”不符。"}, "sentence_index": 6, "correct_answer": "亦作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山亦作“泰山”，很有名。", "explanation": "这里应该用〈又名〉。“亦作”只用于说明词的另一种写法，不能用来说山的另一个名字。"}, {"text": "这块布亦作桌布使用。", "explanation": "这里的“亦作”表示“也当作”，指把某物用作别的用途，不是“也写作”。此处应说〈也用作〉。"}, {"text": "这个问题亦作难题，大家都很头疼。", "explanation": "这里的“亦作”表示“也看作”，指把某事物看作某种性质，不是“也写作”。此处应说〈也看作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
