INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "也写作；引出同一个词的另一种写法。", "primary_collocate": null, "pronunciation": "yì zuò", "ipa": "i˥˩ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "“交代”亦作“交待”，意思一样。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "词典里说，“唯一”亦作“惟一”。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“笔画”亦作“笔划”，两种写法都对。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“糊涂”亦作“胡涂”，不过现在很少用。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“作料”亦作“佐料”，指做菜用的调味品。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，“含糊”亦作“含胡”。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“唯独”亦作“惟独”，用法完全相同。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“账目”亦作“帐目”，旧书里常这样写。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“淡泊”亦作“澹泊”。老师说这是另一种写法。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“唯有”亦作“惟有”，常用在书面语里。", "target_word": "亦作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "词典或书面注释中，引出同一个词的另一种写法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88774, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦作", "is_correct": true, "explanation": "亦作：也写作，是正确答案。"}, {"text": "遗作", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是遗留下来的作品。"}, {"text": "一座", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一座，如“一座山”。"}, {"text": "以作", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用作、当作。"}], "explanations": {"亦作": "亦作：也写作，是正确答案。", "遗作": "yí（第二声）与 yì（第四声）声调不同，意思是遗留下来的作品。", "一座": "yī（第一声）与 yì（第四声）声调不同，意思是一座，如“一座山”。", "以作": "yǐ（第三声）与 yì（第四声）声调不同，意思是用作、当作。"}, "sentence_index": null, "correct_answer": "亦作"}, "level_3": {"options": [{"text": "亦作", "is_correct": true, "explanation": "正确：“亦作”表示也写作，“交代”亦作“交待”。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：“拆分”是把整体分开，不能用来连接两个词形。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示对立，与“意思一样”相矛盾。"}, {"text": "超过", "is_correct": false, "explanation": "语义：“超过”表示数量或程度更高，与“意思一样”不符。"}], "explanations": {"亦作": "正确：“亦作”表示也写作，“交代”亦作“交待”。", "拆分": "语义：“拆分”是把整体分开，不能用来连接两个词形。", "反对": "语义：“反对”表示对立，与“意思一样”相矛盾。", "超过": "语义：“超过”表示数量或程度更高，与“意思一样”不符。"}, "sentence_index": 0, "correct_answer": "亦作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书亦作教材使用，学生们都很喜欢。", "explanation": "这里的“亦作”表示“也当作”，指把某物用作别的用途，不是“也写作”。这个意思不能用来说明词的写法。"}, {"text": "这种植物亦作“水仙”，花开得很香。", "explanation": "这里应该用〈又称〉。“亦作”只用于说明同一个词的另一种写法，不能用来说事物的另一个名字。"}, {"text": "我昨天亦作了一份作业。", "explanation": "这里应该用〈做〉。“亦作”表示“也写作”，不能用来说“做作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亦作", "is_correct": true, "explanation": "正确：“亦作”表示也写作，“唯独”亦作“惟独”。"}, {"text": "区别", "is_correct": false, "explanation": "语义：“区别”表示不同，与“用法完全相同”相矛盾。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”用于具体物件，不能用来拆分两个词形。"}, {"text": "分离", "is_correct": false, "explanation": "语义：“分离”表示分开，与“用法完全相同”不符。"}], "explanations": {"亦作": "正确：“亦作”表示也写作，“唯独”亦作“惟独”。", "区别": "语义：“区别”表示不同，与“用法完全相同”相矛盾。", "拆开": "搭配：“拆开”用于具体物件，不能用来拆分两个词形。", "分离": "语义：“分离”表示分开，与“用法完全相同”不符。"}, "sentence_index": 6, "correct_answer": "亦作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市亦作“古都”，游客很多。", "explanation": "这里应该用〈又称〉。“亦作”只用于说明词的另一种写法，不能用来说城市的另一个名字。"}, {"text": "他亦作班长，管理班级。", "explanation": "这里的“亦作”表示“也担任”，指担任某种职务，不是“也写作”。此处应说〈也担任〉。"}, {"text": "这件事亦作小事，不用担心。", "explanation": "这里的“亦作”表示“也看作”，指把事情看作某种性质，不是“也写作”。此处应说〈也看作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
