INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88775, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没了是原来有的东西,现在没有了。", "primary_collocate": null, "pronunciation": "méi le", "ipa": "mei˧˥ lɤ", "syllable_count": 2, "sentences": [{"text": "我想喝牛奶，可是家里的牛奶没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭没了，我们再做一点吧。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的卫生纸昨天就没了，只能用纸巾。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面包很好吃，下午四点就没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔里的墨水没了，请借我一支笔。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的苹果早就没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱没了，我们不能再买东西了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书已经卖完，店里没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖没了，今天不能做蛋糕。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤没了，要不要再来一碗？", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有了", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "原来有的东西用完或卖完，现在已经没有了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88775, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：没了 méi le，表示原有的东西用完或卖完，现在已经没有了。"}, {"text": "美了", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）只差声调，意思是变美。"}, {"text": "赔了", "is_correct": false, "explanation": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是亏了钱。"}, {"text": "肥了", "is_correct": false, "explanation": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}], "explanations": {"没了": "正确：没了 méi le，表示原有的东西用完或卖完，现在已经没有了。", "美了": "měi（第三声）与 méi（第二声）只差声调，意思是变美。", "赔了": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是亏了钱。", "肥了": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}, "sentence_index": null, "correct_answer": "没了"}, "level_3": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：“没了”表示牛奶已经用完，与“可是”的转折相合。"}, {"text": "哭了", "is_correct": false, "explanation": "语义：牛奶不会哭，句意不通。"}, {"text": "提高了", "is_correct": false, "explanation": "搭配：“提高”说水平、质量，不用来说牛奶的数量。"}, {"text": "睡着了", "is_correct": false, "explanation": "语义：牛奶不会睡觉，句意不通。"}], "explanations": {"没了": "正确：“没了”表示牛奶已经用完，与“可是”的转折相合。", "哭了": "语义：牛奶不会哭，句意不通。", "提高了": "搭配：“提高”说水平、质量，不用来说牛奶的数量。", "睡着了": "语义：牛奶不会睡觉，句意不通。"}, "sentence_index": 0, "correct_answer": "没了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家从来没了汽车，出门都坐公交车。", "explanation": "这里应该用〈没有〉。没了表示原来有的东西用完或卖完，家里从来没有汽车，不能说没了。"}, {"text": "这种面包的销量比去年没了，老板很担心。", "explanation": "这里应该用〈减少〉。没了表示全部用完，销量只是下降，不能用“比去年没了”这样的说法。"}, {"text": "这家店的价格没了，比以前便宜了两成。", "explanation": "这里应该用〈降低〉。没了表示全部消失，价格只是下降，两句话矛盾，不能说没了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88775, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：没了 méi le，表示原有的东西用完或卖完，现在已经没有了。"}, {"text": "卖了", "is_correct": false, "explanation": "mài（第四声）与 méi（第二声）韵母、声调都不同，意思是把东西卖出去。"}, {"text": "陪了", "is_correct": false, "explanation": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。"}, {"text": "肥了", "is_correct": false, "explanation": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}], "explanations": {"没了": "正确：没了 méi le，表示原有的东西用完或卖完，现在已经没有了。", "卖了": "mài（第四声）与 méi（第二声）韵母、声调都不同，意思是把东西卖出去。", "陪了": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。", "肥了": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}, "sentence_index": null, "correct_answer": "没了"}, "level_3": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：“没了”表示钱已经用完，与“不能再买东西”的语境相合。"}, {"text": "多了", "is_correct": false, "explanation": "语义：钱多了与“不能再买东西”矛盾，句意不通。"}, {"text": "生病了", "is_correct": false, "explanation": "搭配：“生病”只用于人或动物，不能用于钱。"}, {"text": "醒了", "is_correct": false, "explanation": "语义：钱不会醒来，句意不通。"}], "explanations": {"没了": "正确：“没了”表示钱已经用完，与“不能再买东西”的语境相合。", "多了": "语义：钱多了与“不能再买东西”矛盾，句意不通。", "生病了": "搭配：“生病”只用于人或动物，不能用于钱。", "醒了": "语义：钱不会醒来，句意不通。"}, "sentence_index": 6, "correct_answer": "没了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这锅汤的量没了，比刚才多了一半。", "explanation": "这里应该用〈增加〉。没了表示全部用完，汤的量是在增多，两者矛盾，不能说没了。"}, {"text": "这锅汤的热度没了，比刚才更烫了。", "explanation": "这里应该用〈升温〉。没了表示原有的热度全部消失，热度是在升高，两句话矛盾，不能说没了。"}, {"text": "这首歌的力量没了，听起来比以前更有劲儿。", "explanation": "这里应该用〈增强〉。没了表示原有的东西全部消失，力量是在增强，两句话矛盾，不能说没了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
