INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汤没了了，我们就去别的店吧。", "corrected_sentence": "汤没了，我们就去别的店吧。", "error_description": "错误：“没了了”。应改为“没了”。“了”只用一次，重复的“了”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
