INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "原有的东西消失了,不再有。", "primary_collocate": null, "pronunciation": "méi le", "ipa": "mei˧˥ lɤ", "syllable_count": 2, "sentences": [{"text": "我的手机放在桌上，一转身就没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，天上的云都没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了以后，家里的笑声也没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的蛋糕怎么一会儿就没了？", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖了新楼以后，那条小河没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不哭了，疼的感觉也慢慢没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天放在这儿的钱，今天没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡醒以后，头疼没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气，好心情全没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子拆了，小时候的回忆也没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有了", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "原来存在的东西或感觉消失，不见了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
