INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：没了 méi le，表示原有的东西不见了。"}, {"text": "卖了", "is_correct": false, "explanation": "mài（第四声）与 méi（第二声）韵母、声调都不同，意思是把东西卖出去。"}, {"text": "陪了", "is_correct": false, "explanation": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。"}, {"text": "肥了", "is_correct": false, "explanation": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}], "explanations": {"没了": "正确：没了 méi le，表示原有的东西不见了。", "卖了": "mài（第四声）与 méi（第二声）韵母、声调都不同，意思是把东西卖出去。", "陪了": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。", "肥了": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}, "sentence_index": null, "correct_answer": "没了"}, "level_3": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：“没了”表示钱不见了，与“今天”的语境相合。"}, {"text": "醒了", "is_correct": false, "explanation": "语义：钱不会醒来，句意不通。"}, {"text": "生病了", "is_correct": false, "explanation": "搭配：“生病”只用于人或动物，不能用于钱。"}, {"text": "退休了", "is_correct": false, "explanation": "语义：钱不会退休，句意不通。"}], "explanations": {"没了": "正确：“没了”表示钱不见了，与“今天”的语境相合。", "醒了": "语义：钱不会醒来，句意不通。", "生病了": "搭配：“生病”只用于人或动物，不能用于钱。", "退休了": "语义：钱不会退休，句意不通。"}, "sentence_index": 6, "correct_answer": "没了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的人口没了，比去年多了一百万。", "explanation": "这里应该用〈增加〉。没了表示全部消失，人口只是增多，不能说没了。"}, {"text": "这次考试的成绩没了，我比上次进步了十分。", "explanation": "这里应该用〈提高〉。没了表示原有的东西全部消失，成绩是变好，不能说没了。"}, {"text": "这个公园的面积没了，比以前大了不少。", "explanation": "这里应该用〈扩大〉。没了表示全部消失，面积只是变大，不能说没了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一转身，桌上的饼干就不没了。", "corrected_sentence": "妈妈一转身，桌上的饼干就没了。", "error_description": "错误：“不没了”。应改为“没了”。“没”本身已表示否定，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小猫跑进巷子以后就没了了。", "corrected_sentence": "那只小猫跑进巷子以后就没了。", "error_description": "错误：“没了了”。应改为“没了”。“没了”中的“了”已经表示完成，后面不能再加一个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抓住", "is_correct": true, "explanation": "反义：抓住指握紧不放，与放手的松开相对。"}, {"text": "看", "is_correct": false, "explanation": "与放手没有反义关系，「看」是视觉动作，与松开抓着的东西无对立关系。"}, {"text": "走", "is_correct": false, "explanation": "与放手没有反义关系，「走」是移动，与松开抓着的东西无对立关系。"}, {"text": "写", "is_correct": false, "explanation": "与放手没有反义关系，「写」是书写动作，与松开抓着的东西无对立关系。"}], "correct_answer": "抓住", "explanations": {"抓住": "反义：抓住指握紧不放，与放手的松开相对。", "看": "与放手没有反义关系，「看」是视觉动作，与松开抓着的东西无对立关系。", "走": "与放手没有反义关系，「走」是移动，与松开抓着的东西无对立关系。", "写": "与放手没有反义关系，「写」是书写动作，与松开抓着的东西无对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "握紧", "is_correct": true, "explanation": "反义：握紧指抓牢不放，与松开相对。"}, {"text": "坐", "is_correct": false, "explanation": "与放手没有反义关系，「坐」是身体动作，与松开抓着的东西无对立关系。"}, {"text": "读", "is_correct": false, "explanation": "与放手没有反义关系，「读」是阅读动作，与松开抓着的东西无对立关系。"}, {"text": "跑", "is_correct": false, "explanation": "与放手没有反义关系，「跑」是移动，与松开抓着的东西无对立关系。"}], "correct_answer": "握紧", "explanations": {"握紧": "反义：握紧指抓牢不放，与松开相对。", "坐": "与放手没有反义关系，「坐」是身体动作，与松开抓着的东西无对立关系。", "读": "与放手没有反义关系，「读」是阅读动作，与松开抓着的东西无对立关系。", "跑": "与放手没有反义关系，「跑」是移动，与松开抓着的东西无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放手是把抓着的东西松开。", "primary_collocate": null, "pronunciation": "fàng shǒu", "ipa": "faŋ˥˩ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "你快放手，我的手很疼。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抓着绳子，不肯放手。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一放手，气球就飞走了。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你放手，让我把门打开。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一放手，杯子掉在地上了。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别放手，抓紧这根绳子！", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻放手，小鸟飞走了。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不放手，你就走不了。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山的时候，千万不能放手。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟放手以后，风筝飞高了。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放了手", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "松开抓着的东西（手上的动作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。放手指松开抓着的东西。"}, {"text": "防守", "is_correct": false, "explanation": "防守 fángshǒu 与 放手 fàngshǒu 只有第一个音节声调不同（第二声与第四声），意思是防守，不是松开手。"}, {"text": "反手", "is_correct": false, "explanation": "反手 fǎnshǒu 与 放手 fàngshǒu 第一个音节韵母不同（an 与 ang），声调也不同，意思是反面的手或反手击球。"}, {"text": "放走", "is_correct": false, "explanation": "放走 fàngzǒu 与 放手 fàngshǒu 第二个音节声母不同（z 与 sh），意思是让人或动物逃走。"}, {"text": "烫手", "is_correct": false, "explanation": "烫手 tàngshǒu 与 放手 fàngshǒu 第一个音节声母不同（t 与 f），意思是东西很热，摸上去烫。"}], "explanations": {"放手": "正确答案。放手指松开抓着的东西。", "防守": "防守 fángshǒu 与 放手 fàngshǒu 只有第一个音节声调不同（第二声与第四声），意思是防守，不是松开手。", "反手": "反手 fǎnshǒu 与 放手 fàngshǒu 第一个音节韵母不同（an 与 ang），声调也不同，意思是反面的手或反手击球。", "放走": "放走 fàngzǒu 与 放手 fàngshǒu 第二个音节声母不同（z 与 sh），意思是让人或动物逃走。", "烫手": "烫手 tàngshǒu 与 放手 fàngshǒu 第一个音节声母不同（t 与 f），意思是东西很热，摸上去烫。"}, "sentence_index": null, "correct_answer": "放手"}, "level_3": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。「放手」表示松开抓着的手，与「我的手很疼」的请求相符。"}, {"text": "抓紧", "is_correct": false, "explanation": "语义：「抓紧」是握得更紧，与「我的手很疼」的请求正好相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」与「我的手很疼」之间没有合理的语境联系，搭配不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与「手很疼」的请求无关，句子不通。"}], "explanations": {"放手": "正确答案。「放手」表示松开抓着的手，与「我的手很疼」的请求相符。", "抓紧": "语义：「抓紧」是握得更紧，与「我的手很疼」的请求正好相反。", "唱": "搭配：「唱」与「我的手很疼」之间没有合理的语境联系，搭配不通。", "吃": "语义：「吃」与「手很疼」的请求无关，句子不通。"}, "sentence_index": 0, "correct_answer": "放手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈应该慢慢放手，让孩子自己选择。", "explanation": "这句话的「放手」是「不再干预、让人自己去做」的意思，与这里「松开抓着的东西」的意思不同。"}, {"text": "老板对员工很放手，大家做事都很自由。", "explanation": "这句话的「放手」是「不再干预、让人自己去做」的意思，与这里「松开抓着的东西」的意思不同。"}, {"text": "领导一放手，员工就会主动做事。", "explanation": "这句话的「放手」是「不再干预、让人自己去做」的意思，与这里「松开手」的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。「放手」表示松开抓着的东西，小鸟因此飞走。"}, {"text": "关", "is_correct": false, "explanation": "语义：「关」指关闭，与「小鸟飞走」的语境不符，关上就不能让小鸟飞走。"}, {"text": "洗", "is_correct": false, "explanation": "配价：「洗」需要宾语，这里没有宾语，句子不完整。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」与「小鸟飞走」无关，句子不通。"}], "explanations": {"放手": "正确答案。「放手」表示松开抓着的东西，小鸟因此飞走。", "关": "语义：「关」指关闭，与「小鸟飞走」的语境不符，关上就不能让小鸟飞走。", "洗": "配价：「洗」需要宾语，这里没有宾语，句子不完整。", "写": "语义：「写」与「小鸟飞走」无关，句子不通。"}, "sentence_index": 6, "correct_answer": "放手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师放手让学生自己去讨论，效果很好。", "explanation": "这句话的「放手」是「不再干预、让人自己去做」的意思，与这里「松开抓着的东西」的意思不同。"}, {"text": "父母一直管着孩子，什么都不放手。", "explanation": "这句话的「放手」是「不再干预」的意思，与这里「松开手上东西」的意思不同。"}, {"text": "妈妈终于放手，让女儿独立生活。", "explanation": "这句话的「放手」是「让人自己去做」的意思，与这里「松开手」的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一放手杯子，杯子就掉在地上了。", "corrected_sentence": "他一放手，杯子就掉在地上了。", "error_description": "错误形式是「放手杯子」，正确形式是「放手」。「放手」是不带宾语的动词，表示松开手，后面不能直接接东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我轻轻了放手，鸟就飞走了。", "corrected_sentence": "我轻轻放了手，鸟就飞走了。", "error_description": "「了」位置错误。「了」应紧接在动词「放」之后，表示完成，应为「放了手」，不能放在「放手」前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "插手", "is_correct": true, "explanation": "反义：插手指参与干涉，与放手的不再干预相对。"}, {"text": "唱", "is_correct": false, "explanation": "与放手没有反义关系，「唱」是歌唱动作，与不再干预无对立关系。"}, {"text": "写", "is_correct": false, "explanation": "与放手没有反义关系，「写」是书写动作，与不再干预无对立关系。"}, {"text": "睡", "is_correct": false, "explanation": "与放手没有反义关系，「睡」是休息动作，与不再干预无对立关系。"}], "correct_answer": "插手", "explanations": {"插手": "反义：插手指参与干涉，与放手的不再干预相对。", "唱": "与放手没有反义关系，「唱」是歌唱动作，与不再干预无对立关系。", "写": "与放手没有反义关系，「写」是书写动作，与不再干预无对立关系。", "睡": "与放手没有反义关系，「睡」是休息动作，与不再干预无对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "管", "is_correct": true, "explanation": "反义：管指干预、管束，与放手的不再干预相对。"}, {"text": "坐", "is_correct": false, "explanation": "与放手没有反义关系，「坐」是身体动作，与不再干预无对立关系。"}, {"text": "读", "is_correct": false, "explanation": "与放手没有反义关系，「读」是阅读动作，与不再干预无对立关系。"}, {"text": "跑", "is_correct": false, "explanation": "与放手没有反义关系，「跑」是移动，与不再干预无对立关系。"}], "correct_answer": "管", "explanations": {"管": "反义：管指干预、管束，与放手的不再干预相对。", "坐": "与放手没有反义关系，「坐」是身体动作，与不再干预无对立关系。", "读": "与放手没有反义关系，「读」是阅读动作，与不再干预无对立关系。", "跑": "与放手没有反义关系，「跑」是移动，与不再干预无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放手是不再干预，让人自己去做。", "primary_collocate": null, "pronunciation": "fàng shǒu", "ipa": "faŋ˥˩ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子长大了，妈妈应该放手。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师放手让学生自己做实验。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要学会放手，让孩子自己选择。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理放手让新人去做这个项目。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放手去做吧，我相信你。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不放手，什么事都要自己管。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板放手以后，公司变得更好。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈终于放手，让女儿一个人去旅行。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想孩子独立，家长就得放手。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一放手，他就发现自己能做好。", "target_word": "放手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放了手", "label": "体标（了）"}], "register": "口语", "sense_fingerprint": "不再干预，让别人自己去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。放手指不再干预，让人自己去做。"}, {"text": "防守", "is_correct": false, "explanation": "防守 fángshǒu 与 放手 fàngshǒu 只有第一个音节声调不同（第二声与第四声），意思是防守。"}, {"text": "反手", "is_correct": false, "explanation": "反手 fǎnshǒu 与 放手 fàngshǒu 第一个音节韵母不同（an 与 ang），声调也不同，意思是反手击球。"}, {"text": "放走", "is_correct": false, "explanation": "放走 fàngzǒu 与 放手 fàngshǒu 第二个音节声母不同（z 与 sh），意思是让人或动物逃走。"}, {"text": "烫手", "is_correct": false, "explanation": "烫手 tàngshǒu 与 放手 fàngshǒu 第一个音节声母不同（t 与 f），意思是东西很热。"}], "explanations": {"放手": "正确答案。放手指不再干预，让人自己去做。", "防守": "防守 fángshǒu 与 放手 fàngshǒu 只有第一个音节声调不同（第二声与第四声），意思是防守。", "反手": "反手 fǎnshǒu 与 放手 fàngshǒu 第一个音节韵母不同（an 与 ang），声调也不同，意思是反手击球。", "放走": "放走 fàngzǒu 与 放手 fàngshǒu 第二个音节声母不同（z 与 sh），意思是让人或动物逃走。", "烫手": "烫手 tàngshǒu 与 放手 fàngshǒu 第一个音节声母不同（t 与 f），意思是东西很热。"}, "sentence_index": null, "correct_answer": "放手"}, "level_3": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。「放手」表示不再干预，让孩子自己做事，与「孩子长大了」相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与「孩子长大了」该让孩子独立的语境无关，句子不通。"}, {"text": "买", "is_correct": false, "explanation": "配价：「应该买」后面没有合适的宾语，句子不完整。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与「孩子长大了」的语境无关，句子不通。"}], "explanations": {"放手": "正确答案。「放手」表示不再干预，让孩子自己做事，与「孩子长大了」相符。", "唱": "语义：「唱」与「孩子长大了」该让孩子独立的语境无关，句子不通。", "买": "配价：「应该买」后面没有合适的宾语，句子不完整。", "吃": "语义：「吃」与「孩子长大了」的语境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "放手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天学生们放手，不用上课。", "explanation": "这里应该用〈放假〉。放手只表示松开或不再干预，不能用来说学校停课。"}, {"text": "天气一放手，就变好了。", "explanation": "这里应该用〈放晴〉。放手只表示松开或不再干预，不能用来说天气转好。"}, {"text": "这些树苗一放手，就很快长高了。", "explanation": "这里应该用〈生长〉。放手只表示松开或不再干预，不能用来说植物生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放手", "is_correct": true, "explanation": "正确答案。「放手」指不再干预，让下属自己做事，公司因此变好。"}, {"text": "穿", "is_correct": false, "explanation": "配价：「穿」需要宾语（如衣服），这里没有宾语，句子不完整。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」与「公司变得更好」的语境不相符，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "配价：「洗」需要宾语，这里没有宾语，句子不完整。"}], "explanations": {"放手": "正确答案。「放手」指不再干预，让下属自己做事，公司因此变好。", "穿": "配价：「穿」需要宾语（如衣服），这里没有宾语，句子不完整。", "哭": "语义：「哭」与「公司变得更好」的语境不相符，句子不通。", "洗": "配价：「洗」需要宾语，这里没有宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "放手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今晚的烟花放手了，大家都很失望。", "explanation": "这里应该用〈燃放〉。放手只表示松开或不再干预，不能用来说烟花燃放。"}, {"text": "这家超市的灯放手了，很多人都看不清。", "explanation": "这里应该用〈灭〉。放手只表示松开或不再干预，不能用来说灯熄灭。"}, {"text": "这场雨一放手，路就好走了。", "explanation": "这里应该用〈停〉。放手只表示松开或不再干预，不能用来说雨停。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母应该学会放手孩子，让孩子自己做决定。", "corrected_sentence": "父母应该学会放手，让孩子自己做决定。", "error_description": "错误形式是「放手孩子」，正确形式是「放手」。「放手」不带宾语，表示不再干预，后面不能直接接人作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板了放手以后，员工的积极性提高了。", "corrected_sentence": "老板放手以后，员工的积极性提高了。", "error_description": "「了」位置错误。「了」不能放在「放手」前面，应为「放手以后」，不能写成「了放手」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：活与死是反义词，表示有生命与没有生命的对立。"}, {"text": "站", "is_correct": false, "explanation": "“站”与“活”没有反义关系，也不在此义项中相对。"}, {"text": "读", "is_correct": false, "explanation": "“读”与“活”没有反义关系，不是此义项的对立词。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“活”没有反义关系，不是此义项的对立词。"}], "correct_answer": "死", "explanations": {"死": "正确：活与死是反义词，表示有生命与没有生命的对立。", "站": "“站”与“活”没有反义关系，也不在此义项中相对。", "读": "“读”与“活”没有反义关系，不是此义项的对立词。", "坐": "“坐”与“活”没有反义关系，不是此义项的对立词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：活与死是反义词，表示有生命与没有生命的对立。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“活”没有反义关系，不是此义项的对立词。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“活”没有反义关系，不是此义项的对立词。"}, {"text": "笑", "is_correct": false, "explanation": "“笑”与“活”没有反义关系，不是此义项的对立词。"}], "correct_answer": "死", "explanations": {"死": "正确：活与死是反义词，表示有生命与没有生命的对立。", "走": "“走”与“活”没有反义关系，不是此义项的对立词。", "写": "“写”与“活”没有反义关系，不是此义项的对立词。", "笑": "“笑”与“活”没有反义关系，不是此义项的对立词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "活是有生命,能动,能长大。", "primary_collocate": null, "pronunciation": "huó", "ipa": "xuo˧˥", "syllable_count": 1, "sentences": [{"text": "这条鱼还活着。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的小树活了。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只小鸟没有死，还活着。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只蝴蝶是活的，它在扇翅膀。", "target_word": "活", "complexity_tier": "T3", "furigana": "zhè zhī hú dié shì huó de, tā zài shān chì bǎng。", "sentence_source": "generated"}, {"text": "这棵树去年冬天没死，今年还活着。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫掉进水里，幸好还活着。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池子里的鱼都活着，一条也没死。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新种的花都活了，没有一棵死。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只乌龟很老了，但还是活的。", "target_word": "活", "complexity_tier": "T3", "furigana": "zhè zhī wū guī hěn lǎo le, dàn hái shì huó de。", "sentence_source": "generated"}, {"text": "那只受伤的鸟虽然很冷，但它是活的。", "target_word": "活", "complexity_tier": "T3", "furigana": "nà zhī shòu shāng de niǎo suī rán hěn lěng, dàn tā shì huó de。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活着", "label": "体标"}, {"form": "活过", "label": "体标"}], "register": "中性", "sense_fingerprint": "活：（动植物）有生命，没有死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "活", "is_correct": true, "explanation": "正确答案：活（huó）指有生命、能动。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huó（第二声）声调不同，意思是火。"}, {"text": "或", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是或者。"}, {"text": "祸", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}], "explanations": {"活": "正确答案：活（huó）指有生命、能动。", "火": "huǒ（第三声）与 huó（第二声）声调不同，意思是火。", "或": "huò（第四声）与 huó（第二声）声调不同，意思是或者。", "祸": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}, "sentence_index": null, "correct_answer": "活"}, "level_3": {"options": [{"text": "活", "is_correct": true, "explanation": "正确：“活着”表示仍有生命，与“还”的意思相合。"}, {"text": "死", "is_correct": false, "explanation": "语义：“死”表示没有生命，与“还”所表示的仍然存活的意思相矛盾。"}, {"text": "跑", "is_correct": false, "explanation": "语义：鱼不能“跑”，“还跑着”与这条鱼的状态不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：鱼不会“唱”，“还唱着”与这条鱼的状态不符。"}], "explanations": {"活": "正确：“活着”表示仍有生命，与“还”的意思相合。", "死": "语义：“死”表示没有生命，与“还”所表示的仍然存活的意思相矛盾。", "跑": "语义：鱼不能“跑”，“还跑着”与这条鱼的状态不符。", "唱": "语义：鱼不会“唱”，“还唱着”与这条鱼的状态不符。"}, "sentence_index": 0, "correct_answer": "活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子还活着。", "explanation": "桌子没有生命，不能说“还活着”。“活”指有生命、能动，这里应该说〈还在〉。"}, {"text": "这台冰箱已经活了三年。", "explanation": "冰箱没有生命，不能说“活了三年”。“活”指有生命、能长大，这里应该说〈用了〉。"}, {"text": "这只花瓶活过来了。", "explanation": "花瓶没有生命，不能“活过来”。“活过来”指复活，这里应该说〈修好了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "活", "is_correct": true, "explanation": "正确答案：活（huó）指有生命、能动。"}, {"text": "货", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是货物。"}, {"text": "祸", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huó（第二声）声调不同，意思是伙伴。"}], "explanations": {"活": "正确答案：活（huó）指有生命、能动。", "货": "huò（第四声）与 huó（第二声）声调不同，意思是货物。", "祸": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。", "伙": "huǒ（第三声）与 huó（第二声）声调不同，意思是伙伴。"}, "sentence_index": null, "correct_answer": "活"}, "level_3": {"options": [{"text": "活", "is_correct": true, "explanation": "正确：“都……着”表示鱼仍然活着，与“一条也没死”相合。"}, {"text": "开", "is_correct": false, "explanation": "语义：鱼不能“开”，“都开着”与池子里鱼的状态不符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：鱼不会“飞”，“都飞着”与语境完全不符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：鱼若被烧着就会死，与“一条也没死”的语境相矛盾。"}], "explanations": {"活": "正确：“都……着”表示鱼仍然活着，与“一条也没死”相合。", "开": "语义：鱼不能“开”，“都开着”与池子里鱼的状态不符。", "飞": "语义：鱼不会“飞”，“都飞着”与语境完全不符。", "烧": "语义：鱼若被烧着就会死，与“一条也没死”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只煮熟的鸡还活着。", "explanation": "煮熟的鸡已经没有生命，不能说“还活着”。“活”指有生命、能动，这里应该说〈已经死了〉。"}, {"text": "这盆塑料花活了一百年。", "explanation": "塑料花没有生命，不能说“活了一百年”。“活”指有生命、能长大，这里应该说〈存在〉。"}, {"text": "这块石头活到了一百岁。", "explanation": "石头没有生命，不能说“活到一百岁”。“活”指有生命、能长大，这里应该说〈存在〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆兰花被冻了一夜，还活了着。", "corrected_sentence": "这盆兰花被冻了一夜，还活着。", "error_description": "错误：“了”和“着”不能同时用在“活”后，“还活了着”不通。正确：“还活着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条鱼被放回水里以后，又活来了。", "corrected_sentence": "那条鱼被放回水里以后，又活过来了。", "error_description": "错误：表示恢复生命要说“活过来”，“活来了”缺少“过”，句子不通。正确：“又活过来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "正确：活与死是反义词，表示生存与死亡的对立。"}, {"text": "站", "is_correct": false, "explanation": "“站”与“活”没有反义关系，不是此义项的对立词。"}, {"text": "读", "is_correct": false, "explanation": "“读”与“活”没有反义关系，不是此义项的对立词。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“活”没有反义关系，不是此义项的对立词。"}], "correct_answer": "死", "explanations": {"死": "正确：活与死是反义词，表示生存与死亡的对立。", "站": "“站”与“活”没有反义关系，不是此义项的对立词。", "读": "“读”与“活”没有反义关系，不是此义项的对立词。", "坐": "“坐”与“活”没有反义关系，不是此义项的对立词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
