INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生存;具有生命。", "primary_collocate": null, "pronunciation": "huó", "ipa": "xuo˧˥", "syllable_count": 1, "sentences": [{"text": "人没有水活不了几天。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷活到了九十岁。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一辈子都活得很开心。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有空气，人就不能活。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人活了一百岁才去世。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼在冷水里活不了。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他病得很重，医生说他活不过今年。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想活到一百岁。", "target_word": "活", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在山里活了二十年。", "target_word": "活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要还活着，就有希望。", "target_word": "活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活着", "label": "体标"}, {"form": "活过", "label": "体标"}], "register": "中性", "sense_fingerprint": "活：生存，维持生命，可指活多久、怎样生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "活", "is_correct": true, "explanation": "正确答案：活（huó）指生存、维持生命。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huó（第二声）声调不同，意思是火。"}, {"text": "货", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是货物。"}, {"text": "祸", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}], "explanations": {"活": "正确答案：活（huó）指生存、维持生命。", "火": "huǒ（第三声）与 huó（第二声）声调不同，意思是火。", "货": "huò（第四声）与 huó（第二声）声调不同，意思是货物。", "祸": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}, "sentence_index": null, "correct_answer": "活"}, "level_3": {"options": [{"text": "活", "is_correct": true, "explanation": "正确：“活不了几天”表示生存的时间，与“没有水”的语境相合。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“没有水飞不了几天”的意思荒谬，“飞”与“没有水”的条件不搭。"}, {"text": "写", "is_correct": false, "explanation": "语义：“没有水写不了几天”荒谬，与人的生存语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“没有水唱不了几天”与生存的语境不符，句意荒谬。"}], "explanations": {"活": "正确：“活不了几天”表示生存的时间，与“没有水”的语境相合。", "飞": "语义：“没有水飞不了几天”的意思荒谬，“飞”与“没有水”的条件不搭。", "写": "语义：“没有水写不了几天”荒谬，与人的生存语境不符。", "唱": "语义：“没有水唱不了几天”与生存的语境不符，句意荒谬。"}, "sentence_index": 0, "correct_answer": "活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只杯子活到了一百岁。", "explanation": "杯子没有生命，不能说“活到一百岁”。“活”指生存、具有生命，这里应该说〈用了〉。"}, {"text": "那座桥活了一千年，还在长高。", "explanation": "桥没有生命，不能说“活了一千年”或“长高”。“活”表示生存，这里应该说〈存在〉。"}, {"text": "这台洗衣机活到了十岁。", "explanation": "洗衣机没有生命，不能说“活到十岁”。“活”表示生存，这里应该说〈用了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "活", "is_correct": true, "explanation": "正确答案：活（huó）指生存、维持生命。"}, {"text": "或", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是或者。"}, {"text": "祸", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huó（第二声）声调不同，意思是伙伴。"}], "explanations": {"活": "正确答案：活（huó）指生存、维持生命。", "或": "huò（第四声）与 huó（第二声）声调不同，意思是或者。", "祸": "huò（第四声）与 huó（第二声）声调不同，意思是灾祸。", "伙": "huǒ（第三声）与 huó（第二声）声调不同，意思是伙伴。"}, "sentence_index": null, "correct_answer": "活"}, "level_3": {"options": [{"text": "活", "is_correct": true, "explanation": "正确：“活不过今年”表示生存的期限，与“病得很重”的语境相合。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑不过今年”的意思荒谬，与“病得很重”的语境不符。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑不过今年”的意思荒谬，与“医生说”的病情判断不符。"}, {"text": "修", "is_correct": false, "explanation": "配价：“修”需要宾语，不能以“他……不过今年”的形式作谓语。"}], "explanations": {"活": "正确：“活不过今年”表示生存的期限，与“病得很重”的语境相合。", "跑": "语义：“跑不过今年”的意思荒谬，与“病得很重”的语境不符。", "笑": "语义：“笑不过今年”的意思荒谬，与“医生说”的病情判断不符。", "修": "配价：“修”需要宾语，不能以“他……不过今年”的形式作谓语。"}, "sentence_index": 6, "correct_answer": "活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张床活到了一百岁。", "explanation": "床没有生命，不能说“活到一百岁”。“活”表示生存，这里应该说〈存在〉。"}, {"text": "这把铁锅活了一百年。", "explanation": "铁锅没有生命，不能说“活了一百年”。“活”表示生存，这里应该说〈用了〉。"}, {"text": "这支铅笔活到了一百岁。", "explanation": "铅笔没有生命，不能说“活到一百岁”。“活”表示生存，这里应该说〈存在〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老人活着了九十多岁。", "corrected_sentence": "那位老人活了九十多岁。", "error_description": "错误：“着”不能用于“活了……岁”这种表示经历年数的结构，多加“着”使句子不通。正确：“活了九十多岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人住在山里，活很开心。", "corrected_sentence": "他一个人住在山里，活得很开心。", "error_description": "错误：表示状态的补语需要“得”，缺少“得”使句子不通。正确：“活得很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
