INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "任所是当官的人工作的那个地方。", "primary_collocate": null, "pronunciation": "rèn suǒ", "ipa": "ʐən⁵¹ suo²¹⁴", "syllable_count": 2, "sentences": [{"text": "这位县官一直住在任所，很少回家。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开任所，回老家看望母亲。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的知府已经赶到任所了。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，官员的家人常常不能去任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在任所里写了一封长信。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了十多天才到任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大人死在任所，百姓都很难过。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员调动后，要尽快去新的任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的任所离京城很远。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟着丈夫去了任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "官员工作所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任所", "is_correct": true, "explanation": "任所：官员任职所在的地方，与“县官”“住在”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是县官长期居住的地方，与句意不合。"}, {"text": "棺材", "is_correct": false, "explanation": "语义：人不能住在棺材里，与县官“住在”的日常居住不合。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：鱼缸是盛水的器具，不能住人，与句意矛盾。"}], "explanations": {"任所": "任所：官员任职所在的地方，与“县官”“住在”相符。", "厨房": "语义：厨房不是县官长期居住的地方，与句意不合。", "棺材": "语义：人不能住在棺材里，与县官“住在”的日常居住不合。", "鱼缸": "语义：鱼缸是盛水的器具，不能住人，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "任所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的一只任所在南方，很少有人去。", "explanation": "这里应该用〈处〉。任所是地点，量词用“处”，“只”不用于地点。"}, {"text": "他的任所是一份教书的工作。", "explanation": "这里应该用〈职务〉。任所指官员任职的地点，不能当作职务使用。"}, {"text": "他的任所是正县级。", "explanation": "这里应该用〈职级〉。任所指任职的地点，不是官员的级别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任所", "is_correct": true, "explanation": "任所：官员任职所在的地方，与“大人”“死在”的语境相符。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：人不能“死在米饭”里，与句意不合。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话是逗人笑的话，不是地方，不能说“死在笑话”。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，多指坏人的巢穴，与“大人”的敬称不合。"}], "explanations": {"任所": "任所：官员任职所在的地方，与“大人”“死在”的语境相符。", "米饭": "语义：人不能“死在米饭”里，与句意不合。", "笑话": "语义：笑话是逗人笑的话，不是地方，不能说“死在笑话”。", "老窝": "语域：“老窝”是口语，多指坏人的巢穴，与“大人”的敬称不合。"}, "sentence_index": 6, "correct_answer": "任所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每年夏天都回任所看望父母。", "explanation": "这里应该用〈老家〉。任所指官员任职的地方，回去看望父母要说老家。"}, {"text": "她在京城租了一套任所。", "explanation": "这里应该用〈住所〉。任所指官员任职的地点，不能当作租来的房子。"}, {"text": "这次的任所是三年。", "explanation": "这里应该用〈任期〉。任所指地点，表示任职的时间长度要用任期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位知府的一只任所在北方，他很少回去。", "corrected_sentence": "这位知府的任所在北方，他很少回去。", "error_description": "错误：一只任所。正确：任所。任所是地点，不能用量词“只”修饰，此处直接说“的任所”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚到很任所，还没安顿好。", "corrected_sentence": "他刚到那个任所，还没安顿好。", "error_description": "错误：很任所。正确：那个任所。“很”是程度副词，不能修饰名词“任所”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
