INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "官员任职所在的地方。", "primary_collocate": null, "pronunciation": "rèn suǒ", "ipa": "ʐən⁵¹ suo²¹⁴", "syllable_count": 2, "sentences": [{"text": "他的任所在南方的一个小县城。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员很少离开任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从京城到任所，要走一个月。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每到一处任所，都会修路建桥。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家人留在老家，一个人去了任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知县的任所就在县城。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在任所办了一所学校。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲在外地做官，我们很难去他的任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从任所寄回了一些茶叶。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说皇上要调他离开任所。", "target_word": "任所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "官员任职所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任所", "is_correct": true, "explanation": "任所：官员任职所在的地方，与“在南方的一个小县城”相符。"}, {"text": "京城", "is_correct": false, "explanation": "语义：京城是首都，不会是小县城，与句意矛盾。"}, {"text": "皇宫", "is_correct": false, "explanation": "语义：皇宫在京城，不在南方的小县城，与句意矛盾。"}, {"text": "皇陵", "is_correct": false, "explanation": "语义：皇陵是帝王的陵墓，不是官员任职的地方，与句意矛盾。"}], "explanations": {"任所": "任所：官员任职所在的地方，与“在南方的一个小县城”相符。", "京城": "语义：京城是首都，不会是小县城，与句意矛盾。", "皇宫": "语义：皇宫在京城，不在南方的小县城，与句意矛盾。", "皇陵": "语义：皇陵是帝王的陵墓，不是官员任职的地方，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "任所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他前后换过三只任所，都在南方。", "explanation": "这里应该用〈处〉。任所是地点，量词用“处”，不用“只”。"}, {"text": "他告老还乡后，回到任所养老。", "explanation": "这里应该用〈老家〉。任所指官员任职的地方，退休养老的地方不是任所。"}, {"text": "他的任所是从七品。", "explanation": "这里应该用〈职级〉。任所指任职的地点，不是官员的品级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任所", "is_correct": true, "explanation": "任所：官员任职所在的地方，与“在……办了一所学校”相符。"}, {"text": "猪圈", "is_correct": false, "explanation": "语义：猪圈是养猪的地方，不能用来办学校，与句意不合。"}, {"text": "鱼塘", "is_correct": false, "explanation": "语义：鱼塘是养鱼的水域，不能用来办学校，与句意不合。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，多指坏人的巢穴，与办学校的语境不合。"}], "explanations": {"任所": "任所：官员任职所在的地方，与“在……办了一所学校”相符。", "猪圈": "语义：猪圈是养猪的地方，不能用来办学校，与句意不合。", "鱼塘": "语义：鱼塘是养鱼的水域，不能用来办学校，与句意不合。", "老窝": "语域：“老窝”是口语，多指坏人的巢穴，与办学校的语境不合。"}, "sentence_index": 6, "correct_answer": "任所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项任所他已经完成了。", "explanation": "这里应该用〈任务〉。任所指任职的地点，不指要完成的事情。"}, {"text": "他把老家的房子卖了，在京城买了一套任所。", "explanation": "这里应该用〈住所〉。任所指官员任职的地点，不能当作买来的房子。"}, {"text": "他这次的任所是五年。", "explanation": "这里应该用〈任期〉。任所指地点，表示任职的时间长度要用任期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位官员一年后才到一只任所。", "corrected_sentence": "这位官员一年后才到任所。", "error_description": "错误：“任所”前加了“一只”。“任所”是地点，不能用“只”计量，应直接说“到任所”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被派去一只偏远的任所。", "corrected_sentence": "他被派去一处偏远的任所。", "error_description": "错误：一只任所。正确：一处任所。任所是地点，量词用“处”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
