INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "新出版或新修订的版本。", "primary_collocate": null, "pronunciation": "xīn bǎn", "ipa": "ɕin˥ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本词典出了新版。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新版的课本多了很多图片。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们买新版的教材。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新版小说下个月就能买到。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新版书的封面是蓝色的。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里还没有这本书的新版。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新版词典加了很多新词。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书的新版改了不少内容。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看过新版，比旧版清楚多了。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社明年会出新版的地图。", "target_word": "新版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "书籍、词典等新出版或修订的版本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新版", "is_correct": true, "explanation": "正确答案。「新版」指新出版的版本，与「出了」相符。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：「出了作者」不能说，「出」与「作者」不搭配。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：「盒子」不是可以「出」的出版物，句子不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：「座位」与词典的出版无关，句子不通。"}], "explanations": {"新版": "正确答案。「新版」指新出版的版本，与「出了」相符。", "作者": "搭配：「出了作者」不能说，「出」与「作者」不搭配。", "盒子": "语义：「盒子」不是可以「出」的出版物，句子不通。", "座位": "语义：「座位」与词典的出版无关，句子不通。"}, "sentence_index": 0, "correct_answer": "新版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机的新版比旧版便宜。", "explanation": "这里的「新版」指产品的新款式，不是出版物的新修订版本。"}, {"text": "新版的河流很宽，很美。", "explanation": "这里应该用〈大〉。「新版」指出版物或产品的新版本，不能修饰河流。"}, {"text": "新版的夏天很热。", "explanation": "这里应该用〈炎热〉。「新版」指出版物或产品的新版本，不能用来描述季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新版", "is_correct": true, "explanation": "正确答案。「新版」指新修订的版本，与「加了很多新词」相符。"}, {"text": "封面", "is_correct": false, "explanation": "搭配：「封面词典」说不通，「封面」不能修饰「词典」。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」与「加了很多新词」的语境无关，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色词典」说不通，且与「加了新词」的语境不符。"}], "explanations": {"新版": "正确答案。「新版」指新修订的版本，与「加了很多新词」相符。", "封面": "搭配：「封面词典」说不通，「封面」不能修饰「词典」。", "价格": "语义：「价格」与「加了很多新词」的语境无关，句子不通。", "颜色": "搭配：「颜色词典」说不通，且与「加了新词」的语境不符。"}, "sentence_index": 6, "correct_answer": "新版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款饼干的新版比旧版好吃。", "explanation": "这里的「新版」指产品的新款式，不是书籍或词典的新修订版本。"}, {"text": "这顿饭的新版很便宜。", "explanation": "这里应该用〈新菜〉。「新版」指出版或修订的版本，不能用来说一顿饭。"}, {"text": "新版的天空很蓝。", "explanation": "这里应该用〈晴朗〉。「新版」指出版物或产品的新版本，不能修饰天空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本词典下个月会新版。", "corrected_sentence": "这本词典下个月会出新版。", "error_description": "错误：「新版」是名词，不能直接作动词。应说「出新版」，即「会出新版」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套书的一只新版已经卖完了。", "corrected_sentence": "这套书的新版已经卖完了。", "error_description": "错误：「一只新版」，量词「只」只用于动物或成对物品中的一个，不能计量「新版」。正确：「这套书的新版」，去掉「一只」，直接用「新版」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
