INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88785, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "特是比别的更多、更厉害的意思。", "primary_collocate": null, "pronunciation": "tè", "ipa": "tʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "这道题特难，大家都不会做。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那座山特高，爬上去要三个小时。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们特早出门，路上一个人也没有。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间特大，住五个人没问题。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面的风特大，别出去了。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话声音特小，我听不清楚。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机特贵，我买不起。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业特多，我写了三个小时。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李特会说话，大家都喜欢他。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路特远，我们坐车去吧。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语程度副词，强调程度比一般更高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特（tè）表示比一般更厉害，程度很高。"}, {"text": "太", "is_correct": false, "explanation": "太（tài，第四声）与 tè 韵母不同（ai 对 e），意思是过于，如「太大了」。"}, {"text": "替", "is_correct": false, "explanation": "替（tì，第四声）与 tè 韵母不同（i 对 e），意思是代替。"}, {"text": "测", "is_correct": false, "explanation": "测（cè，第四声）与 tè 声母不同（c 对 t），意思是测量。"}, {"text": "色", "is_correct": false, "explanation": "色（sè，第四声）与 tè 声母不同（s 对 t），意思是颜色。"}], "explanations": {"特": "正确：特（tè）表示比一般更厉害，程度很高。", "太": "太（tài，第四声）与 tè 韵母不同（ai 对 e），意思是过于，如「太大了」。", "替": "替（tì，第四声）与 tè 韵母不同（i 对 e），意思是代替。", "测": "测（cè，第四声）与 tè 声母不同（c 对 t），意思是测量。", "色": "色（sè，第四声）与 tè 声母不同（s 对 t），意思是颜色。"}, "sentence_index": null, "correct_answer": "特"}, "level_3": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特表示程度比一般更高，符合「这道题难」的描述。"}, {"text": "被", "is_correct": false, "explanation": "搭配：「被」须用于被动句，「这道题被难」不成立。"}, {"text": "曾", "is_correct": false, "explanation": "搭配：「曾」一般不修饰形容词，不能说「曾难」。"}, {"text": "都", "is_correct": false, "explanation": "搭配：「都」表示全部，「这道题」是单一对象，不能说「这道题都难」。"}], "explanations": {"特": "正确：特表示程度比一般更高，符合「这道题难」的描述。", "被": "搭配：「被」须用于被动句，「这道题被难」不成立。", "曾": "搭配：「曾」一般不修饰形容词，不能说「曾难」。", "都": "搭配：「都」表示全部，「这道题」是单一对象，不能说「这道题都难」。"}, "sentence_index": 0, "correct_answer": "特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一个特习惯，每天都早起。", "explanation": "这里应该用〈特别的〉。特只作副词，不能直接修饰名词「习惯」，应说「特别的习惯」。"}, {"text": "今天的作业不特多，我很快就写完了。", "explanation": "这里应该用〈不太〉。特只用于肯定句，否定程度要用「不太」。"}, {"text": "这座山比那座特高，爬起来很难。", "explanation": "这里应该用〈更〉。特不能用于比较句，比较要用「更」，如「比那座更高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88785, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特（tè）表示比一般更厉害，程度很高。"}, {"text": "德", "is_correct": false, "explanation": "德（dé，第二声）与 tè 声母不同（d 对 t），意思是道德。"}, {"text": "社", "is_correct": false, "explanation": "社（shè，第四声）与 tè 声母不同（sh 对 t），意思是团体、社会。"}, {"text": "得", "is_correct": false, "explanation": "得（dé，第二声）与 tè 声母和声调不同，意思是得到。"}, {"text": "厕", "is_correct": false, "explanation": "厕（cè，第四声）与 tè 声母不同（c 对 t），意思是厕所。"}], "explanations": {"特": "正确：特（tè）表示比一般更厉害，程度很高。", "德": "德（dé，第二声）与 tè 声母不同（d 对 t），意思是道德。", "社": "社（shè，第四声）与 tè 声母不同（sh 对 t），意思是团体、社会。", "得": "得（dé，第二声）与 tè 声母和声调不同，意思是得到。", "厕": "厕（cè，第四声）与 tè 声母不同（c 对 t），意思是厕所。"}, "sentence_index": null, "correct_answer": "特"}, "level_3": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特表示程度很高，符合「手机贵，我买不起」的因果。"}, {"text": "没", "is_correct": false, "explanation": "语义：「没贵」是否定，与后半句「我买不起」的理由不协调。"}, {"text": "才", "is_correct": false, "explanation": "搭配：「才」表示仅仅、刚刚，不能直接修饰「贵」作评价。"}, {"text": "只", "is_correct": false, "explanation": "语义：「只」表示仅仅，与「我买不起」的理由不符。"}], "explanations": {"特": "正确：特表示程度很高，符合「手机贵，我买不起」的因果。", "没": "语义：「没贵」是否定，与后半句「我买不起」的理由不协调。", "才": "搭配：「才」表示仅仅、刚刚，不能直接修饰「贵」作评价。", "只": "语义：「只」表示仅仅，与「我买不起」的理由不符。"}, "sentence_index": 6, "correct_answer": "特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天特学习，成绩很好。", "explanation": "这里应该用〈经常〉。特主要修饰形容词和心理动词，一般不修饰「学习」这类动作动词，表示频率要用「经常」。"}, {"text": "这道题很特难，大家都做不出来。", "explanation": "「很」和「特」都表示程度，不能同时修饰一个形容词，应去掉「很」。"}, {"text": "这间教室特在三楼，大家都不想去。", "explanation": "这里应该用〈就〉。特主要修饰形容词和心理动词，不能修饰「在三楼」这类方位短语，应说「就在三楼」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套特的厚，冬天穿正好。", "corrected_sentence": "这件外套特厚，冬天穿正好。", "error_description": "特后面直接接形容词，中间不能加「的」，应说「特厚」，不能说「特的厚」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市大特，我们一天走不完。", "corrected_sentence": "这座城市特大，我们一天走不完。", "error_description": "特是程度副词，要放在形容词前，应说「特大」，不能说「大特」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
