INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88786, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示程度很高;特别。", "primary_collocate": null, "pronunciation": "tè", "ipa": "tʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "今天天气特好，我们去公园玩吧。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面条特好吃。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，妈妈特高兴。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我特累，早早就睡了。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得特快，一下就到终点了。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服特便宜，我买了两件。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的北京特冷，要穿厚衣服。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟特爱看书，每天都看。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人对我们特热情。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电影特有意思，你一定要看。", "target_word": "特", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语程度副词，放在形容词前表示很", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特（tè）表示很、非常，是口语程度副词。"}, {"text": "太", "is_correct": false, "explanation": "太（tài，第四声）与 tè 韵母不同（ai 对 e），意思是过于，如「太好了」。"}, {"text": "得", "is_correct": false, "explanation": "得（dé，第二声）与 tè 声母不同（d 对 t），意思是得到、获得。"}, {"text": "替", "is_correct": false, "explanation": "替（tì，第四声）与 tè 韵母不同（i 对 e），意思是代替。"}, {"text": "测", "is_correct": false, "explanation": "测（cè，第四声）与 tè 声母不同（c 对 t），意思是测量。"}], "explanations": {"特": "正确：特（tè）表示很、非常，是口语程度副词。", "太": "太（tài，第四声）与 tè 韵母不同（ai 对 e），意思是过于，如「太好了」。", "得": "得（dé，第二声）与 tè 声母不同（d 对 t），意思是得到、获得。", "替": "替（tì，第四声）与 tè 韵母不同（i 对 e），意思是代替。", "测": "测（cè，第四声）与 tè 声母不同（c 对 t），意思是测量。"}, "sentence_index": null, "correct_answer": "特"}, "level_3": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特表示很，符合「天气好、适合去公园」的语境。"}, {"text": "不", "is_correct": false, "explanation": "语义：「不好」是否定，与后半句「我们去公园玩吧」的建议相矛盾。"}, {"text": "总", "is_correct": false, "explanation": "语义：「总」表示经常、一向，与「今天」这一具体时间冲突。"}, {"text": "都", "is_correct": false, "explanation": "搭配：「都」表示全部，「天气」是单一对象，不能说「天气都好」。"}], "explanations": {"特": "正确：特表示很，符合「天气好、适合去公园」的语境。", "不": "语义：「不好」是否定，与后半句「我们去公园玩吧」的建议相矛盾。", "总": "语义：「总」表示经常、一向，与「今天」这一具体时间冲突。", "都": "搭配：「都」表示全部，「天气」是单一对象，不能说「天气都好」。"}, "sentence_index": 0, "correct_answer": "特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送了我一个特礼物，我很喜欢。", "explanation": "这里应该用〈特别的〉。特只作副词，不能直接修饰名词，「特礼物」应为「特别的礼物」。"}, {"text": "今天我不特累，还能去爬山。", "explanation": "这里应该用〈不太〉。特只用于肯定句表示程度高，否定程度要用「不太」。"}, {"text": "他是我们班特最高的学生。", "explanation": "这里应该只用〈最〉，「特」与「最」不能叠用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特（tè）表示很、非常，是口语程度副词。"}, {"text": "德", "is_correct": false, "explanation": "德（dé，第二声）与 tè 声母不同（d 对 t），意思是道德。"}, {"text": "色", "is_correct": false, "explanation": "色（sè，第四声）与 tè 声母不同（s 对 t），意思是颜色。"}, {"text": "厕", "is_correct": false, "explanation": "厕（cè，第四声）与 tè 声母不同（c 对 t），意思是厕所。"}], "explanations": {"特": "正确：特（tè）表示很、非常，是口语程度副词。", "德": "德（dé，第二声）与 tè 声母不同（d 对 t），意思是道德。", "色": "色（sè，第四声）与 tè 声母不同（s 对 t），意思是颜色。", "厕": "厕（cè，第四声）与 tè 声母不同（c 对 t），意思是厕所。"}, "sentence_index": null, "correct_answer": "特"}, "level_3": {"options": [{"text": "特", "is_correct": true, "explanation": "正确：特表示很，符合「冬天的北京冷，要穿厚衣服」的描述。"}, {"text": "没", "is_correct": false, "explanation": "语义：「没冷」是否定，与后半句「要穿厚衣服」的提醒相矛盾。"}, {"text": "被", "is_correct": false, "explanation": "搭配：「被」须用于被动句，「冬天的北京被冷」不成立。"}, {"text": "曾", "is_correct": false, "explanation": "搭配：「曾」一般不修饰形容词，不能说「曾冷」。"}], "explanations": {"特": "正确：特表示很，符合「冬天的北京冷，要穿厚衣服」的描述。", "没": "语义：「没冷」是否定，与后半句「要穿厚衣服」的提醒相矛盾。", "被": "搭配：「被」须用于被动句，「冬天的北京被冷」不成立。", "曾": "搭配：「曾」一般不修饰形容词，不能说「曾冷」。"}, "sentence_index": 6, "correct_answer": "特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天特学习，成绩很好。", "explanation": "这里应该用〈经常〉。特只修饰形容词或少数心理动词，不修饰「学习」这类动作动词，表示频率要用「经常」。"}, {"text": "这个房间比那个特大。", "explanation": "这里应该用〈更〉。特不能用于比较句，比较要用「更」，如「比那个更大」。"}, {"text": "今天很特冷，要多穿点衣服。", "explanation": "「很」和「特」都表示程度，不能同时修饰一个形容词，只用其中一个即可，如「今天特冷」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书特很有意思，我看了两遍。", "corrected_sentence": "这本书特有意思，我看了两遍。", "error_description": "「特」和「很」都是程度副词，不能连在一起用。应去掉「很」，说「特有意思」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的菜特的便宜，学生都爱去。", "corrected_sentence": "这家餐厅的菜特便宜，学生都爱去。", "error_description": "特后面直接接形容词，中间不能加「的」，应说「特便宜」，不能说「特的便宜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
