INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "作别是说再见，要走了。", "primary_collocate": null, "pronunciation": "zuò bié", "ipa": "tsuɔ˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他在车站与家人作别。", "target_word": "作别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "临走前，我向老师作别。", "target_word": "作别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在门口与朋友作别。", "target_word": "作别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈挥着手，与我们作别。", "target_word": "作别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，同学们向老师作别。", "target_word": "作别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉着朋友的手，向大家作别。", "target_word": "作别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车快开了，我只好与她作别。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向送行的人作别，上了飞机。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天快黑了，客人们起身与主人作别。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭着与奶奶作别。", "target_word": "作别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作别了", "label": "完成体"}, {"form": "作别过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "临走时向某人说再见、道别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作别", "is_correct": true, "explanation": "“作别”指临走时向人道别，与“在车站”离开家人的情境相符。"}, {"text": "相识", "is_correct": false, "explanation": "语义：“相识”指初次认识，与家人早已相熟的关系不合。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的对象是配偶，不能说与家人结婚。"}, {"text": "签名", "is_correct": false, "explanation": "搭配：“签名”需要文件或物品作对象，不能说与家人签名。"}], "explanations": {"作别": "“作别”指临走时向人道别，与“在车站”离开家人的情境相符。", "相识": "语义：“相识”指初次认识，与家人早已相熟的关系不合。", "结婚": "搭配：“结婚”的对象是配偶，不能说与家人结婚。", "签名": "搭配：“签名”需要文件或物品作对象，不能说与家人签名。"}, "sentence_index": 0, "correct_answer": "作别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一进门，就向主人作别。", "explanation": "这里应该用〈问好〉。作别指临走时向人道别，刚进门的人应说〈问好〉。"}, {"text": "一别多年，我们终于在车站作别。", "explanation": "这里应该用〈相见〉。作别表示临走时分开，久别重逢要用〈相见〉。"}, {"text": "这是我第一次来到这座城市，我向它作别。", "explanation": "这里应该用〈认识〉。作别指临走时告别，初次到一座城市应表示结识，不能说作别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作别", "is_correct": true, "explanation": "“作别”指临走时道别，与“火车快开了”的离开情境相符。"}, {"text": "相遇", "is_correct": false, "explanation": "语义：“相遇”指偶然碰见，与火车快开、要分开的情境相反。"}, {"text": "挽留", "is_correct": false, "explanation": "配价：“挽留”要带受事宾语，应说“挽留某人”，不能说“与她挽留”。"}, {"text": "迎接", "is_correct": false, "explanation": "配价：“迎接”直接带宾语，应说“迎接她”，不能说“与她迎接”；且迎接与离开的情境相反。"}], "explanations": {"作别": "“作别”指临走时道别，与“火车快开了”的离开情境相符。", "相遇": "语义：“相遇”指偶然碰见，与火车快开、要分开的情境相反。", "挽留": "配价：“挽留”要带受事宾语，应说“挽留某人”，不能说“与她挽留”。", "迎接": "配价：“迎接”直接带宾语，应说“迎接她”，不能说“与她迎接”；且迎接与离开的情境相反。"}, "sentence_index": 6, "correct_answer": "作别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他哭着向奶奶作别，不让她走。", "explanation": "这里应该用〈挽留〉。作别是告别、分开，“不让她走”要用〈挽留〉。"}, {"text": "大家作别明天的比赛，早早就来到了场馆。", "explanation": "这里应该用〈期待〉。作别是告别、离开，不能表示对未来事情的盼望。"}, {"text": "店员热情地向我们作别，还请我们进屋坐。", "explanation": "这里应该用〈接待〉。作别指临走时道别，店员招待客人时应说〈接待〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他临走时从我作别，然后离开了。", "corrected_sentence": "他临走时向我作别，然后离开了。", "error_description": "“作别”的对象要用介词“向”引出，“从”表示起点，不能用来引出道别的对象，应说“向我作别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们一个个地老师作别。", "corrected_sentence": "孩子们一个个地向老师作别。", "error_description": "错误：“作别”前漏掉了介词“向”。作别的对象要用“向”引出，正确形式是“向老师作别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
