INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告别；分手。", "primary_collocate": null, "pronunciation": "zuò bié", "ipa": "tsuɔ˥˩ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "毕业了，我们要作别校园。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他决定与过去的生活作别。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天，我们作别这座小城。", "target_word": "作别", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她作别了故乡，去北京工作。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要作别童年，走向新的生活。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他戒了烟，与坏习惯作别。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人搬走时，向住了多年的小院作别。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个夏天，我们一起作别旧时光。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两人平静地作别，各走各的路。", "target_word": "作别", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把旧衣服送人，作别了过去。", "target_word": "作别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作别了", "label": "完成体"}, {"form": "作别过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "告别某个地方、某段生活或习惯，或与人分手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作别", "is_correct": true, "explanation": "“作别”指告别、离开，与“毕业了，我们要……校园”的离开之意相符。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造，与毕业后离开校园的意思不合。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉，与“毕业了”的情境不合，校园不会因毕业被拆掉。"}, {"text": "挥手", "is_correct": false, "explanation": "配价：“挥手”是不及物动词，不能带“校园”作宾语，应说“向校园挥手”。"}], "explanations": {"作别": "“作别”指告别、离开，与“毕业了，我们要……校园”的离开之意相符。", "修建": "语义：“修建”指建造，与毕业后离开校园的意思不合。", "拆除": "语义：“拆除”指拆掉，与“毕业了”的情境不合，校园不会因毕业被拆掉。", "挥手": "配价：“挥手”是不及物动词，不能带“校园”作宾语，应说“向校园挥手”。"}, "sentence_index": 0, "correct_answer": "作别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他作别了童年的老照片，每年都翻出来看。", "explanation": "这里应该用〈保留〉。作别表示告别、离开，不能用来说留存某物。"}, {"text": "今天，我们作别了新的生活。", "explanation": "这里应该用〈迎来〉。作别表示告别、离开，不能表示开始。"}, {"text": "他刚到新公司，就作别了很多同事。", "explanation": "这里应该用〈结识〉。作别指告别、分开，刚到新公司的人不能说作别同事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作别", "is_correct": true, "explanation": "“作别”指离开、告别，与“老人搬走时”的情境相符。"}, {"text": "占据", "is_correct": false, "explanation": "语义：“占据”指占有，与“搬走”的离开之意相反。"}, {"text": "装修", "is_correct": false, "explanation": "配价：“装修”直接带宾语，不能用“向”引出“小院”。"}, {"text": "扩建", "is_correct": false, "explanation": "语义：“扩建”指扩大房屋，与搬走后不再居住的情况不合。"}], "explanations": {"作别": "“作别”指离开、告别，与“老人搬走时”的情境相符。", "占据": "语义：“占据”指占有，与“搬走”的离开之意相反。", "装修": "配价：“装修”直接带宾语，不能用“向”引出“小院”。", "扩建": "语义：“扩建”指扩大房屋，与搬走后不再居住的情况不合。"}, "sentence_index": 6, "correct_answer": "作别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们向他作别，请他继续留下。", "explanation": "这里应该用〈挽留〉。作别是告别、分开，要让人留下时应说〈挽留〉。"}, {"text": "他刚搬进新家，就作别了这间屋子。", "explanation": "这里应该用〈住进〉。作别表示告别、离开某地，刚搬进来不能说作别。"}, {"text": "他作别了跑步的好习惯，从此每天都去跑步。", "explanation": "这里应该用〈养成〉。作别表示告别、放下，每天坚持跑步应说〈养成〉习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于作别着小镇，搬到了南方。", "corrected_sentence": "她终于作别了小镇，搬到了南方。", "error_description": "“作别”表示一次性完成的离开，不能用表示持续的“着”，应说“作别了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于作别着过去的烦恼。", "corrected_sentence": "他终于作别了过去的烦恼。", "error_description": "“作别”表示一次性完成的动作，不能用“着”表示持续，应说“作别了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
