INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "普通话是全国人都能听懂的说话方式。", "primary_collocate": null, "pronunciation": "pǔ tōng huà", "ipa": "pʰu˨˩ tʰʊŋ˥ xua˥˩", "syllable_count": 3, "sentences": [{"text": "他是南方人，但会说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的家乡话不一样，所以说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地客人听不懂方言，我就说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在火车上，大家都说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用普通话问路，大家都听懂了。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不会说普通话，孩子来帮忙。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的人用普通话交流。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说普通话，全国人都听得懂。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们要多说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说普通话，我听不懂方言。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "各地人用来互相交流的通用说话方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通话", "is_correct": true, "explanation": "普通话是全国人都能听懂的说话方式，南方人也能说，与句意相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“会说”搭配语言，钢琴要说“会弹”。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能用“说”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是唱的，不是说的。"}], "explanations": {"普通话": "普通话是全国人都能听懂的说话方式，南方人也能说，与句意相符。", "钢琴": "搭配：“会说”搭配语言，钢琴要说“会弹”。", "数学": "语义：数学是学科，不能用“说”。", "歌曲": "语义：歌曲是唱的，不是说的。"}, "sentence_index": 0, "correct_answer": "普通话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在火车上，大家都说一个普通话。", "explanation": "这里应该用〈门〉或〈种〉。语言的量词是“门”“种”，不能用“个”。"}, {"text": "在火车上，他说话带着很重的普通话。", "explanation": "这里应该用〈口音〉。说话带有很重的是口音，普通话是标准语，没有轻重之分。"}, {"text": "在火车上，大家都说普通话，外地人一句也听不懂。", "explanation": "这里应该用〈方言〉。普通话是全国人都能听懂的说话方式，外地人听不懂的是方言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通话", "is_correct": true, "explanation": "普通话是各地人互相交流的通用说话方式，用来交流正合句意。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不是交流的工具。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头不能用来交流。"}, {"text": "小提琴", "is_correct": false, "explanation": "搭配：“用……交流”的工具是语言或文字，小提琴只用来演奏。"}], "explanations": {"普通话": "普通话是各地人互相交流的通用说话方式，用来交流正合句意。", "面粉": "语义：面粉不是交流的工具。", "砖头": "语义：砖头不能用来交流。", "小提琴": "搭配：“用……交流”的工具是语言或文字，小提琴只用来演奏。"}, "sentence_index": 6, "correct_answer": "普通话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种普通话只有本村的人才听得懂，外地人一头雾水。", "explanation": "这里应该用〈方言〉。只有本地人听得懂、外地人听不懂，是方言的特点；普通话是全国人都能听懂的说话方式。"}, {"text": "他这套普通话只有同行听得懂，外行人全都听不懂。", "explanation": "这里应该用〈行话〉。只有同行听得懂、外行听不懂，是行话的特点；普通话是全国人都能听懂的。"}, {"text": "这篇古文是用普通话写的，现代人很难读懂。", "explanation": "这里应该用〈文言〉。古文是用文言写的，普通话是全国人都能听懂的说话方式，不是古文的书面语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用这个普通话交流很顺利。", "corrected_sentence": "他们用普通话交流很顺利。", "error_description": "错误：“这个普通话”，量词“个”不能修饰“普通话”。正确：“用普通话”，去掉多余的“这个”，其余不变。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前学过一个普通话。", "corrected_sentence": "我以前学过普通话。", "error_description": "错误：“学过一个普通话”，量词“个”不能修饰“普通话”。正确：“学过普通话”，去掉多余的数量词，直接说“普通话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
