INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代汉民族共同语，以北京语音为标准音。", "primary_collocate": null, "pronunciation": "pǔ tōng huà", "ipa": "pʰu˨˩ tʰʊŋ˥ xua˥˩", "syllable_count": 3, "sentences": [{"text": "普通话以北京语音为标准音。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学校学习普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用普通话上课。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的新闻用普通话播报。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通话有四个声调。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学普通话要先学拼音。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的普通话说得很标准。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求学生说普通话。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通话的发音以北京语音为准。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了普通话水平考试。", "target_word": "普通话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以北京语音为标准音的现代汉民族共同语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通话", "is_correct": true, "explanation": "普通话以北京语音为标准音，正是定义中的全民共同语，句意相符。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言各地不同，没有统一的标准音，不能说“方言以北京语音为标准音”。"}, {"text": "英语", "is_correct": false, "explanation": "语义：英语是另一种语言，它的标准音不以北京语音为准。"}, {"text": "大白话", "is_correct": false, "explanation": "语义：“大白话”指通俗易懂的话，不是一种有标准音的语言，不能说它“以北京语音为标准音”。"}], "explanations": {"普通话": "普通话以北京语音为标准音，正是定义中的全民共同语，句意相符。", "方言": "语义：方言各地不同，没有统一的标准音，不能说“方言以北京语音为标准音”。", "英语": "语义：英语是另一种语言，它的标准音不以北京语音为准。", "大白话": "语义：“大白话”指通俗易懂的话，不是一种有标准音的语言，不能说它“以北京语音为标准音”。"}, "sentence_index": 0, "correct_answer": "普通话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话带着很重的普通话。", "explanation": "这里应该用〈口音〉。普通话是标准语，本身没有轻重之分，说话的口音才会“带着很重的”。"}, {"text": "我会说一个普通话。", "explanation": "这里量词用错了：〈个〉不能修饰普通话。普通话是语言，应该用〈门〉或〈种〉。"}, {"text": "我会说一把普通话。", "explanation": "这里量词用错了：〈把〉不能修饰普通话。普通话是语言，应该用〈门〉或〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通话", "is_correct": true, "explanation": "普通话指标准语言，可以“说得很标准”，符合句意。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“说得很标准”用于语言，口音不能这样“说”。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是唱出来的，不能“说得很标准”。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是写字的艺术，与“说”没有关系。"}], "explanations": {"普通话": "普通话指标准语言，可以“说得很标准”，符合句意。", "口音": "搭配：“说得很标准”用于语言，口音不能这样“说”。", "歌声": "语义：歌声是唱出来的，不能“说得很标准”。", "书法": "语义：书法是写字的艺术，与“说”没有关系。"}, "sentence_index": 6, "correct_answer": "普通话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "普通话有很多方言，各地的人说的都不一样。", "explanation": "这里应该用〈汉语〉。普通话是标准语，本身没有方言；“汉语有很多方言”是对的，把普通话说成有方言，就用错了它的性质。"}, {"text": "普通话以上海话的语音为标准音。", "explanation": "这里把标准音的依据弄错了。普通话以〈北京语音〉为标准音，不是上海话。"}, {"text": "普通话只是某个地区的土话，各地的人都要学它。", "explanation": "这里应该用〈共同语〉。普通话是全国共同语，不是某个地区的土话；把它说成地方话，就用错了它的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爷爷的一个普通话说得很流利。", "corrected_sentence": "我爷爷的普通话说得很流利。", "error_description": "错误：“的一个普通话”，量词“个”不能修饰“普通话”。正确：“的普通话”，去掉多余的数量词，其余不变。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一个普通话学得很好。", "corrected_sentence": "他把普通话学得很好。", "error_description": "错误：“一个普通话”，量词“个”不能修饰“普通话”。正确：“普通话”，去掉数量词，其余不变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与两人感情好坏没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大形容身材或事物的体积，与“要好”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋形容做事认真努力，与“要好”描述的感情关系无关。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。", "明亮": "明亮形容光线或颜色，与两人感情好坏没有反义关系。", "高大": "高大形容身材或事物的体积，与“要好”没有反义关系。", "勤奋": "勤奋形容做事认真努力，与“要好”描述的感情关系无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事专注严肃，与“要好”描述的感情关系无关。"}, {"text": "宽大", "is_correct": false, "explanation": "宽大形容空间或态度宽厚，与“要好”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，与“要好”没有反义关系。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。", "认真": "认真形容做事专注严肃，与“要好”描述的感情关系无关。", "宽大": "宽大形容空间或态度宽厚，与“要好”没有反义关系。", "清楚": "清楚指明白、分明，与“要好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "要好是两个人感情很好,常在一起。", "primary_collocate": null, "pronunciation": "yào hǎo", "ipa": "jau˥˩ xau˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们俩是最要好的朋友。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和小李从小就很要好。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们两个要好得像姐妹一样。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同桌很要好，天天一起回家。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩很要好，每天一起吃饭。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个要好的同学，我们住在同一个房间。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两个男孩要好极了，走到哪儿都在一起。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红和小美从小学起就要好，常在一起玩。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在班里，你和谁最要好？", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是要好的邻居，常常一起去买菜。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很要好", "label": "程度"}, {"form": "最要好", "label": "程度"}, {"form": "要好的", "label": "定语形式"}, {"form": "要好了", "label": "体标"}], "register": "通用", "sense_fingerprint": "两人感情好,常常在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“朋友”的身份相矛盾。"}, {"text": "要好", "is_correct": true, "explanation": "要好形容两人感情好、关系亲密，正好修饰“朋友”，句意通顺。"}, {"text": "敌对", "is_correct": false, "explanation": "语义：“敌对”指互相对立，与“朋友”的关系正好相反。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多形容身体或物品的坚固，不能修饰表示人际关系的“朋友”。"}], "explanations": {"陌生": "语义：“陌生”指彼此不熟悉，与“朋友”的身份相矛盾。", "要好": "要好形容两人感情好、关系亲密，正好修饰“朋友”，句意通顺。", "敌对": "语义：“敌对”指互相对立，与“朋友”的关系正好相反。", "结实": "搭配：“结实”多形容身体或物品的坚固，不能修饰表示人际关系的“朋友”。"}, "sentence_index": 0, "correct_answer": "要好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很要好。", "explanation": "这里应该用〈好用〉。好用形容物品使用方便，要好只形容两人之间的感情，不能用于电脑。"}, {"text": "他的成绩很要好。", "explanation": "这里应该用〈优秀〉。优秀形容成绩、能力等表现，要好只描述人与人之间的感情，不能形容成绩。"}, {"text": "我对这个城市很要好。", "explanation": "这里应该用〈熟悉〉。熟悉指对地方或事物了解，要好只描述两人之间的感情，不能用于城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指不热情、疏远，与“走到哪儿都在一起”的亲密情形相矛盾。"}, {"text": "要好", "is_correct": true, "explanation": "要好形容两人关系亲密，与后半句“走到哪儿都在一起”一致。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”指不依赖他人，与“走到哪儿都在一起”的状态不符。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”多形容物体的硬度，不能用来形容两个男孩的关系或状态。"}], "explanations": {"冷淡": "语义：“冷淡”指不热情、疏远，与“走到哪儿都在一起”的亲密情形相矛盾。", "要好": "要好形容两人关系亲密，与后半句“走到哪儿都在一起”一致。", "独立": "语义：“独立”指不依赖他人，与“走到哪儿都在一起”的状态不符。", "坚硬": "搭配：“坚硬”多形容物体的硬度，不能用来形容两个男孩的关系或状态。"}, "sentence_index": 6, "correct_answer": "要好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很要好。", "explanation": "这里应该用〈不错〉。不错用于评价菜肴、物品的质量，要好只形容人与人之间感情深，不能形容菜。"}, {"text": "这个方案很要好。", "explanation": "这里应该用〈可行〉。可行形容方案能够实施，要好只形容两人之间的感情，不能用来形容方案。"}, {"text": "这份报告写得很要好。", "explanation": "这里应该用〈精彩〉。精彩形容内容出色、吸引人，要好只形容两人之间的感情，不能用来评价报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把隔壁的王叔叔要好，从小一起长大。", "corrected_sentence": "我和隔壁的王叔叔要好，从小一起长大。", "error_description": "“要好”表示与某人关系好，要用“和”引出对象，写作“我和隔壁的王叔叔要好”。“我把隔壁的王叔叔要好”中“把”用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她们俩要好地不得了，上课也坐在一起。", "corrected_sentence": "她们俩要好得不得了，上课也坐在一起。", "error_description": "“要好”后面的程度补语要用“得”，写作“要好得不得了”。“地”是状语的标记，不能用在补语的位置，“要好地不得了”中“地”用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
