INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88793, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "来得是比起别的来，更怎么样。", "primary_collocate": null, "pronunciation": "lái de", "ipa": "lai˧˥ tɤ", "syllable_count": 2, "sentences": [{"text": "走路去比坐车来得健康。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路比那条路来得近。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大城市的生活比小城市来得忙。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红茶比绿茶来得浓。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "亲口说比写信来得清楚。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末的公园比平时来得热闹。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他比哥哥来得聪明。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北方的冬天比南方来得冷。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试比上次来得难。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老办法比新办法来得稳。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "比较句中表示比起别的更怎么样（比…来得+形容词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88793, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来得", "is_correct": true, "explanation": "正确：来得（lái de）表示比起别的来，更怎么样。"}, {"text": "来了", "is_correct": false, "explanation": "第二音节声母不同（de 的 d 与 le 的 l），意思是“来了”（到达）。"}, {"text": "白的", "is_correct": false, "explanation": "第一音节声母不同（l 与 b），声调相同，意思是白色的。"}, {"text": "蓝的", "is_correct": false, "explanation": "第一音节韵母不同（ai 与 an），声调相同，意思是蓝色的。"}, {"text": "来个", "is_correct": false, "explanation": "第二音节声母不同（d 与 g），意思是“来个”（口语中的量词用法）。"}], "explanations": {"来得": "正确：来得（lái de）表示比起别的来，更怎么样。", "来了": "第二音节声母不同（de 的 d 与 le 的 l），意思是“来了”（到达）。", "白的": "第一音节声母不同（l 与 b），声调相同，意思是白色的。", "蓝的": "第一音节韵母不同（ai 与 an），声调相同，意思是蓝色的。", "来个": "第二音节声母不同（d 与 g），意思是“来个”（口语中的量词用法）。"}, "sentence_index": null, "correct_answer": "来得"}, "level_3": {"options": [{"text": "闹得", "is_correct": false, "explanation": "语义：“闹得”多指搞出混乱的结果，与“健康”不相容。"}, {"text": "来得", "is_correct": true, "explanation": "正确：“走路去比坐车来得健康”表示走路比坐车更健康。"}, {"text": "卖得", "is_correct": false, "explanation": "搭配：“卖得”接的是价钱、销量等，不说“卖得健康”。"}, {"text": "比得", "is_correct": false, "explanation": "配价：句中已有“比”，再用“比得”会重复比较结构，不成立。"}], "explanations": {"闹得": "语义：“闹得”多指搞出混乱的结果，与“健康”不相容。", "来得": "正确：“走路去比坐车来得健康”表示走路比坐车更健康。", "卖得": "搭配：“卖得”接的是价钱、销量等，不说“卖得健康”。", "比得": "配价：句中已有“比”，再用“比得”会重复比较结构，不成立。"}, "sentence_index": 0, "correct_answer": "来得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案来得很完整。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}, {"text": "她的裙子来得很漂亮。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}, {"text": "他听完这个消息来得很惊讶。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88793, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来得", "is_correct": true, "explanation": "正确：来得（lái de）表示比起别的来，更怎么样。"}, {"text": "来呢", "is_correct": false, "explanation": "第二音节声母不同（de 的 d 与 ne 的 n），意思是“来呢”（反问语气）。"}, {"text": "赖的", "is_correct": false, "explanation": "第一音节声调不同（第四声与第二声），意思是“赖的”。"}, {"text": "来到", "is_correct": false, "explanation": "第二音节韵母和声调不同（de 与 dào），意思是“到达某处”。"}], "explanations": {"来得": "正确：来得（lái de）表示比起别的来，更怎么样。", "来呢": "第二音节声母不同（de 的 d 与 ne 的 n），意思是“来呢”（反问语气）。", "赖的": "第一音节声调不同（第四声与第二声），意思是“赖的”。", "来到": "第二音节韵母和声调不同（de 与 dào），意思是“到达某处”。"}, "sentence_index": null, "correct_answer": "来得"}, "level_3": {"options": [{"text": "看得", "is_correct": false, "explanation": "语义：“看得”指视觉或看的结果，与“聪明”的比较无关。"}, {"text": "来得", "is_correct": true, "explanation": "正确：“他比哥哥来得聪明”表示他比哥哥更聪明。"}, {"text": "搞得", "is_correct": false, "explanation": "语义：“搞得”多指弄出某种（常为不好的）结果，不能说“比哥哥搞得聪明”。"}, {"text": "赚得", "is_correct": false, "explanation": "搭配：“赚得”接的是钱、利润等，不说“赚得聪明”。"}], "explanations": {"看得": "语义：“看得”指视觉或看的结果，与“聪明”的比较无关。", "来得": "正确：“他比哥哥来得聪明”表示他比哥哥更聪明。", "搞得": "语义：“搞得”多指弄出某种（常为不好的）结果，不能说“比哥哥搞得聪明”。", "赚得": "搭配：“赚得”接的是钱、利润等，不说“赚得聪明”。"}, "sentence_index": 6, "correct_answer": "来得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子来得很稳。", "explanation": "这里应该用〈很〉，去掉〈来得〉。来得表示与别的相比更怎样，需要比较对象。"}, {"text": "这座山来得高。", "explanation": "这里应该用〈很〉。来得表示比较，描述山的高度时要用“很”或“比”字句。"}, {"text": "这顿饭来得贵了。", "explanation": "这里应该用〈太〉。来得表示比较，单独说“来得贵了”没有比较对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅比那家来得打扫。", "corrected_sentence": "这家餐厅比那家来得干净。", "error_description": "错误：“来得”后接了动词“打扫”。“来得”后须接形容词，正确说法是“来得干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的冬天比去年来得冷的。", "corrected_sentence": "今年的冬天比去年来得冷。", "error_description": "错误：形容词“冷”后多加了“的”，“来得”后应直接接形容词。正确：“来得冷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
