INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示与别的相比更具某种性质。", "primary_collocate": null, "pronunciation": "lái de", "ipa": "lai˧˥ tɤ", "syllable_count": 2, "sentences": [{"text": "坐地铁比开车来得快。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服比那件来得舒服。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法比那个来得简单。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天的夜晚比白天来得长。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话比我的话来得有用。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自己动手做比买现成的来得便宜。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对面聊天比发短信来得亲切。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的面条比那家来得好吃。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的办法有时比年轻人的来得可靠。", "target_word": "来得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多听比多看来得有效。", "target_word": "来得", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "比较句中表示相比之下更具某种性质（比…来得+形容词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来得", "is_correct": true, "explanation": "正确：来得（lái de）表示比较句中比别的更具某种性质。"}, {"text": "来了", "is_correct": false, "explanation": "第二音节声母不同（d 与 l），意思是“来了”（到达）。"}, {"text": "白的", "is_correct": false, "explanation": "第一音节声母不同（l 与 b），声调相同，意思是白色的。"}, {"text": "蓝的", "is_correct": false, "explanation": "第一音节韵母不同（ai 与 an），声调相同，意思是蓝色的。"}, {"text": "来个", "is_correct": false, "explanation": "第二音节声母不同（d 与 g），意思是“来个”（口语中的量词用法）。"}], "explanations": {"来得": "正确：来得（lái de）表示比较句中比别的更具某种性质。", "来了": "第二音节声母不同（d 与 l），意思是“来了”（到达）。", "白的": "第一音节声母不同（l 与 b），声调相同，意思是白色的。", "蓝的": "第一音节韵母不同（ai 与 an），声调相同，意思是蓝色的。", "来个": "第二音节声母不同（d 与 g），意思是“来个”（口语中的量词用法）。"}, "sentence_index": null, "correct_answer": "来得"}, "level_3": {"options": [{"text": "落得", "is_correct": false, "explanation": "语义：“落得”表示落到某种结果，多指不好的结局，与快慢的比较不相容。"}, {"text": "来得", "is_correct": true, "explanation": "正确：“坐地铁比开车来得快”表示与开车相比，坐地铁更快。"}, {"text": "差得", "is_correct": false, "explanation": "语义：“差得”表示相差的程度，不用来说快慢的比较。"}, {"text": "比得", "is_correct": false, "explanation": "配价：句中已有“比”，再用“比得”会重复比较结构，“比得”需要“比得上”的对象，不成立。"}], "explanations": {"落得": "语义：“落得”表示落到某种结果，多指不好的结局，与快慢的比较不相容。", "来得": "正确：“坐地铁比开车来得快”表示与开车相比，坐地铁更快。", "差得": "语义：“差得”表示相差的程度，不用来说快慢的比较。", "比得": "配价：句中已有“比”，再用“比得”会重复比较结构，“比得”需要“比得上”的对象，不成立。"}, "sentence_index": 0, "correct_answer": "来得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在台上来得很自信。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}, {"text": "这件衣服来得很大方。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}, {"text": "她说话的样子来得很冷静。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看得", "is_correct": false, "explanation": "语义：“看得”指看的结果或能力，不能用来描述“亲切”这种感受。"}, {"text": "来得", "is_correct": true, "explanation": "正确：“面对面聊天比发短信来得亲切”表示面对面聊天更亲切。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”接的是好评、尊重等，不说“赢得亲切”。"}, {"text": "闹得", "is_correct": false, "explanation": "语义：“闹得”多指搞出混乱或不好的结果，与“亲切”不相容。"}], "explanations": {"看得": "语义：“看得”指看的结果或能力，不能用来描述“亲切”这种感受。", "来得": "正确：“面对面聊天比发短信来得亲切”表示面对面聊天更亲切。", "赢得": "搭配：“赢得”接的是好评、尊重等，不说“赢得亲切”。", "闹得": "语义：“闹得”多指搞出混乱或不好的结果，与“亲切”不相容。"}, "sentence_index": 6, "correct_answer": "来得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩来得好。", "explanation": "这里应该用〈很〉。来得表示与别的相比更怎样，需要比较对象；只说成绩的好坏程度要用“很”。"}, {"text": "他的笑容来得很温和。", "explanation": "这里应该用〈显得〉。显得表示看起来怎样；来得表示与别的相比更怎样，需要“比”字句。"}, {"text": "这顿饭来得贵了。", "explanation": "这里应该用〈太〉。来得需要比较对象，这里没有比较，应改为“太贵了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题和那个来得难。", "corrected_sentence": "这个问题比那个来得难。", "error_description": "错误：比较标记“比”误写成“和”。“来得”用于“比…来得+形容词”的比较句，“和”只表示并列，不能引出比较对象。正确：“比那个来得难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告那份来得详细。", "corrected_sentence": "这份报告比那份来得详细。", "error_description": "错误：漏掉了比较标记“比”。“来得”用于“比…来得+形容词”，要先用“比”引出比较对象。正确：“这份报告比那份来得详细。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
