INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "书法是用毛笔把字写得好看的本事。", "primary_collocate": null, "pronunciation": "shū fǎ", "ipa": "ʂu˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的书法很好，大家都夸他。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的书法比我好多了。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想练好书法，就得每天写字。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的书法不太好，字写得很难看。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我的书法有进步。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书法这么好，是从小练出来的。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的书法一个比一个好。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的书法真漂亮，能教教我吗？", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想练书法，把字写得更好看。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠着好书法，找到了一份工作。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "書法", "label": "繁体"}, {"form": "书法家", "label": "复合"}, {"form": "书法水平", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人把字写得好看的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气指气候，不是一个人的本事，“他的天气很好”说不通。"}, {"text": "书法", "is_correct": true, "explanation": "书法指写字的本事，用“很好”评价它，大家夸他很自然。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“很好”不能用来评价噪音，“他的噪音”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是本事，不能说“他的年龄很好”。"}], "explanations": {"天气": "语义：天气指气候，不是一个人的本事，“他的天气很好”说不通。", "书法": "书法指写字的本事，用“很好”评价它，大家夸他很自然。", "噪音": "搭配：“很好”不能用来评价噪音，“他的噪音”说不通。", "年龄": "语义：年龄是岁数，不是本事，不能说“他的年龄很好”。"}, "sentence_index": 0, "correct_answer": "书法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书法跑得很快，大家都很佩服。", "explanation": "这里应该用〈写得很好〉。“跑”用于人或动物，书法是写字的本事，应说“书法很好”，不能说“跑得很快”。"}, {"text": "他每天都弹书法，弹得很熟练。", "explanation": "这里应该用〈练〉。“弹”用于乐器，书法是写字的本事，应说“练书法”，不能说“弹书法”。"}, {"text": "他的书法很甜，大家都很喜欢。", "explanation": "这里应该用〈好〉。“甜”形容食物或声音，书法是写字的本事，应说“书法很好”，不能说“很甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "距离", "is_correct": false, "explanation": "语义：距离是间隔的长度，不是能力，“一个比一个好”说不通。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是导电的物体，不是能力，“一个比一个好”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“一个比一个好”用于可以比较优劣的本事或事物，体重一般不作这样的评价。"}, {"text": "书法", "is_correct": true, "explanation": "书法指写字的本事，可以比较优劣，“同学们的……一个比一个好”搭配自然。"}], "explanations": {"距离": "语义：距离是间隔的长度，不是能力，“一个比一个好”说不通。", "电线": "语义：电线是导电的物体，不是能力，“一个比一个好”说不通。", "体重": "搭配：“一个比一个好”用于可以比较优劣的本事或事物，体重一般不作这样的评价。", "书法": "书法指写字的本事，可以比较优劣，“同学们的……一个比一个好”搭配自然。"}, "sentence_index": 6, "correct_answer": "书法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的书法唱得很好，大家都爱听。", "explanation": "这里应该用〈写〉。“唱”用于歌曲，书法是用毛笔写字的本事，应说“写书法”，不能说“唱书法”。"}, {"text": "他把书法吃得很干净。", "explanation": "这里应该用〈练〉。“吃”用于食物，书法是写字的本事，应说“练书法”，不能说“吃书法”。"}, {"text": "他的书法很好喝，老师都夸他。", "explanation": "这里应该用〈好〉。“好喝”形容饮料，书法是写字的本事，应说“书法很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的书法写的很好。", "corrected_sentence": "他的书法写得很好。", "error_description": "补语标记错误：程度补语前应用“得”，不能用“的”，应说“写得很好”，把“的”改为“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他练了过很多年书法，字写得很漂亮。", "corrected_sentence": "他练过很多年书法，字写得很漂亮。", "error_description": "体标重复：“了”和“过”不能同时用在动词“练”后面，经历体只用“过”，应说“练过很多年书法”，删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用毛笔等书写汉字的艺术。", "primary_collocate": null, "pronunciation": "shū fǎ", "ipa": "ʂu˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "书法是中国的传统艺术。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一个书法展览。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很喜欢中国书法。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后每天在家练书法。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅书法挂在客厅里，很好看。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我带孩子去学书法。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对书法很感兴趣，每周都跟老师学写毛笔字。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法和国画都要用毛笔。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外国人觉得书法很神秘。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法讲究一笔一画，要用心写。", "target_word": "书法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "書法", "label": "繁体"}, {"form": "书法家", "label": "复合"}, {"form": "书法作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "用毛笔写汉字的传统艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育运动，不是传统艺术。"}, {"text": "书法", "is_correct": true, "explanation": "书法是用毛笔写字的传统艺术，与“是中国的传统艺术”一致。"}, {"text": "餐桌", "is_correct": false, "explanation": "语义：餐桌是家具，不属于艺术。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“传统艺术”指可以欣赏、传承的文化形式，火车不能与之搭配。"}], "explanations": {"篮球": "语义：篮球是体育运动，不是传统艺术。", "书法": "书法是用毛笔写字的传统艺术，与“是中国的传统艺术”一致。", "餐桌": "语义：餐桌是家具，不属于艺术。", "火车": "搭配：“传统艺术”指可以欣赏、传承的文化形式，火车不能与之搭配。"}, "sentence_index": 0, "correct_answer": "书法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢这支书法，常拿出来看。", "explanation": "这里应该用〈幅〉。书法作品用“幅”，“支”多用于笔、歌曲等，不能用于书法作品。"}, {"text": "这幅书法跳得很精彩，观众都看呆了。", "explanation": "这里应该用〈舞蹈〉。“跳”的对象是舞蹈，书法是用毛笔写字的艺术，不能“跳”。"}, {"text": "他每天都听书法，觉得很放松。", "explanation": "这里应该用〈音乐〉。“听”的对象是音乐，书法是用毛笔写字的艺术，不能“听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是可以跟老师学写毛笔字的对象。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不能用来学写毛笔字。"}, {"text": "书法", "is_correct": true, "explanation": "书法是用毛笔写字的艺术，与“跟老师学写毛笔字”搭配自然。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头不能用毛笔写字，不是学写毛笔字的对象。"}], "explanations": {"厨房": "语义：厨房是房间，不是可以跟老师学写毛笔字的对象。", "雨伞": "语义：雨伞是日用品，不能用来学写毛笔字。", "书法": "书法是用毛笔写字的艺术，与“跟老师学写毛笔字”搭配自然。", "水龙头": "语义：水龙头不能用毛笔写字，不是学写毛笔字的对象。"}, "sentence_index": 6, "correct_answer": "书法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅书法煮得很香，大家都很喜欢。", "explanation": "这里应该用〈菜〉。“煮”的对象是食物，书法是写出来的字，不能煮。"}, {"text": "他每天都画书法，画得很认真。", "explanation": "这里应该用〈国画〉。书法是用“写”的艺术，“画”搭配“国画”，不说“画书法”。"}, {"text": "他在晚会上朗诵了那段书法。", "explanation": "这里应该用〈诗〉。朗诵的是诗文，书法是写出来的字，不能朗诵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷年轻时学了过书法。", "corrected_sentence": "爷爷年轻时学过书法。", "error_description": "体标重复：“了”和“过”不能同时用在同一个动词后面；经历体只用“过”，应说“学过书法”，删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想被这幅书法送给老师。", "corrected_sentence": "我想把这幅书法送给老师。", "error_description": "介词错误：表示处置“这幅书法”要用“把”，不能用“被”（“被”表示被动），应说“把这幅书法送给老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
