INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "这位是说这一个人,有礼貌的叫法。", "primary_collocate": null, "pronunciation": "zhè wèi", "ipa": "tʂɤ⁵¹ weɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "这位同学，你的书掉了。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位阿姨在我们学校工作。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位客人想要一杯热茶。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位大哥帮了我很多忙。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位是新来的张经理。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师教我们汉语。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "您看，这位叔叔是我的邻居。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位小朋友真有礼貌。", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问这位怎么称呼？", "target_word": "这位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位朋友说他想学做中国菜。", "target_word": "这位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌", "sense_fingerprint": "有礼貌地称呼这一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这", "is_correct": false, "explanation": "搭配：「这」后面要接量词才能修饰名词，不能直接说「这同学」。"}, {"text": "他", "is_correct": false, "explanation": "语义：「他」是第三人称，不能用来直接称呼听话人。"}, {"text": "这位", "is_correct": true, "explanation": "「这位」礼貌地称呼身边的同学，和「你的书掉了」的提醒语气相配。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」是疑问代词，不能用作称呼，也不能指对方。"}], "explanations": {"这": "搭配：「这」后面要接量词才能修饰名词，不能直接说「这同学」。", "他": "语义：「他」是第三人称，不能用来直接称呼听话人。", "这位": "「这位」礼貌地称呼身边的同学，和「你的书掉了」的提醒语气相配。", "谁": "语义：「谁」是疑问代词，不能用作称呼，也不能指对方。"}, "sentence_index": 0, "correct_answer": "这位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位电视机又坏了，快叫人来修吧。", "explanation": "「这位」只用于人，不能指电视机，应该用量词「台」，说「这台电视机又坏了」。"}, {"text": "这位三位老师都来了。", "explanation": "「这位」已含单数量词「位」，不能再与「三位」并用，应该说「这三位老师都来了」。"}, {"text": "这位小狗咬坏了我的鞋。", "explanation": "「这位」只指人，不能指小狗这样的动物，应该用「这只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "它", "is_correct": false, "explanation": "语义：「它」指事物或动物，不能指人，而「叔叔」是人。"}, {"text": "这", "is_correct": false, "explanation": "搭配：「这」后面要接量词才能修饰名词，不能直接说「这叔叔」。"}, {"text": "这位", "is_correct": true, "explanation": "「这位」礼貌地指身边的人，「您看」时指着对方视线内的人，正好相配。"}, {"text": "咱", "is_correct": false, "explanation": "语义：「咱」包括说话人和听话人，不能用来指第三者。"}], "explanations": {"它": "语义：「它」指事物或动物，不能指人，而「叔叔」是人。", "这": "搭配：「这」后面要接量词才能修饰名词，不能直接说「这叔叔」。", "这位": "「这位」礼貌地指身边的人，「您看」时指着对方视线内的人，正好相配。", "咱": "语义：「咱」包括说话人和听话人，不能用来指第三者。"}, "sentence_index": 6, "correct_answer": "这位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位是我。", "explanation": "「这位」只指说话人身边的他人，不能用来指说话人自己。"}, {"text": "这位书很好看，你可以拿去看看。", "explanation": "「这位」只指人，书要用量词「本」，应该说「这本书很好看，你可以拿去看看」。"}, {"text": "这位公司下个月要搬到新楼。", "explanation": "「这位」只用于人，公司是机构，应该用量词「家」，说「这家公司下个月要搬到新楼」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位个叔叔在门口等你。", "corrected_sentence": "这位叔叔在门口等你。", "error_description": "「这位」的量词「位」已经包含在词中，中间不能再加「个」。「这位个叔叔」是重复量词，正确说法是「这位叔叔」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位个客人明天到。", "corrected_sentence": "这位客人明天到。", "error_description": "「这位」已经包含量词「位」，中间不能再加「个」。正确说法是「这位客人」，「这位个客人」是重复量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
