INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88799, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "来讲是从某个人的方面想，会怎么样。", "primary_collocate": null, "pronunciation": "lái jiǎng", "ipa": "lai˧˥ tɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "对我来讲，早起很难。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对妈妈来讲，孩子的健康最重要。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来讲，这个工作太简单。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小孩子来讲，这本书太难。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对你来讲，这可能是个好机会。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老师来讲，学生的进步最让人高兴。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对爸爸来讲，每天回家吃饭很重要。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对刚来的人来讲，这里的路不好找。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对她来讲，学汉语不是难事。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我朋友来讲，一百块不算多。", "target_word": "来讲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "对某人来讲：从某个人的方面想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来讲", "is_correct": true, "explanation": "正确。“对我来讲”表示从我的角度看，早起很难。"}, {"text": "关于", "is_correct": false, "explanation": "配价：“关于”引出话题，“对我关于”不成立，句子不通。"}, {"text": "按照", "is_correct": false, "explanation": "配价：“按照”要带依据，“对我按照”缺少依据，不能成立。"}, {"text": "根据", "is_correct": false, "explanation": "配价：“根据”要接依据，不能接在“对我”之后。"}], "explanations": {"来讲": "正确。“对我来讲”表示从我的角度看，早起很难。", "关于": "配价：“关于”引出话题，“对我关于”不成立，句子不通。", "按照": "配价：“按照”要带依据，“对我按照”缺少依据，不能成立。", "根据": "配价：“根据”要接依据，不能接在“对我”之后。"}, "sentence_index": 0, "correct_answer": "来讲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请他到前面来讲讲早起的好处。", "explanation": "这里的“来讲”是动词，指到前面讲述，不表示从某个人的方面想。"}, {"text": "老师让学生来讲一下早睡的经验。", "explanation": "这里的“来讲”是动词，指讲述经验，不表示“对……来讲”的观察角度。"}, {"text": "今天轮到你来讲，我先听听。", "explanation": "这里的“来讲”是动词，指轮到对方发言，不表示从某个人的方面想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来讲", "is_correct": true, "explanation": "正确。“对爸爸来讲”表示从爸爸的角度看，每天回家吃饭很重要。"}, {"text": "凭借", "is_correct": false, "explanation": "配价：“凭借”要接手段或条件，不能接在“对爸爸”之后。"}, {"text": "本着", "is_correct": false, "explanation": "配价：“本着”要接原则或态度，“对爸爸本着”不成立。"}, {"text": "鉴于", "is_correct": false, "explanation": "语义：“鉴于”表示因为某种情况，不表示从爸爸的角度看。"}], "explanations": {"来讲": "正确。“对爸爸来讲”表示从爸爸的角度看，每天回家吃饭很重要。", "凭借": "配价：“凭借”要接手段或条件，不能接在“对爸爸”之后。", "本着": "配价：“本着”要接原则或态度，“对爸爸本着”不成立。", "鉴于": "语义：“鉴于”表示因为某种情况，不表示从爸爸的角度看。"}, "sentence_index": 6, "correct_answer": "来讲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节目里请我朋友来讲讲他的理财经验。", "explanation": "这里的“来讲”是动词，指到前面讲述，不表示从某个人的方面想。"}, {"text": "班会上让他来讲一讲省钱的办法。", "explanation": "这里的“来讲”是动词，指讲述办法，不表示“对……来讲”的观察角度。"}, {"text": "这些话你来讲比我合适。", "explanation": "这里的“来讲”是动词，指由谁来开口说，不表示从某个人的方面想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对爷爷来讲讲，早起很难。", "corrected_sentence": "对爷爷来讲，早起很难。", "error_description": "错误：“对……来讲”是介词结构，不能重叠为“来讲讲”，应去掉多出的“讲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对妹妹的来讲，每天回家吃饭很重要。", "corrected_sentence": "对妹妹来讲，每天回家吃饭很重要。", "error_description": "错误：“对……来讲”中间多出了“的”。应说“对妹妹来讲”，不能说“对妹妹的来讲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
