INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请客，当主人并付钱。", "primary_collocate": null, "pronunciation": "zuò dōng", "ipa": "tswo˥˩ tʊŋ˥", "syllable_count": 2, "sentences": [{"text": "今天我做东，大家想吃什么？", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这顿饭我来做东，你们别客气。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上次是你请的，这次让我做东。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友过生日，这次他做东。", "target_word": "做东", "complexity_tier": "T3", "furigana": "zuò dōng", "sentence_source": "generated"}, {"text": "同学聚会，谁做东谁付钱。", "target_word": "做东", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板做东，请全公司的人吃火锅。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "难得你来，今天晚饭我做东。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业了，说这次要做东。", "target_word": "做东", "complexity_tier": "T3", "furigana": "zuò dōng", "sentence_source": "generated"}, {"text": "这次聚会轮到小王做东。", "target_word": "做东", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很大方，每次聚餐都抢着做东。", "target_word": "做东", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了东", "label": "体标（完成）"}, {"form": "做过东", "label": "体标（经历）"}], "register": "口语", "sense_fingerprint": "做东道主请客并付钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做东", "is_correct": true, "explanation": "正确：做东（zuò dōng）指请客并付钱。"}, {"text": "做工", "is_correct": false, "explanation": "第二音节声母不同（d 与 g），声调相同，意思是“做工”（干活、手艺）。"}, {"text": "做通", "is_correct": false, "explanation": "第二音节声母不同（d 与 t），声调相同，意思是把道理讲通、说服。"}, {"text": "做空", "is_correct": false, "explanation": "第二音节声母不同（d 与 k），声调相同，意思是“做空”（卖空股票）。"}, {"text": "做单", "is_correct": false, "explanation": "第二音节韵母不同（ong 与 an），声调相同，意思是“做单”（开单、下单）。"}], "explanations": {"做东": "正确：做东（zuò dōng）指请客并付钱。", "做工": "第二音节声母不同（d 与 g），声调相同，意思是“做工”（干活、手艺）。", "做通": "第二音节声母不同（d 与 t），声调相同，意思是把道理讲通、说服。", "做空": "第二音节声母不同（d 与 k），声调相同，意思是“做空”（卖空股票）。", "做单": "第二音节韵母不同（ong 与 an），声调相同，意思是“做单”（开单、下单）。"}, "sentence_index": null, "correct_answer": "做东"}, "level_3": {"options": [{"text": "请假", "is_correct": false, "explanation": "语义：请假与张罗饭局、问大家想吃什么的语境不符。"}, {"text": "做东", "is_correct": true, "explanation": "正确：做东即请客付钱，与“大家想吃什么”的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与请客、点菜无关，句子是在张罗饭局。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“今天我”张罗饭局、问大家想吃什么的语境不符。"}], "explanations": {"请假": "语义：请假与张罗饭局、问大家想吃什么的语境不符。", "做东": "正确：做东即请客付钱，与“大家想吃什么”的语境相符。", "散步": "语义：散步与请客、点菜无关，句子是在张罗饭局。", "睡觉": "语义：睡觉与“今天我”张罗饭局、问大家想吃什么的语境不符。"}, "sentence_index": 0, "correct_answer": "做东"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末我去朋友家做东，吃得很开心。", "explanation": "这里应该用〈做客〉。做东是请客付钱的主人，去朋友家吃饭的是客人，不能说“去朋友家做东”。"}, {"text": "这件事我替你做东，你放心。", "explanation": "这里应该用〈做主〉。做东指请客付钱，不指替人拿主意；替人决定事情要用“做主”。"}, {"text": "邻居常来我家做东，很热闹。", "explanation": "这里应该用〈串门〉。邻居来我家是客人，不是请客的主人，不能说“来我家做东”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“难得你来，今天晚饭我”的待客语境冲突。"}, {"text": "做东", "is_correct": true, "explanation": "正确：“难得你来，今天晚饭我做东”表示由我请客。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑与“难得你来”的待客语境相反。"}, {"text": "散心", "is_correct": false, "explanation": "搭配：“散心”指消遣解闷，不用来安排待客的晚饭。"}], "explanations": {"睡觉": "语义：睡觉与“难得你来，今天晚饭我”的待客语境冲突。", "做东": "正确：“难得你来，今天晚饭我做东”表示由我请客。", "逃跑": "语义：逃跑与“难得你来”的待客语境相反。", "散心": "搭配：“散心”指消遣解闷，不用来安排待客的晚饭。"}, "sentence_index": 6, "correct_answer": "做东"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周都去做东，很快乐。", "explanation": "这里应该用〈赴宴〉。做东是请客的人，去赴宴的是客人，不能说“去做东”。"}, {"text": "欢迎大家常来做东。", "explanation": "这里应该用〈光顾〉。做东指请客付钱，欢迎别人来店里消费要用“光顾”。"}, {"text": "明天我去做东，带些水果。", "explanation": "这里应该用〈拜访〉。带着水果去别人那里的是客人，不是请客付钱的主人，不能说“去做东”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很做东，请大家吃饭。", "corrected_sentence": "他经常做东，请大家吃饭。", "error_description": "错误：“很”不能修饰动词“做东”。正确：应用表示频率的“经常”来修饰“做东”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我做东过，知道其中的麻烦。", "corrected_sentence": "我做过东，知道其中的麻烦。", "error_description": "错误：体标“过”放错了位置。“做东”是动宾结构，“过”应紧接在“做”后：“做过东”。正确：“我做过东，知道其中的麻烦。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
