INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请客；当主人。", "primary_collocate": null, "pronunciation": "zuò dōng", "ipa": "tswo˥˩ tʊŋ˥", "syllable_count": 2, "sentences": [{"text": "春节我们家做东，请亲戚来吃饭。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次同学会由他做东。", "target_word": "做东", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他总爱做东，家里常有客人。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁来做东，谁就要安排好菜。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的欢迎会由经理做东。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人从远方来，我们应该做东，好好款待。", "target_word": "做东", "complexity_tier": "T3", "furigana": "zuò dōng", "sentence_source": "generated"}, {"text": "周末的晚宴由大哥做东。", "target_word": "做东", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了谢谢大家，这次我来做东。", "target_word": "做东", "complexity_tier": "T3", "furigana": "zuò dōng", "sentence_source": "generated"}, {"text": "他在北京做东，招待了老朋友们。", "target_word": "做东", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次聚会是朋友做东的。", "target_word": "做东", "complexity_tier": "T3", "furigana": "zuò dōng", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了东", "label": "体标（完成）"}, {"form": "做过东", "label": "体标（经历）"}], "register": "口语", "sense_fingerprint": "当东道主，招待客人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做东", "is_correct": true, "explanation": "正确：做东（zuò dōng）指当东道主，招待客人。"}, {"text": "做工", "is_correct": false, "explanation": "第二音节声母不同（d 与 g），声调相同，意思是“做工”（干活、手艺）。"}, {"text": "做通", "is_correct": false, "explanation": "第二音节声母不同（d 与 t），声调相同，意思是把道理讲通、说服。"}, {"text": "做空", "is_correct": false, "explanation": "第二音节声母不同（d 与 k），声调相同，意思是“做空”（卖空股票）。"}, {"text": "做单", "is_correct": false, "explanation": "第二音节韵母不同（ong 与 an），声调相同，意思是“做单”（开单、下单）。"}], "explanations": {"做东": "正确：做东（zuò dōng）指当东道主，招待客人。", "做工": "第二音节声母不同（d 与 g），声调相同，意思是“做工”（干活、手艺）。", "做通": "第二音节声母不同（d 与 t），声调相同，意思是把道理讲通、说服。", "做空": "第二音节声母不同（d 与 k），声调相同，意思是“做空”（卖空股票）。", "做单": "第二音节韵母不同（ong 与 an），声调相同，意思是“做单”（开单、下单）。"}, "sentence_index": null, "correct_answer": "做东"}, "level_3": {"options": [{"text": "请假", "is_correct": false, "explanation": "语义：请假与“请亲戚来吃饭”的待客安排冲突。"}, {"text": "做东", "is_correct": true, "explanation": "正确：“春节我们家做东，请亲戚来吃饭”表示我们家招待亲戚。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与请亲戚吃饭无关，句子讲的是待客安排。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“请亲戚来吃饭”的待客安排不相容。"}], "explanations": {"请假": "语义：请假与“请亲戚来吃饭”的待客安排冲突。", "做东": "正确：“春节我们家做东，请亲戚来吃饭”表示我们家招待亲戚。", "散步": "语义：散步与请亲戚吃饭无关，句子讲的是待客安排。", "睡觉": "语义：睡觉与“请亲戚来吃饭”的待客安排不相容。"}, "sentence_index": 0, "correct_answer": "做东"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去张家做东，主人很热情。", "explanation": "这里应该用〈做客〉。去张家吃饭的是客人，招待客人的主人才是做东，不能说“去张家做东”。"}, {"text": "这事由她做东。", "explanation": "这里应该用〈做主〉。做东指招待客人，不指替人拿主意或决定事情。"}, {"text": "我回老家做东，住了一周。", "explanation": "这里应该用〈探亲〉。回老家探亲是回去看望家人，不是招待客人，不能说“回老家做东”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“周末的晚宴由大哥”的安排不相符。"}, {"text": "做东", "is_correct": true, "explanation": "正确：“周末的晚宴由大哥做东”表示大哥负责请客招待。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑与“晚宴由大哥”的安排相反。"}, {"text": "散心", "is_correct": false, "explanation": "搭配：“散心”指消遣解闷，不能用来描述晚宴的安排。"}], "explanations": {"睡觉": "语义：睡觉与“周末的晚宴由大哥”的安排不相符。", "做东": "正确：“周末的晚宴由大哥做东”表示大哥负责请客招待。", "逃跑": "语义：逃跑与“晚宴由大哥”的安排相反。", "散心": "搭配：“散心”指消遣解闷，不能用来描述晚宴的安排。"}, "sentence_index": 6, "correct_answer": "做东"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她昨晚去做东，回来很晚。", "explanation": "这里应该用〈赴宴〉。赴宴的人是客人，不能说“去做东”。"}, {"text": "下午我去做东，聊了很久。", "explanation": "这里应该用〈拜访〉。“去”别人那里聊天的是客人，不是招待客人的主人，不能说“去做东”。"}, {"text": "周末我去朋友家做东。", "explanation": "这里应该用〈串门〉。去朋友家串门的是客人，不能说“去朋友家做东”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们家很做东，请同事吃饭。", "corrected_sentence": "周末我们家常做东，请同事吃饭。", "error_description": "错误：“很”不能修饰动词“做东”。正确：应用表示频率的“常”来修饰“做东”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二十年前他做东过，请大家吃饭。", "corrected_sentence": "二十年前他做过东，请大家吃饭。", "error_description": "错误：体标“过”放错了位置。“做东”是动宾结构，“过”应紧接在“做”后：“做过东”。正确：“二十年前他做过东，请大家吃饭。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
