INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本事是一个人会做某件事的能力。", "primary_collocate": null, "pronunciation": "běn shi", "ipa": "pən˨˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "他的本事真大。", "target_word": "本事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没有他那样的本事。", "target_word": "本事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小孩儿有做饭的本事。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有本事你来试试看。", "target_word": "本事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他有本事一个人把车修好。", "target_word": "本事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当好医生，就得有真本事。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的本事是在工作中一点一点学来的。", "target_word": "本事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王有本事，三年就当上了经理。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说自己没本事，其实是太客气了。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这么有本事，能不能教教我？", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本事：一个人会做某件事的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88803, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事（běn shi）指本领、能力，是正确答案。"}, {"text": "本市", "is_correct": false, "explanation": "本市（běn shì）与本事只差第二个音节的声调（第四声与轻声），意思是这座城市。"}, {"text": "本子", "is_correct": false, "explanation": "本子（běn zi）与本事的第二个音节声母不同（z 与 sh），意思是笔记本。"}, {"text": "本职", "is_correct": false, "explanation": "本职（běn zhí）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是本来的职务。"}, {"text": "本质", "is_correct": false, "explanation": "本质（běn zhì）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是事物的根本性质。"}], "explanations": {"本事": "本事（běn shi）指本领、能力，是正确答案。", "本市": "本市（běn shì）与本事只差第二个音节的声调（第四声与轻声），意思是这座城市。", "本子": "本子（běn zi）与本事的第二个音节声母不同（z 与 sh），意思是笔记本。", "本职": "本职（běn zhí）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是本来的职务。", "本质": "本质（běn zhì）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是事物的根本性质。"}, "sentence_index": null, "correct_answer": "本事"}, "level_3": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事指能力，“他的本事真大”说他的能力强，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“大”不用来修饰颜色，不能说“颜色真大”。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向没有大小之分，与“真大”不搭。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：说时间多用“长”或“多”，不说“时间真大”。"}], "explanations": {"本事": "本事指能力，“他的本事真大”说他的能力强，与句意相符。", "颜色": "搭配：“大”不用来修饰颜色，不能说“颜色真大”。", "方向": "语义：方向没有大小之分，与“真大”不搭。", "时间": "搭配：说时间多用“长”或“多”，不说“时间真大”。"}, "sentence_index": 0, "correct_answer": "本事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是本事毕业的。", "explanation": "这里应该用〈本科〉。本科指学历层次，本事指能力，不能说“本事毕业”。"}, {"text": "他有一只好本事，大家都很佩服。", "explanation": "这里应该用〈身〉。“本事”要说一身本事，“只”多用于动物及成对物件中的单个，不能计量能力。"}, {"text": "这笔本事不够开店。", "explanation": "这里应该用〈本钱〉。本钱指资金，本事指能力，“这笔本事”说成钱是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88803, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事（běn shi）指本领、能力，是正确答案。"}, {"text": "本是", "is_correct": false, "explanation": "本是（běn shì）与本事只差第二个音节的声调，意思是原本、原来。"}, {"text": "本书", "is_correct": false, "explanation": "本书（běn shū）与本事的第二个音节韵母不同（ū 与 i），意思是这本书。"}, {"text": "本身", "is_correct": false, "explanation": "本身（běn shēn）与本事的第二个音节韵母和声调都不同，意思是本体、自身。"}], "explanations": {"本事": "本事（běn shi）指本领、能力，是正确答案。", "本是": "本是（běn shì）与本事只差第二个音节的声调，意思是原本、原来。", "本书": "本书（běn shū）与本事的第二个音节韵母不同（ū 与 i），意思是这本书。", "本身": "本身（běn shēn）与本事的第二个音节韵母和声调都不同，意思是本体、自身。"}, "sentence_index": null, "correct_answer": "本事"}, "level_3": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事指能力，“在工作中一点一点学来”正说明它是学来的。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是天生的，不是在工作中学来的。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不能靠学习获得，与“学来的”不合。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“学”不搭配脚步，不能说“学来的脚步”。"}], "explanations": {"本事": "本事指能力，“在工作中一点一点学来”正说明它是学来的。", "眼睛": "语义：眼睛是天生的，不是在工作中学来的。", "身高": "语义：身高不能靠学习获得，与“学来的”不合。", "脚步": "搭配：“学”不搭配脚步，不能说“学来的脚步”。"}, "sentence_index": 6, "correct_answer": "本事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在本事上记下了地址。", "explanation": "这里应该用〈本子〉。本子指笔记本，本事指能力，不能说“记在本事上”。"}, {"text": "他有一张好本事，能不能教教我？", "explanation": "这里应该用〈身〉。“张”用于平面的东西，不能计量“本事”。"}, {"text": "这笔本事他还要还。", "explanation": "这里应该用〈本金〉。本金指本钱、资金，本事指能力，不能用来说借的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一块真本事，连老师都佩服他。", "corrected_sentence": "他有一身真本事，连老师都佩服他。", "error_description": "量词错误：“本事”应用量词“身”，“块”用于块状的东西，不能用来计量“本事”。正确说法是“一身真本事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的这一块本事是一点一点学来的，不是天生的。", "corrected_sentence": "她的这一身本事是一点一点学来的，不是天生的。", "error_description": "量词错误：“本事”应用量词“身”（一身本事），“块”用于块状的东西，不能用来计量“本事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
