INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本领；能力。", "primary_collocate": null, "pronunciation": "běn shi", "ipa": "pən˨˩ ʂɨ", "syllable_count": 2, "sentences": [{"text": "他很有本事，什么都会做。", "target_word": "本事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想在大城市找到工作，要有本事。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孙悟空的本事很大，会七十二变。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跟爸爸学了一身好本事。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有本事就自己把这件事做完。", "target_word": "本事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠自己的本事考上了大学。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人要多学本事，将来才不怕找不到工作。", "target_word": "本事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师傅的本事，我们都很佩服。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有什么本事，却总爱说大话。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别看他个子小，本事可不小。", "target_word": "本事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本事：人所具有的本领、能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事（běn shi）指本领、能力，是正确答案。"}, {"text": "本市", "is_correct": false, "explanation": "本市（běn shì）与本事只差第二个音节的声调（第四声与轻声），意思是这座城市。"}, {"text": "本子", "is_correct": false, "explanation": "本子（běn zi）与本事的第二个音节声母不同（z 与 sh），意思是笔记本。"}, {"text": "本职", "is_correct": false, "explanation": "本职（běn zhí）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是本来的职务。"}, {"text": "本质", "is_correct": false, "explanation": "本质（běn zhì）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是事物的根本性质。"}], "explanations": {"本事": "本事（běn shi）指本领、能力，是正确答案。", "本市": "本市（běn shì）与本事只差第二个音节的声调（第四声与轻声），意思是这座城市。", "本子": "本子（běn zi）与本事的第二个音节声母不同（z 与 sh），意思是笔记本。", "本职": "本职（běn zhí）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是本来的职务。", "本质": "本质（běn zhì）与本事的第二个音节声母（zh 与 sh）和声调都不同，意思是事物的根本性质。"}, "sentence_index": null, "correct_answer": "本事"}, "level_3": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事指能力，与后句“什么都会做”相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“有脾气”说的是性情，与“什么都会做”没有关系。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“很有名字”不是常用说法，“有名字”说的是有名气，不是能做事。"}, {"text": "房子", "is_correct": false, "explanation": "语义：有房子不能说明能做什么，与后句不搭。"}], "explanations": {"本事": "本事指能力，与后句“什么都会做”相符。", "脾气": "语义：“有脾气”说的是性情，与“什么都会做”没有关系。", "名字": "搭配：“很有名字”不是常用说法，“有名字”说的是有名气，不是能做事。", "房子": "语义：有房子不能说明能做什么，与后句不搭。"}, "sentence_index": 0, "correct_answer": "本事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开店时，他的本事只有五千元。", "explanation": "这里应该用〈本钱〉。本钱指做生意的资金，本事指能力，不能说“本事只有五千元”。"}, {"text": "他跟爸爸学了一颗好本事。", "explanation": "这里应该用〈身〉。“本事”要说一身本事，“颗”用于小而圆的东西，不这样计量能力。"}, {"text": "他把作业写在新本事上。", "explanation": "这里应该用〈本子〉。本子指笔记本，本事指能力，不能说“写在本事上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88804, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事（běn shi）指本领、能力，是正确答案。"}, {"text": "本是", "is_correct": false, "explanation": "本是（běn shì）与本事只差第二个音节的声调，意思是原本、原来。"}, {"text": "本书", "is_correct": false, "explanation": "本书（běn shū）与本事的第二个音节韵母不同（ū 与 i），意思是这本书。"}, {"text": "本身", "is_correct": false, "explanation": "本身（běn shēn）与本事的第二个音节韵母和声调都不同，意思是本体、自身。"}], "explanations": {"本事": "本事（běn shi）指本领、能力，是正确答案。", "本是": "本是（běn shì）与本事只差第二个音节的声调，意思是原本、原来。", "本书": "本书（běn shū）与本事的第二个音节韵母不同（ū 与 i），意思是这本书。", "本身": "本身（běn shēn）与本事的第二个音节韵母和声调都不同，意思是本体、自身。"}, "sentence_index": null, "correct_answer": "本事"}, "level_3": {"options": [{"text": "本事", "is_correct": true, "explanation": "本事指能力，“学本事”是常用说法，与“将来不怕找不到工作”相符。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“学”说的是学知识、学技能，不说“学衣服”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能靠学习得到，与后句“不怕找不到工作”无关。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“学桌子”没有这种说法，桌子也不是学来的。"}], "explanations": {"本事": "本事指能力，“学本事”是常用说法，与“将来不怕找不到工作”相符。", "衣服": "搭配：“学”说的是学知识、学技能，不说“学衣服”。", "天气": "语义：天气不能靠学习得到，与后句“不怕找不到工作”无关。", "桌子": "搭配：“学桌子”没有这种说法，桌子也不是学来的。"}, "sentence_index": 6, "correct_answer": "本事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这么做，本事是为了帮你。", "explanation": "这里应该用〈本意〉。本意指原本的用意，本事指能力，不能用来说目的。"}, {"text": "他跟同学学了一本好本事。", "explanation": "这里应该用〈身〉。“本”是书的量词，不能用来计量“本事”，应说一身本事。"}, {"text": "他从本事毕业后就工作了。", "explanation": "这里应该用〈本科〉。本科指学历层次，本事指能力，不能说“从本事毕业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一颗好本事，大家都很佩服。", "corrected_sentence": "他有一身好本事，大家都很佩服。", "error_description": "量词错误：“本事”应用量词“身”（一身好本事），“颗”用于小而圆的东西，不能用来计量“本事”。正确说法是“一身好本事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是本事，别人都佩服他。", "corrected_sentence": "他有本事，别人都佩服他。", "error_description": "动词错误：“本事”前应用“有”，说“他有本事”；“是”不能直接接“本事”作谓语。正确说法是“他有本事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
