INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88805, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": false, "explanation": "吵闹指声音大、乱，与“充实”没有反义关系。"}, {"text": "模糊", "is_correct": false, "explanation": "模糊指不清楚，与“充实”没有反义关系。"}, {"text": "空洞", "is_correct": true, "explanation": "空洞：内容空，没有实际东西，与“内容充实”正相反。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指头绪多、不简单，与“充实”没有反义关系。"}], "correct_answer": "空洞", "explanations": {"吵闹": "吵闹指声音大、乱，与“充实”没有反义关系。", "模糊": "模糊指不清楚，与“充实”没有反义关系。", "空洞": "空洞：内容空，没有实际东西，与“内容充实”正相反。", "复杂": "复杂指头绪多、不简单，与“充实”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88805, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "充实是里面的东西很多，不空。", "primary_collocate": null, "pronunciation": "chōng shí", "ipa": "ʈʂʰʊŋ⁵⁵ ʂɨ³⁵", "syllable_count": 2, "sentences": [{"text": "这篇文章的内容很充实。", "target_word": "充实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师把课上得很充实。", "target_word": "充实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容不够充实，看完没学到什么。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个展览内容充实，值得去看。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的报告数据多，内容很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门课安排得很充实，每天都有新东西。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份计划写得很充实，每一步都很清楚。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个节目内容充实，一点也不无聊。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议的材料非常充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的演讲内容充实，大家听得很认真。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "充实感", "label": "复合"}], "register": "中性", "sense_fingerprint": "文章、课程、报告等的内容丰富、材料多、不空洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠实", "is_correct": false, "explanation": "zhōng（第一声）与 chōng（第一声）声母不同（zh 与 ch），意思是忠诚、可靠，不是内容多。"}, {"text": "充实", "is_correct": true, "explanation": "充实：里面的东西很多，不空，与听到的读音一致。"}, {"text": "充值", "is_correct": false, "explanation": "zhí（第二声）与 shí（第二声）声母不同（zh 与 sh），意思是往账户里存钱，如充值卡。"}, {"text": "诚实", "is_correct": false, "explanation": "chéng（第二声）与 chōng（第一声）的韵母和声调都不同，意思是说真话、不欺骗。"}], "explanations": {"忠实": "zhōng（第一声）与 chōng（第一声）声母不同（zh 与 ch），意思是忠诚、可靠，不是内容多。", "充实": "充实：里面的东西很多，不空，与听到的读音一致。", "充值": "zhí（第二声）与 shí（第二声）声母不同（zh 与 sh），意思是往账户里存钱，如充值卡。", "诚实": "chéng（第二声）与 chōng（第一声）的韵母和声调都不同，意思是说真话、不欺骗。"}, "sentence_index": null, "correct_answer": "充实"}, "level_3": {"options": [{"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度，不能用来形容文章的内容。"}, {"text": "充实", "is_correct": true, "explanation": "充实：内容丰富、不空，与“内容”搭配，能填入空格。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”多用于食物、滋味，不能说内容香甜。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或外表，文章的内容不能发亮。"}], "explanations": {"冰凉": "语义：“冰凉”形容温度，不能用来形容文章的内容。", "充实": "充实：内容丰富、不空，与“内容”搭配，能填入空格。", "香甜": "搭配：“香甜”多用于食物、滋味，不能说内容香甜。", "明亮": "语义：“明亮”形容光线或外表，文章的内容不能发亮。"}, "sentence_index": 0, "correct_answer": "充实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的货源很充实，什么都买得到。", "explanation": "这里应该用〈充足〉。充足说数量够、供应不缺，货源是数量，应说“充足”；充实说内容或材料丰富、不空，不用于货物数量。"}, {"text": "这家餐厅的菜品很充实，每道菜都很好吃。", "explanation": "这里应该用〈丰富〉。丰富说种类多，菜品的种类数量应说“丰富”；充实强调内容扎实、不空，不用来说菜品种类多。"}, {"text": "这个房间里充实着浓浓的烟味。", "explanation": "这里应该用〈充斥〉。充斥指某种气味或东西到处都是，烟味弥漫要用充斥；充实说内容扎实、不空，不用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或地面的水分，不能用于计划的写法。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容环境里的声音，不用来形容计划写得怎样。"}, {"text": "充实", "is_correct": true, "explanation": "充实：内容扎实、安排完整，与“写得”和“每一步都很清楚”相符。"}, {"text": "咸涩", "is_correct": false, "explanation": "语义：“咸涩”形容滋味，用在计划的写法上说不通。"}], "explanations": {"潮湿": "语义：“潮湿”形容空气或地面的水分，不能用于计划的写法。", "嘈杂": "搭配：“嘈杂”形容环境里的声音，不用来形容计划写得怎样。", "充实": "充实：内容扎实、安排完整，与“写得”和“每一步都很清楚”相符。", "咸涩": "语义：“咸涩”形容滋味，用在计划的写法上说不通。"}, "sentence_index": 6, "correct_answer": "充实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日的宴席很充实，大家都吃得很开心。", "explanation": "这里应该用〈丰盛〉。丰盛说饭菜品种多、分量足；充实强调内容扎实、不空，不用来形容宴席。"}, {"text": "今天的天气很充实，适合出去玩。", "explanation": "这里应该用〈晴朗〉。晴朗说天空无云、阳光好，天气要用晴朗；充实说内容或生活有收获，不用来形容天气。"}, {"text": "长跑之后，他的体力依然很充实。", "explanation": "这里应该用〈充沛〉。充沛说体力、精力饱满有力，体力要用充沛；充实说内容或生活有收获，不说体力充实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
