INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "内容丰富、不空虚。", "primary_collocate": null, "pronunciation": "chōng shí", "ipa": "ʈʂʰʊŋ⁵⁵ ʂɨ³⁵", "syllable_count": 2, "sentences": [{"text": "退休后，爷爷的生活过得很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天学习和工作，我觉得很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个假期，我每天都很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的大学生活丰富又充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她忙着照顾孩子，心里却很充实。", "target_word": "充实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去山里走一走，让我觉得很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一天的工作结束后，他感到充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想让自己的每一天都充实一些。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了新东西，他觉得日子很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然很累，但是这样的日子很充实。", "target_word": "充实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "充实感", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活、日子或心里有事可做、有收获，感到不空虚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠实", "is_correct": false, "explanation": "zhōng（第一声）与 chōng（第一声）声母不同（zh 与 ch），意思是忠诚、可靠，不是生活充实。"}, {"text": "充实", "is_correct": true, "explanation": "充实：生活或心里有事做、有收获，不空虚，与听到的读音一致。"}, {"text": "充值", "is_correct": false, "explanation": "zhí（第二声）与 shí（第二声）声母不同（zh 与 sh），意思是往账户里存钱，如充值卡。"}, {"text": "诚实", "is_correct": false, "explanation": "chéng（第二声）与 chōng（第一声）的韵母和声调都不同，意思是说真话、不欺骗。"}], "explanations": {"忠实": "zhōng（第一声）与 chōng（第一声）声母不同（zh 与 ch），意思是忠诚、可靠，不是生活充实。", "充实": "充实：生活或心里有事做、有收获，不空虚，与听到的读音一致。", "充值": "zhí（第二声）与 shí（第二声）声母不同（zh 与 sh），意思是往账户里存钱，如充值卡。", "诚实": "chéng（第二声）与 chōng（第一声）的韵母和声调都不同，意思是说真话、不欺骗。"}, "sentence_index": null, "correct_answer": "充实"}, "level_3": {"options": [{"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度，不能用来说生活过得怎样。"}, {"text": "充实", "is_correct": true, "explanation": "充实：生活有事做、有收获，不空虚，与句意相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多用于空气、地面，不用来形容生活过得如何。"}, {"text": "腥臭", "is_correct": false, "explanation": "语义：“腥臭”形容难闻的气味，不能用来说生活过得怎样。"}], "explanations": {"冰凉": "语义：“冰凉”形容温度，不能用来说生活过得怎样。", "充实": "充实：生活有事做、有收获，不空虚，与句意相符。", "潮湿": "搭配：“潮湿”多用于空气、地面，不用来形容生活过得如何。", "腥臭": "语义：“腥臭”形容难闻的气味，不能用来说生活过得怎样。"}, "sentence_index": 0, "correct_answer": "充实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨晚他睡得很好，睡眠很充实。", "explanation": "这里应该用〈充足〉。充足说睡眠时间够，睡眠的长短要用充足；充实说生活或心里有事做、有收获，不用来形容睡眠。"}, {"text": "这顿晚饭的菜很充实，大家都吃得很满意。", "explanation": "这里应该用〈丰盛〉。丰盛说饭菜品种多、分量足；充实说生活或心里有收获，不用来形容饭菜。"}, {"text": "他经过多年训练，嗓音很充实，唱起歌来很有力量。", "explanation": "这里应该用〈浑厚〉。浑厚指声音低沉有力、饱满，嗓音要用浑厚；充实说生活或心里有收获，不用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道刺激，不能用来形容心里的感受。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境，不用来形容人的感受。"}, {"text": "充实", "is_correct": true, "explanation": "充实：心里有收获、不空虚，与“感到”搭配，符合句意。"}, {"text": "刺鼻", "is_correct": false, "explanation": "语义：“刺鼻”形容气味强烈，不能用来说感到刺鼻的心情。"}], "explanations": {"辛辣": "语义：“辛辣”形容味道刺激，不能用来形容心里的感受。", "嘈杂": "搭配：“嘈杂”形容声音或环境，不用来形容人的感受。", "充实": "充实：心里有收获、不空虚，与“感到”搭配，符合句意。", "刺鼻": "语义：“刺鼻”形容气味强烈，不能用来说感到刺鼻的心情。"}, "sentence_index": 6, "correct_answer": "充实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动后，他的精力很充实。", "explanation": "这里应该用〈充沛〉。充沛说精力、体力饱满有力，精力要用充沛；充实说生活或心里有收获，不用于精力。"}, {"text": "这把椅子很充实，坐上去很舒服。", "explanation": "这里应该用〈结实〉。结实说物体坚固、不易坏，椅子坚固要用结实；充实说生活或心里有收获，不用来形容椅子。"}, {"text": "早高峰的地铁里，车厢很充实，大家都挤在一起。", "explanation": "这里应该用〈拥挤〉。拥挤指人多、空间不够，车厢里人多要用拥挤；充实说内容或生活有收获，不用来形容人多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个暑假我过得很充实感，学会了游泳。", "corrected_sentence": "这个暑假我过得很充实，学会了游泳。", "error_description": "错误：“充实感”。“充实感”是名词，这里要用形容词“充实”，说过得充实。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他充实的度过了这一天。", "corrected_sentence": "他充实地度过了这一天。", "error_description": "错误：“充实的”。“充实”修饰后面的动词“度过”时要用“地”，应说“充实地度过”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
