INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88807, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "项是数事情或东西时用的字,比如一项比赛。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "跑步是一项很好的运动。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有一项重要的比赛。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了三项比赛。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项活动对孩子很有帮助。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳是一项他很喜欢的运动。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了一项有趣的实验。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举办了一项读书活动。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究花了五年时间。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球是一项团体运动。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我报名参加了两项比赛。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "項", "label": "繁体"}, {"form": "项目", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词,用于比赛、运动、活动、研究等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88807, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "项", "is_correct": true, "explanation": "项（xiàng）是用于分项目事物的量词，如“一项比赛”，是正确答案。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香气。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想念或想法。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是下降。"}, {"text": "亮", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同（l 与 x），意思是明亮。"}], "explanations": {"项": "项（xiàng）是用于分项目事物的量词，如“一项比赛”，是正确答案。", "香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香气。", "想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想念或想法。", "降": "jiàng 与 xiàng 声母不同（j 与 x），意思是下降。", "亮": "liàng 与 xiàng 声母不同（l 与 x），意思是明亮。"}, "sentence_index": null, "correct_answer": "项"}, "level_3": {"options": [{"text": "条", "is_correct": false, "explanation": "搭配：“条”多用于河流、道路、消息等细长的东西，不说“一条运动”。"}, {"text": "项", "is_correct": true, "explanation": "正确。“项”用于比赛、运动、活动等分项目的事物，与“运动”搭配。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、桥、楼等大型固定的东西，不能用来数运动。"}, {"text": "颗", "is_correct": false, "explanation": "体貌：“颗”指粒状的小东西，运动没有这种形态，不能用“颗”。"}], "explanations": {"条": "搭配：“条”多用于河流、道路、消息等细长的东西，不说“一条运动”。", "项": "正确。“项”用于比赛、运动、活动等分项目的事物，与“运动”搭配。", "座": "语义：“座”指山、桥、楼等大型固定的东西，不能用来数运动。", "颗": "体貌：“颗”指粒状的小东西，运动没有这种形态，不能用“颗”。"}, "sentence_index": 0, "correct_answer": "项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨晚看了一项电影。", "explanation": "这里应该用〈部〉。电影是作品，要用“部”来数；“项”可以数活动、研究等事情，但不用来数电影。"}, {"text": "我吃了一项苹果。", "explanation": "这里应该用〈个〉。苹果要用“个”来数，“项”不能用来数水果。"}, {"text": "我想喝一项茶。", "explanation": "这里应该用〈杯〉。茶要用“杯”来数，“项”不能用来数饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88807, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "项", "is_correct": true, "explanation": "项（xiàng）是用于分项目事物的量词，如“一项活动”，是正确答案。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是现在。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}], "explanations": {"项": "项（xiàng）是用于分项目事物的量词，如“一项活动”，是正确答案。", "详": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。", "现": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是现在。", "响": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。", "乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}, "sentence_index": null, "correct_answer": "项"}, "level_3": {"options": [{"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲等，不能用来数活动。"}, {"text": "项", "is_correct": true, "explanation": "正确。“项”用于比赛、运动、活动等分项目的事物，此处指一次读书活动。"}, {"text": "幅", "is_correct": false, "explanation": "体貌：“幅”用于画、布匹等平面的东西，活动没有这种形态。"}, {"text": "支", "is_correct": false, "explanation": "搭配：“支”用于队伍、笔、歌曲等，不说“一支活动”。"}], "explanations": {"首": "语义：“首”用于诗歌、歌曲等，不能用来数活动。", "项": "正确。“项”用于比赛、运动、活动等分项目的事物，此处指一次读书活动。", "幅": "体貌：“幅”用于画、布匹等平面的东西，活动没有这种形态。", "支": "搭配：“支”用于队伍、笔、歌曲等，不说“一支活动”。"}, "sentence_index": 6, "correct_answer": "项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校开设了一项课。", "explanation": "这里应该用〈门〉。课程要用“门”来数；“项”可以数活动、研究等事情，但不用来数课程。"}, {"text": "他唱了一项歌。", "explanation": "这里应该用〈首〉。歌曲要用“首”来数，“项”不能用来数歌。"}, {"text": "我买了一项车。", "explanation": "这里应该用〈辆〉。车要用“辆”来数，“项”不能用来数车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他参加了一体育比赛。", "corrected_sentence": "他参加了一项体育比赛。", "error_description": "数词“一”和名词“体育比赛”之间缺少量词，应说“一项体育比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
