INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88808, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于分项目的事物。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这项工作很重要。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有三项新规定。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完成了一项大任务。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司提出了两项新措施。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一项很难的工程。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上讨论了五项内容。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们还有一项工作没做完。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项计划明年开始。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师布置了四项任务。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府推出了一项新政策。", "target_word": "项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "項", "label": "繁体"}, {"form": "项目", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词,用于工作、规定、任务等分项目的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "项", "is_correct": true, "explanation": "项（xiàng）是用于分项目事物的量词，如“这项工作”，是正确答案。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香气。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想念或想法。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是下降。"}, {"text": "亮", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同（l 与 x），意思是明亮。"}], "explanations": {"项": "项（xiàng）是用于分项目事物的量词，如“这项工作”，是正确答案。", "香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香气。", "想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想念或想法。", "降": "jiàng 与 xiàng 声母不同（j 与 x），意思是下降。", "亮": "liàng 与 xiàng 声母不同（l 与 x），意思是明亮。"}, "sentence_index": null, "correct_answer": "项"}, "level_3": {"options": [{"text": "条", "is_correct": false, "explanation": "搭配：“条”多用于河流、道路、消息、规定等细长的事物，不能说“这条工作”。"}, {"text": "项", "is_correct": true, "explanation": "正确。“项”是量词，用于工作、任务、计划等分项目的事物，与“工作”搭配。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”用于山、桥、楼等大型固定的东西，工作不能用“座”来数。"}, {"text": "本", "is_correct": false, "explanation": "体貌：“本”指装订成册的书刊，工作没有这种形态，不能用“本”。"}], "explanations": {"条": "搭配：“条”多用于河流、道路、消息、规定等细长的事物，不能说“这条工作”。", "项": "正确。“项”是量词，用于工作、任务、计划等分项目的事物，与“工作”搭配。", "座": "语义：“座”用于山、桥、楼等大型固定的东西，工作不能用“座”来数。", "本": "体貌：“本”指装订成册的书刊，工作没有这种形态，不能用“本”。"}, "sentence_index": 0, "correct_answer": "项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市有一项大河。", "explanation": "这里应该用〈条〉。“条”用于河流、道路等细长的东西，“项”只用于工作、规定、计划等分项目的事物。"}, {"text": "他买了一项新衣服。", "explanation": "这里应该用〈件〉。衣服是具体物品，要用“件”来数，“项”不能用来数衣服。"}, {"text": "我买了一项书。", "explanation": "这里应该用〈本〉。书要用“本”来数，“项”不能用来数书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88808, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "项", "is_correct": true, "explanation": "项（xiàng）是用于分项目事物的量词，如“一项工作”，是正确答案。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是现在。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}], "explanations": {"项": "项（xiàng）是用于分项目事物的量词，如“一项工作”，是正确答案。", "详": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。", "现": "xiàn 与 xiàng 韵尾不同（-n 与 -ng），意思是现在。", "响": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。", "乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}, "sentence_index": null, "correct_answer": "项"}, "level_3": {"options": [{"text": "支", "is_correct": false, "explanation": "搭配：“支”用于队伍、笔、歌曲等，不说“一支工作”。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画、布匹等平面的东西，工作不能用“幅”来数。"}, {"text": "项", "is_correct": true, "explanation": "正确。“项”用于工作、任务等分项目的事物，此处指一件待完成的工作。"}, {"text": "颗", "is_correct": false, "explanation": "体貌：“颗”指粒状的小东西，工作没有这种形态，不能用“颗”。"}], "explanations": {"支": "搭配：“支”用于队伍、笔、歌曲等，不说“一支工作”。", "幅": "语义：“幅”用于画、布匹等平面的东西，工作不能用“幅”来数。", "项": "正确。“项”用于工作、任务等分项目的事物，此处指一件待完成的工作。", "颗": "体貌：“颗”指粒状的小东西，工作没有这种形态，不能用“颗”。"}, "sentence_index": 6, "correct_answer": "项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村子附近有一项大桥。", "explanation": "这里应该用〈座〉。大桥等大型建筑要用“座”，“项”不能用来数桥。"}, {"text": "我喝了一项牛奶。", "explanation": "这里应该用〈杯〉。牛奶要用“杯”或“瓶”来数，“项”不能用来数饮料。"}, {"text": "我家有一项椅子。", "explanation": "这里应该用〈把〉。椅子要用“把”来数，“项”只用于工作、规定、计划等分项目的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.co