INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88809, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "校对是把写的字拿来对一对，看有没有写错。", "primary_collocate": null, "pronunciation": "jiào duì", "ipa": "tɕjɑʊ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "写完作文，你要自己校对一下。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈帮我校对作业里的字。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张通知请你先校对再贴出去。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把名单校对了两遍，没有错字。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校对的时候，要一个字一个字地看。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王校对完信，才放进信封。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我校对一下这几个字写得对不对。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校对一遍再交，可以少写错字。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人互相校对对方的笔记。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室里校对同学们写的字。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "校对了", "label": "体标"}, {"form": "校对过", "label": "体标"}, {"form": "校对校对", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把写好的字对一对，看有没有写错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校对", "is_correct": true, "explanation": "检查作文的错字并改正，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不用于作文，不说唱作文。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于物品，不说洗作文。"}, {"text": "吃", "is_correct": false, "explanation": "语义：作文不能吃，句意不通。"}], "explanations": {"校对": "检查作文的错字并改正，符合句意。", "唱": "搭配：“唱”不用于作文，不说唱作文。", "洗": "搭配：“洗”用于物品，不说洗作文。", "吃": "语义：作文不能吃，句意不通。"}, "sentence_index": 0, "correct_answer": "校对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把桌子校对了两遍。", "explanation": "这里应该用〈擦〉。校对是对照文字查错，擦桌子应说擦。"}, {"text": "妈妈校对了一锅汤。", "explanation": "这里应该用〈煮〉。校对不能用于汤，煮汤应说煮。"}, {"text": "我校对了一只猫。", "explanation": "这里应该用〈喂〉。校对不能用于动物，喂猫应说喂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校对", "is_correct": true, "explanation": "检查这几个字是否写对，符合句意。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不用于检查字的对错，不说放字。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”不能用于字，不说倒这几个字。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”与“看字写得对不对”的意思矛盾。"}], "explanations": {"校对": "检查这几个字是否写对，符合句意。", "放": "搭配：“放”不用于检查字的对错，不说放字。", "倒": "搭配：“倒”不能用于字，不说倒这几个字。", "扔": "语义：“扔”与“看字写得对不对”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "校对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师在校对菜。", "explanation": "这里应该用〈切〉。校对用于文字，切菜应说切。"}, {"text": "他在校对衣服。", "explanation": "这里应该用〈穿〉。校对不能用于衣服，穿衣服应说穿。"}, {"text": "农民在校对树苗。", "explanation": "这里应该用〈种〉。校对不能用于植物，种树苗应说种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王校对了完那张纸。", "corrected_sentence": "小王校对完了那张纸。", "error_description": "补语与体标错误：“完”是“校对”的结果补语，“了”要放在“完”之后，应说“校对完了”，不能说“校对了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在校对了我的作业。", "corrected_sentence": "妈妈正在校对我的作业。", "error_description": "体标错误：“正在”表示动作正在进行，不能和“了”一起用，应说“妈妈正在校对我的作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
