INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对照原稿检查文字、图表等有无错误并加以订正。", "primary_collocate": null, "pronunciation": "jiào duì", "ipa": "tɕjɑʊ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这篇文章发给读者前，要先校对一遍。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是校对书里的错字。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份合同再校对一次。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑正在对照原稿校对文章。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校对图表时，他发现数字写错了。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校对完以后，报纸才能印出来。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书校对了三次，还是有错。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们互相校对作文。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上校对一遍明天要用的材料。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她校对得很认真，一个字都没漏。", "target_word": "校对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "校对了", "label": "体标"}, {"form": "校对过", "label": "体标"}, {"form": "校对校对", "label": "重叠"}], "register": "书面", "sense_fingerprint": "对照原稿检查文字图表并订正错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校对", "is_correct": true, "explanation": "对照原稿检查文字错误，符合句意。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开刊登，与“发给读者前”的先后顺序矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于文章，不说唱文章。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于场地或物品，不说打扫文章。"}], "explanations": {"校对": "对照原稿检查文字错误，符合句意。", "发表": "语义：“发表”指公开刊登，与“发给读者前”的先后顺序矛盾。", "唱": "搭配：“唱”不能用于文章，不说唱文章。", "打扫": "搭配：“打扫”用于场地或物品，不说打扫文章。"}, "sentence_index": 0, "correct_answer": "校对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在校对病人的身体。", "explanation": "这里应该用〈检查〉。校对只用于文字、图表等书面材料，不能用于身体。"}, {"text": "他正在校对花园里的花。", "explanation": "这里应该用〈浇〉。校对是检查文字、图表的错误，不能用于花，给花浇水应说浇。"}, {"text": "工人正在校对电脑。", "explanation": "这里应该用〈修理〉。校对是查找文字错误，不能用于修理电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校对", "is_correct": true, "explanation": "检查这本书的错误并改正，符合句意。"}, {"text": "睡", "is_correct": false, "explanation": "语义：书不会睡觉，句意不通。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”不能用于书，不说书跑了三次。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能用于书，不说书跳了三次。"}], "explanations": {"校对": "检查这本书的错误并改正，符合句意。", "睡": "语义：书不会睡觉，句意不通。", "跑": "搭配：“跑”不能用于书，不说书跑了三次。", "跳": "搭配：“跳”不能用于书，不说书跳了三次。"}, "sentence_index": 6, "correct_answer": "校对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她校对了一首歌。", "explanation": "这里应该用〈听〉。校对用于文字材料，不能用于歌曲，应说听歌。"}, {"text": "她校对了一场比赛。", "explanation": "这里应该用〈看〉。校对用于文字和图表，不能用于比赛；观看比赛应说看。"}, {"text": "她校对了一碗饭。", "explanation": "这里应该用〈吃〉。校对不能用于饭，应说吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正在校对了稿子。", "corrected_sentence": "她正在校对稿子。", "error_description": "体标错误：“正在”表示动作进行，不能与“了”同用，应说“她正在校对稿子。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把稿子再校校对对吧。", "corrected_sentence": "你把稿子再校对校对吧。", "error_description": "重叠错误：双音节动词“校对”重叠应为ABAB式“校对校对”，不能说“校校对对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放电", "is_correct": true, "explanation": "“放电”与“充电”相对，指电池释放电能。"}, {"text": "写字", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}, {"text": "跑步", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}], "correct_answer": "放电", "explanations": {"放电": "“放电”与“充电”相对，指电池释放电能。", "写字": "与“充电”没有反义关系，不在任何义项上相反。", "跑步": "与“充电”没有反义关系，不在任何义项上相反。", "睡觉": "与“充电”没有反义关系，不在任何义项上相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放电", "is_correct": true, "explanation": "“放电”与“充电”相对，指电池释放电能。"}, {"text": "打开", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}, {"text": "修理", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}, {"text": "散步", "is_correct": false, "explanation": "与“充电”没有反义关系，不在任何义项上相反。"}], "correct_answer": "放电", "explanations": {"放电": "“放电”与“充电”相对，指电池释放电能。", "打开": "与“充电”没有反义关系，不在任何义项上相反。", "修理": "与“充电”没有反义关系，不在任何义项上相反。", "散步": "与“充电”没有反义关系，不在任何义项上相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "充电是给电池或手机补上电。", "primary_collocate": null, "pronunciation": "chōng diàn", "ipa": "tʂʰʊŋ˥ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我的手机没电了，要充电。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上睡觉前，我给手机充电。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机正在充电，你等一下再打。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电池充电要三个小时。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的电脑已经充电了吗？", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门以前，请先给平板电脑充电。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机在充电的时候，别玩游戏。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办公室里有地方可以充电吗？", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找个地方给电动车充电。", "target_word": "充电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手机放在桌子上充电。", "target_word": "充电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "充了电", "label": "体标（了）"}, {"form": "充过电", "label": "体标（过）"}, {"form": "充电器", "label": "复合"}, {"form": "充电宝", "label": "复合"}], "register": "中性", "sense_fingerprint": "给电池、手机等设备补充电量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充电", "is_correct": true, "explanation": "“充电”表示给手机补充电能，与“没电了”的语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与手机没电无关，不能用来表示补电。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”只用于人，不能说手机洗澡。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：手机不能跑步，这里要表达的是补电。"}], "explanations": {"充电": "“充电”表示给手机补充电能，与“没电了”的语境相符。", "唱歌": "语义：“唱歌”与手机没电无关，不能用来表示补电。", "洗澡": "搭配：“洗澡”只用于人，不能说手机洗澡。", "跑步": "语义：手机不能跑步，这里要表达的是补电。"}, "sentence_index": 0, "correct_answer": "充电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车没油了，要去充电。", "explanation": "这里应该用〈加油〉。汽车靠汽油行驶，要用“加油”；“充电”用于电池、手机等蓄电设备。"}, {"text": "我的手机卡没钱了，要去给它充电。", "explanation": "这里应该用〈充值〉。给手机卡、银行卡补钱要说“充值”；“充电”只用于补充电能。"}, {"text": "这台冰箱不制冷了，要去充电。", "explanation": "这里应该用〈修理〉。冰箱不制冷要修理；“充电”只用于电池、手机等蓄电设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充电", "is_correct": true, "explanation": "“充电”表示给手机补充电能，与“别玩游戏”的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：手机不能散步，这里说的是给手机补电。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：手机不吃饭，句子说的是补电。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：手机不会“喜欢”，这里说的是给手机补电。"}], "explanations": {"充电": "“充电”表示给手机补充电能，与“别玩游戏”的语境相符。", "散步": "语义：手机不能散步，这里说的是给手机补电。", "吃饭": "语义：手机不吃饭，句子说的是补电。", "喜欢": "语义：手机不会“喜欢”，这里说的是给手机补电。"}, "sentence_index": 6, "correct_answer": "充电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "轮胎没气了，要去充电。", "explanation": "这里应该用〈打气〉。给轮胎补充气体要说“打气”；“充电”用于电池等蓄电设备。"}, {"text": "这辆自行车的链条有点涩，该充电了。", "explanation": "这里应该用〈上油〉。链条发涩要上油；“充电”只用于电池等蓄电设备。"}, {"text": "这些花很干，需要充电。", "explanation": "这里应该用〈浇水〉。给花补充水分要说“浇水”；“充电”只用于蓄电装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的平板还没充了电，你先用手机吧。", "corrected_sentence": "我的平板还没充电，你先用手机吧。", "error_description": "错误：“还没充了电”。正确：“还没充电”。“没”否定动作时，动词后不能再带“了”；“没电了”表示状态，不属此类。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把平板在床头充电。", "corrected_sentence": "他把平板放在床头充电。", "error_description": "错误：“把平板在床头充电”。正确：“把平板放在床头充电”。“把”字句中“在床头”表示处所，前面需要有动词“放”，把平板放到床头，不能直接把“在”接在宾语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
