INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词,用于句末,表示过去曾经发生的事,有时用于追问。", "primary_collocate": null, "pronunciation": "lái zhe", "ipa": "lai˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "他前天去哪儿来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是谁的来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在哪儿见过你来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚才在聊什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的生日是几号来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚才还在找你来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候学过画画来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店叫什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们上周看的电影叫什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁昨天给你打电话来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "来着:语气助词:句末,表过去曾发生的事,可追问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
