INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88815, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "条文是一条一条写下来的规定。", "primary_collocate": null, "pronunciation": "tiáo wén", "ipa": "tʰjɑʊ˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这份规定的条文写得很清楚。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把条文贴在了墙上。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先读一读这些条文。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的条文一共有十条。", "target_word": "条文", "complexity_tier": "T3", "furigana": "zhè cì bǐ sài de tiáo wén yí gòng yǒu shí tiáo", "sentence_source": "generated"}, {"text": "这条条文的意思不难懂。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条文里写着，迟到三次要扣分。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房前，要看清合同的条文。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公司的条文都背下来了。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些条文是大家一起写的。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条文太长，我一时记不住。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "法律条文", "label": "复合"}], "register": "中性", "sense_fingerprint": "一条一条写下来的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图片", "is_correct": false, "explanation": "搭配：图片要说“画”或“拍”，不说“写”，而且规定里不会有图片。"}, {"text": "条文", "is_correct": true, "explanation": "正确：规定中分条写下的文字可以“写得很清楚”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是规定里分条写下的内容，不能“写得很清楚”。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是位置，不是可以“写得很清楚”的文字内容。"}], "explanations": {"图片": "搭配：图片要说“画”或“拍”，不说“写”，而且规定里不会有图片。", "条文": "正确：规定中分条写下的文字可以“写得很清楚”。", "天气": "语义：天气不是规定里分条写下的内容，不能“写得很清楚”。", "座位": "语义：座位是位置，不是可以“写得很清楚”的文字内容。"}, "sentence_index": 0, "correct_answer": "条文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "条文讲的是小红的故事。", "explanation": "这里应该用〈课文〉。条文是法规中分条写下的规定，讲故事的是课文，不是条文。"}, {"text": "这把条文我还没看完。", "explanation": "量词用错。条文应该用〈条〉计量，〈把〉用于有把手的东西，不能用在条文上。"}, {"text": "这只条文太长，大家都记不住。", "explanation": "量词用错。〈只〉用于动物或成对器官中的一个，条文应该用〈条〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "搭配：味道要说“闻”或“尝”，不能用“看清”。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：合同里不会有花朵，句子说的是“看清”合同内容。"}, {"text": "条文", "is_correct": true, "explanation": "正确：租房前要看清的是合同中分条写下的内容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：合同的内容里不会有窗户，这个搭配讲不通。"}], "explanations": {"味道": "搭配：味道要说“闻”或“尝”，不能用“看清”。", "花朵": "语义：合同里不会有花朵，句子说的是“看清”合同内容。", "条文": "正确：租房前要看清的是合同中分条写下的内容。", "窗户": "语义：合同的内容里不会有窗户，这个搭配讲不通。"}, "sentence_index": 6, "correct_answer": "条文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣上有很多红色的条文。", "explanation": "同音误用：花纹应说〈条纹〉。条文指法规等分条写下的文字，不指毛衣上的图案。"}, {"text": "妈妈把条文切成了小段，放进锅里。", "explanation": "搭配错误：〈条文〉是写下来的文字，不能用“切”，切的是面条之类的食物。"}, {"text": "他把条文当成被子，盖在身上睡觉。", "explanation": "语义错误：这里把〈条文〉当成了“盖在身上取暖的织物”的意思，而〈条文〉指法规等分条写下的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同的三只条文我都看了。", "corrected_sentence": "这份合同的三条条文我都看了。", "error_description": "量词用错：条文应该用量词“条”，“只”用于动物等，不能用于条文。正确说法是“三条条文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把一块条文抄下来了。", "corrected_sentence": "妹妹把一条条文抄下来了。", "error_description": "量词用错：条文应该用量词“条”，“块”用于块状的东西，不能用于条文。正确说法是“一条条文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
