INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律、规章等分条列出的文字。", "primary_collocate": null, "pronunciation": "tiáo wén", "ipa": "tʰjɑʊ˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "法律条文有时很难懂。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师仔细读了合同的条文。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法的条文已经公布了。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条条文说明了公民应该做什么。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按条文办事，不要随便改。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官在法庭上读出了相关条文。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪法的条文写得简单清楚。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部规章的条文一共有五十条。", "target_word": "条文", "complexity_tier": "T3", "furigana": "zhè bù guī zhāng de tiáo wén yí gòng yǒu wǔ shí tiáo", "sentence_source": "generated"}, {"text": "他对照条文，发现公司做错了。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上学习交通法规的条文。", "target_word": "条文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "法律条文", "label": "复合"}], "register": "书面", "sense_fingerprint": "法律、规章中分条列出的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是需要“懂”的内容，法律里没有这种东西。"}, {"text": "条文", "is_correct": true, "explanation": "正确：法律中分条写下的文字，才会“难懂”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是法律的一部分，句子讲的是法律文字。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能用“难懂”来形容，应说“好闻”或“难闻”。"}], "explanations": {"颜色": "语义：颜色不是需要“懂”的内容，法律里没有这种东西。", "条文": "正确：法律中分条写下的文字，才会“难懂”。", "花园": "语义：花园不是法律的一部分，句子讲的是法律文字。", "味道": "搭配：“味道”不能用“难懂”来形容，应说“好闻”或“难闻”。"}, "sentence_index": 0, "correct_answer": "条文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的条文很好听。", "explanation": "这里应该用〈歌词〉。条文是法规中分条写的文字，不能用来说歌好听。"}, {"text": "这把条文我看了很久。", "explanation": "量词用错。条文应该用〈条〉计量，〈把〉用于有把手的东西。"}, {"text": "这只条文太长，大家都没读完。", "explanation": "量词用错。〈只〉用于动物或成对器官中的一个，条文应该用〈条〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "搭配：脚步要说“轻”或“重”，不能说“写得简单清楚”。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：宪法里没有花朵，句子说的是文字的写法。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以“写得清楚”的内容，宪法里也不会有窗户。"}, {"text": "条文", "is_correct": true, "explanation": "正确：宪法中分条写下的文字可以“写得简单清楚”。"}], "explanations": {"脚步": "搭配：脚步要说“轻”或“重”，不能说“写得简单清楚”。", "花朵": "语义：宪法里没有花朵，句子说的是文字的写法。", "窗户": "语义：窗户不是可以“写得清楚”的内容，宪法里也不会有窗户。", "条文": "正确：宪法中分条写下的文字可以“写得简单清楚”。"}, "sentence_index": 6, "correct_answer": "条文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣上有很多红色的条文。", "explanation": "同音误用：毛衣上的花纹应说〈条纹〉。条文指法规等分条写下的文字。"}, {"text": "妈妈把条文切成了小段，放进锅里。", "explanation": "搭配错误：〈条文〉是写下来的文字，不能用“切”，切的是食物。"}, {"text": "他把条文当成被子，盖在身上睡觉。", "explanation": "语义错误：这里把〈条文〉当成了“盖在身上取暖的织物”的意思，而〈条文〉指法规等分条写下的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了这三只条文。", "corrected_sentence": "我读了这三条条文。", "error_description": "量词用错：条文应该用量词“条”，不能用“只”。正确说法是“这三条条文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们记下了这把条文。", "corrected_sentence": "同学们记下了这条条文。", "error_description": "量词用错：条文应该用量词“条”，“把”用于有把手的东西，不能用于条文。正确说法是“这条条文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
