INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88817, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公民社会是政府和市场以外，大家自愿组织起来一起做事的领域。", "primary_collocate": null, "pronunciation": "gōng mín shè huì", "ipa": "kʊŋ˥ min˧˥ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 4, "sentences": [{"text": "我们可以在公民社会里为身边的人做点事。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公民社会里，人们自己组织起来帮助别人。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公民社会里，大家自愿组织起来做事。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的公民社会很活跃，很多人常常一起做公益。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让社会变好，需要有力量的公民社会。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的公民社会越来越热闹了。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人在公民社会中学会了合作。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民社会需要每个人出一点力。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公民社会里做了很多年志愿者。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了公民社会，小问题可以自己解决。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大家自愿组织起来，一起做对大家好的事的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公民社会", "is_correct": true, "explanation": "正确：“公民社会”指公民自愿组织起来做事的领域，与“在……里为身边的人做点事”相符。"}, {"text": "股市", "is_correct": false, "explanation": "语义：“股市”是买卖股票的市场，不是可以为身边的人做点事的地方。"}, {"text": "字典", "is_correct": false, "explanation": "语义：“字典”是工具书，不是可以为身边的人做事的场所。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是报酬，不能放在“在……里”之后作做事的场所。"}], "explanations": {"公民社会": "正确：“公民社会”指公民自愿组织起来做事的领域，与“在……里为身边的人做点事”相符。", "股市": "语义：“股市”是买卖股票的市场，不是可以为身边的人做点事的地方。", "字典": "语义：“字典”是工具书，不是可以为身边的人做事的场所。", "工资": "搭配：“工资”是报酬，不能放在“在……里”之后作做事的场所。"}, "sentence_index": 0, "correct_answer": "公民社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天傍晚都在公民社会里散步，很放松。", "explanation": "这里应该用〈社区〉。公民社会是公民自愿做事的领域，不是可以散步的地方，应说“在社区里散步”。"}, {"text": "我参加了一个公民社会，每周末去做志愿服务。", "explanation": "这里应该用〈社团〉。公民社会泛指一个领域，不是可以加入的具体团体，“参加”后应接〈社团〉。"}, {"text": "学生们在公民社会里自习。", "explanation": "这里应该用〈图书馆〉。公民社会不是自习的场所，应说“在图书馆里自习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公民社会", "is_correct": true, "explanation": "正确：“公民社会”指公民自愿组织起来做事的领域，可以作为年轻人学会合作的场所。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是储存食物的家电，不能让人在其中学会合作。"}, {"text": "香皂", "is_correct": false, "explanation": "搭配：“香皂”是清洁用品，不能作“在……中”的场所。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”是书写用的液体，不是学习合作的场所。"}], "explanations": {"公民社会": "正确：“公民社会”指公民自愿组织起来做事的领域，可以作为年轻人学会合作的场所。", "冰箱": "语义：“冰箱”是储存食物的家电，不能让人在其中学会合作。", "香皂": "搭配：“香皂”是清洁用品，不能作“在……中”的场所。", "墨水": "语义：“墨水”是书写用的液体，不是学习合作的场所。"}, "sentence_index": 6, "correct_answer": "公民社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公民社会今年收治了很多病人。", "explanation": "这里应该用〈医院〉。公民社会是政府和市场之外的领域，不收治病人；“收治病人”是医院的职能，应说“医院今年收治了很多病人”。"}, {"text": "公民社会每个月给员工发工资。", "explanation": "这里应该用〈公司〉。公民社会是自愿做事的领域，没有员工，不发工资；给员工发工资是公司的职能。"}, {"text": "公民社会今年新招了三十名老师。", "explanation": "这里应该用〈学校〉。公民社会不招聘老师，招老师是学校的职能，应说“学校今年新招了三十名老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一只活跃的公民社会。", "corrected_sentence": "这个城市有一个活跃的公民社会。", "error_description": "量词错误：“公民社会”是抽象的领域，应该用“个”，“只”只用于动物等，不能用于“公民社会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多年轻人公民社会中找到了自己的位置。", "corrected_sentence": "许多年轻人在公民社会中找到了自己的位置。", "error_description": "介词缺失：“公民社会”作地点时前面要加“在”，应说“在公民社会中”，去掉“在”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
