INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府和市场之外，由公民自愿组成的各种组织与活动的领域。", "primary_collocate": null, "pronunciation": "gōng mín shè huì", "ipa": "kʊŋ˥ min˧˥ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 4, "sentences": [{"text": "公民社会在政府和市场之外。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者说，公民社会是第三个领域。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民社会由自愿组成的团体构成。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府、市场和公民社会各有各的作用。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的公民社会发展得很快。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民社会里的人不是为了赚钱。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民社会的活动都是大家自愿参加的。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了公民社会的历史。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强大的公民社会可以监督政府。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究公民社会已经十年了。", "target_word": "公民社会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "政府和市场之外，公民自愿组成的组织与活动的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5711a20d-cc1d-4fa4-8418-82e7fbd4729e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公民社会", "is_correct": true, "explanation": "正确：“公民社会”是政府和市场之外的领域，与“在政府和市场之外”相符。"}, {"text": "政府", "is_correct": false, "explanation": "语义：句中“政府”已是与“市场”并列的一方，“政府在政府和市场之外”自相矛盾。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮品，不能与政府、市场并列作为社会领域。"}, {"text": "香皂", "is_correct": false, "explanation": "搭配：“香皂”是日用品，不能用来表示“在……之外”的社会领域。"}], "explanations": {"公民社会": "正确：“公民社会”是政府和市场之外的领域，与“在政府和市场之外”相符。", "政府": "语义：句中“政府”已是与“市场”并列的一方，“政府在政府和市场之外”自相矛盾。", "咖啡": "语义：“咖啡”是饮品，不能与政府、市场并列作为社会领域。", "香皂": "搭配：“香皂”是日用品，不能用来表示“在……之外”的社会领域。"}, "sentence_index": 0, "correct_answer": "公民社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公民社会由市长亲自领导，每周开一次会。", "explanation": "这里应该用〈政府部门〉。公民社会是政府和市场之外的领域，不受市长领导；“由市长领导、开会”说的是政府部门。"}, {"text": "这个公民社会每年参加一次国家考试。", "explanation": "这里应该用〈考生〉。公民社会是领域，不是个人，不能参加考试；应说「考生每年参加一次国家考试」。"}, {"text": "公民社会每年制定一部法律。", "explanation": "这里应该用〈立法机关〉。公民社会是政府和市场之外的领域，不负责立法；制定法律是立法机关的职能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公民社会", "is_correct": true, "explanation": "正确：“公民社会”指大家自愿参加各种活动的领域，与“活动都是大家自愿参加的”相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：“股票”是有价证券，不是大家自愿参加的活动。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是设备，没有让大家自愿参加的“活动”。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：“塑料”是材料，不是可以自愿参加的活动。"}], "explanations": {"公民社会": "正确：“公民社会”指大家自愿参加各种活动的领域，与“活动都是大家自愿参加的”相符。", "股票": "语义：“股票”是有价证券，不是大家自愿参加的活动。", "电梯": "语义：“电梯”是设备，没有让大家自愿参加的“活动”。", "塑料": "语义：“塑料”是材料，不是可以自愿参加的活动。"}, "sentence_index": 6, "correct_answer": "公民社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公民社会每年审理几千起案件。", "explanation": "这里应该用〈法院〉。公民社会是政府和市场之外的领域，不审理案件；审理案件是法院的职能，应说“法院每年审理几千起案件”。"}, {"text": "公民社会今年发行了三亿元国债。", "explanation": "这里应该用〈财政部〉。发行国债是政府财政部门的职能，公民社会不发行国债；应说「财政部今年发行了三亿元国债」。"}, {"text": "工程师修好了那个公民社会。", "explanation": "这里应该用〈电脑〉。公民社会是领域，不是机器，不能修理；“修好”的是电脑这类机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有一座独特的公民社会。", "corrected_sentence": "这个国家有一种独特的公民社会。", "error_description": "量词错误：“公民社会”是抽象的领域，应说“一种”，“座”用于山、建筑等大型固定的物体，不能用于抽象领域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们公民社会中积累了很多经验。", "corrected_sentence": "他们在公民社会中积累了很多经验。", "error_description": "介词缺失：表示地点的“公民社会”前要加“在”，应说“在公民社会中”，没有“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a537a9-2db8-4fc3-80ad-14935eb32aaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
