INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "依据是做判断或做事时所凭借的根据，能让人知道对不对。", "primary_collocate": null, "pronunciation": "yī jù", "ipa": "i˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "你说他错了，有什么依据？", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定没有科学依据。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律是法官判案的依据。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有依据的话，请不要乱说。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告给了我们重要的依据。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，做题要找到答案的依据。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要有依据才能说病人没事。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话有什么依据，我们不知道。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价格有什么依据吗？", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出一份合同作为依据。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词，做判断或做事所靠的根据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据（yī jù）表示做判断或做事所靠的根据。"}, {"text": "依序", "is_correct": false, "explanation": "依序（yī xù）第二音节声母不同（x 对 j），意思是按照顺序。"}, {"text": "一具", "is_correct": false, "explanation": "一具（yí jù）第一音节声调不同（yí 对 yī），是量词用法。"}, {"text": "依旧", "is_correct": false, "explanation": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。"}], "explanations": {"依据": "正确：依据（yī jù）表示做判断或做事所靠的根据。", "依序": "依序（yī xù）第二音节声母不同（x 对 j），意思是按照顺序。", "一具": "一具（yí jù）第一音节声调不同（yí 对 yī），是量词用法。", "依旧": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。"}, "sentence_index": null, "correct_answer": "依据"}, "level_3": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据指判断对错所凭的根据，符合「你说他错了，有什么依据」的语境。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：「脾气」指性情，与「说他错了」的判断无关，不能作为判断的根据。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或滋味，与判断对错无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：问「有什么……」时，「颜色」不能用来指判断所凭的根据。"}], "explanations": {"依据": "正确：依据指判断对错所凭的根据，符合「你说他错了，有什么依据」的语境。", "脾气": "语义：「脾气」指性情，与「说他错了」的判断无关，不能作为判断的根据。", "味道": "语义：「味道」指气味或滋味，与判断对错无关。", "颜色": "搭配：问「有什么……」时，「颜色」不能用来指判断所凭的根据。"}, "sentence_index": 0, "correct_answer": "依据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "没有依据的人很难生活，大家要帮帮他。", "explanation": "这里应该用〈依靠〉。依据指做判断的根据，不指生活中可以依靠的人或事物。"}, {"text": "妈妈是我生活的依据，我离不开她。", "explanation": "这里应该用〈依靠〉。依据指判断的根据，不指生活上可以依靠的人。"}, {"text": "这个说法很依据，你们可以相信。", "explanation": "这里应该用〈有依据〉。依据作名词，不能直接受「很」修饰，应说「很有依据」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88819, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据（yī jù）表示做判断或做事所靠的根据。"}, {"text": "一句", "is_correct": false, "explanation": "一句（yí jù）第一音节声调不同（yí 对 yī），意思是一句话。"}, {"text": "一举", "is_correct": false, "explanation": "一举（yī jǔ）第二音节声调不同（jǔ 对 jù），意思是一个行动、一下子。"}, {"text": "依旧", "is_correct": false, "explanation": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。"}], "explanations": {"依据": "正确：依据（yī jù）表示做判断或做事所靠的根据。", "一句": "一句（yí jù）第一音节声调不同（yí 对 yī），意思是一句话。", "一举": "一举（yī jǔ）第二音节声调不同（jǔ 对 jù），意思是一个行动、一下子。", "依旧": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。"}, "sentence_index": null, "correct_answer": "依据"}, "level_3": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据指医生判断病人没事所需的根据，符合语境。"}, {"text": "力气", "is_correct": false, "explanation": "语义：「力气」指体力，与医生判断病情的根据无关。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：「胃口」指食欲，与医生的判断无关。"}, {"text": "口音", "is_correct": false, "explanation": "语义：「口音」指说话的腔调，与医生判断病情的根据无关。"}], "explanations": {"依据": "正确：依据指医生判断病人没事所需的根据，符合语境。", "力气": "语义：「力气」指体力，与医生判断病情的根据无关。", "胃口": "语义：「胃口」指食欲，与医生的判断无关。", "口音": "语义：「口音」指说话的腔调，与医生判断病情的根据无关。"}, "sentence_index": 6, "correct_answer": "依据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿出一只依据，证明自己没有错。", "explanation": "这里应该用〈份〉或〈个〉。依据不用「只」，「只」多用于动物或成对的东西。"}, {"text": "他是我最好的依据，什么事都帮我。", "explanation": "这里应该用〈依靠〉。依据指判断的根据，不指能帮助自己的人。"}, {"text": "这棵大树是小鸟的依据，它们每天在上面休息。", "explanation": "这里应该用〈依靠〉。依据指判断的根据，不指可以栖身依靠的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你说这些话，有什么的依据？", "corrected_sentence": "你说这些话，有什么依据？", "error_description": "疑问代词「什么」修饰「依据」时，中间不加「的」。应说「有什么依据」，不能说「有什么的依据」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些数据是报告的重要依据们。", "corrected_sentence": "这些数据是报告的重要依据。", "error_description": "「依据」是抽象名词，不能加「们」表示复数，应说「重要依据」，不能说「重要依据们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
