INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88820, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以某种事物作为根据。", "primary_collocate": null, "pronunciation": "yī jù", "ipa": "i˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "医生依据检查结果决定怎么治。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师依据同学们的成绩分班。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察依据证据找到了小偷。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司依据规定给工人放假。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该依据事实说话。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他依据地图找到了那家饭店。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官依据法律做出了决定。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员依据名单叫大家进去。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校依据考试成绩发奖学金。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家依据数据判断明年会涨价。", "target_word": "依据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词，以某事物为根据来做判断或决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据（yī jù）表示以某事物作为根据。"}, {"text": "一句", "is_correct": false, "explanation": "一句（yí jù）第一音节声调不同（yí 对 yī），意思是一句话。"}, {"text": "依旧", "is_correct": false, "explanation": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。"}, {"text": "一举", "is_correct": false, "explanation": "一举（yī jǔ）第二音节声调不同（jǔ 对 jù），意思是一个行动、一下子。"}, {"text": "依序", "is_correct": false, "explanation": "依序（yī xù）第二音节声母不同（x 对 j），意思是按照顺序。"}], "explanations": {"依据": "正确：依据（yī jù）表示以某事物作为根据。", "一句": "一句（yí jù）第一音节声调不同（yí 对 yī），意思是一句话。", "依旧": "依旧（yī jiù）与依据的韵母不同（iu 对 ü），意思是仍然。", "一举": "一举（yī jǔ）第二音节声调不同（jǔ 对 jù），意思是一个行动、一下子。", "依序": "依序（yī xù）第二音节声母不同（x 对 j），意思是按照顺序。"}, "sentence_index": null, "correct_answer": "依据"}, "level_3": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据表示以检查结果为根据来决定治疗，符合语境。"}, {"text": "违反", "is_correct": false, "explanation": "搭配：「违反」一般搭配规定、法律，不说「违反检查结果」。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」表示不接受，与「决定怎么治」所依靠的检查结果相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：「忽略」表示不理会，与「依据检查结果决定治疗」的意思矛盾。"}], "explanations": {"依据": "正确：依据表示以检查结果为根据来决定治疗，符合语境。", "违反": "搭配：「违反」一般搭配规定、法律，不说「违反检查结果」。", "拒绝": "语义：「拒绝」表示不接受，与「决定怎么治」所依靠的检查结果相反。", "忽略": "语义：「忽略」表示不理会，与「依据检查结果决定治疗」的意思矛盾。"}, "sentence_index": 0, "correct_answer": "依据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民依据土地生活，不能离开。", "explanation": "这里应该用〈依靠〉。依据表示以某事物为根据，不表示靠某物生活或获得支持。"}, {"text": "藤蔓依据墙壁向上爬。", "explanation": "这里应该用〈依附〉。依据表示以某事物为根据，不表示像藤蔓一样附着在别物上。"}, {"text": "她依据自己的美貌，不肯认真学习。", "explanation": "这里应该用〈依仗〉。依据表示以某事物为根据，不表示倚仗某种优势而自恃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88820, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据（yī jù）表示以某事物作为根据。"}, {"text": "一局", "is_correct": false, "explanation": "一局（yì jú）两个音节的声调都不同，意思是一盘、一场，如「一局棋」。"}, {"text": "移居", "is_correct": false, "explanation": "移居（yí jū）两个音节的声调都不同，意思是搬到别处居住。"}, {"text": "一具", "is_correct": false, "explanation": "一具（yí jù）第一音节声调不同（yí 对 yī），是量词用法，意思是一件器具或一具遗体。"}], "explanations": {"依据": "正确：依据（yī jù）表示以某事物作为根据。", "一局": "一局（yì jú）两个音节的声调都不同，意思是一盘、一场，如「一局棋」。", "移居": "移居（yí jū）两个音节的声调都不同，意思是搬到别处居住。", "一具": "一具（yí jù）第一音节声调不同（yí 对 yī），是量词用法，意思是一件器具或一具遗体。"}, "sentence_index": null, "correct_answer": "依据"}, "level_3": {"options": [{"text": "依据", "is_correct": true, "explanation": "正确：依据表示法官判案时以法律为根据，符合语境。"}, {"text": "出卖", "is_correct": false, "explanation": "搭配：「出卖」一般不接「法律」这类抽象对象，不能说「出卖法律」。"}, {"text": "玩弄", "is_correct": false, "explanation": "语义：「玩弄」带有贬义，与法官依法做决定的身份不符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：「反对法律」与法官依法判案的身份相矛盾。"}], "explanations": {"依据": "正确：依据表示法官判案时以法律为根据，符合语境。", "出卖": "搭配：「出卖」一般不接「法律」这类抽象对象，不能说「出卖法律」。", "玩弄": "语义：「玩弄」带有贬义，与法官依法做决定的身份不符。", "反对": "语义：「反对法律」与法官依法判案的身份相矛盾。"}, "sentence_index": 6, "correct_answer": "依据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他依据父亲的权力欺负同学。", "explanation": "这里应该用〈依仗〉。依据表示以某事物为根据，不表示倚仗权势。"}, {"text": "小树依据大树生长。", "explanation": "这里应该用〈依附〉。依据不表示依附在某物上生长。"}, {"text": "孩子依据父母生活，不能独立。", "explanation": "这里应该用〈依赖〉。依据不表示依赖别人生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师依据修改了方案。", "corrected_sentence": "工程师依据图纸修改了方案。", "error_description": "依据是及物动词，后面须带它的对象「图纸」。省略对象后「依据修改了方案」中动词「依据」悬空，应说「依据图纸修改了方案」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判很依据规则判罚了这次犯规。", "corrected_sentence": "裁判依据规则判罚了这次犯规。", "error_description": "依据是动词，不能直接用「很」修饰，应去掉「很」，说「裁判依据规则判罚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
