INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼上是在楼的上面,是比这一层更高的地方。", "primary_collocate": null, "pronunciation": "lóu shàng", "ipa": "loʊ˧˥ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "楼上有人在跳舞,太吵了。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在楼上,你先上去吧。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的邻居每天晚上都弹钢琴。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到楼上去拿一下我的书包。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上传来了孩子的笑声。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在我家楼上。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的灯亮着,他应该在家。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在楼下等我,我去楼上拿东西。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上漏水了,我家天花板湿了。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在楼上叫我吃饭。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "相对于说话人所在楼层,更高的楼层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "搭配：“有人在跳舞”需要能容纳人活动的处所，“冰箱”不能与之搭配。"}, {"text": "楼上", "is_correct": true, "explanation": "楼上指比说话人所在楼层更高的地方，人可以在那里跳舞，与“太吵了”的情境相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以让人跳舞的处所，“月亮上有人在跳舞”与常识相悖。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是楼层，“树有人在跳舞”不成立，与“楼上”所指的上层空间无关。"}], "explanations": {"冰箱": "搭配：“有人在跳舞”需要能容纳人活动的处所，“冰箱”不能与之搭配。", "楼上": "楼上指比说话人所在楼层更高的地方，人可以在那里跳舞，与“太吵了”的情境相符。", "月亮": "语义：月亮不是可以让人跳舞的处所，“月亮上有人在跳舞”与常识相悖。", "树": "语义：树不是楼层，“树有人在跳舞”不成立，与“楼上”所指的上层空间无关。"}, "sentence_index": 0, "correct_answer": "楼上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书在桌子楼上。", "explanation": "这里应该用〈上面〉。“楼上”只指楼房的上层，桌上的东西要用“上面”，不能说“桌子楼上”。"}, {"text": "箱子的楼上有一件衣服。", "explanation": "这里应该用〈上边〉。“楼上”只指楼房的上层，箱子不是楼房，应说“箱子的上边”。"}, {"text": "墙楼上挂着一幅画。", "explanation": "这里应该用〈上头〉。“楼上”只指楼房的上层，墙面的上部要说“墙上”或“墙上头”，不能说“墙楼上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "搭配：太阳不是房间，“太阳的灯”不能成立，与“灯亮着”搭配不上。"}, {"text": "楼上", "is_correct": true, "explanation": "楼上指比说话人所在楼层更高的地方，灯可以在那里亮着，与“他应该在家”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校的灯亮着说明他可能在学校，与“他应该在家”矛盾。"}, {"text": "河", "is_correct": false, "explanation": "搭配：灯不能附着在河上，“河的灯”不是常见说法，与“灯亮着”不搭。"}], "explanations": {"太阳": "搭配：太阳不是房间，“太阳的灯”不能成立，与“灯亮着”搭配不上。", "楼上": "楼上指比说话人所在楼层更高的地方，灯可以在那里亮着，与“他应该在家”相符。", "学校": "语义：学校的灯亮着说明他可能在学校，与“他应该在家”矛盾。", "河": "搭配：灯不能附着在河上，“河的灯”不是常见说法，与“灯亮着”不搭。"}, "sentence_index": 6, "correct_answer": "楼上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屏幕楼上有一行字。", "explanation": "这里应该用〈上方〉。“楼上”只指楼房的上层，屏幕上的位置要说“上方”，不能说“楼上”。"}, {"text": "草地楼上有一座庙。", "explanation": "这里应该用〈草地上〉。“楼上”只指楼房的上层，草地不是楼房，表示位置要说“草地上”，不能说“草地楼上”。"}, {"text": "杯子楼上有一层灰。", "explanation": "这里应该用〈杯子上〉。“楼上”只指楼房的上层，杯子不是楼房，表示位置要说“杯子上”，不能说“杯子楼上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我往楼上写作业。", "corrected_sentence": "我在楼上写作业。", "error_description": "错误：“往楼上写作业”。正确：“在楼上写作业”。“楼上”表示动作发生的处所，要用“在”引出；“往”表示动作的方向，只能与移动动词搭配，“写作业”不是移动动作，不能用“往”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在楼上下来了。", "corrected_sentence": "他从楼上下来了。", "error_description": "错误：“在楼上下来”。正确：“从楼上下来”。“楼上”作动作的起点时要用“从”引出；“在”只表示静止的处所，不能与表示移动的“下来”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
