INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼房的上层。", "primary_collocate": null, "pronunciation": "lóu shàng", "ipa": "loʊ˧˥ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这栋房子楼上是卧室,楼下是客厅。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店楼上是餐厅,楼下是商店。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上比楼下安静,我睡在楼上。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的楼上有两间小屋。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店楼上可以看到整条街。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家楼上住人,楼下开店。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店楼上卖外文书,楼下卖小说。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的房间夏天比较热。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小楼,楼上的窗户特别大。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别墅的楼上有一个大阳台。", "target_word": "楼上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "楼房中位于下层之上的部分,常与楼下对举", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能作卧室，与“是卧室”冲突。"}, {"text": "楼上", "is_correct": true, "explanation": "楼上指楼房的上层，与“楼下是客厅”相对，卧室在上层，符合句意。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶不是可以住人的房间，“屋顶是卧室”不成立。"}, {"text": "楼房", "is_correct": false, "explanation": "搭配：“楼房”指整栋建筑，与“这栋房子”重复，不能作“是卧室”的处所。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，不能作卧室，与“是卧室”冲突。", "楼上": "楼上指楼房的上层，与“楼下是客厅”相对，卧室在上层，符合句意。", "屋顶": "语义：屋顶不是可以住人的房间，“屋顶是卧室”不成立。", "楼房": "搭配：“楼房”指整栋建筑，与“这栋房子”重复，不能作“是卧室”的处所。"}, "sentence_index": 0, "correct_answer": "楼上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架楼上有一本词典。", "explanation": "这里应该用〈上面〉。“楼上”只指楼房的上层，书架上的物品要说“上面”，不能说“书架楼上”。"}, {"text": "床的楼上挂着蚊帐。", "explanation": "这里应该用〈上边〉。“楼上”只指楼房的上层，床不是楼房，应说“床的上边”。"}, {"text": "山楼上有一棵大树。", "explanation": "这里应该用〈山上〉。“楼上”只指楼房的上层，山不是楼房，表示位置要说“山上”，不能说“山楼上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停车场", "is_correct": false, "explanation": "语义：停车场不能卖书，与“卖外文书”冲突。"}, {"text": "楼上", "is_correct": true, "explanation": "楼上指楼房的上层，与“楼下卖小说”相对，外文书在上层，符合句意。"}, {"text": "水池", "is_correct": false, "explanation": "语义：水池不能卖书，“水池卖外文书”与常识相悖。"}, {"text": "山顶", "is_correct": false, "explanation": "搭配：“山顶”不是书店的一部分，与“楼下卖小说”的上下对举不能搭配。"}], "explanations": {"停车场": "语义：停车场不能卖书，与“卖外文书”冲突。", "楼上": "楼上指楼房的上层，与“楼下卖小说”相对，外文书在上层，符合句意。", "水池": "语义：水池不能卖书，“水池卖外文书”与常识相悖。", "山顶": "搭配：“山顶”不是书店的一部分，与“楼下卖小说”的上下对举不能搭配。"}, "sentence_index": 6, "correct_answer": "楼上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "照片楼上有一行字。", "explanation": "这里应该用〈上方〉。“楼上”只指楼房的上层，照片上的位置要说“上方”，不能说“照片楼上”。"}, {"text": "湖水楼上漂着一条船。", "explanation": "这里应该用〈水面上〉。“楼上”只指楼房的上层，湖水不是楼房，表示位置要说“水面上”，不能说“湖水楼上”。"}, {"text": "墙头楼上有一只猫。", "explanation": "这里应该说“墙头上”。“楼上”只指楼房的上层，墙头的位置不能用“楼上”表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐往楼上住。", "corrected_sentence": "我姐姐在楼上住。", "error_description": "错误：“往楼上住”。正确：“在楼上住”。“往”表示动作的朝向，“住”是静止的居住，处所要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们到楼上跑下来了。", "corrected_sentence": "孩子们从楼上跑下来了。", "error_description": "错误：“到楼上跑下来”。正确：“从楼上跑下来”。表示动作的起点要用“从”引出；“到”引出终点，与“跑下来”（向说话人所在处移动）的方向矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
