INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出入是进去又出来，来来去去。", "primary_collocate": null, "pronunciation": "chū rù", "ipa": "tʂʰu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "车站里人来人往，大家不停地出入。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门口每天有很多人出入。", "target_word": "出入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们放学后都从这个院门出入。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上商店里出入的客人特别多。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一整天都在各个办公室之间出入，没有休息。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口出入的车很多，要小心。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末超市的人出入不断。", "target_word": "出入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们从这个小门出入工地。", "target_word": "出入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只小狗从门下的小洞出入，一会儿进一会儿出。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行里出入的人很多，大家都排着队。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "出入：人或车来来去去，进去又出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出入", "is_correct": true, "explanation": "正确。“出入”指人或车来来去去，与“人来人往，大家不停地”相符。"}, {"text": "停留", "is_correct": false, "explanation": "搭配：“不停地”修饰持续的动作，“停留”本身含有停下的意思，不能说“不停地停留”。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”指停下不动，与“人来人往”的移动场景相矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指降生，与车站里人群来回走动的情境毫不相关。"}], "explanations": {"出入": "正确。“出入”指人或车来来去去，与“人来人往，大家不停地”相符。", "停留": "搭配：“不停地”修饰持续的动作，“停留”本身含有停下的意思，不能说“不停地停留”。", "休息": "语义：“休息”指停下不动，与“人来人往”的移动场景相矛盾。", "出生": "语义：“出生”指降生，与车站里人群来回走动的情境毫不相关。"}, "sentence_index": 0, "correct_answer": "出入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家出版社每年出入很多书。", "explanation": "这里应该用〈出版〉。出入指进出某处，不能用来说出版社编印并发行书籍，说出书要用“出版”。"}, {"text": "屏幕上突然出入了一行字。", "explanation": "这里应该用〈出现〉。出入指进出某处，不能用来说文字突然显示出来。"}, {"text": "双方昨天出入了合同。", "explanation": "这里应该用〈签订〉。出入指进出或往来，不能用来说双方在文件上签字订立合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出入", "is_correct": true, "explanation": "正确。“出入”指人来人往地进出，与“周末超市的人…不断”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与超市里人来人往的情境不符，句子说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是个人行为，不能用来形容超市里的人群。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“不断”表示持续，与“停止”意思相反，不能说“停止不断”。"}], "explanations": {"出入": "正确。“出入”指人来人往地进出，与“周末超市的人…不断”相符。", "睡觉": "语义：“睡觉”与超市里人来人往的情境不符，句子说不通。", "洗澡": "语义：“洗澡”是个人行为，不能用来形容超市里的人群。", "停止": "搭配：“不断”表示持续，与“停止”意思相反，不能说“停止不断”。"}, "sentence_index": 6, "correct_answer": "出入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于出入了这个难题。", "explanation": "这里应该用〈解决〉。出入是进出某处的意思，不能用来说处理难题。"}, {"text": "他积极出入公益活动。", "explanation": "这里应该用〈参与〉。出入不能表示参加活动，说参加要用“参与”。"}, {"text": "他很快出入了篮球队。", "explanation": "这里应该用〈加入〉。出入指进出某处，不表示成为某个组织的成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车辆每天出入了学校。", "corrected_sentence": "车辆每天出入学校。", "error_description": "“每天”表示经常性动作，“出入”后不能加“了”表示完成。应去掉“了”，说“每天出入学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里实验室不把外人出入。", "corrected_sentence": "夜里实验室不让外人出入。", "error_description": "“出入”不能用于“把”字句处置“外人”，应把“把”改为“让”，说“夜里实验室不让外人出入。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
