INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出去和进来；往来。", "primary_collocate": null, "pronunciation": "chū rù", "ipa": "tʂʰu˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "请大家出入时注意安全。", "target_word": "出入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有卡的人不能出入这栋楼。", "target_word": "出入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里是公园的大门，出入很方便。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区门口有人检查出入的车辆。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上这个仓库很少有人出入。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人出入需要人帮忙，要有电梯。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的学生出入都要刷卡。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常出入图书馆，认识很多书友。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店晚上不让外人出入。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间里很安静，没有人出入。", "target_word": "出入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "出入：从某处出去、进来，往来于某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出入", "is_correct": true, "explanation": "正确。“出入”指进出，与“请大家…时注意安全”的活动情境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指降生，与“注意安全”的活动无关，句子说不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状态，不是需要提醒“注意安全”的进出活动；生病时一般说“注意休息”。"}, {"text": "睡着", "is_correct": false, "explanation": "搭配：“睡着”是结果补语，不能接“…时注意安全”这种表示动作时段的结构。"}], "explanations": {"出入": "正确。“出入”指进出，与“请大家…时注意安全”的活动情境相符。", "出生": "语义：“出生”指降生，与“注意安全”的活动无关，句子说不通。", "生病": "语义：“生病”是身体状态，不是需要提醒“注意安全”的进出活动；生病时一般说“注意休息”。", "睡着": "搭配：“睡着”是结果补语，不能接“…时注意安全”这种表示动作时段的结构。"}, "sentence_index": 0, "correct_answer": "出入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他顺利出入了一所名牌大学。", "explanation": "这里应该用〈进入〉。出入指往来于某处，不能用来说考入或进入某个机构。"}, {"text": "他出入了很多朋友。", "explanation": "这里应该用〈结交〉。出入不能带人作宾语，说交朋友要用“结交”。"}, {"text": "他去年出入了三篇论文。", "explanation": "这里应该用〈发表〉。出入指进出或往来，不能用来说把文章公开刊登出来，说发表论文要用“发表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出入", "is_correct": true, "explanation": "正确。“出入”指进出，与“学生…都要刷卡”的校园门禁情境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与刷卡进出校园的动作无关，句子说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是私人行为，与校园刷卡管理的场景不符。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“停止”不能与“都要刷卡”组成合理的动作，刷卡只用于进出。"}], "explanations": {"出入": "正确。“出入”指进出，与“学生…都要刷卡”的校园门禁情境相符。", "散步": "语义：“散步”与刷卡进出校园的动作无关，句子说不通。", "洗澡": "语义：“洗澡”是私人行为，与校园刷卡管理的场景不符。", "停止": "搭配：“停止”不能与“都要刷卡”组成合理的动作，刷卡只用于进出。"}, "sentence_index": 6, "correct_answer": "出入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他积极出入这次比赛。", "explanation": "这里应该用〈参加〉。出入指进出某处，比赛不是可以进出的场所，说参加比赛要用“参加”。"}, {"text": "警察出入了这名证人。", "explanation": "这里应该用〈保护〉。出入是进出的意思，不能带人作宾语表示照顾或守护。"}, {"text": "爱迪生出入了电灯。", "explanation": "这里应该用〈发明〉。出入不表示创造新事物，说创造新东西要用“发明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家把出入电梯时要注意安全。", "corrected_sentence": "大家出入电梯时要注意安全。", "error_description": "“把”字句中不能把“出入”直接放在“把”后作动词，“把出入电梯”结构错误，应删去“把”，说“大家出入电梯时要注意安全。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个门禁系统只把本单位员工出入。", "corrected_sentence": "这个门禁系统只让本单位员工出入。", "error_description": "“出入”不能用于“把”字句处置“员工”，应把“把”改为“让”，说“这个门禁系统只让本单位员工出入。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小月", "is_correct": true, "explanation": "正确。“小月”指公历中有三十天的月份，与“大月”相对。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”是一周中的休息时间，与“大月”没有反义关系。"}, {"text": "季度", "is_correct": false, "explanation": "“季度”指三个月的时间段，与“大月”没有反义关系。"}, {"text": "年份", "is_correct": false, "explanation": "“年份”指年的概念，与“大月”没有反义关系。"}], "correct_answer": "小月", "explanations": {"小月": "正确。“小月”指公历中有三十天的月份，与“大月”相对。", "周末": "“周末”是一周中的休息时间，与“大月”没有反义关系。", "季度": "“季度”指三个月的时间段，与“大月”没有反义关系。", "年份": "“年份”指年的概念，与“大月”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小月", "is_correct": true, "explanation": "正确。“小月”指公历中有三十天的月份，与“大月”相对。"}, {"text": "夏天", "is_correct": false, "explanation": "“夏天”是季节，与“大月”没有反义关系。"}, {"text": "年度", "is_correct": false, "explanation": "“年度”指一年的时间段，与“大月”没有反义关系。"}, {"text": "春节", "is_correct": false, "explanation": "“春节”是节日，与“大月”没有反义关系。"}], "correct_answer": "小月", "explanations": {"小月": "正确。“小月”指公历中有三十天的月份，与“大月”相对。", "夏天": "“夏天”是季节，与“大月”没有反义关系。", "年度": "“年度”指一年的时间段，与“大月”没有反义关系。", "春节": "“春节”是节日，与“大月”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公历中有三十一天的月份。", "primary_collocate": null, "pronunciation": "dà yuè", "ipa": "ta˥˩ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "公历中的一月、三月都是大月。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历一年有七个大月。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历的大月有三十一天。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八月是公历的大月，天气很热。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历里，二月不是大月，它只有二十八或二十九天。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不住哪些是大月，常常要翻日历。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历里，四月不是大月，六月也不是。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学习了大月和小月的区别。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历里，下个月是大月，我们要多工作一天。", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公历里哪些月是大月，你分得清吗？", "target_word": "大月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "公历中有三十一天的月份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 公历 (Zipf 3.0), 二十八 (Zipf 3.15), 九天 (Zipf 3.59)']::text[], 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大月", "is_correct": true, "explanation": "正确。公历的一月、三月都有三十一天，属于大月。"}, {"text": "小月", "is_correct": false, "explanation": "语义：一月、三月有三十一天，是大月，不是小月。"}, {"text": "满月", "is_correct": false, "explanation": "搭配：“满月”指月亮圆，不作月份名称。"}, {"text": "阴历", "is_correct": false, "explanation": "语义：阴历是另一套历法，与句中“公历中”矛盾。"}], "explanations": {"大月": "正确。公历的一月、三月都有三十一天，属于大月。", "小月": "语义：一月、三月有三十一天，是大月，不是小月。", "满月": "搭配：“满月”指月亮圆，不作月份名称。", "阴历": "语义：阴历是另一套历法，与句中“公历中”矛盾。"}, "sentence_index": 0, "correct_answer": "大月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "六月是公历的大月，一共有三十天。", "explanation": "这里应该用〈小月〉。公历大月有三十一天，六月只有三十天，属于小月。"}, {"text": "这个大月天气很热，我们都不想出门。", "explanation": "这里应该用〈这个月〉。大月只指有三十一天的月份，不能泛指当前的月份。"}, {"text": "我记得一只公历大月有三十一天。", "explanation": "这里应该用〈个〉。量词〈只〉用于动物，不能用于月份，应说“一个大月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大月", "is_correct": true, "explanation": "正确。句子说公历的四月、六月都不是大月（它们各有三十天，属于小月），所以空缺处应填“大月”。"}, {"text": "农历", "is_correct": false, "explanation": "语义：句中说的是公历，公历里不用农历。"}, {"text": "旧历", "is_correct": false, "explanation": "语义：旧历指农历，是另一套历法，与句中“公历里”不符。"}, {"text": "夏历", "is_correct": false, "explanation": "语义：夏历是农历的古称，与句中“公历里”矛盾。"}], "explanations": {"大月": "正确。句子说公历的四月、六月都不是大月（它们各有三十天，属于小月），所以空缺处应填“大月”。", "农历": "语义：句中说的是公历，公历里不用农历。", "旧历": "语义：旧历指农历，是另一套历法，与句中“公历里”不符。", "夏历": "语义：夏历是农历的古称，与句中“公历里”矛盾。"}, "sentence_index": 6, "correct_answer": "大月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们常用“公历大月”来形容很大的东西。", "explanation": "“大月”是月份名称，不能当形容词用，表示东西很大应说“巨大”。"}, {"text": "公历一年里只有两个大月，其他都是小月。", "explanation": "公历一年有七个大月（一、三、五、七、八、十、十二月），不是两个。"}, {"text": "公历大月的最后一天是三十号。", "explanation": "这里应该用〈小月〉。大月的最后一天是三十一号，最后一天是三十号的月份属于小月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七月是公历的一本大月。", "corrected_sentence": "七月是公历的大月。", "error_description": "量词用错了。“本”是书册的量词，不能用于月份；可以说“公历的一个大月”，或不加量词说“公历的大月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十月是公历的很大月，天气已经凉了。", "corrected_sentence": "十月是公历的大月，天气已经凉了。", "error_description": "“大月”是名词，前面不能加副词“很”。应写作“公历的大月”，不能说“很大月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
