INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比较级是说这个比那个更怎么样的说法。", "primary_collocate": null, "pronunciation": "bǐ jiào jí", "ipa": "pi˨˩ tɕjɑʊ˥˩ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "今天老师教了比较级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比较级用来比较两个东西。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高的比较级是更高。", "target_word": "比较级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学汉语时，我先学了比较级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说“我比他高”，就是用了比较级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个句子里的比较级用得很好。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还不太会用比较级，常常说错。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学会比较级以后，你就能说“他比我大”了。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们用比较级写三个句子。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比较级可以让我们说清楚谁更好、谁更快。", "target_word": "比较级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比较级：说这个比那个更怎么样的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比较级", "is_correct": true, "explanation": "比较级是语法术语，老师可以教，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“教”的对象是知识，不能说“教天气”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“眼镜”不是可以教的内容，“教眼镜”不成立。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，老师不能教，与句意不合。"}], "explanations": {"比较级": "比较级是语法术语，老师可以教，与句意相符。", "天气": "搭配：“教”的对象是知识，不能说“教天气”。", "眼镜": "搭配：“眼镜”不是可以教的内容，“教眼镜”不成立。", "感冒": "语义：感冒是疾病，老师不能教，与句意不合。"}, "sentence_index": 0, "correct_answer": "比较级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "珠峰是世界上比较级的山。", "explanation": "这里应该用〈最高级〉。比较级只用于两者相比，说“世界上最高”要用最高级。"}, {"text": "“高”是比较级。", "explanation": "这里应该用〈形容词〉。“高”本身是形容词，比较级是形容词、副词的一种形式，不是“高”的词类。"}, {"text": "学汉语时，我先背了一首比较级。", "explanation": "这里应该用〈种〉。“首”用于诗歌、歌曲，比较级不这样计量，应说一种比较级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比较级", "is_correct": true, "explanation": "比较级是语法形式，“会用比较级”与“常常说错”相符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“说错”的对象应是语言或知识，眼泪说不上对错，与句意不合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“说错”的对象应是语言或知识，河流说不上对错，与句意不合。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“说错”的对象应是语言或知识，梦想说不上对错，与句意不合。"}], "explanations": {"比较级": "比较级是语法形式，“会用比较级”与“常常说错”相符。", "眼泪": "语义：“说错”的对象应是语言或知识，眼泪说不上对错，与句意不合。", "河流": "语义：“说错”的对象应是语言或知识，河流说不上对错，与句意不合。", "梦想": "语义：“说错”的对象应是语言或知识，梦想说不上对错，与句意不合。"}, "sentence_index": 6, "correct_answer": "比较级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的比较级很高，大家都很尊敬他。", "explanation": "这里应该用〈级别〉。级别指等级高低，比较级是语法形式，不能用来说人的级别。"}, {"text": "我终于学会了一张比较级。", "explanation": "这里不该用〈张〉。“张”用于平面的东西，比较级不这样计量。"}, {"text": "这次考试按比较级给分。", "explanation": "这里应该用〈等级〉。等级指评定的档次，比较级是语法形式，不能用来给分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先学了一首比较级，再学最高级。", "corrected_sentence": "他先学了比较级，再学最高级。", "error_description": "量词错误：“比较级”前不应加“一首”，“首”用于诗歌、歌曲。正确说法是“他先学了比较级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没弄懂一颗比较级，常常用错。", "corrected_sentence": "他还没弄懂比较级，常常用错。", "error_description": "量词错误：“比较级”前不应加“一颗”，“颗”用于小而圆的东西。正确说法是“他还没弄懂比较级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
