INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法中表示两者相比有高下、强弱之分的形容词或副词形式。", "primary_collocate": null, "pronunciation": "bǐ jiào jí", "ipa": "pi˨˩ tɕjɑʊ˥˩ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "形容词有比较级和最高级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本语法书讲了比较级的用法。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "副词也有比较级。", "target_word": "比较级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "“更”常常放在形容词前面，构成比较级。", "target_word": "比较级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的比较级没有词尾变化。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写作文时，他用对了比较级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多语言的形容词都有比较级的变化。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试里有一道题，要写出形容词的比较级。", "target_word": "比较级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语法课上，我们学过比较级和最高级。", "target_word": "比较级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇语法文章专门讲副词的比较级。", "target_word": "比较级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比较级：语法中形容词、副词表示高下强弱的形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比较级", "is_correct": true, "explanation": "比较级是形容词的形式之一，与“最高级”并列，符合句意。"}, {"text": "名词", "is_correct": false, "explanation": "语义：名词是另一种词类，不是形容词的形式。"}, {"text": "动词", "is_correct": false, "explanation": "语义：动词也是另一种词类，不属于形容词的形式。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“形容词有眼镜”不成立，“眼镜”不是词的形式。"}], "explanations": {"比较级": "比较级是形容词的形式之一，与“最高级”并列，符合句意。", "名词": "语义：名词是另一种词类，不是形容词的形式。", "动词": "语义：动词也是另一种词类，不属于形容词的形式。", "眼镜": "搭配：“形容词有眼镜”不成立，“眼镜”不是词的形式。"}, "sentence_index": 0, "correct_answer": "比较级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“最”常常放在形容词前面，构成比较级。", "explanation": "这里应该用〈最高级〉。“最”构成最高级，比较级要用“更”。"}, {"text": "“很”是比较级，常用来表示程度。", "explanation": "这里应该用〈副词〉。“很”是程度副词，不是比较级。"}, {"text": "汉语有一首比较级，很好听。", "explanation": "这里应该用〈种〉。“首”用于诗歌、歌曲，比较级不这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比较级", "is_correct": true, "explanation": "比较级是形容词的变化形式，与“的变化”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于形容词的变化形式，与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“形容词都有天气的变化”不成立，天气不是形容词的变化形式。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道与形容词的词形变化无关。"}], "explanations": {"比较级": "比较级是形容词的变化形式，与“的变化”搭配，符合句意。", "颜色": "语义：颜色不属于形容词的变化形式，与句意不合。", "天气": "搭配：“形容词都有天气的变化”不成立，天气不是形容词的变化形式。", "味道": "语义：味道与形容词的词形变化无关。"}, "sentence_index": 6, "correct_answer": "比较级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "形容词的比较级是词本身的形式。", "explanation": "这里应该用〈原级〉。原级是词本身的形式，比较级要加“更”等才表示比较。"}, {"text": "这篇语法文章专门讲副词的一首比较级。", "explanation": "这里不该用〈首〉。“首”用于诗歌、歌曲，比较级不这样计量。"}, {"text": "这两个数的比较级是二比三。", "explanation": "这里应该用〈比例〉。比例指两个数的比，比较级是语法形式，不能表示数的比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "形容词和副词都有一张比较级。", "corrected_sentence": "形容词和副词都有比较级。", "error_description": "量词错误：“比较级”前不应加“一张”，“张”用于平面的东西。正确说法是“形容词和副词都有比较级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“最大”是形容词“大”的比较级。", "corrected_sentence": "“最大”是形容词“大”的最高级。", "error_description": "术语错误：“最”构成最高级，不是比较级；比较级要用“更”，如“更大”。应说“最大”是“大”的最高级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
