INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妈是孩子叫生下自己、养大自己的女人的名字。", "primary_collocate": null, "pronunciation": "mā", "ipa": "ma˥", "syllable_count": 1, "sentences": [{"text": "小时候，我一直叫她妈。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次开口，叫了一声“妈”。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈把我养大，很不容易。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给妈打个电话。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈生了我，也养大了我。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着喊：“妈，我饿了！”", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是三个孩子的妈。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈很爱我，我也爱我妈。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是妈的生日，我送了花。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一看见妈就笑了。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妈妈", "label": "重叠"}, {"form": "媽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "孩子对生养自己的女人的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确答案：妈读第一声 mā，指生养自己的女人。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mā（第一声）声调不同，意思是马。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mā（第一声）声调不同，意思是麻或麻木。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 mā（第一声）声调不同，意思是责骂。"}, {"text": "吗", "is_correct": false, "explanation": "ma（轻声）与 mā（第一声）声调不同，意思是疑问语气词。"}, {"text": "摸", "is_correct": false, "explanation": "mō 与 mā 韵母不同（o 与 a），意思是用手触碰。"}], "explanations": {"妈": "正确答案：妈读第一声 mā，指生养自己的女人。", "马": "mǎ（第三声）与 mā（第一声）声调不同，意思是马。", "麻": "má（第二声）与 mā（第一声）声调不同，意思是麻或麻木。", "骂": "mà（第四声）与 mā（第一声）声调不同，意思是责骂。", "吗": "ma（轻声）与 mā（第一声）声调不同，意思是疑问语气词。", "摸": "mō 与 mā 韵母不同（o 与 a），意思是用手触碰。"}, "sentence_index": null, "correct_answer": "妈"}, "level_3": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确：“叫她妈”是孩子对生养自己的女人的称呼，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，不能被孩子用作称呼。"}, {"text": "老公", "is_correct": false, "explanation": "语义：“老公”指丈夫，孩子不会这样称呼生养自己的女人。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“叫她”后面要接称谓，“厨房”不能作人的称呼。"}], "explanations": {"妈": "正确：“叫她妈”是孩子对生养自己的女人的称呼，符合句意。", "汽车": "语义：汽车不是人，不能被孩子用作称呼。", "老公": "语义：“老公”指丈夫，孩子不会这样称呼生养自己的女人。", "厨房": "搭配：“叫她”后面要接称谓，“厨房”不能作人的称呼。"}, "sentence_index": 0, "correct_answer": "妈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直把邻居王阿姨叫妈。", "explanation": "这里误用了“妈”。“妈”只指生养自己的母亲，邻居不能这样称呼；若要表示这种亲密关系，要说“干妈”。"}, {"text": "我的妈是我的同桌，我们每天一起回家。", "explanation": "这里误用了“妈”。“妈”只指生养自己的母亲，不能用来指同学。"}, {"text": "隔壁的老太太今年八十岁，我每天叫她妈。", "explanation": "这里应该用〈奶奶〉。“妈”只指生养自己的母亲，不能用来称呼邻居家的老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88829, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确答案：妈读第一声 mā，指生养自己的女人。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 mā 声母不同（b 与 m），意思是数字八。"}, {"text": "发", "is_correct": false, "explanation": "fā 与 mā 声母不同（f 与 m），声调相同，意思是发出。"}, {"text": "哇", "is_correct": false, "explanation": "wā 与 mā 声母不同（w 与 m），意思是表示惊讶的叹词。"}, {"text": "嘛", "is_correct": false, "explanation": "ma（轻声）与 mā（第一声）声调不同，意思是语气词。"}], "explanations": {"妈": "正确答案：妈读第一声 mā，指生养自己的女人。", "八": "bā 与 mā 声母不同（b 与 m），意思是数字八。", "发": "fā 与 mā 声母不同（f 与 m），声调相同，意思是发出。", "哇": "wā 与 mā 声母不同（w 与 m），意思是表示惊讶的叹词。", "嘛": "ma（轻声）与 mā（第一声）声调不同，意思是语气词。"}, "sentence_index": null, "correct_answer": "妈"}, "level_3": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确：“她是三个孩子的妈”指她是这三个孩子的母亲，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能作孩子的母亲，句意不通。"}, {"text": "国王", "is_correct": false, "explanation": "语义：“国王”是统治者，与“三个孩子的”身份不符。"}, {"text": "胖子", "is_correct": false, "explanation": "语义：“胖子”描述体型，不是亲属称谓，不能说明她和三个孩子的关系。"}], "explanations": {"妈": "正确：“她是三个孩子的妈”指她是这三个孩子的母亲，符合句意。", "房子": "语义：房子不能作孩子的母亲，句意不通。", "国王": "语义：“国王”是统治者，与“三个孩子的”身份不符。", "胖子": "语义：“胖子”描述体型，不是亲属称谓，不能说明她和三个孩子的关系。"}, "sentence_index": 6, "correct_answer": "妈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "结婚十年了，我每天都叫我的丈夫“妈”。", "explanation": "这里应该用〈老公〉。“妈”指生养自己的母亲，不能用来称呼配偶。"}, {"text": "我正在和妈谈恋爱。", "explanation": "这里应该用〈恋人〉。“谈恋爱”的对象是恋人，不能是母亲。"}, {"text": "我的妈是我的弟弟，我们一起去公园玩。", "explanation": "这里误用了“妈”。“妈”只指生养自己的母亲，不能用来指兄弟姐妹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从小就有一条温柔的妈。", "corrected_sentence": "我从小就有一个温柔的妈。", "error_description": "错误形式：“一条”。正确形式：“一个”。“条”用于细长的东西，不能用来数人，数人的母亲应该用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给妈了打个电话。", "corrected_sentence": "我给妈打了个电话。", "error_description": "错误形式：“给妈了打”。正确形式：“给妈打了”。“了”表示动作完成，应紧接在动词“打”之后，不能插在介词宾语“妈”和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
