INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "母亲。", "primary_collocate": null, "pronunciation": "mā", "ipa": "ma˥", "syllable_count": 1, "sentences": [{"text": "我妈今天在家做饭。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈，我回来了！", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈每天早上六点起床。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的妈在医院工作。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈，今天晚上吃什么？", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给我妈买了一件新衣服。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我跟妈去超市买菜。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈说我今天要早点睡觉。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你妈在哪儿？她在等你。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈做的鱼特别好吃。", "target_word": "妈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妈妈", "label": "重叠"}, {"form": "媽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "母亲，口语称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确答案：妈读第一声 mā，意思是母亲。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mā（第一声）声调不同，意思是马。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 mā（第一声）声调不同，意思是麻或麻木。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 mā（第一声）声调不同，意思是责骂。"}, {"text": "吗", "is_correct": false, "explanation": "ma（轻声）与 mā（第一声）声调不同，意思是疑问语气词。"}, {"text": "摸", "is_correct": false, "explanation": "mō 与 mā 韵母不同（o 与 a），意思是用手触碰。"}], "explanations": {"妈": "正确答案：妈读第一声 mā，意思是母亲。", "马": "mǎ（第三声）与 mā（第一声）声调不同，意思是马。", "麻": "má（第二声）与 mā（第一声）声调不同，意思是麻或麻木。", "骂": "mà（第四声）与 mā（第一声）声调不同，意思是责骂。", "吗": "ma（轻声）与 mā（第一声）声调不同，意思是疑问语气词。", "摸": "mō 与 mā 韵母不同（o 与 a），意思是用手触碰。"}, "sentence_index": null, "correct_answer": "妈"}, "level_3": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确：“我妈”指说话人的母亲，在家做饭的是母亲，句意通顺。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会在家做饭，与“做饭”的动作主体不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人，不能作“做饭”的主语。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：“饭馆”是外出用餐的场所，与“在家做饭”的场所矛盾。"}], "explanations": {"妈": "正确：“我妈”指说话人的母亲，在家做饭的是母亲，句意通顺。", "狗": "语义：狗不会在家做饭，与“做饭”的动作主体不符。", "冰箱": "语义：冰箱不是人，不能作“做饭”的主语。", "饭馆": "搭配：“饭馆”是外出用餐的场所，与“在家做饭”的场所矛盾。"}, "sentence_index": 0, "correct_answer": "妈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位妈是我们楼下的邻居。", "explanation": "这里应该用〈阿姨〉。“妈”指自己的母亲，称呼邻居这样的女性要用“阿姨”。"}, {"text": "我的妈和我同岁，我们一起上小学。", "explanation": "这里应该用〈同学〉。“妈”指生养自己的母亲，不能用来指同龄的同学。"}, {"text": "这位大叔是我的妈，他很喜欢下棋。", "explanation": "这里应该用〈爸爸〉。“妈”只指女性的母亲，不能用来指男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88830, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确答案：妈读第一声 mā，意思是母亲。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 mā 声母不同（b 与 m），意思是数字八。"}, {"text": "巴", "is_correct": false, "explanation": "bā 与 mā 声母不同（b 与 m），意思是尾巴或巴掌。"}, {"text": "发", "is_correct": false, "explanation": "fā 与 mā 声母不同（f 与 m），声调相同，意思是发出。"}, {"text": "哇", "is_correct": false, "explanation": "wā 与 mā 声母不同（w 与 m），意思是表示惊讶的叹词。"}, {"text": "嘛", "is_correct": false, "explanation": "ma（轻声）与 mā（第一声）声调不同，意思是语气词。"}], "explanations": {"妈": "正确答案：妈读第一声 mā，意思是母亲。", "八": "bā 与 mā 声母不同（b 与 m），意思是数字八。", "巴": "bā 与 mā 声母不同（b 与 m），意思是尾巴或巴掌。", "发": "fā 与 mā 声母不同（f 与 m），声调相同，意思是发出。", "哇": "wā 与 mā 声母不同（w 与 m），意思是表示惊讶的叹词。", "嘛": "ma（轻声）与 mā（第一声）声调不同，意思是语气词。"}, "sentence_index": null, "correct_answer": "妈"}, "level_3": {"options": [{"text": "妈", "is_correct": true, "explanation": "正确：“跟妈去超市”指和母亲同行，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能走路，也不能跟人一起去超市。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“跟……去超市买菜”需要能行动的人作同行者，“作业”不能作同行的对象。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不能和人一起去超市买菜。"}], "explanations": {"妈": "正确：“跟妈去超市”指和母亲同行，符合句意。", "椅子": "语义：椅子不能走路，也不能跟人一起去超市。", "作业": "配价：“跟……去超市买菜”需要能行动的人作同行者，“作业”不能作同行的对象。", "电视": "语义：电视是家用电器，不能和人一起去超市买菜。"}, "sentence_index": 6, "correct_answer": "妈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的妈是一台机器，我每天用她写作业。", "explanation": "这里应该用〈电脑〉。“妈”只指生养自己的母亲，不能用来指机器。"}, {"text": "我周末想跟妈约会，一起看电影。", "explanation": "这里应该用〈恋人〉。“约会”的对象是恋人，不能是母亲。"}, {"text": "我和妈结婚已经十年了。", "explanation": "这里应该用〈丈夫〉或〈妻子〉（视说话人性别而定）。“结婚”的对象是配偶，“妈”不能指配偶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只很温柔的妈。", "corrected_sentence": "我有一个很温柔的妈。", "error_description": "错误形式：“一只”。正确形式：“一个”。“只”用于动物，妈是人，应该用“个”（或更礼貌的“位”）来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我最喜欢温柔妈。", "corrected_sentence": "我最喜欢温柔的妈。", "error_description": "错误形式：“温柔妈”。正确形式：“温柔的妈”。形容词作定语修饰名词“妈”时，中间要加“的”，缺少“的”则不成定中结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
