INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水处理是把脏水变干净的办法。", "primary_collocate": null, "pronunciation": "shuǐ chǔ lǐ", "ipa": "ʂweɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "水处理就是把脏水变干净。", "target_word": "水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的井水要先做水处理，才能直接喝。", "target_word": "水处理", "complexity_tier": "T3", "furigana": "wǒ jiā de jǐng shuǐ yào xiān zuò shuǐ chǔ lǐ, cái néng zhí jiē hē。", "sentence_source": "generated"}, {"text": "这个村子以前没有水处理，水不能直接喝。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水处理做好以后，河里的鱼多了。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天检查水处理的效果。", "target_word": "水处理", "complexity_tier": "T3", "furigana": "bà ba měi tiān jiǎn chá shuǐ chǔ lǐ de xiào guǒ。", "sentence_source": "generated"}, {"text": "学水处理的学生，以后可以去自来水厂工作。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学校里学过水处理的办法。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了水处理的几个步骤。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的水处理很好，水很干净。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想喝干净的水，就要做好水处理。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水处理机", "label": "复合词"}, {"form": "水处理厂", "label": "复合词"}, {"form": "水處理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把脏水变干净的办法（日常义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是把脏水变干净的办法。"}, {"text": "水处理", "is_correct": true, "explanation": "正确：水处理就是对脏水进行净化的办法，与句意相符。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“就是把脏水变干净”的主语应是方法或过程，饮料不能充当。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是把脏水变干净的办法。"}], "explanations": {"电脑": "语义：电脑是机器，不是把脏水变干净的办法。", "水处理": "正确：水处理就是对脏水进行净化的办法，与句意相符。", "饮料": "搭配：“就是把脏水变干净”的主语应是方法或过程，饮料不能充当。", "水果": "语义：水果是食物，不是把脏水变干净的办法。"}, "sentence_index": 0, "correct_answer": "水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河是城市的水处理。", "explanation": "这里应该用〈水源〉。水处理是净化水的办法，不是河流。"}, {"text": "下大雨后，水处理被冲走了。", "explanation": "这里应该用〈污泥〉。水处理是加工水的办法，不是可以被冲走的物质。"}, {"text": "老师教了我们一条水处理的方法，叫过滤。", "explanation": "这里应该用〈种〉。〈条〉多用于线状的东西，水处理的方法要用〈种〉：一种水处理的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是可以学习的办法，“学过月亮的办法”说不通。"}, {"text": "水处理", "is_correct": true, "explanation": "正确：水处理的办法指净化脏水的方法，可以学习，与“学校里学过”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不是可以学习的办法，“学过石头的办法”说不通。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是自然现象，不是可以学习的办法，“学过云朵的办法”说不通。"}], "explanations": {"月亮": "语义：月亮是天体，不是可以学习的办法，“学过月亮的办法”说不通。", "水处理": "正确：水处理的办法指净化脏水的方法，可以学习，与“学校里学过”相符。", "石头": "语义：石头是物体，不是可以学习的办法，“学过石头的办法”说不通。", "云朵": "语义：云朵是自然现象，不是可以学习的办法，“学过云朵的办法”说不通。"}, "sentence_index": 6, "correct_answer": "水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水处理很甜，我想再喝一杯。", "explanation": "这里把“水处理”当作饮料，但它表示净化水的办法，不是可以喝的东西，不能说“甜”。"}, {"text": "我每天要洗三次水处理。", "explanation": "这里“洗”的对象应是具体的东西，而“水处理”是办法，不能被洗。"}, {"text": "学校的水处理在操场上踢球。", "explanation": "这里把“水处理”当作有行动能力的主体，但它是加工水的办法，不能踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校的水处理了很有效。", "corrected_sentence": "我们学校的水处理很有效。", "error_description": "“水处理”是名词，后面不能直接加“了”。这里多了“了”，应去掉，说“水处理很有效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水处理做很好，河水变清了。", "corrected_sentence": "水处理做得很好，河水变清了。", "error_description": "作补语的结构需要助词“得”，应说“做得很好”，这里少了“得”，写成“做很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
