INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对水进行净化、消毒等加工，使其达到使用或排放标准。", "primary_collocate": null, "pronunciation": "shuǐ chǔ lǐ", "ipa": "ʂweɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家工厂的脏水要先经过水处理才能排放。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水处理的第一步是把大的脏东西去掉。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自来水厂通过水处理，让河水变得可以直接饮用。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家水处理公司工作。", "target_word": "水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水处理要用到很多机器。", "target_word": "水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水处理后的水可以用来浇花。", "target_word": "水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市需要好的水处理技术。", "target_word": "水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个厂的水处理做得不好，河水变脏了。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水处理中，消毒是很重要的一步。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的游泳池也需要做水处理。", "target_word": "水处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水处理厂", "label": "复合词"}, {"form": "水处理技术", "label": "复合词"}, {"form": "水處理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "净化、消毒等使水达到使用或排放标准的加工（专业义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：食堂是就餐的场所，不是排放前对污水进行的加工过程。"}, {"text": "水处理", "is_correct": true, "explanation": "正确：水处理指对脏水进行净化、消毒等加工，使其达到排放标准，与“经过……才能排放”相符。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水是加工后的成品，不是加工过程，不能“经过”它再排放。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，不是加工过程，脏水不能“经过粮食”再排放。"}], "explanations": {"食堂": "语义：食堂是就餐的场所，不是排放前对污水进行的加工过程。", "水处理": "正确：水处理指对脏水进行净化、消毒等加工，使其达到排放标准，与“经过……才能排放”相符。", "饮用水": "语义：饮用水是加工后的成品，不是加工过程，不能“经过”它再排放。", "粮食": "语义：粮食是食物，不是加工过程，脏水不能“经过粮食”再排放。"}, "sentence_index": 0, "correct_answer": "水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的水处理直接流进了河里。", "explanation": "这里应该用〈污水〉。水处理指净化水的过程，本身不是液体，不能流进河里。"}, {"text": "池底积了很多水处理。", "explanation": "这里应该用〈沉淀〉。水处理是加工过程，不是可以积在池底的物质。"}, {"text": "这里有一只水处理。", "explanation": "这里应该用〈项〉或〈套〉。水处理作为工艺或系统，不用〈只〉；〈只〉多用于动物或成对的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果", "is_correct": false, "explanation": "语义：水果不是技术，“好的水果技术”说不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是鞋，不是技术，“好的拖鞋技术”说不通。"}, {"text": "水处理", "is_correct": true, "explanation": "正确：水处理技术指水的净化、消毒等加工技术，与“城市需要好的……”相符。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“技术”一般不与家具搭配，“沙发技术”说不通。"}], "explanations": {"水果": "语义：水果不是技术，“好的水果技术”说不通。", "拖鞋": "语义：拖鞋是鞋，不是技术，“好的拖鞋技术”说不通。", "水处理": "正确：水处理技术指水的净化、消毒等加工技术，与“城市需要好的……”相符。", "沙发": "搭配：“技术”一般不与家具搭配，“沙发技术”说不通。"}, "sentence_index": 6, "correct_answer": "水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居是一个水处理，每天都很忙。", "explanation": "这里把“水处理”当作指人的名词，但它表示对水进行加工的过程，不指人。"}, {"text": "游泳池的孩子们都在水处理里玩。", "explanation": "这里把“水处理”当作可以玩耍的场所，但它表示水的加工过程，不是场所。"}, {"text": "今天的水处理很好吃，大家都吃了两碗。", "explanation": "这里把“水处理”当作食物，但它表示净化、消毒水的加工，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要对这些脏水水处理。", "corrected_sentence": "我们要对这些脏水进行水处理。", "error_description": "“水处理”是名词，作谓语前需要动词“进行”。这里漏掉了“进行”，应说“进行水处理”，不能直接把名词当动词用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小城的水处理得做很好。", "corrected_sentence": "这座小城的水处理做得很好。", "error_description": "“做得”是“做”的补语结构，“得”要紧跟动词，应说“做得很好”，不能说“得做很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
