INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "条约是国家和国家写下来的约定，两边都要照着做。", "primary_collocate": null, "pronunciation": "tiáo yuē", "ipa": "tʰiɑʊ˧˥ ɥɛ˥", "syllable_count": 2, "sentences": [{"text": "两个国家签了一个新条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国都要照着条约去做。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个条约写了很多规定。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，条约是国家之间的约定。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上签下了和平条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家没有遵守条约，别国很生气。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上写了很多国家的条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份条约一共有十条规定。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表在桌前读完了条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了条约的基本知识。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條約", "label": "繁体"}, {"form": "和平条约", "label": "复合"}, {"form": "一份条约", "label": "量词"}], "register": "中性", "sense_fingerprint": "国家之间写下来、双方都要遵守的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8062f93-f3e7-40ad-97d7-3e2fe343f9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88835, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确答案：条约（tiáo yuē），国家之间签订的书面约定。"}, {"text": "跳跃", "is_correct": false, "explanation": "跳跃（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，意思是跳起来。"}, {"text": "跳月", "is_correct": false, "explanation": "跳月（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，指苗族等民族的一种传统舞蹈活动。"}, {"text": "跳越", "is_correct": false, "explanation": "跳越（tiào yuè）两个字的声调都与条约不同，意思是跳过去。"}], "explanations": {"条约": "正确答案：条约（tiáo yuē），国家之间签订的书面约定。", "跳跃": "跳跃（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，意思是跳起来。", "跳月": "跳月（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，指苗族等民族的一种传统舞蹈活动。", "跳越": "跳越（tiào yuè）两个字的声调都与条约不同，意思是跳过去。"}, "sentence_index": null, "correct_answer": "条约"}, "level_3": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确：“条约”是国家之间签订的书面约定，与“两个国家签了”相符。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“签”的对象是协议、文件，不能说签一个城市。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是机构或场所，不是签订的约定，句中说的是国家之间的约定。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：礼物是送的，不是签的，“签”不能用于礼物。"}], "explanations": {"条约": "正确：“条约”是国家之间签订的书面约定，与“两个国家签了”相符。", "城市": "搭配：“签”的对象是协议、文件，不能说签一个城市。", "学校": "语义：学校是机构或场所，不是签订的约定，句中说的是国家之间的约定。", "礼物": "搭配：礼物是送的，不是签的，“签”不能用于礼物。"}, "sentence_index": 0, "correct_answer": "条约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和房东签了一份租房条约，房租每月付一次。", "explanation": "这里应该用〈协议〉。条约专指国家之间的约定，个人之间的租房约定用协议。"}, {"text": "他们在公司签了一份劳动条约，工资按月发放。", "explanation": "这里应该用〈合同〉。劳动关系中的书面约定用合同，条约只用于国家之间。"}, {"text": "学校新发布了一项条约，要求学生按时到校。", "explanation": "这里应该用〈规定〉。学校发布的要求用规定，条约只指国家之间的书面协议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确：“条约”指国家之间的约定，与“历史书上写了很多国家的……”相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来指国家之间的条约。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，历史书不记录国家的脾气。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，历史书记载的不是体重，与句意不符。"}], "explanations": {"条约": "正确：“条约”指国家之间的约定，与“历史书上写了很多国家的……”相符。", "身材": "体貌：“身材”指人的体形，不能用来指国家之间的条约。", "脾气": "语义：“脾气”指性格，历史书不记录国家的脾气。", "体重": "语义：“体重”指人或物的重量，历史书记载的不是体重，与句意不符。"}, "sentence_index": 6, "correct_answer": "条约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村民在大会上通过了一份条约，大家都要遵守。", "explanation": "这里应该用〈公约〉。条约专指国家之间的约定，村民之间的共同约定用公约。"}, {"text": "这位歌手和公司签了一份条约，为期三年。", "explanation": "这里应该用〈合约〉。条约只用于国家之间，歌手与公司之间的约定用合约。"}, {"text": "两个朋友立下了一份条约，周末一起去爬山。", "explanation": "这里应该用〈约定〉。条约专指国家之间的书面约定，朋友之间的约定不用条约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个国家签了一只新条约。", "corrected_sentence": "两个国家签了一项新条约。", "error_description": "量词错误：“只”用于动物等，不能修饰条约。应改为“一项”，即“签了一项新条约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国曾经签订着一项条约。", "corrected_sentence": "两国曾经签订过一项条约。", "error_description": "“着”表示持续的状态，与“曾经”表示的已完成经历矛盾，应写作“签订过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba684ca-f31d-4c30-8ef2-dd0d7bbd2fc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
