INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前辈是比你年纪大、先做这件事的人。", "primary_collocate": null, "pronunciation": "qián bèi", "ipa": "tɕʰjɛn˧˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "他是公司里的前辈，我常向他请教。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位前辈比我早来五年。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前辈告诉我，这件事要慢慢做。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很感谢那位前辈的帮助。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校里，前辈们常常帮助新同学。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我在这家公司的前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请前辈给我一些建议。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我早学两年，所以我叫他前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟着前辈做事，我学到了很多。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事都很尊敬前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前辈们", "label": "复数"}, {"form": "一位前辈", "label": "量词"}, {"form": "前輩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年纪更大、先做这件事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校学习的人，与“公司里的”身份矛盾。"}, {"text": "前辈", "is_correct": true, "explanation": "前辈：比我年长、先做这件事的人，与“我常向他请教”相符。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：“邻居”指住得近的人，不说“公司里的邻居”，与句意不符。"}, {"text": "弟弟", "is_correct": false, "explanation": "搭配：“弟弟”是亲属称谓，不用于公司里的同事关系，也不说“向弟弟请教”。"}], "explanations": {"学生": "语义：“学生”指在校学习的人，与“公司里的”身份矛盾。", "前辈": "前辈：比我年长、先做这件事的人，与“我常向他请教”相符。", "邻居": "语义：“邻居”指住得近的人，不说“公司里的邻居”，与句意不符。", "弟弟": "搭配：“弟弟”是亲属称谓，不用于公司里的同事关系，也不说“向弟弟请教”。"}, "sentence_index": 0, "correct_answer": "前辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位前辈比我小两岁，和我同时进的公司。", "explanation": "这里应该用〈同事〉。前辈要比自己年长，或比自己先做这件事；与我同时入职、年纪又比我小的人只能说“同事”。"}, {"text": "这位前辈刚出生三个月，很可爱。", "explanation": "这里应该用〈宝宝〉。前辈指年长或资历较深的人，刚出生的婴儿要说“宝宝”。"}, {"text": "他昨天才来公司，是我们这里的前辈。", "explanation": "这里应该用〈新人〉。前辈要比自己先做这件事，昨天才来的人只能说“新人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会给建议，与“给我一些建议”矛盾。"}, {"text": "前辈", "is_correct": true, "explanation": "前辈：资历较深的人，请他给建议符合句意。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能提供建议，与句意不符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能提供建议，“请玩具给我建议”不成立。"}], "explanations": {"石头": "语义：石头不会给建议，与“给我一些建议”矛盾。", "前辈": "前辈：资历较深的人，请他给建议符合句意。", "狗": "语义：狗不能提供建议，与句意不符。", "玩具": "语义：玩具不能提供建议，“请玩具给我建议”不成立。"}, "sentence_index": 6, "correct_answer": "前辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫是我的前辈，比我早来家里三年。", "explanation": "这里应该用〈宠物〉。前辈指人，家里的猫应说“宠物”。"}, {"text": "我和同学是同一年出生的，他是我的前辈。", "explanation": "这里应该用〈同学〉。前辈要比自己年长或先做这件事，同年出生的同学只能说“同学”。"}, {"text": "这个学生比我晚学三年，是我的前辈。", "explanation": "这里应该用〈后辈〉。前辈要比自己先做这件事，比我晚学的人应说“后辈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每位前辈们都很友好。", "corrected_sentence": "每位前辈都很友好。", "error_description": "多了“们”：“每”表示逐个，与复数词尾“们”冲突，应说“每位前辈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只前辈很热心，常常帮助新人。", "corrected_sentence": "那位前辈很热心，常常帮助新人。", "error_description": "量词错误：“前辈”指人，应用“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年长的人，或在某方面资历较深的人。", "primary_collocate": null, "pronunciation": "qián bèi", "ipa": "tɕʰjɛn˧˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "对前辈要有礼貌，不能随便说话。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位前辈年纪很大，走路很慢。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前辈们的经验值得我们学习。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是画画方面的前辈，大家都很佩服。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，我们要去看望学校里的老前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位前辈一辈子都在教书。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院工作三十年，是大家的前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们村里，他是最受人尊敬的前辈。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该多听听前辈的话。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位前辈虽然头发白了，说话还很有力。", "target_word": "前辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前辈们", "label": "复数"}, {"form": "一位前辈", "label": "量词"}, {"form": "前輩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年长或资历较深的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是需要礼貌对待的对象，“对石头要有礼貌”不成立。"}, {"text": "前辈", "is_correct": true, "explanation": "前辈：年长或资历较深的人，是需要有礼貌对待的对象，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有礼貌的对象，与“不能随便说话”的语境不符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“对……要有礼貌”一般针对人，“椅子”不能作礼貌的对象。"}], "explanations": {"石头": "语义：石头不是需要礼貌对待的对象，“对石头要有礼貌”不成立。", "前辈": "前辈：年长或资历较深的人，是需要有礼貌对待的对象，与句意相符。", "窗户": "语义：窗户没有礼貌的对象，与“不能随便说话”的语境不符。", "椅子": "搭配：“对……要有礼貌”一般针对人，“椅子”不能作礼貌的对象。"}, "sentence_index": 0, "correct_answer": "前辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位前辈是刚入学的新生，今天第一次上课。", "explanation": "这里应该用〈新人〉。前辈指年长或资历较深的人，刚入学的学生只能说“新人”。"}, {"text": "这位前辈的年纪比他的孙子还小。", "explanation": "这里应该用〈晚辈〉。前辈指年长或资历较深的人，年纪比孙子还小的人应说“晚辈”。"}, {"text": "这位前辈今年才五岁，刚上幼儿园。", "explanation": "这里应该用〈小朋友〉。前辈指年长或资历较深的人，五岁的孩子只能说“小朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：在医院工作三十年的人不会是病人，与句意矛盾。"}, {"text": "客人", "is_correct": false, "explanation": "语义：“客人”指做客的人，与“在医院工作三十年”的身份不符。"}, {"text": "前辈", "is_correct": true, "explanation": "前辈：资历较深的人，与“在医院工作三十年”相符。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生”与“工作三十年”的身份不搭配。"}], "explanations": {"病人": "语义：在医院工作三十年的人不会是病人，与句意矛盾。", "客人": "语义：“客人”指做客的人，与“在医院工作三十年”的身份不符。", "前辈": "前辈：资历较深的人，与“在医院工作三十年”相符。", "学生": "搭配：“学生”与“工作三十年”的身份不搭配。"}, "sentence_index": 6, "correct_answer": "前辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩刚满一岁，已经是班里的前辈了。", "explanation": "这里应该用〈宝宝〉。前辈指年长或资历较深的人，刚满一岁的孩子要说“宝宝”。"}, {"text": "这位前辈是我的同桌，和我同岁，也是今年刚入学。", "explanation": "这里应该用〈同学〉。前辈指年长或资历较深的人，同岁又同时入学的同桌要说“同学”。"}, {"text": "这位前辈刚上一年级，还不认识几个字。", "explanation": "这里应该用〈学生〉。前辈要年长或资历较深，刚入学的一年级学生只能说“学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我的前辈们，教我很多东西。", "corrected_sentence": "她是我的前辈，教我很多东西。", "error_description": "多了“们”：“她”指一个人，“前辈”不能加复数“们”，应说“她是我的前辈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座前辈在村里教了几十年书。", "corrected_sentence": "这位前辈在村里教了几十年书。", "error_description": "量词错误：“前辈”指人，应用“位”，不能用“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
