INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88840, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词,表示动作的方向;朝,向。", "primary_collocate": null, "pronunciation": "wǎng", "ipa": "waŋ˨˩", "syllable_count": 1, "sentences": [{"text": "请往前走,不要停。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路往左拐就是学校。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往窗外看了一眼。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车往南开,我们明天到。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往里坐,这里还有位子。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们往河边跑去了。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水往低处流。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书往桌上一放就走了。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你往右看,那个红房子就是我家。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风往东边吹,天气会变好。", "target_word": "往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "往前", "label": "复合"}, {"form": "往后", "label": "复合"}], "register": "中性", "sense_fingerprint": "介词,引出动作的方向或目标位置,如往前走、往左拐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "往", "is_correct": true, "explanation": "往 wǎng，介词，表示动作的方向，如“往前走”。"}, {"text": "忘", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。"}, {"text": "王", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn 与 wǎng 的韵尾不同（n 与 ng），意思是晚上。"}], "explanations": {"往": "往 wǎng，介词，表示动作的方向，如“往前走”。", "忘": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。", "王": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。", "晚": "wǎn 与 wǎng 的韵尾不同（n 与 ng），意思是晚上。"}, "sentence_index": null, "correct_answer": "往"}, "level_3": {"options": [{"text": "把", "is_correct": false, "explanation": "配价：“把”字句要求后接处置对象和动词，“把前”不成立。"}, {"text": "往", "is_correct": true, "explanation": "往是介词，表示动作的方向，与“前走”搭配，符合句意。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对前”不能组成方向短语，“对”不表示移动的方向。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“给前走”不成立。"}], "explanations": {"把": "配价：“把”字句要求后接处置对象和动词，“把前”不成立。", "往": "往是介词，表示动作的方向，与“前走”搭配，符合句意。", "对": "搭配：“对前”不能组成方向短语，“对”不表示移动的方向。", "给": "配价：“给”需要接受者，“给前走”不成立。"}, "sentence_index": 0, "correct_answer": "往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我往老师请教了一个问题。", "explanation": "这里应该用〈向〉。“向”可以引出请教的对象，“往”只表示具体的移动方向，不能引出请教的对象。"}, {"text": "他往音乐很感兴趣。", "explanation": "这里应该用〈对〉。“对”可以引出感兴趣的对象，“往”不能与“感兴趣”搭配。"}, {"text": "我往他买了一份礼物。", "explanation": "这里应该用〈给〉。“给”引出接受者，“往”表示方向，不能引出接受礼物的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88840, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "往", "is_correct": true, "explanation": "往 wǎng，介词，表示动作的方向，如“往东走”。"}, {"text": "望", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是望向。"}, {"text": "汪", "is_correct": false, "explanation": "wāng（第一声）与 wǎng（第三声）声调不同，“汪”是狗叫声（汪汪），也是姓。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 wǎng 的韵尾不同（n 与 ng），意思是碗。"}], "explanations": {"往": "往 wǎng，介词，表示动作的方向，如“往东走”。", "望": "wàng（第四声）与 wǎng（第三声）声调不同，意思是望向。", "汪": "wāng（第一声）与 wǎng（第三声）声调不同，“汪”是狗叫声（汪汪），也是姓。", "碗": "wǎn 与 wǎng 的韵尾不同（n 与 ng），意思是碗。"}, "sentence_index": null, "correct_answer": "往"}, "level_3": {"options": [{"text": "为", "is_correct": false, "explanation": "搭配：“为低处流”不成立，“为”不表示水流的方向。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替低处”表示替代，与水流的方向无关。"}, {"text": "往", "is_correct": true, "explanation": "往是介词，表示方向，“水往低处流”表示水向低的地方流，符合句意。"}, {"text": "跟", "is_correct": false, "explanation": "配价：“跟”需要共行的对象，“跟低处流”不成立。"}], "explanations": {"为": "搭配：“为低处流”不成立，“为”不表示水流的方向。", "替": "语义：“替低处”表示替代，与水流的方向无关。", "往": "往是介词，表示方向，“水往低处流”表示水向低的地方流，符合句意。", "跟": "配价：“跟”需要共行的对象，“跟低处流”不成立。"}, "sentence_index": 6, "correct_answer": "往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我往同学讲了一个故事。", "explanation": "这里应该用〈对〉。“对”可以引出听话的对象，“往”只表示动作的方向，不能引出听故事的人，应说“对同学讲了一个故事”。"}, {"text": "他往房间里学习。", "explanation": "这里应该用〈在〉。“往”只表示动作的方向，“学习”是静止的动作，处所要用“在”引出，应说“在房间里学习”。"}, {"text": "我往医生看病。", "explanation": "这里应该用〈找〉。“往”只表示方向，不能引出看病的对象，应说“找医生看病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们往的前走了一段路。", "corrected_sentence": "他们往前走了一段路。", "error_description": "错误：“往”是介词，后面不能直接加结构助词“的”，“往的前”不成立。正确应删去“的”，即“他们往前走了一段路”。“往”引出动作的方向，放在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们往大门口站着。", "corrected_sentence": "他们在大门口站着。", "error_description": "错误：“往”表示动作的方向，只能与移动动词搭配；“站着”是静止的状态，处所要用“在”引出。正确应为“在大门口站着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
