INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88841, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水马是放在路上，用来挡住车子的大东西。", "primary_collocate": null, "pronunciation": "shuǐ mǎ", "ipa": "ʂweɪ˨˩˦ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "路中间有很多水马，车不能过去。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有水马，车只能走左边。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路口放了几个水马。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水马很大，一个人搬不动。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水马是用来挡车的。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车不小心撞到了水马。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有水马，我们走了另一条路。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水马挡住了路，车都停下来了。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口放着两个水马。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水马一个一个排好了。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "排", "label": "量词"}, {"form": "水馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放在路上挡住车子的大型障碍物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水马", "is_correct": true, "explanation": "正确：“水马”是放在路上挡车的隔离物，与“路中间有很多……车不能过去”相合。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不能挡住车辆通行，与“车不能过去”需要实物障碍的语境不合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是小东西，不能挡住车辆，与“车不能过去”不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能挡住车辆通行，与句中的语境不符。"}], "explanations": {"水马": "正确：“水马”是放在路上挡车的隔离物，与“路中间有很多……车不能过去”相合。", "云": "语义：云不能挡住车辆通行，与“车不能过去”需要实物障碍的语境不合。", "书包": "语义：书包是小东西，不能挡住车辆，与“车不能过去”不合。", "歌曲": "语义：歌曲不能挡住车辆通行，与句中的语境不符。"}, "sentence_index": 0, "correct_answer": "水马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提着一个水马去打水了。", "explanation": "这里应该用〈水桶〉。水桶可以提着去打水；“水马”是大的隔离设施，一个人搬不动，不能提。"}, {"text": "水马吃了很多草，长得很胖。", "explanation": "这里把“水马”读成了动物，而它是路上的隔离设施，不吃草，也不会长胖。"}, {"text": "水马响了，我拿起来接电话。", "explanation": "这里应该用〈手机〉。手机会响，可以接电话；“水马”是路上挡车的隔离物，不能接电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水马", "is_correct": true, "explanation": "正确：“水马”是路上的挡车物，“因为有……我们走了另一条路”正是因障碍而绕行。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不挡车，不会让人因此绕路。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不妨碍通行，不构成绕路的原因。"}, {"text": "诗句", "is_correct": false, "explanation": "语义：诗句不挡车，不会成为绕路的原因。"}], "explanations": {"水马": "正确：“水马”是路上的挡车物，“因为有……我们走了另一条路”正是因障碍而绕行。", "音乐": "语义：音乐不挡车，不会让人因此绕路。", "笑话": "语义：笑话不妨碍通行，不构成绕路的原因。", "诗句": "语义：诗句不挡车，不会成为绕路的原因。"}, "sentence_index": 6, "correct_answer": "水马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把水马一个一个讲给大家听了。", "explanation": "这里把“水马”当成了可以讲述的〈消息〉，误取了抽象的义项；“水马”是实物，不能讲给别人听。"}, {"text": "她用水马擦了桌子。", "explanation": "这里把“水马”误当成了〈抹布〉，取了擦拭用具的义项；“水马”是路上的隔离设施，不能用来擦桌子。"}, {"text": "这个水马是一种鸟，天上飞来飞去。", "explanation": "这里把“水马”误当成了〈飞禽〉，取了会飞的生物义项；“水马”是路上灌水的隔离设施，不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路中间放了一棵水马，车根本过不去。", "corrected_sentence": "路中间放了一个水马，车根本过不去。", "error_description": "量词错误：“水马”的量词是“个”，不用“棵”（“棵”用于树木、植物）。错误形式“一棵水马”，正确形式“一个水马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车主把水马推了路边。", "corrected_sentence": "车主把水马推到了路边。", "error_description": "补语错误：“推”后要用“到”引出处所，说“推了路边”不通。错误形式“推了路边”，正确形式“推到了路边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
