INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种灌水后使用的塑料隔离设施，用于道路围挡。", "primary_collocate": null, "pronunciation": "shuǐ mǎ", "ipa": "ʂweɪ˨˩˦ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人在路边摆了一排水马。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水马里灌满了水，风吹不倒。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "施工的地方用水马围起来了。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的水马放在路中间。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路在修，路口放着水马。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水马是塑料做的，里面可以灌水。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看到前面的水马，慢慢停了车。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把水马搬到了路边。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水马把快车道和慢车道分开了。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，水马旁边亮着黄色的灯。", "target_word": "水马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "排", "label": "量词"}, {"form": "水馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "灌水后的塑料隔离设施，用来围挡道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水马", "is_correct": true, "explanation": "正确：“水马”是放在路边的隔离设施，可以成排摆放，与“摆了一排”相合。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是天边的景象，不能摆在路边，与句意不符。"}, {"text": "乌云", "is_correct": false, "explanation": "语义：乌云不是可以摆放在路边的东西，与句中的语境不合。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“墙”应说“砌”或“修”，不说“摆”。"}], "explanations": {"水马": "正确：“水马”是放在路边的隔离设施，可以成排摆放，与“摆了一排”相合。", "晚霞": "语义：晚霞是天边的景象，不能摆在路边，与句意不符。", "乌云": "语义：乌云不是可以摆放在路边的东西，与句中的语境不合。", "墙": "搭配：“墙”应说“砌”或“修”，不说“摆”。"}, "sentence_index": 0, "correct_answer": "水马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水马放在火上烧了一会儿。", "explanation": "这里应该用〈锅〉。锅可以放在火上加热；“水马”是塑料隔离设施，不能放在火上烧。"}, {"text": "水马跑得很快，一下子就过了桥。", "explanation": "这里把“水马”误解为会跑的〈动物〉，取了动物的义项；水马是灌水的隔离设施，不会跑，也不能过桥。"}, {"text": "他把水马当饮料喝了一杯。", "explanation": "这里把“水马”误当成了可以食用的〈食品〉，取了食品的义项；“水马”是灌水的塑料隔离设施，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水马", "is_correct": true, "explanation": "正确：司机看到前面的“水马”会停车避让，与“慢慢停了车”的语境相合。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“看到”不能接“笑声”，应说“听到”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“看到”不能接“心情”，看不见心情。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“看到”不能接“歌曲”，应说“听到”。"}], "explanations": {"水马": "正确：司机看到前面的“水马”会停车避让，与“慢慢停了车”的语境相合。", "笑声": "搭配：“看到”不能接“笑声”，应说“听到”。", "心情": "搭配：“看到”不能接“心情”，看不见心情。", "歌曲": "搭配：“看到”不能接“歌曲”，应说“听到”。"}, "sentence_index": 6, "correct_answer": "水马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的水马很好吃，大家都抢着买。", "explanation": "这里应该用〈点心〉。点心可以吃；“水马”是路上的隔离设施，不能吃。"}, {"text": "水马是一种植物，春天开满了红花。", "explanation": "这里把“水马”误当成了〈草木〉，取了草木的义项；“水马”是路上的隔离设施，不是草木，也不会开花。"}, {"text": "他坐在水马前面，用水马当桌子写作业。", "explanation": "这里把“水马”误当成了〈书桌〉，取了可供书写的义项；“水马”是灌水的塑料隔离设施，不是写作业用的桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "施工队在路口摆了一朵水马，车只能慢行。", "corrected_sentence": "施工队在路口摆了一排水马，车只能慢行。", "error_description": "量词错误：“水马”的量词是“个”或“排”，不用“朵”（“朵”用于花朵、云朵）。错误形式“一朵水马”，正确形式“一排水马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把水马推了路边。", "corrected_sentence": "工人把水马推到了路边。", "error_description": "补语错误：“推”后要用“到”引出处所，说“推了路边”不通。错误形式“推了路边”，正确形式“推到了路边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
