INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "秘书是帮领导写文件、安排事情的人。", "primary_collocate": null, "pronunciation": "mì shū", "ipa": "mi˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "秘书帮经理写了一封信。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的秘书每天都很忙。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请秘书安排明天的会。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公司做秘书。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书给老板倒了一杯茶。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让秘书打电话给客人。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的秘书很年轻。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书每天早上告诉经理今天有什么事。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王秘书不在，请你下午再来。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当经理的秘书，但是没有经验。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "帮领导写东西、安排事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秘书", "is_correct": true, "explanation": "正确答案：秘书（mì shū），帮领导处理文书和事务的人。"}, {"text": "蜜薯", "is_correct": false, "explanation": "蜜薯 mì shǔ 与 秘书 mì shū 只有第二个音节声调不同（shǔ 为第三声，shū 为第一声），意思是甘薯。"}, {"text": "必输", "is_correct": false, "explanation": "必输 bì shū 与 秘书 mì shū 声母不同（b 与 m），意思是一定会输。"}, {"text": "秘术", "is_correct": false, "explanation": "秘术 mì shù 与 秘书 mì shū 只有第二个音节声调不同（shù 为第四声），意思是秘密的技术或法术。"}], "explanations": {"秘书": "正确答案：秘书（mì shū），帮领导处理文书和事务的人。", "蜜薯": "蜜薯 mì shǔ 与 秘书 mì shū 只有第二个音节声调不同（shǔ 为第三声，shū 为第一声），意思是甘薯。", "必输": "必输 bì shū 与 秘书 mì shū 声母不同（b 与 m），意思是一定会输。", "秘术": "秘术 mì shù 与 秘书 mì shū 只有第二个音节声调不同（shù 为第四声），意思是秘密的技术或法术。"}, "sentence_index": null, "correct_answer": "秘书"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：“石头”是没有生命的物体，不能帮人写信。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”是饮品，不能和“写信”搭配作主语。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”指房间，不能帮经理写信。"}, {"text": "秘书", "is_correct": true, "explanation": "“秘书”指帮领导写东西的人，符合“帮经理写了一封信”这一句意。"}], "explanations": {"石头": "语义：“石头”是没有生命的物体，不能帮人写信。", "咖啡": "搭配：“咖啡”是饮品，不能和“写信”搭配作主语。", "厨房": "语义：“厨房”指房间，不能帮经理写信。", "秘书": "“秘书”指帮领导写东西的人，符合“帮经理写了一封信”这一句意。"}, "sentence_index": 0, "correct_answer": "秘书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司新来了一只秘书。", "explanation": "这里量词用错。秘书指人，应用“位”或“个”，“只”多用于动物。"}, {"text": "我们办公室新买了一台秘书。", "explanation": "这里量词用错。“台”用于机器，秘书是人，应用“位”。"}, {"text": "我家的狗是我们公司的秘书。", "explanation": "这句把“秘书”用来指〈动物〉（狗），但“秘书”只指协助领导处理事务的人，词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课桌", "is_correct": false, "explanation": "语义：“课桌”是家具，不能用来形容年轻。"}, {"text": "秘书", "is_correct": true, "explanation": "“秘书”指人，可以说“年轻”，符合“新来的秘书很年轻”这一句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不能说年轻。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“年轻”一般形容人，不能和“雨伞”搭配。"}], "explanations": {"课桌": "语义：“课桌”是家具，不能用来形容年轻。", "秘书": "“秘书”指人，可以说“年轻”，符合“新来的秘书很年轻”这一句意。", "窗户": "语义：“窗户”是建筑部件，不能说年轻。", "雨伞": "搭配：“年轻”一般形容人，不能和“雨伞”搭配。"}, "sentence_index": 6, "correct_answer": "秘书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把秘书放在书桌上。", "explanation": "“秘书”指人，不能像物品一样用“放”来处置，这里的用法不对。"}, {"text": "这个秘书的保质期是两年，过期后就不能再用了。", "explanation": "“保质期”只用于食品、药品等物品，这句把“秘书”当成了〈商品〉来用，词义用错了。"}, {"text": "秘书的颜色是绿色的。", "explanation": "这句把“秘书”当成了有颜色的〈物品〉来描述，但“秘书”指人，不能用“颜色”来说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一只秘书今天请假了。", "corrected_sentence": "我的一位秘书今天请假了。", "error_description": "量词用错。“秘书”指人，应用“位”，不能用“只”。应说“我的一位秘书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司请了一位经验丰富秘书。", "corrected_sentence": "公司请了一位经验丰富的秘书。", "error_description": "“经验丰富”是四个音节的形容词性短语，修饰“秘书”作定语时要加“的”，不能省略。应说“一位经验丰富的秘书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
