INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助领导处理文书、日常事务的人员。", "primary_collocate": null, "pronunciation": "mì shū", "ipa": "mi˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "秘书正在整理公司的文件。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件要先让秘书看一看。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书负责接电话和写通知。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的秘书很会处理日常的工作。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书把会议记录发给了大家。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想见校长，要先跟秘书约时间。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书每天要回很多邮件。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司招了一位会英语的秘书。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书打印好了明天开会用的材料。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位秘书会写文件，也会安排会议。", "target_word": "秘书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "协助领导处理文件和日常事务的工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88844, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秘书", "is_correct": true, "explanation": "正确答案：秘书（mì shū），协助领导处理文件和日常事务的工作人员。"}, {"text": "蜜薯", "is_correct": false, "explanation": "蜜薯 mì shǔ 与 秘书 mì shū 只有第二个音节声调不同（shǔ 为第三声，shū 为第一声），意思是甘薯。"}, {"text": "必输", "is_correct": false, "explanation": "必输 bì shū 与 秘书 mì shū 声母不同（b 与 m），意思是一定会输。"}, {"text": "秘术", "is_correct": false, "explanation": "秘术 mì shù 与 秘书 mì shū 只有第二个音节声调不同（shù 为第四声），意思是秘密的技术或法术。"}], "explanations": {"秘书": "正确答案：秘书（mì shū），协助领导处理文件和日常事务的工作人员。", "蜜薯": "蜜薯 mì shǔ 与 秘书 mì shū 只有第二个音节声调不同（shǔ 为第三声，shū 为第一声），意思是甘薯。", "必输": "必输 bì shū 与 秘书 mì shū 声母不同（b 与 m），意思是一定会输。", "秘术": "秘术 mì shù 与 秘书 mì shū 只有第二个音节声调不同（shù 为第四声），意思是秘密的技术或法术。"}, "sentence_index": null, "correct_answer": "秘书"}, "level_3": {"options": [{"text": "猫", "is_correct": false, "explanation": "语义：“猫”不会整理文件，不能作“整理公司的文件”的主语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不会整理文件。"}, {"text": "秘书", "is_correct": true, "explanation": "“秘书”是处理文件的人员，符合“正在整理公司的文件”这一语境。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“整理”的主体要能进行这一动作，“窗户”不能和“整理文件”搭配。"}], "explanations": {"猫": "语义：“猫”不会整理文件，不能作“整理公司的文件”的主语。", "石头": "语义：“石头”没有生命，不会整理文件。", "秘书": "“秘书”是处理文件的人员，符合“正在整理公司的文件”这一语境。", "窗户": "搭配：“整理”的主体要能进行这一动作，“窗户”不能和“整理文件”搭配。"}, "sentence_index": 0, "correct_answer": "秘书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司门口站着一只秘书。", "explanation": "这里量词用错。秘书指人，应用“位”或“名”，“只”多用于动物。"}, {"text": "我家的小猫是公司的秘书。", "explanation": "这句把“秘书”用来指〈动物〉（小猫），但“秘书”只指协助领导处理事务的人，词义用错了。"}, {"text": "我们办公室新买了一台秘书。", "explanation": "这里量词用错。“台”用于机器，秘书是人，应用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是计时的物品，不会回邮件。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：“台灯”是照明的物品，不能回邮件。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“回邮件”的主体必须是人，“冰箱”不能和它搭配。"}, {"text": "秘书", "is_correct": true, "explanation": "“秘书”是处理文件和邮件的人员，符合“每天要回很多邮件”这一语境。"}], "explanations": {"闹钟": "语义：“闹钟”是计时的物品，不会回邮件。", "台灯": "语义：“台灯”是照明的物品，不能回邮件。", "冰箱": "搭配：“回邮件”的主体必须是人，“冰箱”不能和它搭配。", "秘书": "“秘书”是处理文件和邮件的人员，符合“每天要回很多邮件”这一语境。"}, "sentence_index": 6, "correct_answer": "秘书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位秘书很甜，很好喝。", "explanation": "“好喝”只用于饮料，这句把“秘书”当成了〈饮料〉来形容，词义用错了。"}, {"text": "这位秘书的颜色是绿色的。", "explanation": "这句把“秘书”当成了有颜色的〈物品〉来描述，但“秘书”指人，不能用“颜色”来说明。"}, {"text": "这位秘书是我家的宠物，每天在地上打滚。", "explanation": "这句把“秘书”当成了〈宠物〉（动物）来用，但“秘书”指协助领导处理事务的人，不能用来指宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司有三个秘书们。", "corrected_sentence": "我们公司有三个秘书。", "error_description": "“秘书”前面已有数量词“三个”，后面不能再加“们”。应说“我们公司有三个秘书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司请了一本秘书。", "corrected_sentence": "公司请了一位秘书。", "error_description": "量词用错。“秘书”指人，应用“位”，不能用“本”。应说“公司请了一位秘书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
