INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "样子是东西或人看起来的模样。", "primary_collocate": null, "pronunciation": "yàng zi", "ipa": "jɑŋ˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "这个蛋糕的样子很好看。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长大以后，样子完全变了。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子的样子和图片上一样。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋样子不错，就是有点贵。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这件衣服的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年没见，她还是以前的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台手机的样子很特别，是方的。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车样子很老，但跑得很快。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你画一下你想要的房子的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识他，只记得他的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副", "label": "量词"}, {"form": "样儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "东西或人外表看起来的模样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指东西或人看起来的模样，读 yàng zi。"}, {"text": "燕子", "is_correct": false, "explanation": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。"}, {"text": "养子", "is_correct": false, "explanation": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng 与 yàng 只差声母（x/y），意思是巷子（小路）。"}, {"text": "浪子", "is_correct": false, "explanation": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}], "explanations": {"样子": "正确。“样子”指东西或人看起来的模样，读 yàng zi。", "燕子": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。", "养子": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。", "巷子": "xiàng 与 yàng 只差声母（x/y），意思是巷子（小路）。", "浪子": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“这个蛋糕的样子”指外观，与“好看”搭配自然。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“好看”形容外观，不能用来形容味道。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能用“好看”来形容，句子说的是蛋糕的外观。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“好看”形容外观，不能用来形容声音。"}], "explanations": {"样子": "正确。“这个蛋糕的样子”指外观，与“好看”搭配自然。", "味道": "搭配：“好看”形容外观，不能用来形容味道。", "价格": "语义：价格不能用“好看”来形容，句子说的是蛋糕的外观。", "声音": "搭配：“好看”形容外观，不能用来形容声音。"}, "sentence_index": 0, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的样子很香。", "explanation": "这里应该用〈味道〉。“样子”指外形，是看到的，不能用“香”来形容；闻到的香要用“味道”或“气味”。"}, {"text": "这首歌的样子很好听。", "explanation": "这里应该用〈声音〉。“样子”指外形，不能用“好听”来形容。"}, {"text": "这幅画的样子很动听。", "explanation": "这里不能用“动听”：“动听”只形容声音、歌曲，画作没有声音；“样子”指外形，同样不能用“动听”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88845, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指东西或人看起来的模样，读 yàng zi。"}, {"text": "胖子", "is_correct": false, "explanation": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。"}, {"text": "帐子", "is_correct": false, "explanation": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。"}, {"text": "养子", "is_correct": false, "explanation": "yǎng（第三声）与 yàng 只差声调，意思是养子（被收养的孩子）。"}, {"text": "棒子", "is_correct": false, "explanation": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}], "explanations": {"样子": "正确。“样子”指东西或人看起来的模样，读 yàng zi。", "胖子": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。", "帐子": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。", "养子": "yǎng（第三声）与 yàng 只差声调，意思是养子（被收养的孩子）。", "棒子": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“这台手机的样子”指外观，与“是方的”描述一致。"}, {"text": "功能", "is_correct": false, "explanation": "语义：功能不能是方的，与句中的外形描述矛盾。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量不能是方的，与句中的外形描述矛盾。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“气味”不能用“方的”来形容。"}], "explanations": {"样子": "正确。“这台手机的样子”指外观，与“是方的”描述一致。", "功能": "语义：功能不能是方的，与句中的外形描述矛盾。", "重量": "语义：重量不能是方的，与句中的外形描述矛盾。", "气味": "搭配：“气味”不能用“方的”来形容。"}, "sentence_index": 6, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗饭的样子吃完了。", "explanation": "这里应该用〈饭菜〉。“样子”指外形，不是可以吃的东西，吃完的应是饭菜。"}, {"text": "他这个月的样子涨了很多。", "explanation": "这里应该用〈工资〉。“样子”指外形，不能用来说明数量的增长；涨的是工资、物价等数额。"}, {"text": "这锅粥的样子很烫。", "explanation": "这里应该用〈温度〉。“样子”指外形，不用来说明温度，粥的冷热不是外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个蛋糕的样子得很漂亮。", "corrected_sentence": "这个蛋糕的样子很漂亮。", "error_description": "错误：“样子得很漂亮”；正确：“样子很漂亮”。“得”是补语标记，不能紧跟名词“样子”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子的样子着很漂亮。", "corrected_sentence": "这张桌子的样子很漂亮。", "error_description": "错误：“样子着很漂亮”；正确：“样子很漂亮”。“着”是动词后的体标记，不能跟在名词“样子”后面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
