INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "样子是人在某种情绪下表现出来的神态。", "primary_collocate": null, "pronunciation": "yàng zi", "ipa": "jɑŋ˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "看他生气的样子，我不敢说话。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子高兴的样子真可爱。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她着急的样子让大家很担心。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他装出一副很累的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老师来了，他马上做出认真的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你难过的样子，我不想再看到。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗等主人回家时，一副可怜的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思的样子，让我想笑。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说话的样子很温柔。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟害怕的样子，大家都看见了。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副", "label": "量词"}, {"form": "样儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "人在某种情绪下表现出来的神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指人的神态或事物的模样，读 yàng zi。"}, {"text": "燕子", "is_correct": false, "explanation": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。"}, {"text": "养子", "is_correct": false, "explanation": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng 与 yàng 声母不同（x/y），意思是巷子（小路）。"}, {"text": "浪子", "is_correct": false, "explanation": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}], "explanations": {"样子": "正确。“样子”指人的神态或事物的模样，读 yàng zi。", "燕子": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。", "养子": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。", "巷子": "xiàng 与 yàng 声母不同（x/y），意思是巷子（小路）。", "浪子": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“看他生气的样子”指生气时的神态，与句意一致。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“看”来表示生气时的神情。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与“生气”时的神态无关，句子是在描写他的神态。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”的对象是可见的神情，“味道”不能用“看”来表示。"}], "explanations": {"样子": "正确。“看他生气的样子”指生气时的神态，与句意一致。", "价格": "搭配：“价格”不能用“看”来表示生气时的神情。", "年龄": "语义：“年龄”与“生气”时的神态无关，句子是在描写他的神态。", "味道": "搭配：“看”的对象是可见的神情，“味道”不能用“看”来表示。"}, "sentence_index": 0, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他装出一只很累的样子。", "explanation": "这里应该用〈副〉。指神态的“样子”用量词“副”，不用“只”。"}, {"text": "这首曲子的样子很响亮。", "explanation": "这里应该用〈声音〉。“样子”指神态或外形，不能用来形容声音的洪亮。"}, {"text": "这个木箱的样子很重。", "explanation": "这里应该用〈分量〉。“样子”指外形或神态，不说物体的轻重；表示轻重要用“分量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指神态或模样，读 yàng zi。"}, {"text": "胖子", "is_correct": false, "explanation": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。"}, {"text": "帐子", "is_correct": false, "explanation": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。"}, {"text": "浪子", "is_correct": false, "explanation": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}, {"text": "棒子", "is_correct": false, "explanation": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}], "explanations": {"样子": "正确。“样子”指神态或模样，读 yàng zi。", "胖子": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。", "帐子": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。", "浪子": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。", "棒子": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“一副可怜的样子”指小狗等主人时的神态，与句意一致。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是器具，不能指小狗的神态。"}, {"text": "盔甲", "is_correct": false, "explanation": "语义：“盔甲”是护身器物，与小狗等主人回家的神态无关。"}, {"text": "扑克", "is_correct": false, "explanation": "搭配：“可怜”修饰的应是神态或处境，不能修饰扑克牌。"}], "explanations": {"样子": "正确。“一副可怜的样子”指小狗等主人时的神态，与句意一致。", "眼镜": "语义：“眼镜”是器具，不能指小狗的神态。", "盔甲": "语义：“盔甲”是护身器物，与小狗等主人回家的神态无关。", "扑克": "搭配：“可怜”修饰的应是神态或处境，不能修饰扑克牌。"}, "sentence_index": 6, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的样子很高。", "explanation": "这里应该用〈温度〉。“样子”指外形或神态，不用来说明温度高低。"}, {"text": "弟弟害怕的样子很鲜艳。", "explanation": "这里应该用〈颜色〉。“样子”指外形或神态，不用来形容色彩的鲜艳；色彩鲜艳要用“颜色”来说。"}, {"text": "弟弟一条害怕的样子，大家都看见了。", "explanation": "这里应该用量词〈副〉。“条”用于细长的物体，不能修饰神态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他露出一副很高兴样子。", "corrected_sentence": "他露出一副很高兴的样子。", "error_description": "错误：“很高兴样子”；正确：“很高兴的样子”。形容词修饰“样子”时，中间要加结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她伤心得样子，让我很难受。", "corrected_sentence": "她伤心的样子，让我很难受。", "error_description": "错误：“伤心得样子”；正确：“伤心的样子”。修饰“样子”时用结构助词“的”，“得”用于连接补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
