INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加号是“+”，是表示加起来的记号。", "primary_collocate": null, "pronunciation": "jiā hào", "ipa": "tɕja˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个算式里缺一个加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在三和五中间写一个加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "键盘上的加号在右边。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个大大的加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加号的样子像一个十字。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看见加号，就知道要把数字加起来。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把加号写成减号了，所以答案错了。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加号两边的数字要加在一起。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在作业本上漏写了加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条横线加一条竖线，就是加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "加號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写在算式里表示相加的记号“+”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加号", "is_correct": true, "explanation": "“加号”是算式里表示相加的符号，填入后句子通顺。"}, {"text": "句号", "is_correct": false, "explanation": "语义：“句号”是句末标点，不是算式里的符号，算式中不会缺句号。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是算式的组成部分，“这个算式里缺一个名字”说不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：算式里不会缺“蛋糕”，“这个算式里缺一个蛋糕”说不通。"}], "explanations": {"加号": "“加号”是算式里表示相加的符号，填入后句子通顺。", "句号": "语义：“句号”是句末标点，不是算式里的符号，算式中不会缺句号。", "名字": "语义：“名字”不是算式的组成部分，“这个算式里缺一个名字”说不通。", "蛋糕": "语义：算式里不会缺“蛋糕”，“这个算式里缺一个蛋糕”说不通。"}, "sentence_index": 0, "correct_answer": "加号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上画了一只大大的加号。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对的东西，加号应用“个”。"}, {"text": "老师在黑板上画了一座大大的加号。", "explanation": "这里应该用〈个〉。“座”用于山、楼房等大型固定的东西，加号不用“座”。"}, {"text": "老师在黑板上画了一把大大的加号。", "explanation": "这里应该用〈个〉。“把”多用于带柄的东西，加号没有柄，应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加号", "is_correct": true, "explanation": "“加号”与“减号”相对，写错的应是加号，填入后句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是符号，不能写成减号。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”不是数学符号，不能写成减号。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不是数学符号，不能写成减号。"}], "explanations": {"加号": "“加号”与“减号”相对，写错的应是加号，填入后句意通顺。", "书包": "语义：“书包”不是符号，不能写成减号。", "咖啡": "语义：“咖啡”不是数学符号，不能写成减号。", "苹果": "语义：“苹果”是水果，不是数学符号，不能写成减号。"}, "sentence_index": 6, "correct_answer": "加号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三乘五，中间要写加号。", "explanation": "这里应该用〈乘号〉。加号表示相加，三乘五要用乘号。"}, {"text": "五减三，中间要写加号。", "explanation": "这里应该用〈减号〉。加号表示相加，五减三要用减号。"}, {"text": "两边的数一样多，中间要写加号。", "explanation": "这里应该用〈等号〉。加号表示相加，表示两边相等要用等号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在草稿纸上画了一只加号。", "corrected_sentence": "他在草稿纸上画了一个加号。", "error_description": "量词错误：“加号”应用量词“个”，不用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在作业本上写了一个的加号。", "corrected_sentence": "他在作业本上写了一个加号。", "error_description": "结构错误：数量短语“一个”与名词“加号”之间不加“的”，应为“一个加号”，不能说“一个的加号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
