INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表示相加的数学符号“+”。", "primary_collocate": null, "pronunciation": "jiā hào", "ipa": "tɕja˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "数学书里的加号表示相加。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加号前面是三，后面是五。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学会了认加号和减号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题里有两个加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用红笔把加号圈了起来。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加号读作“加”，意思是相加。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的计算器上有加号。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先看加号，再算后面的数。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：这个符号是加号还是乘号？", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把加号写得太小。", "target_word": "加号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "加號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数学中表示相加运算的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加号", "is_correct": true, "explanation": "“加号”是表示相加的数学符号，填入后与“表示相加”相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不是符号，不能表示相加。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不表示运算，与“表示相加”不符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不是符号，不能表示相加。"}], "explanations": {"加号": "“加号”是表示相加的数学符号，填入后与“表示相加”相符。", "书包": "语义：“书包”不是符号，不能表示相加。", "名字": "语义：“名字”不表示运算，与“表示相加”不符。", "蛋糕": "语义：“蛋糕”是食物，不是符号，不能表示相加。"}, "sentence_index": 0, "correct_answer": "加号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题里有两只加号。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对的东西，加号应用“个”。"}, {"text": "这道题里有两座加号。", "explanation": "这里应该用〈个〉。“座”用于山、楼房等大型固定的东西，加号不用“座”。"}, {"text": "这道题里有两把加号。", "explanation": "这里应该用〈个〉。“把”多用于带柄的东西，加号没有柄，应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加号", "is_correct": true, "explanation": "“加号”是计算器上常见的按键符号，填入后句意通顺。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：计算器上没有“眼睛”，这句话说不通。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：计算器上不会有“心脏”，与常识不符。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：计算器上没有“窗帘”，“我的计算器上有窗帘”说不通。"}], "explanations": {"加号": "“加号”是计算器上常见的按键符号，填入后句意通顺。", "眼睛": "语义：计算器上没有“眼睛”，这句话说不通。", "心脏": "语义：计算器上不会有“心脏”，与常识不符。", "窗帘": "语义：计算器上没有“窗帘”，“我的计算器上有窗帘”说不通。"}, "sentence_index": 6, "correct_answer": "加号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "四乘二，中间要写加号。", "explanation": "这里应该用〈乘号〉。加号表示相加，四乘二要用乘号。"}, {"text": "六除以三，中间要写加号。", "explanation": "这里应该用〈除号〉。加号表示相加，六除以三要用除号。"}, {"text": "七减二，中间要写加号。", "explanation": "这里应该用〈减号〉。加号表示相加，七减二要用减号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
