INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88849, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "流失是东西慢慢地跑走，越来越少。", "primary_collocate": null, "pronunciation": "liú shī", "ipa": "ljoʊ˧˥ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "水桶有个洞，里面的水慢慢流失了。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，身体里的水分会流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开着窗户，房间里的热量慢慢流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球破了个小洞，里面的空气一点一点流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻袋破了个口，里面的大米一粒粒流失。", "target_word": "流失", "complexity_tier": "T3", "furigana": "Mádài pò le gè kǒu, lǐmiàn de dàmǐ yí lì lì liúshī.", "sentence_source": "generated"}, {"text": "公司工资太低，很多员工都流失了。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里服务不好，老顾客一个个流失了。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面的冷气一直流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池裂开了，池水正在流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有树，一下大雨，泥土就慢慢流失了。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流失了", "label": "体标（了）"}, {"form": "流失着", "label": "体标（着）"}, {"form": "流失过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "东西一点一点跑掉，数量越来越少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88849, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确答案。流失 liú shī：东西一点点跑掉，数量越来越少。"}, {"text": "流逝", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是时间或光阴过去。"}, {"text": "刘氏", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是姓刘的人家。"}, {"text": "流食", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是流质食物。"}], "explanations": {"流失": "正确答案。流失 liú shī：东西一点点跑掉，数量越来越少。", "流逝": "shì（第四声）与 shī（第一声）声调不同，意思是时间或光阴过去。", "刘氏": "shì（第四声）与 shī（第一声）声调不同，意思是姓刘的人家。", "流食": "shí（第二声）与 shī（第一声）声调不同，意思是流质食物。"}, "sentence_index": null, "correct_answer": "流失"}, "level_3": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确。流失指东西一点一点跑掉，符合“水慢慢……了”。"}, {"text": "增加", "is_correct": false, "explanation": "语义：句中有“洞”，水应是跑掉、减少，“增加”与语境相反。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”需要任务、工作作宾语，“水慢慢完成了”不成立。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于植物、生物，不能用于“水”。"}], "explanations": {"流失": "正确。流失指东西一点一点跑掉，符合“水慢慢……了”。", "增加": "语义：句中有“洞”，水应是跑掉、减少，“增加”与语境相反。", "完成": "配价：“完成”需要任务、工作作宾语，“水慢慢完成了”不成立。", "生长": "搭配：“生长”用于植物、生物，不能用于“水”。"}, "sentence_index": 0, "correct_answer": "流失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的钱包流失了，只好坐车回家。", "explanation": "这里应该用〈丢失〉。“流失”指东西慢慢跑走、越来越少，钱包突然找不到应说“丢失”。"}, {"text": "月亮慢慢流失在云层后面。", "explanation": "这里应该用〈消失〉。“流失”指东西一点点跑掉、数量渐少，月亮隐入云层是“消失”，不用“流失”。"}, {"text": "那个孩子昨天流失了。", "explanation": "这里应该用〈失踪〉。“流失”指东西一点点跑掉，孩子突然不见应说“失踪”，“流失”不用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确。流失指顾客一个个离开、越来越少，符合“老顾客一个个……了”。"}, {"text": "诞生", "is_correct": false, "explanation": "搭配：“诞生”指事物或生命开始出现，不能说“力气诞生了”。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”要有新的成果，力气不能被发明，与“哭了很久”的语境不合。"}, {"text": "招募", "is_correct": false, "explanation": "语义：“招募”是招人的动作，力气不能被招募，与“觉得”的主观感受不合。"}], "explanations": {"流失": "正确。流失指顾客一个个离开、越来越少，符合“老顾客一个个……了”。", "诞生": "搭配：“诞生”指事物或生命开始出现，不能说“力气诞生了”。", "发明": "语义：“发明”要有新的成果，力气不能被发明，与“哭了很久”的语境不合。", "招募": "语义：“招募”是招人的动作，力气不能被招募，与“觉得”的主观感受不合。"}, "sentence_index": 6, "correct_answer": "流失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙角的垃圾越流失越多。", "explanation": "这里应该用〈堆积〉。“流失”指东西慢慢跑走、越来越少，垃圾越积越多应说“堆积”，两者方向相反。"}, {"text": "杯底慢慢流失了一层茶叶。", "explanation": "这里应该用〈沉淀〉。茶叶沉在杯底是“沉淀”，不是东西跑走，不能用“流失”。"}, {"text": "妈妈流失了一件新衣服给我。", "explanation": "这里应该用〈买〉。“流失”指东西慢慢跑掉、越来越少，不能带“给我”表示给予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水桶有个洞，里面的水正在一点点流失了。", "corrected_sentence": "水桶有个洞，里面的水正在一点点流失。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用。应说“正在流失”，不能说“正在流失了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯子裂开了，把牛奶慢慢流失了。", "corrected_sentence": "杯子裂开了，牛奶慢慢流失了。", "error_description": "句式错误：“流失”是不及物动词，不能用“把”字句。应说“牛奶慢慢流失了”，不能说“把牛奶慢慢流失了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
