INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "散失；指水土、人才、财物等白白地失去。", "primary_collocate": null, "pronunciation": "liú shī", "ipa": "ljoʊ˧˥ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "这家工厂的技术人员大量流失，生产受到了影响。", "target_word": "流失", "complexity_tier": "T3", "furigana": "zhè jiā gōngchǎng de jìshù rényuán dàliàng liúshī, shēngchǎn shòu dào le yǐngxiǎng.", "sentence_source": "generated"}, {"text": "公司工资太低，很多人才流失了。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行有大量客户流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林砍光了，山坡上的泥土大量流失。", "target_word": "流失", "complexity_tier": "T3", "furigana": "sēnlín kǎn guāng le, shānpō shàng de nítǔ dàliàng liúshī.", "sentence_source": "generated"}, {"text": "员工流失给公司带来了很大的损失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法留住人才，不让人才流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷后，商店的顾客流失了不少。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台新政策，防止资金流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师担心好学生都流失到别的学校。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水冲刷河岸，每年都有大量泥沙流失。", "target_word": "流失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流失了", "label": "体标（了）"}, {"form": "流失着", "label": "体标（着）"}, {"form": "流失过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "水土、人才、客户、资金等白白失去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88850, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确答案。流失 liú shī：水土、人才、财物等白白地失去。"}, {"text": "流逝", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是时间或光阴过去。"}, {"text": "六十", "is_correct": false, "explanation": "liù shí 与 liú shī 两个音节的声调都不同，意思是数字六十。"}, {"text": "流食", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是流质食物。"}], "explanations": {"流失": "正确答案。流失 liú shī：水土、人才、财物等白白地失去。", "流逝": "shì（第四声）与 shī（第一声）声调不同，意思是时间或光阴过去。", "六十": "liù shí 与 liú shī 两个音节的声调都不同，意思是数字六十。", "流食": "shí（第二声）与 shī（第一声）声调不同，意思是流质食物。"}, "sentence_index": null, "correct_answer": "流失"}, "level_3": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确。流失指水土、人才等白白失去，与“技术人员大量……”搭配。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”要带任务、工作等宾语，“技术人员大量完成”缺少宾语，不成立。"}, {"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”说规模、范围，不能说“技术人员大量扩大”。"}, {"text": "招募", "is_correct": false, "explanation": "语义：“招募”是招人的动作，“技术人员”不能去招募别人，与“生产受到了影响”的语境也不合。"}], "explanations": {"流失": "正确。流失指水土、人才等白白失去，与“技术人员大量……”搭配。", "完成": "配价：“完成”要带任务、工作等宾语，“技术人员大量完成”缺少宾语，不成立。", "扩大": "搭配：“扩大”说规模、范围，不能说“技术人员大量扩大”。", "招募": "语义：“招募”是招人的动作，“技术人员”不能去招募别人，与“生产受到了影响”的语境也不合。"}, "sentence_index": 0, "correct_answer": "流失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题慢慢流失了，大家都不再担心。", "explanation": "这里应该用〈消失〉。“流失”指水土、人才、财物等白白失去，不用于问题的消散。"}, {"text": "他的钥匙流失了，只好重新配一把。", "explanation": "这里应该用〈丢失〉。“流失”指水土、人才等逐渐或大量失去，单件物品丢了不用“流失”。"}, {"text": "他流失了这份工作，心里很难过。", "explanation": "这里应该用〈失去〉。“流失”多指水土、人才、客户等大量或逐渐失去，个人的一份工作一般说“失去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流失", "is_correct": true, "explanation": "正确。流失指顾客白白失去，“流失了不少”最自然。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于植物或生物的成长，不能说“顾客生长了不少”。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”的对象是新事物，顾客不能发明出顾客，句中语境不合。"}, {"text": "诞生", "is_correct": false, "explanation": "搭配：“诞生”指事物或生命开始出现，不能用于“商店的顾客”。"}], "explanations": {"流失": "正确。流失指顾客白白失去，“流失了不少”最自然。", "生长": "搭配：“生长”用于植物或生物的成长，不能说“顾客生长了不少”。", "发明": "语义：“发明”的对象是新事物，顾客不能发明出顾客，句中语境不合。", "诞生": "搭配：“诞生”指事物或生命开始出现，不能用于“商店的顾客”。"}, "sentence_index": 6, "correct_answer": "流失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的考试成绩流失了，老师很失望。", "explanation": "这里应该用〈下降〉。“流失”指水土、人才、财物等白白失去，成绩降低应说“下降”。"}, {"text": "他的英语水平流失了，他很着急。", "explanation": "这里应该用〈退步〉。水平降低应说“退步”，“流失”指白白失去水土、人才、财物等，不用于能力。"}, {"text": "他把钱包流失在出租车上了。", "explanation": "这里应该用〈丢〉。单件东西不小心落下应说“丢”，“流失”指水土、人才、财物等大量或逐渐地白白失去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司管理太差，许多骨干人才正在流失了。", "corrected_sentence": "这家公司管理太差，许多骨干人才正在流失。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用。应说“正在流失”，不能说“正在流失了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客户正在一点点流失了，老板很着急。", "corrected_sentence": "客户正在一点点流失，老板很着急。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用。应说“正在流失”，不能说“正在流失了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
