INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88855, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "化解是把难办的事、生气的事弄没了。", "primary_collocate": null, "pronunciation": "huà jiě", "ipa": "xwa⁵¹ tɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他笑着说了几句，化解了我的怒气。", "target_word": "化解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一句道歉，就化解了两人的不快。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的几句话化解了我心里的烦恼。", "target_word": "化解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用一杯茶化解大家的尴尬。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我们化解了小小的误会。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件难办的事，终于化解了。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说个笑话，化解了不好的气氛。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要学会自己化解心里的不满。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥主动说话，化解了我们的冷战。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没生气，还笑着化解了这个麻烦。", "target_word": "化解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "化解了", "label": "完成体"}, {"form": "化解过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用话语或行动让个人的怒气、尴尬、误会、难办的事消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用来消除怒气。"}, {"text": "化解", "is_correct": true, "explanation": "化解：用话语消除怒气，与句意相符。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，用在怒气上说不通。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”的对象是语言或文字，不能以“怒气”作宾语。"}], "explanations": {"种植": "语义：“种植”指栽种植物，不能用来消除怒气。", "化解": "化解：用话语消除怒气，与句意相符。", "收割": "语义：“收割”指割取庄稼，用在怒气上说不通。", "翻译": "配价：“翻译”的对象是语言或文字，不能以“怒气”作宾语。"}, "sentence_index": 0, "correct_answer": "化解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳出来后，院子里的积雪很快就化解了。", "explanation": "这里应该用〈融化〉。融化指固体受热变成液体，如积雪；化解指消除怒气、尴尬或误会，不用于积雪。"}, {"text": "他终于化解了那个复杂的绳结。", "explanation": "这里应该用〈解开〉。解开指把打结的东西松开，绳结是实物；化解只用于怒气、尴尬、误会等情绪或事情。"}, {"text": "风一吹，天上的乌云慢慢化解了。", "explanation": "这里应该用〈散开〉。散开指云、雾等向四周分散不见；化解指消除怒气、尴尬或误会，不用于乌云。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒下种子，不能用来改变气氛。"}, {"text": "化解", "is_correct": true, "explanation": "化解：消除不好的气氛，与“不好的”相符。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指用针线修补衣物，用在气氛上说不通。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”要求选择具体的物品，不能说挑选气氛。"}], "explanations": {"播种": "语义：“播种”指撒下种子，不能用来改变气氛。", "化解": "化解：消除不好的气氛，与“不好的”相符。", "缝补": "语义：“缝补”指用针线修补衣物，用在气氛上说不通。", "挑选": "搭配：“挑选”要求选择具体的物品，不能说挑选气氛。"}, "sentence_index": 6, "correct_answer": "化解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把那台旧机器化解成了几个零件。", "explanation": "这里应该用〈分解〉。分解指把整体拆成几部分，机器可以分解；化解只用于消除麻烦、矛盾，不用于拆机器。"}, {"text": "警察终于化解了那个复杂的密码。", "explanation": "这里应该用〈破解〉。破解指解开密码、谜题；化解用于消除麻烦、矛盾，不用于密码。"}, {"text": "糖很快就化解在热水里了。", "explanation": "这里应该用〈溶化〉。溶化指固体在液体里消失，糖溶于水要用溶化；化解不用于糖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位朋友聊了很久，最后终于化解着误会。", "corrected_sentence": "两位朋友聊了很久，最后终于化解了误会。", "error_description": "错误：“化解着”。“着”表示动作持续，与表示完成的“终于”矛盾，应用“了”，说“化解了误会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一句话就很化解了我的委屈。", "corrected_sentence": "妈妈一句话就化解了我的委屈。", "error_description": "错误：“很化解”。“很”是程度副词，不修饰动词，“化解”前面不能加“很”，应直接说“化解了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与“化解”没有反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造，与“化解”没有反义关系。"}, {"text": "激化", "is_correct": true, "explanation": "激化：使矛盾更加尖锐，与“化解”正相反。"}, {"text": "收集", "is_correct": false, "explanation": "收集指聚拢、搜集，与“化解”没有反义关系。"}], "correct_answer": "激化", "explanations": {"观察": "观察指仔细看，与“化解”没有反义关系。", "修建": "修建指建造，与“化解”没有反义关系。", "激化": "激化：使矛盾更加尖锐，与“化解”正相反。", "收集": "收集指聚拢、搜集，与“化解”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准备", "is_correct": false, "explanation": "准备指事先安排，与“化解”没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗指用水除去污垢，与“化解”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与“化解”没有反义关系。"}, {"text": "激化", "is_correct": true, "explanation": "激化：使矛盾更加尖锐，与“化解”正相反。"}], "correct_answer": "激化", "explanations": {"准备": "准备指事先安排，与“化解”没有反义关系。", "清洗": "清洗指用水除去污垢，与“化解”没有反义关系。", "讨论": "讨论指交换意见，与“化解”没有反义关系。", "激化": "激化：使矛盾更加尖锐，与“化解”正相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消除；使矛盾、困难等解除。", "primary_collocate": null, "pronunciation": "huà jiě", "ipa": "xwa⁵¹ tɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "双方谈了很久，终于化解了矛盾。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想办法化解这次危机。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行用新办法化解了风险。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察及时赶到，化解了一场冲突。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国要通过谈话化解分歧。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把问题一个一个化解了。", "target_word": "化解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用耐心化解了邻居之间的纠纷。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场危机，经理很快就化解了。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要及时化解工作中的困难。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起努力，化解了村里的矛盾。", "target_word": "化解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "化解了", "label": "完成体"}, {"form": "化解过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "通过协商或办法消除矛盾、危机、风险、纠纷等较大的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造房屋、道路，不能用于矛盾。"}, {"text": "熬制", "is_correct": false, "explanation": "搭配：“熬制”多用于汤药、食物，不能说熬制矛盾。"}, {"text": "化解", "is_correct": true, "explanation": "化解：通过协商消除矛盾，与句意相符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指把液体烧到冒泡，不能用于矛盾。"}], "explanations": {"修建": "语义：“修建”指建造房屋、道路，不能用于矛盾。", "熬制": "搭配：“熬制”多用于汤药、食物，不能说熬制矛盾。", "化解": "化解：通过协商消除矛盾，与句意相符。", "煮沸": "语义：“煮沸”指把液体烧到冒泡，不能用于矛盾。"}, "sentence_index": 0, "correct_answer": "化解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃了这种药，他的头痛很快就化解了。", "explanation": "这里应该用〈缓解〉。缓解指病痛、紧张等程度减轻，头痛要用缓解；化解用于矛盾、危机、困难的消除。"}, {"text": "农民们用药剂化解了田里的害虫。", "explanation": "这里应该用〈消灭〉。消灭指彻底除掉害虫、敌人；化解用于矛盾、危机、困难，不用于害虫。"}, {"text": "把食盐放进热水里，很快就化解了。", "explanation": "这里应该用〈溶解〉。溶解指固体在液体中逐渐消失，食盐溶于水要用溶解；化解用于消除矛盾、危机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播放", "is_correct": false, "explanation": "语义：“播放”指放送声音或影像，不能用于纠纷。"}, {"text": "化解", "is_correct": true, "explanation": "化解：耐心地消除纠纷，与“耐心”相符。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”指在硬物上刻出图形，用在纠纷上说不通。"}, {"text": "测量", "is_correct": false, "explanation": "配价：“测量”需要具体的对象和数值，不能以“纠纷”作宾语。"}], "explanations": {"播放": "语义：“播放”指放送声音或影像，不能用于纠纷。", "化解": "化解：耐心地消除纠纷，与“耐心”相符。", "雕刻": "语义：“雕刻”指在硬物上刻出图形，用在纠纷上说不通。", "测量": "配价：“测量”需要具体的对象和数值，不能以“纠纷”作宾语。"}, "sentence_index": 6, "correct_answer": "化解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气温升高后，山上的冰川开始化解。", "explanation": "这里应该用〈消融〉。消融指冰雪逐渐融化，冰川要用消融；化解用于矛盾、困难的消除，不用于冰川。"}, {"text": "这种酶能把脂肪化解成小分子。", "explanation": "这里应该用〈分解〉。分解指物质经过化学变化分成较简单的成分，脂肪要用分解；化解用于矛盾、困难。"}, {"text": "早晨的薄雾渐渐化解了。", "explanation": "这里应该用〈消散〉。消散指雾气、烟等散开不见，薄雾要用消散；化解不用于雾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司谈了很久，最后终于化解着分歧。", "corrected_sentence": "两家公司谈了很久，最后终于化解了分歧。", "error_description": "错误：“化解着”。“着”表示动作持续，与表示完成的“终于”矛盾，应用“了”，说“化解了分歧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区的志愿者耐心劝说，很化解了两户人家的纠纷。", "corrected_sentence": "社区的志愿者耐心劝说，化解了两户人家的纠纷。", "error_description": "错误：“很化解”。“很”只修饰形容词，不能放在动词“化解”前面，应直接说“化解了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
