INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泪是眼睛里流出来的水。人很难过或者很高兴时会流泪。", "primary_collocate": null, "pronunciation": "lèi", "ipa": "leɪ˥˩", "syllable_count": 1, "sentences": [{"text": "她哭了，脸上全是泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到好消息，他高兴得流了泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的眼里含着泪。", "target_word": "泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别难过了，快擦干泪吧。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到这一幕，在场的人都流下了泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他哭了，一滴泪落在了手上。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子笑着笑着，泪就流了下来。", "target_word": "泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太感人，很多观众都在流泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想让别人看见自己的泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哭完了，用手帕擦去脸上的泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "眼泪", "label": "复合"}, {"form": "泪水", "label": "复合"}], "register": "中性", "sense_fingerprint": "泪：难过或高兴时从眼睛里流出来的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：眼睛里流出的水，读 lèi（第四声）。"}, {"text": "雷", "is_correct": false, "explanation": "léi（第二声）与 lèi（第四声）声调不同，意思是雷。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 lèi 声母不同（n 与 l），声调相同，意思是里面。"}, {"text": "厉", "is_correct": false, "explanation": "lì（第四声）与 lèi 韵母不同（i 与 ei），声调相同，意思是严厉。"}, {"text": "蕾", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是花蕾。"}], "explanations": {"泪": "泪：眼睛里流出的水，读 lèi（第四声）。", "雷": "léi（第二声）与 lèi（第四声）声调不同，意思是雷。", "内": "nèi 与 lèi 声母不同（n 与 l），声调相同，意思是里面。", "厉": "lì（第四声）与 lèi 韵母不同（i 与 ei），声调相同，意思是严厉。", "蕾": "lěi（第三声）与 lèi 声调不同，意思是花蕾。"}, "sentence_index": null, "correct_answer": "泪"}, "level_3": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：哭的时候从眼睛里流出的水，与“她哭了”的语境相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会“全是”在脸上，与“她哭了”无关。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖是食物，脸上不会全是糖，与“她哭了”无关。"}, {"text": "钱", "is_correct": false, "explanation": "语义：哭的时候脸上不会全是钱。"}], "explanations": {"泪": "泪：哭的时候从眼睛里流出的水，与“她哭了”的语境相符。", "书": "语义：书不会“全是”在脸上，与“她哭了”无关。", "糖": "语义：糖是食物，脸上不会全是糖，与“她哭了”无关。", "钱": "语义：哭的时候脸上不会全是钱。"}, "sentence_index": 0, "correct_answer": "泪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气太热了，他的脸上全是泪。", "explanation": "这里应该用〈汗〉。天热时脸上出的是汗，泪只指哭时从眼睛里流出的水。"}, {"text": "他感冒了，鼻子里一直流泪。", "explanation": "这里应该用〈鼻涕〉。鼻子里流出的是鼻涕，泪是从眼睛里流出的。"}, {"text": "他摔破了膝盖，伤口里流出了很多泪。", "explanation": "这里应该用〈血〉。伤口里流出的是血，泪是眼睛里流出的水，不会从伤口流出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：眼睛里流出的水，读 lèi（第四声）。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是堡垒。"}, {"text": "镭", "is_correct": false, "explanation": "léi（第二声）与 lèi 声调不同，意思是放射性元素镭。"}, {"text": "磊", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是石头堆叠。"}, {"text": "累", "is_correct": false, "explanation": "lěi（第三声，如“积累”）与 lèi 声调不同。"}], "explanations": {"泪": "泪：眼睛里流出的水，读 lèi（第四声）。", "垒": "lěi（第三声）与 lèi 声调不同，意思是堡垒。", "镭": "léi（第二声）与 lèi 声调不同，意思是放射性元素镭。", "磊": "lěi（第三声）与 lèi 声调不同，意思是石头堆叠。", "累": "lěi（第三声，如“积累”）与 lèi 声调不同。"}, "sentence_index": null, "correct_answer": "泪"}, "level_3": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：从眼睛里流下来的水，与“孩子笑着笑着”的语境相符。"}, {"text": "油", "is_correct": false, "explanation": "语义：孩子笑的时候不会有油从身上流下来。"}, {"text": "墨", "is_correct": false, "explanation": "语义：墨是墨汁，不会因为笑而从人身上流出来。"}, {"text": "霜", "is_correct": false, "explanation": "搭配：霜是凝结的白色颗粒，不说“流下来”。"}], "explanations": {"泪": "泪：从眼睛里流下来的水，与“孩子笑着笑着”的语境相符。", "油": "语义：孩子笑的时候不会有油从身上流下来。", "墨": "语义：墨是墨汁，不会因为笑而从人身上流出来。", "霜": "搭配：霜是凝结的白色颗粒，不说“流下来”。"}, "sentence_index": 6, "correct_answer": "泪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一脚踩进水坑，鞋子里灌满了泪。", "explanation": "这里应该用〈雨水〉。鞋里进的是雨水，泪只指眼睛流出的水。"}, {"text": "炒菜时，锅里溅出了很多泪。", "explanation": "这里应该用〈油〉。炒菜时溅出的是油，泪只指眼泪。"}, {"text": "冬天，屋顶上积了厚厚的泪。", "explanation": "这里应该用〈雪〉。冬天屋顶上积的是雪，泪只指眼泪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他哭的时候，眼睛里掉下了一只泪。", "corrected_sentence": "他哭的时候，眼睛里掉下了一滴泪。", "error_description": "“泪”的量词应为“滴”，不说“只”。把“一只泪”改为“一滴泪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，她的泪流上来了。", "corrected_sentence": "听到这个消息，她的泪流下来了。", "error_description": "补语应为“下来”，眼泪从眼睛里向下流，应说“流下来”，不能说“流上来”。把“流上来了”改为“流下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
