INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼泪；泪腺分泌的液体。", "primary_collocate": null, "pronunciation": "lèi", "ipa": "leɪ˥˩", "syllable_count": 1, "sentences": [{"text": "切洋葱时，我的泪流个不停。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，他的眼睛里都是泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泪是从泪腺里出来的。", "target_word": "泪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "眼睛进了沙子，泪一下就流了出来。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打哈欠打得挤出了泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "伤心时，人的泪会比平时多。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，泪能保护我们的眼睛。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑得太厉害，笑出了泪。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷风一吹，我的泪就掉了下来。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的泪滴在地上，很快就干了。", "target_word": "泪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "眼泪", "label": "复合"}, {"form": "泪水", "label": "复合"}], "register": "中性", "sense_fingerprint": "泪：泪腺分泌的液体，即眼泪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：泪腺分泌的液体，读 lèi（第四声）。"}, {"text": "雷", "is_correct": false, "explanation": "léi（第二声）与 lèi（第四声）声调不同，意思是雷。"}, {"text": "内", "is_correct": false, "explanation": "nèi 与 lèi 声母不同（n 与 l），声调相同，意思是里面。"}, {"text": "厉", "is_correct": false, "explanation": "lì（第四声）与 lèi 韵母不同（i 与 ei），声调相同，意思是严厉。"}, {"text": "蕾", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是花蕾。"}], "explanations": {"泪": "泪：泪腺分泌的液体，读 lèi（第四声）。", "雷": "léi（第二声）与 lèi（第四声）声调不同，意思是雷。", "内": "nèi 与 lèi 声母不同（n 与 l），声调相同，意思是里面。", "厉": "lì（第四声）与 lèi 韵母不同（i 与 ei），声调相同，意思是严厉。", "蕾": "lěi（第三声）与 lèi 声调不同，意思是花蕾。"}, "sentence_index": null, "correct_answer": "泪"}, "level_3": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：泪腺分泌的液体，切洋葱时刺激眼睛会流出泪，与语境相符。"}, {"text": "血", "is_correct": false, "explanation": "语义：切洋葱刺激的是眼睛分泌液体，流出来的不是血。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“流个不停”说的是液体从眼睛里淌出，雨从天上落下，不这样说。"}, {"text": "墨", "is_correct": false, "explanation": "语义：墨是墨汁，与切洋葱时眼睛流出的液体无关。"}], "explanations": {"泪": "泪：泪腺分泌的液体，切洋葱时刺激眼睛会流出泪，与语境相符。", "血": "语义：切洋葱刺激的是眼睛分泌液体，流出来的不是血。", "雨": "搭配：“流个不停”说的是液体从眼睛里淌出，雨从天上落下，不这样说。", "墨": "语义：墨是墨汁，与切洋葱时眼睛流出的液体无关。"}, "sentence_index": 0, "correct_answer": "泪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嘴里流出了很多泪。", "explanation": "这里应该用〈口水〉。嘴里流出的是口水，泪只从眼睛里流出。"}, {"text": "他感冒了，鼻子里一直流泪。", "explanation": "这里应该用〈鼻涕〉。鼻子里流出的是鼻涕，泪只从眼睛里流出。"}, {"text": "跑完步，他额头上冒出了泪。", "explanation": "这里应该用〈汗〉。额头上冒出的是汗，泪是从眼睛里流出的液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：泪腺分泌的液体，读 lèi（第四声）。"}, {"text": "垒", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是堡垒。"}, {"text": "镭", "is_correct": false, "explanation": "léi（第二声）与 lèi 声调不同，意思是放射性元素镭。"}, {"text": "磊", "is_correct": false, "explanation": "lěi（第三声）与 lèi 声调不同，意思是石头堆叠。"}, {"text": "累", "is_correct": false, "explanation": "lěi（第三声，如“积累”）与 lèi 声调不同。"}], "explanations": {"泪": "泪：泪腺分泌的液体，读 lèi（第四声）。", "垒": "lěi（第三声）与 lèi 声调不同，意思是堡垒。", "镭": "léi（第二声）与 lèi 声调不同，意思是放射性元素镭。", "磊": "lěi（第三声）与 lèi 声调不同，意思是石头堆叠。", "累": "lěi（第三声，如“积累”）与 lèi 声调不同。"}, "sentence_index": null, "correct_answer": "泪"}, "level_3": {"options": [{"text": "泪", "is_correct": true, "explanation": "泪：泪腺分泌的液体，与“能保护我们的眼睛”的语境相符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子进入眼睛会伤眼，与“保护”的意思相反。"}, {"text": "灰", "is_correct": false, "explanation": "语义：灰尘会刺激眼睛，不能保护眼睛。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“保护眼睛”的主语多是有保护作用的东西，石头不这样用。"}], "explanations": {"泪": "泪：泪腺分泌的液体，与“能保护我们的眼睛”的语境相符。", "沙子": "语义：沙子进入眼睛会伤眼，与“保护”的意思相反。", "灰": "语义：灰尘会刺激眼睛，不能保护眼睛。", "石头": "搭配：“保护眼睛”的主语多是有保护作用的东西，石头不这样用。"}, "sentence_index": 6, "correct_answer": "泪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一脚踩进泥坑，裤腿上溅满了泪。", "explanation": "这里应该用〈泥〉。裤腿上溅的是泥，泪只指眼泪。"}, {"text": "他切菜时手指被划破，伤口渗出了很多泪。", "explanation": "这里应该用〈血〉。伤口渗出的是血，泪只指眼睛里分泌的液体。"}, {"text": "早上起来，窗玻璃上结了厚厚的泪。", "explanation": "这里应该用〈霜〉。窗玻璃上结的是霜，泪只指眼泪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "切菜的时候，我的眼睛里掉下了一个泪。", "corrected_sentence": "切菜的时候，我的眼睛里掉下了一滴泪。", "error_description": "“泪”的量词应为“滴”，不说“个”。把“一个泪”改为“一滴泪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风一吹，他的泪就流了上来。", "corrected_sentence": "风一吹，他的泪就流了出来。", "error_description": "补语应为“出来”，眼泪从眼睛里向外流，应说“流了出来”，不能说“流了上来”。把“上来”改为“出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小事", "is_correct": true, "explanation": "小事指不重要的事，与“要事”（很重要、必须做的事）构成反义。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌是家具，与“要事”没有反义关系。"}, {"text": "树林", "is_correct": false, "explanation": "树林是自然景物，与“要事”没有反义关系。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶是器物，与“要事”没有反义关系。"}], "correct_answer": "小事", "explanations": {"小事": "小事指不重要的事，与“要事”（很重要、必须做的事）构成反义。", "书桌": "书桌是家具，与“要事”没有反义关系。", "树林": "树林是自然景物，与“要事”没有反义关系。", "花瓶": "花瓶是器物，与“要事”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
