INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "要事是很重要、必须做的事。", "primary_collocate": null, "pronunciation": "yào shì", "ipa": "iɑʊ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这件要事今天必须做完。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天先做要事，再做别的事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板有要事找你，请快一点。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在有要事，晚点给你打电话。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，工作是最大的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会不是小事，是一件要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，学习是你现在的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了今天的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了一件要事，早早起床了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把明天的要事都写好了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件要事", "label": "量词"}], "register": "书面", "sense_fingerprint": "要事：必须做的重要事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确答案。要事 yào shì，指很重要、必须做的事。"}, {"text": "要是", "is_correct": false, "explanation": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。"}, {"text": "要使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“必须做的事”无关。"}, {"text": "药师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，药师指配药的人，与“必须做的事”无关。"}], "explanations": {"要事": "正确答案。要事 yào shì，指很重要、必须做的事。", "要是": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。", "要使": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“必须做的事”无关。", "药师": "shī（第一声）与 shì（第四声）声调不同，药师指配药的人，与“必须做的事”无关。"}, "sentence_index": null, "correct_answer": "要事"}, "level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“这件要事今天必须做完”，要事指必须完成的重要事情。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是愿望，不是可以“做完”的事，与“今天必须”的要求冲突。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“做完”不能用于天空。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“做完”不能用于歌声。"}], "explanations": {"要事": "正确：“这件要事今天必须做完”，要事指必须完成的重要事情。", "梦想": "语义：梦想是愿望，不是可以“做完”的事，与“今天必须”的要求冲突。", "天空": "搭配：“做完”不能用于天空。", "歌声": "搭配：“做完”不能用于歌声。"}, "sentence_index": 0, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学校闯了要事，被老师叫去了。", "explanation": "这里应该用〈大祸〉。“闯”后面接“祸”，要事指需要办理的重要事情，不能说“闯要事”。"}, {"text": "他犯了一个要事，很后悔。", "explanation": "这里应该用〈错误〉。“犯”后面接错误、罪过等，要事指需要办理的重要事情，不能说“犯要事”。"}, {"text": "要事你晚点有空，就给我打个电话吧。", "explanation": "这里应该用〈要是〉。这里表示假设，要是是连词；要事是名词，不能放在句首表示条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“学习是你现在的要事”，要事指现阶段必须做的重要事情。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能说“学习是你现在的饼干”。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，与“学习”不能等同，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：窗帘是物品，不能作为“学习”这类活动的对象。"}], "explanations": {"要事": "正确：“学习是你现在的要事”，要事指现阶段必须做的重要事情。", "饼干": "语义：饼干是食物，不能说“学习是你现在的饼干”。", "雨水": "语义：雨水是自然现象，与“学习”不能等同，句意不通。", "窗帘": "搭配：窗帘是物品，不能作为“学习”这类活动的对象。"}, "sentence_index": 6, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一张要事要办。", "explanation": "这里应该用〈件〉。“张”用于纸张等平面的东西，事情要用“件”。"}, {"text": "他有一把要事要办。", "explanation": "这里应该用〈件〉。“把”用于有柄的器具，事情不能用“把”来计量。"}, {"text": "他有一座要事要办。", "explanation": "这里应该用〈件〉。“座”用于山、楼等大型建筑，事情不能用“座”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本要事明天必须交完。", "corrected_sentence": "这件要事明天必须交完。", "error_description": "量词错误：“要事”是事情，应用“件”。“本”用于书籍等，不能用于事情。正确说法是“这件要事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天有两条要事要办。", "corrected_sentence": "他今天有两件要事要办。", "error_description": "量词错误：“要事”是事情，应用“件”。“条”用于细长的东西，不能用于事情。正确说法是“两件要事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小事", "is_correct": true, "explanation": "小事指不重要的事，与“要事”（重要的事）构成反义。"}, {"text": "课本", "is_correct": false, "explanation": "课本是书籍，与“要事”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是场所，与“要事”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑部件，与“要事”没有反义关系。"}], "correct_answer": "小事", "explanations": {"小事": "小事指不重要的事，与“要事”（重要的事）构成反义。", "课本": "课本是书籍，与“要事”没有反义关系。", "花园": "花园是场所，与“要事”没有反义关系。", "窗户": "窗户是建筑部件，与“要事”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
