INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重要的事情。", "primary_collocate": null, "pronunciation": "yào shì", "ipa": "iɑʊ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "今天我有一件要事要办。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说有要事，所以先走了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在谈一件要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么要事吗？", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说要事，再说小事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把要事写在本子上了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天没有要事，我可以去看你。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸有要事，不能来参加比赛。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要事要先做，小事可以以后做。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为一件要事去了北京。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件要事", "label": "量词"}], "register": "书面", "sense_fingerprint": "要事：重要的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确答案。要事 yào shì，指重要的事情。"}, {"text": "要是", "is_correct": false, "explanation": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。"}, {"text": "要使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“重要的事”无关。"}, {"text": "药师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，药师指配药的人，与“重要的事”无关。"}], "explanations": {"要事": "正确答案。要事 yào shì，指重要的事情。", "要是": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。", "要使": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“重要的事”无关。", "药师": "shī（第一声）与 shì（第四声）声调不同，药师指配药的人，与“重要的事”无关。"}, "sentence_index": null, "correct_answer": "要事"}, "level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“今天我有一件要事要办”，要事指需要处理的重要事情。"}, {"text": "往事", "is_correct": false, "explanation": "语义：往事指过去的事，不能是今天要办的事。"}, {"text": "外套", "is_correct": false, "explanation": "搭配：“办”的对象是事务，不能说“办外套”。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：礼物是物品，不能说“要办一件礼物”。"}], "explanations": {"要事": "正确：“今天我有一件要事要办”，要事指需要处理的重要事情。", "往事": "语义：往事指过去的事，不能是今天要办的事。", "外套": "搭配：“办”的对象是事务，不能说“办外套”。", "礼物": "搭配：礼物是物品，不能说“要办一件礼物”。"}, "sentence_index": 0, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "要事不好了，厨房着火了！", "explanation": "这里应该用〈大事〉。“大事不好了”是表示出了严重意外的固定说法；要事指需要办理的重要事情，不能这样说。"}, {"text": "他犯了个要事。", "explanation": "这里应该用〈错误〉。“犯”后面接错误、罪过等，要事指需要办理的重要事情，不能说“犯要事”。"}, {"text": "要事你明天有空，我们就去看电影。", "explanation": "这里应该用〈要是〉。这里表示假设，要是是连词；要事是名词，不能放在句首表示条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“明天没有要事”，指没有需要处理的重要事情。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气总是存在，不能说“明天没有天气”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气时时存在，不能说“明天没有空气”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“没有心情”与后句“我可以去看你”的主动意愿不协调，这样组合不自然。"}], "explanations": {"要事": "正确：“明天没有要事”，指没有需要处理的重要事情。", "天气": "语义：天气总是存在，不能说“明天没有天气”。", "空气": "语义：空气时时存在，不能说“明天没有空气”。", "心情": "搭配：“没有心情”与后句“我可以去看你”的主动意愿不协调，这样组合不自然。"}, "sentence_index": 6, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一条要事要办。", "explanation": "这里应该用〈件〉。“条”用于细长的东西，事情要用“件”。"}, {"text": "他有一朵要事要办。", "explanation": "这里应该用〈件〉。“朵”用于花等物，事情不能用“朵”来计量。"}, {"text": "他有一台要事要办。", "explanation": "这里应该用〈件〉。“台”用于机器等物，事情不能用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我有一本要事要做。", "corrected_sentence": "明天我有一件要事要做。", "error_description": "量词错误：“要事”是事情，应用“件”。“本”用于书籍等，不能用于事情。正确说法是“一件要事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板今天有两本要事找你。", "corrected_sentence": "老板今天有两件要事找你。", "error_description": "量词错误：“要事”是事情，应用“件”。“本”用于书籍等，不能用于事情。正确说法是“两件要事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
