INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分开;距离。", "primary_collocate": null, "pronunciation": "lí", "ipa": "li³⁵", "syllable_count": 1, "sentences": [{"text": "现在离考试只有三天了。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院离这儿很远。", "target_word": "离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书店离我家只有五分钟。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城离大海很近。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们俩离得太远，不能常见面。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼离了水就活不了。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子离不了妈妈。", "target_word": "离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "离春节还有一个星期。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新家离公司太远，每天要坐一个小时车。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在离下课还有十分钟。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分开;相距", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "离", "is_correct": true, "explanation": "「离」读 lí（第二声），意思是分开，或与某处相距一段距离。"}, {"text": "礼", "is_correct": false, "explanation": "「礼」（第三声）与「离」（第二声）声调不同，意思是礼貌。"}, {"text": "利", "is_correct": false, "explanation": "「利」（第四声）与「离」（第二声）声调不同，意思是利益。"}, {"text": "泥", "is_correct": false, "explanation": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}], "explanations": {"离": "「离」读 lí（第二声），意思是分开，或与某处相距一段距离。", "礼": "「礼」（第三声）与「离」（第二声）声调不同，意思是礼貌。", "利": "「利」（第四声）与「离」（第二声）声调不同，意思是利益。", "泥": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}, "sentence_index": null, "correct_answer": "离"}, "level_3": {"options": [{"text": "缺", "is_correct": false, "explanation": "语义：「缺」表示缺少，与表示时间距离的说法不符。"}, {"text": "离", "is_correct": true, "explanation": "「离」表示相距的时间，正好和「只有三天」相配。"}, {"text": "过", "is_correct": false, "explanation": "语义：「过」表示经过，「现在过考试」说不通。"}, {"text": "差", "is_correct": false, "explanation": "搭配：「差」要说成「还差三天」或「差三天考试」，不能说「现在差考试只有三天了」。"}], "explanations": {"缺": "语义：「缺」表示缺少，与表示时间距离的说法不符。", "离": "「离」表示相距的时间，正好和「只有三天」相配。", "过": "语义：「过」表示经过，「现在过考试」说不通。", "差": "搭配：「差」要说成「还差三天」或「差三天考试」，不能说「现在差考试只有三天了」。"}, "sentence_index": 0, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他离老师说了一句话。", "explanation": "「离」不能表示对某人说话，应该用〈对〉，说「他对老师说了一句话」。"}, {"text": "他离我借了钱。", "explanation": "「离」不能表示向某人借，这里应该用〈向〉，说「他向我借了钱」。"}, {"text": "这两张桌子离在一起，很方便。", "explanation": "「离」表示分开或相隔，不表示靠在一起，应该用〈挨〉，说「两张桌子挨在一起，很方便」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象是饮料，「孩子喝不了妈妈」说不通。"}, {"text": "离", "is_correct": true, "explanation": "「离不了」表示不能分开，与「妈妈」的依赖关系相符。"}, {"text": "抛", "is_correct": false, "explanation": "语义：「抛」指扔掉，「孩子抛不了妈妈」没有意义。"}, {"text": "散", "is_correct": false, "explanation": "语义：「散」指分散，与人之间的依赖关系说不通。"}], "explanations": {"喝": "语义：「喝」的对象是饮料，「孩子喝不了妈妈」说不通。", "离": "「离不了」表示不能分开，与「妈妈」的依赖关系相符。", "抛": "语义：「抛」指扔掉，「孩子抛不了妈妈」没有意义。", "散": "语义：「散」指分散，与人之间的依赖关系说不通。"}, "sentence_index": 6, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他离老师走过来。", "explanation": "「离」表示分开或相隔，不能表示朝某人走近，应该用〈朝〉，说「他朝老师走过来」。"}, {"text": "我离老师拿了一本书。", "explanation": "「离」不能表示从某人那里拿东西，这里应该用〈从〉，说「我从老师那儿拿了一本书」。"}, {"text": "这块石头离在地上。", "explanation": "「离」表示分开或相隔，不能表示物体放在某处，应该用〈在〉或〈放〉，说「这块石头放在地上」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开放假还有两个星期。", "corrected_sentence": "离放假还有两个星期。", "error_description": "表示相距时，「离」后面直接接时间点或事件，不能加「开」。「离开放假」中的「开」多余，「离开」指离去某处，与此处的时间距离不符。正确说法是「离放假还有两个星期」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子离没开妈妈。", "corrected_sentence": "孩子离不开妈妈。", "error_description": "「离不开」中的否定要用「不」，「离没开」是错误的否定形式。正确说法是「离不开妈妈」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜欢", "is_correct": true, "explanation": "喜欢：对人或事物有好感，与“厌恶”意思相反，是反义词。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励指使人振作、增加信心，与“厌恶”没有反义关系。"}, {"text": "讲解", "is_correct": false, "explanation": "讲解指讲述并解释，与“厌恶”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使损坏的东西恢复正常，与“厌恶”没有反义关系。"}], "correct_answer": "喜欢", "explanations": {"喜欢": "喜欢：对人或事物有好感，与“厌恶”意思相反，是反义词。", "鼓励": "鼓励指使人振作、增加信心，与“厌恶”没有反义关系。", "讲解": "讲解指讲述并解释，与“厌恶”没有反义关系。", "修理": "修理指使损坏的东西恢复正常，与“厌恶”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喜欢", "is_correct": true, "explanation": "喜欢：对人或事物有好感，与“厌恶”意思相反，是反义词。"}, {"text": "观看", "is_correct": false, "explanation": "观看指注视着看，与“厌恶”没有反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "等待指停留以期待某事发生，与“厌恶”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意地走走，与“厌恶”没有反义关系。"}], "correct_answer": "喜欢", "explanations": {"喜欢": "喜欢：对人或事物有好感，与“厌恶”意思相反，是反义词。", "观看": "观看指注视着看，与“厌恶”没有反义关系。", "等待": "等待指停留以期待某事发生，与“厌恶”没有反义关系。", "散步": "散步指随意地走走，与“厌恶”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "厌恶是非常不喜欢，一看到就烦。", "primary_collocate": null, "pronunciation": "yàn wù", "ipa": "jɛn˥˩ wu˥˩", "syllable_count": 2, "sentences": [{"text": "我厌恶蟑螂。", "target_word": "厌恶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟最厌恶洗碗。", "target_word": "厌恶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很厌恶香菜的味道。", "target_word": "厌恶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我厌恶下雨天出门。", "target_word": "厌恶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他厌恶别人迟到。", "target_word": "厌恶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈厌恶过那种吵闹的音乐，现在习惯了。", "target_word": "厌恶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到乱扔的垃圾，我就很厌恶。", "target_word": "厌恶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这种虚伪的客套话非常厌恶。", "target_word": "厌恶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都厌恶他吃饭时的怪声音。", "target_word": "厌恶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她厌恶地把脏衣服扔进了洗衣机。", "target_word": "厌恶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厌恶过", "label": "体标"}, {"form": "厌恶着", "label": "体标"}, {"form": "厌恶了", "label": "体标"}], "register": "中性", "sense_fingerprint": "厌恶：非常不喜欢，一看到就心烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厌恶", "is_correct": true, "explanation": "厌恶：非常不喜欢，一看到就心烦。"}, {"text": "烟雾", "is_correct": false, "explanation": "厌恶 yàn 与 烟雾 yān 声调不同（第四声与第一声），“烟雾”指烟和雾。"}, {"text": "延误", "is_correct": false, "explanation": "厌恶 yàn 与 延误 yán 声调不同（第四声与第二声），“延误”指耽误时间。"}, {"text": "万物", "is_correct": false, "explanation": "厌恶 yàn 与 万物 wàn 声母不同（y 与 w，声调相同），“万物”指世间的一切事物。"}], "explanations": {"厌恶": "厌恶：非常不喜欢，一看到就心烦。", "烟雾": "厌恶 yàn 与 烟雾 yān 声调不同（第四声与第一声），“烟雾”指烟和雾。", "延误": "厌恶 yàn 与 延误 yán 声调不同（第四声与第二声），“延误”指耽误时间。", "万物": "厌恶 yàn 与 万物 wàn 声母不同（y 与 w，声调相同），“万物”指世间的一切事物。"}, "sentence_index": null, "correct_answer": "厌恶"}, "level_3": {"options": [{"text": "厌恶", "is_correct": true, "explanation": "正确：“厌恶”表示非常不喜欢，可以带“蟑螂”作宾语，句意通顺。"}, {"text": "倾听", "is_correct": false, "explanation": "搭配：“倾听”的对象是声音或别人的话语，不能用于“蟑螂”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用于昆虫，句子不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车辆或船只作宾语，不能支配“蟑螂”。"}], "explanations": {"厌恶": "正确：“厌恶”表示非常不喜欢，可以带“蟑螂”作宾语，句意通顺。", "倾听": "搭配：“倾听”的对象是声音或别人的话语，不能用于“蟑螂”。", "唱": "语义：“唱”的对象是歌曲，不能用于昆虫，句子不通。", "驾驶": "配价：“驾驶”需要车辆或船只作宾语，不能支配“蟑螂”。"}, "sentence_index": 0, "correct_answer": "厌恶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我厌恶地盼着周末的到来。", "explanation": "这里应该用〈向往〉。“厌恶”表示非常不喜欢、一看到就烦，与“盼着周末到来”的心情矛盾。"}, {"text": "我厌恶地把你的礼物收下，还郑重地向你道谢。", "explanation": "这里应该用〈感激〉。“厌恶”表示非常不喜欢，与“郑重道谢”的心情矛盾。"}, {"text": "我厌恶地去医院探望那位生病的老人。", "explanation": "这里应该用〈同情〉。“厌恶”表示非常不喜欢，与“去医院探望”的关心行为矛盾，对生病的人应表示同情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厌恶", "is_correct": true, "explanation": "正确：“很厌恶”表达对乱扔垃圾的反感，符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：看到乱扔的垃圾不会“欢迎”，句子意思与语境相反。"}, {"text": "感激", "is_correct": false, "explanation": "搭配：“感激”需要有人给予帮助或好处，乱扔的垃圾不能使人感激。"}, {"text": "羡慕", "is_correct": false, "explanation": "语义：看到乱扔的垃圾不会引起“羡慕”，句子不通。"}], "explanations": {"厌恶": "正确：“很厌恶”表达对乱扔垃圾的反感，符合语境。", "欢迎": "语义：看到乱扔的垃圾不会“欢迎”，句子意思与语境相反。", "感激": "搭配：“感激”需要有人给予帮助或好处，乱扔的垃圾不能使人感激。", "羡慕": "语义：看到乱扔的垃圾不会引起“羡慕”，句子不通。"}, "sentence_index": 6, "correct_answer": "厌恶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我厌恶地夸他的毅力惊人。", "explanation": "这里应该用〈钦佩〉。“厌恶”表示非常不喜欢，与“夸他毅力惊人”的赞赏态度矛盾，对别人的毅力应表示钦佩。"}, {"text": "妈妈厌恶地把我的画挂在了客厅最显眼的地方。", "explanation": "这里应该用〈欣赏〉。“厌恶”表示非常不喜欢，与“挂在最显眼的地方”的珍视行为矛盾。"}, {"text": "校长厌恶地为他的努力颁发了奖状。", "explanation": "这里应该用〈称赞〉。“厌恶”表示非常不喜欢，与“颁发奖状”的肯定态度矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种虫子我厌恶很。", "corrected_sentence": "这种虫子我厌恶得很。", "error_description": "补语错误：表示程度的“厌恶得很”需要结构助词“得”，不能说“厌恶很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法很厌恶。", "corrected_sentence": "这种做法令人厌恶。", "error_description": "错误：“这种做法很厌恶”。“厌恶”的主语须是有感受的人，“这种做法”不能厌恶；应说“令人厌恶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
