INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "瀑布是从很高的山上流下来的大水，像一块白布。", "primary_collocate": null, "pronunciation": "pù bù", "ipa": "pʰu˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "山上有一道白色的瀑布。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了很久，终于看到了瀑布。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瀑布从山上流下来，声音很大。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在瀑布前拍照。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，很多人去瀑布旁边玩水。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条瀑布像一块长长的白布。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，山里的瀑布更大了。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处传来瀑布的声音。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在瀑布下面洗了洗手。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这道瀑布画下来。", "target_word": "瀑布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "条", "label": "量词"}, {"form": "大瀑布", "label": "复合"}], "register": "中性", "sense_fingerprint": "从高山上流下的大水，像白布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瀑布", "is_correct": true, "explanation": "正确：“瀑布”是从高处流下来的大水，与“一道白色的”搭配，描写的是水流。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“道”用于线状或带状的事物，石头应说“块”或“个”，不能说“一道白色的石头”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是从山上流下来的水，与“白色的一道”所描写的水流不符。"}, {"text": "花", "is_correct": false, "explanation": "搭配：花一般用“朵”计量，“一道白色的花”说不通。"}], "explanations": {"瀑布": "正确：“瀑布”是从高处流下来的大水，与“一道白色的”搭配，描写的是水流。", "石头": "搭配：“道”用于线状或带状的事物，石头应说“块”或“个”，不能说“一道白色的石头”。", "树": "语义：树不是从山上流下来的水，与“白色的一道”所描写的水流不符。", "花": "搭配：花一般用“朵”计量，“一道白色的花”说不通。"}, "sentence_index": 0, "correct_answer": "瀑布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石缝里慢慢冒出一道清凉的瀑布。", "explanation": "这里应该用〈泉水〉。泉水从地下慢慢涌出；瀑布是从高处倾泻下来的水，不会从石缝里冒出。"}, {"text": "一道瀑布在草地上慢慢地流。", "explanation": "这里应该用〈溪流〉。溪流在平地上缓缓流动；瀑布是从高处急速落下的水，不会在草地上慢慢流。"}, {"text": "这里的瀑布很平静，适合划船。", "explanation": "这里应该用〈湖泊〉。湖泊水面平静，适合划船；瀑布水流湍急，不能形容平静，也不适合划船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瀑布", "is_correct": true, "explanation": "正确：雨后山里的水量增加，“瀑布”会因此变大，与“更大了”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会因为下雨而变大，与“雨后”的语境相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是人造物，不会因为雨后而“更大了”。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“更大了”多用于水量、体积会增长的事物，雕像不会因雨变大。"}], "explanations": {"瀑布": "正确：雨后山里的水量增加，“瀑布”会因此变大，与“更大了”相符。", "房子": "语义：房子不会因为下雨而变大，与“雨后”的语境相矛盾。", "桌子": "语义：桌子是人造物，不会因为雨后而“更大了”。", "雕像": "搭配：“更大了”多用于水量、体积会增长的事物，雕像不会因雨变大。"}, "sentence_index": 6, "correct_answer": "瀑布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上的杯子里有一道瀑布。", "explanation": "这里应该用〈水〉。杯子里装的是水；瀑布是从高山上流下来的大水，不会在杯子里。"}, {"text": "这道瀑布在平地上慢慢地流向村子。", "explanation": "这里应该用〈小河〉。小河在平地上慢慢流；瀑布是从高处落下来的水，不会在平地上慢慢流。"}, {"text": "这道瀑布很平静，我们在上面划船。", "explanation": "这里应该用〈湖〉。湖水平静，可以划船；瀑布水流很急，不能在上面划船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷里有一只很高的瀑布。", "corrected_sentence": "山谷里有一道很高的瀑布。", "error_description": "“瀑布”的量词用错了：应说“一道”或“一条”，“只”一般用于动物，不能用来计量瀑布。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这棵瀑布拍下来了。", "corrected_sentence": "我们把这道瀑布拍下来了。", "error_description": "“瀑布”的量词用错了：应说“这道”或“这条”，“棵”用于树木，不能用来计量瀑布。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
