INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "诗是一行一行写出来的、念起来好听的短文。", "primary_collocate": null, "pronunciation": "shī", "ipa": "ʂɨ˥", "syllable_count": 1, "sentences": [{"text": "这首诗只有四行，读起来很好听。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把诗一行一行写在本子上。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多短的诗。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们大声念着诗，声音很整齐。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在黑板上写了一首诗。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗很短，我一下子就背会了。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我读了一首诗，然后我就睡着了。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的每一行都不长。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读诗的声音很好听。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给你写一首诗，写在这张纸上。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首", "label": "量词"}, {"form": "诗人", "label": "复合"}, {"form": "诗歌", "label": "复合"}, {"form": "詩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "分行书写、读起来好听的短文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88867, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗 shī 指分行书写、读起来好听的短文，正是听到的词。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是数字十。"}, {"text": "书", "is_correct": false, "explanation": "shū 与 shī 韵母不同（u 与 i），意思是书籍。"}, {"text": "思", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），意思是思考、思想。"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是是、对。"}], "explanations": {"诗": "诗 shī 指分行书写、读起来好听的短文，正是听到的词。", "十": "shí（第二声）与 shī（第一声）声调不同，意思是数字十。", "书": "shū 与 shī 韵母不同（u 与 i），意思是书籍。", "思": "sī 与 shī 声母不同（s 与 sh），意思是思考、思想。", "是": "shì（第四声）与 shī（第一声）声调不同，意思是是、对。"}, "sentence_index": null, "correct_answer": "诗"}, "level_3": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗：与量词“首”搭配，指短小、分行书写的诗。"}, {"text": "画", "is_correct": false, "explanation": "量词：“首”用于诗、歌等，不用于画，画应说“幅”，“这首画”不成句。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以“读”的东西，且不能用“首”计量，“这首饭”不成句。"}, {"text": "信", "is_correct": false, "explanation": "量词：信用“封”计量，不说“这首信”，而且信不讲究“四行”。"}], "explanations": {"诗": "诗：与量词“首”搭配，指短小、分行书写的诗。", "画": "量词：“首”用于诗、歌等，不用于画，画应说“幅”，“这首画”不成句。", "饭": "语义：饭不是可以“读”的东西，且不能用“首”计量，“这首饭”不成句。", "信": "量词：信用“封”计量，不说“这首信”，而且信不讲究“四行”。"}, "sentence_index": 0, "correct_answer": "诗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这首诗烤着吃了。", "explanation": "这里应该用〈饼〉。诗是纸上的文字，不能烤着吃，烤着吃只用于饼等食物。"}, {"text": "这首诗很胖。", "explanation": "这里应该用〈猫〉。胖只能形容有形体的东西，诗是文字，不能说胖。"}, {"text": "她每天给这首诗喂饭。", "explanation": "这里应该用〈小狗〉。诗不吃饭，不能说喂饭，给小狗喂饭才这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88867, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗 shī 指分行书写、读起来好听的短文，正是听到的词。"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是时间。"}, {"text": "丝", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），意思是丝线、丝绸。"}, {"text": "市", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是城市、市场。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是使用、使得。"}], "explanations": {"诗": "诗 shī 指分行书写、读起来好听的短文，正是听到的词。", "时": "shí（第二声）与 shī（第一声）声调不同，意思是时间。", "丝": "sī 与 shī 声母不同（s 与 sh），意思是丝线、丝绸。", "市": "shì（第四声）与 shī（第一声）声调不同，意思是城市、市场。", "使": "shǐ（第三声）与 shī（第一声）声调不同，意思是使用、使得。"}, "sentence_index": null, "correct_answer": "诗"}, "level_3": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗：与“读”搭配，指读的诗。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：乐曲是用来听的，不能用“读”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以“读”的东西，“读饭”没有意义，且不能用“首”计量。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是用来看的，不能“读”，也不用“首”计量。"}], "explanations": {"诗": "诗：与“读”搭配，指读的诗。", "乐曲": "搭配：乐曲是用来听的，不能用“读”。", "饭": "语义：饭不是可以“读”的东西，“读饭”没有意义，且不能用“首”计量。", "电影": "语义：电影是用来看的，不能“读”，也不用“首”计量。"}, "sentence_index": 6, "correct_answer": "诗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想给你写一张诗，写在这张纸上。", "explanation": "这里应该用〈首〉。诗用“首”计量，“张”用于纸、照片等平面的东西。"}, {"text": "我想给你穿一首诗。", "explanation": "这里应该用〈读〉。诗是文字，不能穿，“穿”只用于衣服等可以穿戴的东西。"}, {"text": "我想给你煎一首诗吃。", "explanation": "这里应该用〈鸡蛋〉。诗是文字，不能煎来吃，煎只用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, i