INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文学体裁，用精练、有节奏的语言抒发感情。", "primary_collocate": null, "pronunciation": "shī", "ipa": "ʂɨ˥", "syllable_count": 1, "sentences": [{"text": "他从小就喜欢读诗。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}, {"text": "诗讲究用词精练。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}, {"text": "他对诗很有兴趣，常写诗表达想家的心情。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗是一种文学，用短短的话写出感情。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢用诗表达自己的心情。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学诗需要多读多背。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}, {"text": "他从十岁起就开始写诗。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}, {"text": "诗能让人安静下来，慢慢感受生活。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}, {"text": "中国的诗很讲究节奏。", "target_word": "诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲课时常常提到诗的历史。", "target_word": "诗", "complexity_tier": "T3", "furigana": "shī", "sentence_source": "generated"}], "morphological_forms": [{"form": "首", "label": "量词"}, {"form": "诗人", "label": "复合"}, {"form": "诗歌", "label": "复合"}, {"form": "詩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "抒发感情的文学体裁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗 shī 指文学体裁，正是听到的词。"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是时间。"}, {"text": "书", "is_correct": false, "explanation": "shū 与 shī 韵母不同（u 与 i），意思是书籍。"}, {"text": "思", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），意思是思考、思想。"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是是、对。"}], "explanations": {"诗": "诗 shī 指文学体裁，正是听到的词。", "时": "shí（第二声）与 shī（第一声）声调不同，意思是时间。", "书": "shū 与 shī 韵母不同（u 与 i），意思是书籍。", "思": "sī 与 shī 声母不同（s 与 sh），意思是思考、思想。", "是": "shì（第四声）与 shī（第一声）声调不同，意思是是、对。"}, "sentence_index": null, "correct_answer": "诗"}, "level_3": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗：与“读”搭配，指读诗。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不是可以“读”的东西，“读车”没有意义。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是可以“读”的东西，“读鱼”没有意义。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以读的东西，“读饭”没有意义。"}], "explanations": {"诗": "诗：与“读”搭配，指读诗。", "车": "语义：车不是可以“读”的东西，“读车”没有意义。", "鱼": "语义：鱼不是可以“读”的东西，“读鱼”没有意义。", "饭": "语义：饭不是可以读的东西，“读饭”没有意义。"}, "sentence_index": 0, "correct_answer": "诗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗规定了双方的责任。", "explanation": "这里应该用〈合同〉。诗抒发感情，不能规定双方的责任，合同才这样用。"}, {"text": "这首诗统计了全市的人口。", "explanation": "这里应该用〈报告〉。诗抒发感情，不用来统计数据，统计数据才这样写。"}, {"text": "这首诗证明我付过钱了。", "explanation": "这里应该用〈收据〉。诗抒发感情，不能用来证明付款，收据才这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88868, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗 shī 指文学体裁，正是听到的词。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是数字十。"}, {"text": "丝", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），意思是丝线、丝绸。"}, {"text": "事", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是事情。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是使用、使得。"}], "explanations": {"诗": "诗 shī 指文学体裁，正是听到的词。", "十": "shí（第二声）与 shī（第一声）声调不同，意思是数字十。", "丝": "sī 与 shī 声母不同（s 与 sh），意思是丝线、丝绸。", "事": "shì（第四声）与 shī（第一声）声调不同，意思是事情。", "使": "shǐ（第三声）与 shī（第一声）声调不同，意思是使用、使得。"}, "sentence_index": null, "correct_answer": "诗"}, "level_3": {"options": [{"text": "诗", "is_correct": true, "explanation": "诗：与“写”搭配，指写诗。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜不是用来写的，“写菜”没有意义。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能用“写”来做，句子说不通。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“写”不与“汤”搭配，做汤要说煮或熬。"}], "explanations": {"诗": "诗：与“写”搭配，指写诗。", "菜": "语义：菜不是用来写的，“写菜”没有意义。", "鱼": "语义：鱼不能用“写”来做，句子说不通。", "汤": "搭配：“写”不与“汤”搭配，做汤要说煮或熬。"}, "sentence_index": 6, "correct_answer": "诗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗标出了山的位置。", "explanation": "这里应该用〈地图〉。诗抒发感情，不能用来标出位置。"}, {"text": "这首诗算出了结果。", "explanation": "这里应该用〈计算器〉。诗是抒发感情的文字，不能算出结果。"}, {"text": "这首诗能测量温度。", "explanation": "这里应该用〈仪器〉。诗是文字，不能测量温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天晚上都读一个诗。", "corrected_sentence": "她每天晚上都读一首诗。", "error_description": "错误：诗的量词应为“首”，不能用“个”。应说“一首诗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写了三诗。", "corrected_sentence": "她写了三首诗。", "error_description": "错误：诗作为数量词后面要加量词“首”，“三诗”应说“三首诗”，不能漏掉量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
