INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听到就是用耳朵知道了声音。", "primary_collocate": null, "pronunciation": "tīng dào", "ipa": "tʰiŋ˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在房间里听到了雷声。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜我听到有人敲门。", "target_word": "听到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你听到外面的雨声了吗？", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没听到妈妈叫他。", "target_word": "听到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我听到楼上有小孩儿在哭。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天早上我听到小鸟唱歌。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我什么都没听到。", "target_word": "听到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你听到音乐声了吗？", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里很安静，我听到了水声。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚进门就听到了电话铃声。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "听到了", "label": "体标（了）"}, {"form": "听到过", "label": "体标（过）"}, {"form": "听不到", "label": "可能补语（否定）"}, {"form": "聽到", "label": "繁体"}], "register": "通用", "sense_fingerprint": "听到：用耳朵知道声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听到", "is_correct": true, "explanation": "正确答案。「我在房间里听到了雷声」中，听到表示耳朵接收到了声音。"}, {"text": "看到", "is_correct": false, "explanation": "语义：雷声是用耳朵听的，不能用眼睛看到。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：雷声没有气味，不能用闻到。"}, {"text": "找到", "is_correct": false, "explanation": "配价：找到要求可寻找的具体事物，雷声不能被找到。"}], "explanations": {"听到": "正确答案。「我在房间里听到了雷声」中，听到表示耳朵接收到了声音。", "看到": "语义：雷声是用耳朵听的，不能用眼睛看到。", "闻到": "语义：雷声没有气味，不能用闻到。", "找到": "配价：找到要求可寻找的具体事物，雷声不能被找到。"}, "sentence_index": 0, "correct_answer": "听到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听到了他的温柔。", "explanation": "这里应该用〈体会到〉。温柔要用心去体会到，听到只用于声音。"}, {"text": "我听到了房间里的温度变化。", "explanation": "这里应该用〈感觉到〉。温度变化要用感觉到，听到只用于声音。"}, {"text": "饭菜的香味飘了过来，我听到了。", "explanation": "这里应该用〈闻到〉。香味要用鼻子闻到，听到只用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听到", "is_correct": true, "explanation": "正确答案。「我什么都没听到」中，听到表示没有接收到任何声音。"}, {"text": "听从", "is_correct": false, "explanation": "搭配：听从用于意见、命令，不能说「什么都没听从」。"}, {"text": "搬到", "is_correct": false, "explanation": "配价：搬到需要搬运的对象和目的地，「什么都没搬到」不通。"}, {"text": "跑到", "is_correct": false, "explanation": "配价：跑到需要明确的地点，「什么都没跑到」语义不通。"}], "explanations": {"听到": "正确答案。「我什么都没听到」中，听到表示没有接收到任何声音。", "听从": "搭配：听从用于意见、命令，不能说「什么都没听从」。", "搬到": "配价：搬到需要搬运的对象和目的地，「什么都没搬到」不通。", "跑到": "配价：跑到需要明确的地点，「什么都没跑到」语义不通。"}, "sentence_index": 6, "correct_answer": "听到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听到了窗外的月亮。", "explanation": "这里应该用〈看到〉。月亮是用眼睛看到的，听到只用于声音。"}, {"text": "我听到了一封朋友的信。", "explanation": "这里应该用〈收到〉。信是收到的，不能用听到。"}, {"text": "我听到了桌子上的一个杯子。", "explanation": "这里应该用〈注意到〉。杯子是看到或注意到的，听到只用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房里听到着铃声。", "corrected_sentence": "妈妈在厨房里听到了铃声。", "error_description": "错误：「听到」后的动态助词应用「了」表示完成，不能用「着」。「听到着」不成立，应说「听到了铃声」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隔壁很吵，我听到不你说话。", "corrected_sentence": "隔壁很吵，我听不到你说话。", "error_description": "错误：否定词「不」放在了补语「到」之后。可能补语的否定形式是「V不C」，应说「听不到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
