INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耳朵接收到声音。", "primary_collocate": null, "pronunciation": "tīng dào", "ipa": "tʰiŋ˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我好像听到了他的声音。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在教室外面也能听到歌声。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户开着，我听到了汽车声。", "target_word": "听到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说话声音太小，我没听到。", "target_word": "听到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉时，他听到了奇怪的声音。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子听到狗叫，有点儿怕。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上很静，能听到钟声。", "target_word": "听到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大声点儿，后面的同学听到了吗？", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她戴着耳机，没有听到火车的声音。", "target_word": "听到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在海边听到了海浪声。", "target_word": "听到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "听到了", "label": "体标（了）"}, {"form": "听到过", "label": "体标（过）"}, {"form": "听不到", "label": "可能补语（否定）"}, {"form": "聽到", "label": "繁体"}], "register": "通用", "sense_fingerprint": "听到：耳朵接收到声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听到", "is_correct": true, "explanation": "正确答案。「我好像听到了他的声音」中，听到表示耳朵接收到了声音。"}, {"text": "看到", "is_correct": false, "explanation": "语义：看到的是画面，不能用眼睛看到声音。"}, {"text": "碰到", "is_correct": false, "explanation": "搭配：碰到用于人或物体，不能说碰到声音。"}, {"text": "摸到", "is_correct": false, "explanation": "语义：摸到是触觉，声音不能被摸到。"}], "explanations": {"听到": "正确答案。「我好像听到了他的声音」中，听到表示耳朵接收到了声音。", "看到": "语义：看到的是画面，不能用眼睛看到声音。", "碰到": "搭配：碰到用于人或物体，不能说碰到声音。", "摸到": "语义：摸到是触觉，声音不能被摸到。"}, "sentence_index": 0, "correct_answer": "听到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听到了汤的咸味。", "explanation": "这里应该用〈尝到〉。咸味要用舌头尝到，听到只用于声音。"}, {"text": "我听到了天上的彩虹。", "explanation": "这里应该用〈看见〉。彩虹是用眼睛看见的，听到只用于声音。"}, {"text": "我听到了一个硬东西。", "explanation": "这里应该用〈摸到〉。硬东西要用手摸到，听到只用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听到", "is_correct": true, "explanation": "正确答案。「晚上很静，能听到钟声」中，听到表示能接收到钟声。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：钟声是声音，不能用鼻子闻到。"}, {"text": "尝到", "is_correct": false, "explanation": "语义：钟声不能用舌头尝到，句子不通。"}, {"text": "找到", "is_correct": false, "explanation": "搭配：找到用于可寻找的事物，钟声不能被找到。"}], "explanations": {"听到": "正确答案。「晚上很静，能听到钟声」中，听到表示能接收到钟声。", "闻到": "语义：钟声是声音，不能用鼻子闻到。", "尝到": "语义：钟声不能用舌头尝到，句子不通。", "找到": "搭配：找到用于可寻找的事物，钟声不能被找到。"}, "sentence_index": 6, "correct_answer": "听到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听到了烤鸭的香味。", "explanation": "这里应该用〈闻到〉。香味要用鼻子闻到，听到只用于声音。"}, {"text": "我听到了那本书。", "explanation": "这里应该用〈找到〉。书是用眼睛或手找到的，听到只用于声音。"}, {"text": "阳光照在身上，我听到了温暖。", "explanation": "这里应该用〈感受到〉。温暖要用身体感受到，听到只用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在远处听到得钟声。", "corrected_sentence": "我在远处听得到钟声。", "error_description": "错误：可能补语「得」与补语「到」位置颠倒。正确的说法是「听得到」，不能说「听到得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上在山里，我能听到过了猫叫声。", "corrected_sentence": "晚上在山里，我能听到猫叫声。", "error_description": "错误：「听到」后同时加了两个体标「过」和「了」，二者不能并用。「听到过」表示经历，「听到了」表示完成，此处应去掉体标，说「能听到猫叫声」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
