INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88871, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参谋是帮着领头人出主意的人。", "primary_collocate": null, "pronunciation": "cān móu", "ipa": "tsʰan⁵⁵ mou³⁵", "syllable_count": 2, "sentences": [{"text": "老板有个好参谋，生意越做越大。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们队长的好参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别光看着，给我当个参谋吧。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给朋友当参谋，帮他挑了一件外套。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长遇到难事，总去找他这个参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是全家人的参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了一位参谋来帮忙做计划。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在班里是班长的参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理身边少不了一位好参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有你这个参谋，我心里就踏实了。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位参谋", "label": "量词"}, {"form": "参谋长", "label": "复合"}, {"form": "参谋部", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮领头人出主意的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参谋", "is_correct": true, "explanation": "正确。“参谋”指帮领头人出主意的人，与“生意越做越大”的语境相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”不能帮老板出主意，与“生意越做越大”的经营语境不搭。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”与“老板”的经营语境冲突，句子不通。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“好参谋”指能帮人出主意的人，“好花”指好看的花，与“老板有个……”不搭。"}], "explanations": {"参谋": "正确。“参谋”指帮领头人出主意的人，与“生意越做越大”的语境相符。", "乐器": "语义：“乐器”不能帮老板出主意，与“生意越做越大”的经营语境不搭。", "病人": "语义：“病人”与“老板”的经营语境冲突，句子不通。", "花": "搭配：“好参谋”指能帮人出主意的人，“好花”指好看的花，与“老板有个……”不搭。"}, "sentence_index": 0, "correct_answer": "参谋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位参谋每天负责打扫办公室。", "explanation": "这里应该用〈清洁工〉。“参谋”是帮人出主意的人，不负责打扫卫生，打扫办公室的是清洁工。"}, {"text": "我们公司新来了一条参谋。", "explanation": "这里应该用〈位〉。“参谋”指人，量词用“位”，“条”多用于长形物或动物，不能用于人。"}, {"text": "他在饭店里当参谋，负责端菜。", "explanation": "这里应该用〈服务员〉。“参谋”出主意，不负责端菜，端菜的人是服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参谋", "is_correct": true, "explanation": "正确。“参谋”指帮人出主意、做计划的人，与“帮忙做计划”的语境一致。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”与“做计划”的工作无关，句子读起来不通。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“位”只用于人，“一位猫”不能说，搭配不当。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：“运动员”的工作与“做计划”不相关，语境冲突。"}], "explanations": {"参谋": "正确。“参谋”指帮人出主意、做计划的人，与“帮忙做计划”的语境一致。", "厨师": "语义：“厨师”与“做计划”的工作无关，句子读起来不通。", "猫": "搭配：量词“位”只用于人，“一位猫”不能说，搭配不当。", "运动员": "语义：“运动员”的工作与“做计划”不相关，语境冲突。"}, "sentence_index": 6, "correct_answer": "参谋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去参谋博物馆。", "explanation": "这里应该用〈参观〉。“参谋”作动词只表示出主意，去某处看要说“参观”。"}, {"text": "他十八岁参谋了。", "explanation": "这里应该用〈参军〉。“参军”指入伍，“参谋”作动词只表示出主意，不表示入伍。"}, {"text": "我在这个参谋里很踏实。", "explanation": "这里不用〈参谋〉作场所。“参谋”指人，表示地点要说“参谋部”，这句话里的“参谋里”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周公司来了一只新参谋，大家都很欢迎。", "corrected_sentence": "上周公司来了一位新参谋，大家都很欢迎。", "error_description": "错误：指人的“参谋”用量词“只”，“只”多用于动物或器物。应改为“位”，正确说法是“上周公司来了一位新参谋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位参谋们给了我很多建议。", "corrected_sentence": "这位参谋给了我很多建议。", "error_description": "错误：“这位”已表示单数，后面又加了复数标记“们”，二者不能同用。应去掉“们”，正确说法是“这位参谋给了我很多建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
