INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帮助指挥者出主意、拟计划的人。", "primary_collocate": null, "pronunciation": "cān móu", "ipa": "tsʰan⁵⁵ mou³⁵", "syllable_count": 2, "sentences": [{"text": "他是将军身边最信任的参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位参谋为部队制订了作战计划。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参谋把地图放在桌子上，开始讲解。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令请参谋提出几个办法。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军队里当过三年参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位年轻的参谋跑进指挥室。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参谋们整夜都在研究这场战斗。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当一名参谋。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参谋建议部队先在山下休息。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位参谋很会看地图，想法也多。", "target_word": "参谋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位参谋", "label": "量词"}, {"form": "参谋长", "label": "复合"}, {"form": "参谋部", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队中帮指挥者出主意、拟计划的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参谋", "is_correct": true, "explanation": "正确。“参谋”指帮指挥者出主意、拟计划的人，与“将军身边”“最信任”的语境相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”是来参观游玩的人，不会是将军身边最信任的人，与语境不搭。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：“清洁工”不是帮将军出主意的身份，与“最信任”的语境冲突。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“最信任的”只修饰人，不能修饰“花”，句子不成立。"}], "explanations": {"参谋": "正确。“参谋”指帮指挥者出主意、拟计划的人，与“将军身边”“最信任”的语境相符。", "游客": "语义：“游客”是来参观游玩的人，不会是将军身边最信任的人，与语境不搭。", "清洁工": "语义：“清洁工”不是帮将军出主意的身份，与“最信任”的语境冲突。", "花": "搭配：“最信任的”只修饰人，不能修饰“花”，句子不成立。"}, "sentence_index": 0, "correct_answer": "参谋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是将军的参谋，每天开车送他上班。", "explanation": "这里应该用〈司机〉。“参谋”指出主意、拟计划的人，不负责开车，开车送人的是司机。"}, {"text": "我们连队来了一只参谋。", "explanation": "这里应该用〈位〉。“参谋”指人，量词用“位”，“只”多用于动物或器物。"}, {"text": "他每天在厨房里当参谋，负责炒菜。", "explanation": "这里应该用〈厨师〉。“参谋”负责出主意，不负责炒菜，炒菜的人才是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参谋", "is_correct": true, "explanation": "正确。“参谋”指能研究作战计划的人，“们”表示复数，与“研究这场战斗”搭配。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”的工作与研究战斗无关，句子读起来不通。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”不研究战斗，与“整夜研究这场战斗”的语境冲突。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“们”通常只接人，“椅子们”不能研究战斗，搭配不当。"}], "explanations": {"参谋": "正确。“参谋”指能研究作战计划的人，“们”表示复数，与“研究这场战斗”搭配。", "厨师": "语义：“厨师”的工作与研究战斗无关，句子读起来不通。", "病人": "语义：“病人”不研究战斗，与“整夜研究这场战斗”的语境冲突。", "椅子": "搭配：“们”通常只接人，“椅子们”不能研究战斗，搭配不当。"}, "sentence_index": 6, "correct_answer": "参谋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去参谋博物馆。", "explanation": "这里应该用〈参观〉。“参谋”作动词只表示出主意，去某处看要说“参观”。"}, {"text": "他十八岁参谋了。", "explanation": "这里应该用〈参军〉。“参军”指入伍，“参谋”作动词只表示出主意，不表示入伍。"}, {"text": "他在参谋里工作，很会看地图。", "explanation": "这里不用〈参谋〉作场所。“参谋”指人，表示地点要说“在参谋部工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天来了一只新参谋，大家都很欢迎。", "corrected_sentence": "昨天来了一位新参谋，大家都很欢迎。", "error_description": "错误：指人的“参谋”用量词“只”，“只”多用于动物或器物。应改为“位”，正确说法是“昨天来了一位新参谋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位参谋们提出了好主意。", "corrected_sentence": "这位参谋提出了好主意。", "error_description": "错误：“这位”已表示单数，后面又加了复数标记“们”，二者不能同用。应去掉“们”，正确说法是“这位参谋提出了好主意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
