INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88873, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无敌是谁也打不过他，比谁都厉害。", "primary_collocate": null, "pronunciation": "wú dí", "ipa": "u˧˥ ti˧˥", "syllable_count": 2, "sentences": [{"text": "他玩这个游戏简直无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥打篮球无敌了。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们班，他打乒乓球无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷下象棋无敌，我们都下不过他。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩儿力气大，在院子里无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做菜的本事真是无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己很厉害，在朋友中无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的足球队今年几乎无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了三碗饭，他觉得自己无敌了。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐游泳无敌，没有人比得上她。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无敌手", "label": "复合"}, {"form": "天下无敌", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里夸人某方面强到谁也比不过，非常厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无敌", "is_correct": true, "explanation": "无敌：谁也打不过，形容玩游戏水平很高，与语境相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或声音，不能用来说玩游戏的水平。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容整洁的状态，玩游戏不说“简直干净”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的体形，不能用来形容玩游戏的本事。"}], "explanations": {"无敌": "无敌：谁也打不过，形容玩游戏水平很高，与语境相符。", "安静": "语义：“安静”形容环境或声音，不能用来说玩游戏的水平。", "干净": "搭配：“干净”形容整洁的状态，玩游戏不说“简直干净”。", "瘦": "体貌：“瘦”形容人或物的体形，不能用来形容玩游戏的本事。"}, "sentence_index": 0, "correct_answer": "无敌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上有无敌的星星。", "explanation": "这里应该用〈无数〉。无敌表示谁也打不过，不能用来形容数量多。"}, {"text": "这张票已经无敌了。", "explanation": "这里应该用〈无效〉。无敌指没有对手，不能用来说票据失去效力。"}, {"text": "他因为生病，无敌参加比赛。", "explanation": "这里应该用〈无法〉。无敌指没有对手，不能表示不能做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无敌", "is_correct": true, "explanation": "无敌：没有人能打败，与“自己很厉害，在朋友中无敌”的语境相符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”说物体能透光，不能用来形容在朋友中的能力。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”说的是物体或环境缺少水分，与人的能力无关。"}, {"text": "漆黑", "is_correct": false, "explanation": "体貌：“漆黑”形容颜色或光线，不能用来形容一个人的本事。"}], "explanations": {"无敌": "无敌：没有人能打败，与“自己很厉害，在朋友中无敌”的语境相符。", "透明": "语义：“透明”说物体能透光，不能用来形容在朋友中的能力。", "干燥": "语义：“干燥”说的是物体或环境缺少水分，与人的能力无关。", "漆黑": "体貌：“漆黑”形容颜色或光线，不能用来形容一个人的本事。"}, "sentence_index": 6, "correct_answer": "无敌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对我无敌地微笑。", "explanation": "这里应该用〈友好〉。无敌指没有对手，不能用来形容态度。"}, {"text": "他被打倒后，只能无敌地躺在地上。", "explanation": "这里应该用〈无力〉。无敌指没有对手，不能形容身体没有力气。"}, {"text": "他的声音无敌地颤抖着。", "explanation": "这里应该用〈微微〉。无敌指谁也比不过，不能用来形容声音颤抖的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她打羽毛球打无敌。", "corrected_sentence": "她打羽毛球打得无敌。", "error_description": "程度补语前缺少结构助词“得”，应说“打得无敌”，不说“打无敌”。补上“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他游泳游无敌。", "corrected_sentence": "他游泳游得无敌。", "error_description": "漏掉了结构助词“得”。程度补语要用“动词＋得＋形容词”，应说“游得无敌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
