INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88874, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有对手；没有人能战胜。", "primary_collocate": null, "pronunciation": "wú dí", "ipa": "u˧˥ ti˧˥", "syllable_count": 2, "sentences": [{"text": "这支军队英勇善战，所向无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的武功天下无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都说这位将军天下无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国王的军队在战场上无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路赢下来，在这个地区无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，这支球队在联赛中无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说中的英雄英勇无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了十年剑，终于天下无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个王朝的海军曾经无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人敢说自己永远无敌。", "target_word": "无敌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天下无敌", "label": "复合"}, {"form": "所向无敌", "label": "复合"}], "register": "书面", "sense_fingerprint": "书面语里指军队、英雄等没有对手，无人能够战胜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ba2d241-c769-4d79-a29b-136e0561a15f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无敌", "is_correct": true, "explanation": "无敌：没有对手，与“所向无敌”的固定说法相符。"}, {"text": "有效", "is_correct": false, "explanation": "搭配：“所向”后不接“有效”，这不是固定说法。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：军队英勇善战，不能说“所向虚弱”，与语境矛盾。"}, {"text": "无名", "is_correct": false, "explanation": "语义：“无名”指没有名气，与“英勇善战”的语境不符。"}], "explanations": {"无敌": "无敌：没有对手，与“所向无敌”的固定说法相符。", "有效": "搭配：“所向”后不接“有效”，这不是固定说法。", "虚弱": "语义：军队英勇善战，不能说“所向虚弱”，与语境矛盾。", "无名": "语义：“无名”指没有名气，与“英勇善战”的语境不符。"}, "sentence_index": 0, "correct_answer": "无敌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们因为受伤，无敌继续作战。", "explanation": "这里应该用〈无法〉。无敌指没有对手，不能表示不能做某事。"}, {"text": "那个被冤枉的人是无敌的。", "explanation": "这里应该用〈无辜〉。无敌指没有对手，不能用来说人没有罪过。"}, {"text": "这份文件已经无敌。", "explanation": "这里应该用〈无效〉。无敌指没有对手，不能用来说文件失去效力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无敌", "is_correct": true, "explanation": "无敌：没有对手，与“英勇无敌”的语境相符。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：“懦弱”与“英勇”意思相反，不能一起形容英雄。"}, {"text": "愚笨", "is_correct": false, "explanation": "语义：“愚笨”形容头脑不灵活，与“英勇”的语境矛盾。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“英勇”后不接“迟钝”，两者不搭配。"}], "explanations": {"无敌": "无敌：没有对手，与“英勇无敌”的语境相符。", "懦弱": "语义：“懦弱”与“英勇”意思相反，不能一起形容英雄。", "愚笨": "语义：“愚笨”形容头脑不灵活，与“英勇”的语境矛盾。", "迟钝": "搭配：“英勇”后不接“迟钝”，两者不搭配。"}, "sentence_index": 6, "correct_answer": "无敌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了这个消息，无敌地摇了摇头。", "explanation": "这里应该用〈无奈〉。无敌指没有对手，不能形容摇头的神情。"}, {"text": "他听到这个消息，眼睛无敌地湿了。", "explanation": "这里应该用〈慢慢〉。无敌指没有对手，不能形容眼睛变湿的过程。"}, {"text": "他听完那句话，脸色无敌地红了。", "explanation": "这里应该用〈一下子〉。无敌指没有对手，不能形容脸色变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那支舰队在海上所向很无敌。", "corrected_sentence": "那支舰队在海上所向无敌。", "error_description": "“所向无敌”是固定说法，中间不能插入程度副词“很”，应说“所向无敌”，不说“所向很无敌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他苦练十年，最后天下无敌着。", "corrected_sentence": "他苦练十年，最后天下无敌了。", "error_description": "表示状态变化的“了”不能换成“着”，应说“天下无敌了”，不说“天下无敌着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7306b11-ef26-4f7f-8585-c8afe1b1bec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
