INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责人是管一件事、出了问题要来解决的人。", "primary_collocate": null, "pronunciation": "fù zé rén", "ipa": "fu˥˩ tsɤ˧˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "出了问题，请找我们的负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的负责人是王经理。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这家店的负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "负责人今天不在，明天再来吧。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这次活动的负责人？", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "负责人要把问题解决好。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想见一下你们的负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位负责人对工作很认真。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校让他当安全负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，负责人马上过来了。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "项目负责人", "label": "复合"}, {"form": "負責人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管一件事并要解决问题的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "负责人", "is_correct": true, "explanation": "“负责人”是管事并负责解决问题的人，填入后句意通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能负责处理问题，出了问题不能去找窗户。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”不是人，不能负责解决问题。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“找”后面不说“天气”，“我们的天气”也无法负责解决问题。"}], "explanations": {"负责人": "“负责人”是管事并负责解决问题的人，填入后句意通顺。", "窗户": "语义：“窗户”不能负责处理问题，出了问题不能去找窗户。", "书架": "语义：“书架”不是人，不能负责解决问题。", "天气": "搭配：“找”后面不说“天气”，“我们的天气”也无法负责解决问题。"}, "sentence_index": 0, "correct_answer": "负责人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只负责人今天不在，明天再来吧。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“只”多用于动物。"}, {"text": "那把负责人今天不在，明天再来吧。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“把”多用于带柄的东西。"}, {"text": "那条负责人今天不在，明天再来吧。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“条”多用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "负责人", "is_correct": true, "explanation": "“负责人”是要见的、负责事情的人，填入后句意通顺。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不是人，不能去见。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是人，不能去见。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“见”的对象应是人，不说“见空气”。"}], "explanations": {"负责人": "“负责人”是要见的、负责事情的人，填入后句意通顺。", "雨伞": "语义：“雨伞”不是人，不能去见。", "冰箱": "语义：“冰箱”不是人，不能去见。", "空气": "搭配：“见”的对象应是人，不说“见空气”。"}, "sentence_index": 6, "correct_answer": "负责人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直努力尽到自己的负责人。", "explanation": "这里应该用〈责任〉。“尽到”搭配“责任”“义务”，“负责人”指担任职务的人，不能被尽到。"}, {"text": "这辆车是这个项目的负责人。", "explanation": "这里指的是物，不是人。“负责人”只指人，不能用来称呼车辆。"}, {"text": "他遇到问题就躲，从不承担自己的负责人。", "explanation": "这里应该用〈责任〉。“承担”搭配“责任”，“负责人”指担任职务的人，不能被承担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
