INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "担负某项工作责任的人。", "primary_collocate": null, "pronunciation": "fù zé rén", "ipa": "fu˥˩ tsɤ˧˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "小李是我们组的负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新来了一位负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了三年负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议由负责人来主持。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的负责人不是我。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个小组都有一位负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请负责人在表上签字。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这个部门的负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "负责人说下周开始工作。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很相信这位负责人。", "target_word": "负责人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "总负责人", "label": "复合"}, {"form": "負責人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "担负某项工作责任的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5456ff-15e9-40ec-b901-9b4471d7eed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "负责人", "is_correct": true, "explanation": "“负责人”指担任组内职务的人，填入后句意通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能担任组的负责人。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”不是人，不能担任组的负责人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“是……的”后面接职务人员，不说“是……的天气”。"}], "explanations": {"负责人": "“负责人”指担任组内职务的人，填入后句意通顺。", "冰箱": "语义：“冰箱”是家电，不能担任组的负责人。", "书架": "语义：“书架”不是人，不能担任组的负责人。", "天气": "搭配：“是……的”后面接职务人员，不说“是……的天气”。"}, "sentence_index": 0, "correct_answer": "负责人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司新来了一只负责人。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“只”多用于动物。"}, {"text": "公司新来了一座负责人。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“座”用于大型固定的东西。"}, {"text": "公司新来了一条负责人。", "explanation": "这里应该用〈位〉。“负责人”指人，量词用“位”，“条”多用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "负责人", "is_correct": true, "explanation": "“负责人”是负责签字事务的人，填入后句意通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能在表上签字。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不能在表上签字。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：“蜡烛”不是人，不能在表上签字。"}], "explanations": {"负责人": "“负责人”是负责签字事务的人，填入后句意通顺。", "窗户": "语义：“窗户”不能在表上签字。", "雨伞": "语义：“雨伞”不能在表上签字。", "蜡烛": "语义：“蜡烛”不是人，不能在表上签字。"}, "sentence_index": 6, "correct_answer": "负责人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直努力履行自己的负责人。", "explanation": "这里应该用〈职责〉。“履行”搭配“职责”“义务”，“负责人”指担任职务的人，不能被履行。"}, {"text": "谁都不想承担，大家都想推卸负责人。", "explanation": "这里应该用〈责任〉。“推卸”搭配“责任”，“负责人”指担任职务的人，不能被推卸。"}, {"text": "这台机器是我们的负责人。", "explanation": "这里应该用〈设备〉。“负责人”只指人，机器不是人，不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb6bf42d-96ee-4393-8bf5-7682663e03ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
