INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88877, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运用是把学到的东西拿来用。", "primary_collocate": null, "pronunciation": "yùn yòng", "ipa": "yn˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学了新词要多运用。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把学到的语法运用到写作里。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能灵活运用课堂上学的知识。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过的东西要在生活中运用。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把数学知识运用到工作中。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练习是为了更好地运用所学知识。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在运用刚学的方法做题。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规则你会运用吗?", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有多说,才能熟练运用汉语。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少运用学过的英语。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运用了", "label": "体标"}, {"form": "运用着", "label": "体标"}, {"form": "运用过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把学到的知识、语法、规则等用到实际中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运用", "is_correct": true, "explanation": "运用（yùn yòng）指把学到的东西拿来用，是正确答案。"}, {"text": "运动", "is_correct": false, "explanation": "yùn dòng 与 yùn yòng 第二音节声母不同（d 与 y），意思是体育锻炼。"}, {"text": "运送", "is_correct": false, "explanation": "yùn sòng 与 yùn yòng 第二音节声母不同（s 与 y），意思是把货物送到别处。"}, {"text": "运营", "is_correct": false, "explanation": "yùn yíng 与 yùn yòng 第二音节韵母不同（ing 与 ong），意思是经营管理。"}], "explanations": {"运用": "运用（yùn yòng）指把学到的东西拿来用，是正确答案。", "运动": "yùn dòng 与 yùn yòng 第二音节声母不同（d 与 y），意思是体育锻炼。", "运送": "yùn sòng 与 yùn yòng 第二音节声母不同（s 与 y），意思是把货物送到别处。", "运营": "yùn yíng 与 yùn yòng 第二音节韵母不同（ing 与 ong），意思是经营管理。"}, "sentence_index": null, "correct_answer": "运用"}, "level_3": {"options": [{"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”指欣赏景物或表演，不能用来说学习新词。"}, {"text": "运用", "is_correct": true, "explanation": "正确。“运用”指把学到的东西拿来用，与“学了新词”的语境相符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物等有形物体，不说“搬运新词”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指以愉快的心情得到好处，不能用来说把新词用于实际。"}], "explanations": {"观赏": "语义：“观赏”指欣赏景物或表演，不能用来说学习新词。", "运用": "正确。“运用”指把学到的东西拿来用，与“学了新词”的语境相符。", "搬运": "搭配：“搬运”的对象是货物等有形物体，不说“搬运新词”。", "享受": "语义：“享受”指以愉快的心情得到好处，不能用来说把新词用于实际。"}, "sentence_index": 0, "correct_answer": "运用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他运用一把剪刀剪开了纸箱。", "explanation": "这里应该用〈用〉。“运用”指把学到的方法、知识拿来用，用剪刀剪东西只是一般的使用，应说“用”。"}, {"text": "她每天运用一个小时去跑步。", "explanation": "这里应该用〈用〉。“用一个小时跑步”指花时间，“运用”指把学到的东西拿来用，不能用来说花时间。"}, {"text": "他运用了很长时间背单词。", "explanation": "这里应该用〈花〉。背单词要花时间，应说“花了很长时间”；“运用”指把学到的东西拿来用，不用来说花费时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐曲，不说“演奏方法”。"}, {"text": "运用", "is_correct": true, "explanation": "正确。“运用”指把学到的方法拿来用，与“刚学的方法做题”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、物品等，不说“修理方法”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得美好而观赏，不能用来说用方法做题。"}], "explanations": {"演奏": "搭配：“演奏”的对象是乐曲，不说“演奏方法”。", "运用": "正确。“运用”指把学到的方法拿来用，与“刚学的方法做题”相符。", "修理": "搭配：“修理”的对象是机器、物品等，不说“修理方法”。", "欣赏": "语义：“欣赏”指觉得美好而观赏，不能用来说用方法做题。"}, "sentence_index": 6, "correct_answer": "运用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他运用了一顿美味的晚饭。", "explanation": "这里应该用〈享受〉。“享受”是享用、得到愉快，吃美味的晚饭要说“享受”，“运用”不能用于吃饭。"}, {"text": "他运用了一张机票。", "explanation": "这里应该用〈订〉。机票要用“订”来取得，“运用”不能用于取得机票。"}, {"text": "她运用了一位老师帮助自己。", "explanation": "这里应该用〈请〉。“运用”的对象是方法、知识等，不能用来指人；请老师来帮忙要用“请”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学过的语法要运用了起来。", "corrected_sentence": "学过的语法要运用起来。", "error_description": "“要”后面的动词不能带“了”，应说“要运用起来”，不能说“要运用了起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我会把学到的方法运用工作里。", "corrected_sentence": "我会把学到的方法运用到工作里。", "error_description": "“运用”后面要用介词“到”引出用于的范围，应说“运用到工作里”，不能省略“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
