INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据事物的特点加以利用。", "primary_collocate": null, "pronunciation": "yùn yòng", "ipa": "yn˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很会运用各种方法解决问题。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家巧妙地运用语言表达感情。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生运用新技术治好了病人。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师运用图片让课堂更有意思。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家善于运用颜色。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人运用科学方法提高了产量。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要运用好手里的资源。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他运用自己的经验帮助了大家。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事运用了很多比喻。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司运用大数据了解客人需要。", "target_word": "运用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运用了", "label": "体标"}, {"form": "运用着", "label": "体标"}, {"form": "运用过", "label": "体标"}], "register": "书面", "sense_fingerprint": "根据特点利用方法、技术、语言等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运用", "is_correct": true, "explanation": "运用（yùn yòng）指根据事物特点加以利用，是正确答案。"}, {"text": "运动", "is_correct": false, "explanation": "yùn dòng 与 yùn yòng 第二音节声母不同（d 与 y），意思是体育锻炼。"}, {"text": "运送", "is_correct": false, "explanation": "yùn sòng 与 yùn yòng 第二音节声母不同（s 与 y），意思是把货物送到别处。"}, {"text": "运营", "is_correct": false, "explanation": "yùn yíng 与 yùn yòng 第二音节韵母不同（ing 与 ong），意思是经营管理。"}], "explanations": {"运用": "运用（yùn yòng）指根据事物特点加以利用，是正确答案。", "运动": "yùn dòng 与 yùn yòng 第二音节声母不同（d 与 y），意思是体育锻炼。", "运送": "yùn sòng 与 yùn yòng 第二音节声母不同（s 与 y），意思是把货物送到别处。", "运营": "yùn yíng 与 yùn yòng 第二音节韵母不同（ing 与 ong），意思是经营管理。"}, "sentence_index": null, "correct_answer": "运用"}, "level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指以愉快的心情接受或得到好处，不能用来说利用方法。"}, {"text": "运用", "is_correct": true, "explanation": "正确。“运用”指把方法、技术等用到实际中，与“方法”搭配。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物等有形物体，不说“搬运方法”。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的宾语是活动、比赛等，不说“举办方法”。"}], "explanations": {"享受": "语义：“享受”指以愉快的心情接受或得到好处，不能用来说利用方法。", "运用": "正确。“运用”指把方法、技术等用到实际中，与“方法”搭配。", "搬运": "搭配：“搬运”的对象是货物等有形物体，不说“搬运方法”。", "举办": "搭配：“举办”的宾语是活动、比赛等，不说“举办方法”。"}, "sentence_index": 0, "correct_answer": "运用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他运用得很开心。", "explanation": "这里应该用〈玩〉。“运用”指把方法、技术等用到实际中，不能用来描述玩得开心，应说“玩得很开心”。"}, {"text": "她运用了一场大雨。", "explanation": "这里应该用〈遇到〉。雨是天气，不是可以拿来利用的方法或资源，“运用”不能用于天气，应说“遇到一场大雨”。"}, {"text": "他运用了很大的脾气。", "explanation": "这里应该用〈发〉。“运用”的对象是方法、技术、知识等，不能用于情绪，应说“发了很大的脾气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与句中善用资源的意思相反。"}, {"text": "运用", "is_correct": true, "explanation": "正确。“运用”指把资源等用到实际中，与“好”连用表示用得恰当。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”指扔掉，与句中要求善用资源的意思相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”是不及物动词，不能带“资源”作宾语。"}], "explanations": {"浪费": "语义：“浪费”指白白耗费，与句中善用资源的意思相反。", "运用": "正确。“运用”指把资源等用到实际中，与“好”连用表示用得恰当。", "丢弃": "语义：“丢弃”指扔掉，与句中要求善用资源的意思相反。", "睡觉": "搭配：“睡觉”是不及物动词，不能带“资源”作宾语。"}, "sentence_index": 6, "correct_answer": "运用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天运用一小时跑步。", "explanation": "这里应该用〈用〉。“用一小时跑步”指花时间，“运用”指根据特点利用方法、技术等，不能用来说花时间。"}, {"text": "我们运用了一个愉快的周末。", "explanation": "这里应该用〈度过〉。“运用”不能用来说过时光，应说“度过了一个愉快的周末”。"}, {"text": "他运用了一个感冒。", "explanation": "这里应该用〈得〉。感冒是疾病，要说“得”，“运用”不能用于疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他运用了过这种方法。", "corrected_sentence": "他运用过这种方法。", "error_description": "“运用”的经历体标是“过”，不能与“了”同用，应说“运用过”，不能说“运用了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司善于运用了新技术。", "corrected_sentence": "这家公司善于运用新技术。", "error_description": "“善于”表示一般能力，后面不能加表示动态完成的“了”，应说“善于运用新技术”，不能说“善于运用了新技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "反应时是看到东西到动手去做的那一小会儿时间。", "primary_collocate": null, "pronunciation": "fǎn yìng shí", "ipa": "fan˨˩˦ iŋ˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "打游戏的人反应时往往很短。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的反应时太长，没接住球。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员的反应时必须很短。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从看到红灯到踩刹车，中间就是反应时。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩儿的反应时比大人长一点。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的反应时很短，一下就抓住了杯子。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "累的时候，我的反应时会变长。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球飞过来，我的反应时只有一小会儿。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反应时短的人，打乒乓球更有优势。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，喝咖啡能让反应时变短。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "看到东西到动手去做之间的短暂时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反应时", "is_correct": true, "explanation": "反应时：看到东西到动手去做之间的短暂时间，打游戏的人反应时往往很短。"}, {"text": "脉搏", "is_correct": false, "explanation": "搭配：“脉搏”说快慢，不说“很短”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”说高低，不说长短，句意不通。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”说好坏、强弱，不说长短。"}], "explanations": {"反应时": "反应时：看到东西到动手去做之间的短暂时间，打游戏的人反应时往往很短。", "脉搏": "搭配：“脉搏”说快慢，不说“很短”。", "体温": "语义：“体温”说高低，不说长短，句意不通。", "视力": "搭配：“视力”说好坏、强弱，不说长短。"}, "sentence_index": 0, "correct_answer": "反应时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这件事的反应时很深。", "explanation": "这里应该用〈感受〉。反应时指时间，不能表示心里的感受深浅，要用〈感受〉。"}, {"text": "这辆车的反应时很快。", "explanation": "这里应该用〈速度〉。反应时是时间，说快慢要用〈速度〉。"}, {"text": "这次考试的反应时是两个小时。", "explanation": "这里应该用〈时间〉。反应时专指从看到刺激到做出动作之间的一小段时间，整场考试的时长不能叫反应时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反应时", "is_correct": true, "explanation": "反应时：从看到刺激到做出动作的时间，累的时候它会变长。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说轻重、增减，不说变长。"}, {"text": "记忆力", "is_correct": false, "explanation": "搭配：“记忆力”说好坏、强弱，不说变长。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是冷热的程度，不会变长。"}], "explanations": {"反应时": "反应时：从看到刺激到做出动作的时间，累的时候它会变长。", "体重": "搭配：“体重”说轻重、增减，不说变长。", "记忆力": "搭配：“记忆力”说好坏、强弱，不说变长。", "体温": "语义：“体温”是冷热的程度，不会变长。"}, "sentence_index": 6, "correct_answer": "反应时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个运动员的反应时很灵活。", "explanation": "这里应该用〈动作〉。灵活形容动作敏捷，反应时只指时间，不能用来形容动作。"}, {"text": "我看了看钟，他的反应时是三点整。", "explanation": "这里应该用〈时刻〉。反应时指一小会儿时间，不能说某个时间点，说某一时刻要用〈时刻〉。"}, {"text": "这场演出的反应时很精彩。", "explanation": "这里应该用〈表现〉。反应时只指一小会儿的时间，不能用来评价一场演出精不精彩，那要用〈表现〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的反应时比他快。", "corrected_sentence": "我的反应时比他短。", "error_description": "错误在“快”。“反应时”是时间，应说“长”或“短”，不说“快”；想说反应快，应说“反应时比他短”，或用“反应速度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的反应时比他短多。", "corrected_sentence": "我的反应时比他短得多。", "error_description": "错误在“得”的遗漏。比较句中表示差距的补语要用“短得多”，不说“短多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
