INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从刺激出现到做出反应所需的时间。", "primary_collocate": null, "pronunciation": "fǎn yìng shí", "ipa": "fan˨˩˦ iŋ˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "司机的反应时越短，越安全。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验要测量人的反应时。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝酒以后，人的反应时会变长。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的反应时比普通人短。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的反应时一般比年轻人长。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们记录每个人的反应时。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车打电话会让反应时变长。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以测反应时。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得不好，反应时也会变长。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的反应时只有零点二秒。", "target_word": "反应时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "刺激到反应所需的时间（心理学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反应时", "is_correct": true, "explanation": "反应时：从刺激出现到做出反应所需的时间，司机的反应时越短越安全。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”说好坏、强弱，不说长短。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”是快慢的比率，不是时间的长短，不能说“越短”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”说大小、年轻或年长，不说“越短”。"}], "explanations": {"反应时": "反应时：从刺激出现到做出反应所需的时间，司机的反应时越短越安全。", "视力": "搭配：“视力”说好坏、强弱，不说长短。", "速度": "语义：“速度”是快慢的比率，不是时间的长短，不能说“越短”。", "年龄": "搭配：“年龄”说大小、年轻或年长，不说“越短”。"}, "sentence_index": 0, "correct_answer": "反应时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事的反应时很冷淡。", "explanation": "这里应该用〈反应〉。反应时只指从刺激出现到做出动作的时间，说人对事情的态度要用〈反应〉。"}, {"text": "这个小孩的反应时比大人快。", "explanation": "这里应该用〈反应速度〉。反应时是时间，只能说长或短，说快慢要用〈反应速度〉。"}, {"text": "这场比赛的反应时比计划长。", "explanation": "这里应该用〈时间〉。反应时专指从刺激到动作之间的那一小段时间，整场比赛的时长不能叫反应时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反应时", "is_correct": true, "explanation": "正确。反应时是从刺激出现到做出反应所需的时间，开车打电话会分心，让反应时变长。"}, {"text": "注意力", "is_correct": false, "explanation": "搭配：“注意力”说集中或分散，不说变长。"}, {"text": "脉搏", "is_correct": false, "explanation": "搭配：“脉搏”说快慢，不说变长。"}, {"text": "胆子", "is_correct": false, "explanation": "语义：“胆子”说大小，开车打电话不会让胆子变长。"}], "explanations": {"反应时": "正确。反应时是从刺激出现到做出反应所需的时间，开车打电话会分心，让反应时变长。", "注意力": "搭配：“注意力”说集中或分散，不说变长。", "脉搏": "搭配：“脉搏”说快慢，不说变长。", "胆子": "语义：“胆子”说大小，开车打电话不会让胆子变长。"}, "sentence_index": 6, "correct_answer": "反应时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的反应时比普通人高。", "explanation": "这里应该用〈灵敏度〉。反应时只能说长或短，说高低要用〈灵敏度〉。"}, {"text": "这次手术的反应时很顺利。", "explanation": "这里应该用〈过程〉。反应时只指一小段时间，不能用来说一件事进展得顺不顺利，那要用〈过程〉。"}, {"text": "我看了看表，他的反应时是三点整。", "explanation": "这里应该用〈时刻〉。反应时指一段时间，不能说某个时间点，说某一时刻要用〈时刻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个司机的反应时很快。", "corrected_sentence": "这个司机的反应时很短。", "error_description": "错误在“很快”。“反应时”是时间，应说“很短”，不说“很快”；说快慢要用“反应速度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子的反应时比我长一下。", "corrected_sentence": "这个孩子的反应时比我长一点。", "error_description": "错误在“一下”。表示比较差距的“稍微”要用“一点”，说“比我长一下”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
